import io.gatling.javaapi.core.*;
import io.gatling.javaapi.http.*;
import io.gatling.javaapi.core.CoreDsl.*;
import io.gatling.javaapi.http.HttpDsl.*;

import java.time.Duration;
import java.util.*;
import java.util.regex.*;

public class ModelSimulation extends Simulation {

    private static final String BASE_URL = System.getenv().getOrDefault("BASE_URL", "http://127.0.0.1:8000");

    private static final Pattern CSRF_PATTERN = Pattern.compile("name=\"csrf\"\\s+value=\"([^\"]+)\"");
    private static final Pattern CHALLENGE_ACTION_PATTERN = Pattern.compile("action=\"(/v2/challenges/[^\"]+)\"");
    private static final Pattern CHALLENGE_NAME_PATTERN = Pattern.compile("name=\"challenge\"\\s+value=\"([^\"]+)\"");
    private static final Pattern LOCATION_PATTERN = Pattern.compile("Location:\\s*(.+)", Pattern.CASE_INSENSITIVE);

    private static final HttpProtocolBuilder httpProtocol = http
            .baseUrl(BASE_URL)
            .disableAutoRedirect()
            .acceptHeader("application/json")
            .contentTypeHeader("application/json")
            .userAgentHeader("gatling-perf-test");

    private static String extractCsrfFromHtml(String html) {
        Matcher m = CSRF_PATTERN.matcher(html);
        if (m.find()) {
            return m.group(1);
        }
        // Try attribute variants: value before name, single quotes, etc.
        Pattern p2 = Pattern.compile("value=['\"]([^'\"]+)['\"][^>]*name=['\"]csrf['\"]");
        Matcher m2 = p2.matcher(html);
        if (m2.find()) return m2.group(1);
        Pattern p3 = Pattern.compile("name=['\"]csrf['\"][^>]*value=['\"]([^'\"]+)['\"]");
        Matcher m3 = p3.matcher(html);
        if (m3.find()) return m3.group(1);
        throw new RuntimeException("CSRF not found in HTML");
    }

    private static String extractChallengeAction(String html) {
        Matcher m = CHALLENGE_ACTION_PATTERN.matcher(html);
        if (m.find()) return m.group(1);
        throw new RuntimeException("Challenge action not found");
    }

    private static String extractChallengeValue(String html) {
        Matcher m = CHALLENGE_NAME_PATTERN.matcher(html);
        if (m.find()) return m.group(1);
        throw new RuntimeException("Challenge value not found");
    }

    private static String extractLocation(String headerValue) {
        if (headerValue == null) return null;
        Matcher m = LOCATION_PATTERN.matcher(headerValue);
        if (m.find()) return m.group(1).trim();
        return headerValue.trim();
    }

    private static ChainBuilder doLogin() {
        return exec(
                http("GET login-form")
                        .get("/v2/login-form")
                        .check(status().is(200))
                        .check(bodyString().saveAs("loginFormHtml"))
                        .check(header("Set-Cookie").saveAs("loginCookie"))
        ).exec(session -> {
            String html = session.getString("loginFormHtml");
            String csrf = extractCsrfFromHtml(html);
            return session.set("csrfToken", csrf);
        }).exec(
                http("POST login")
                        .post("/v2/login")
                        .header("X-CSRF-Token", session -> session.getString("csrfToken"))
                        .body(StringBody(session -> {
                            String csrf = session.getString("csrfToken");
                            String user = session.getString("username");
                            String pass = session.getString("password");
                            return String.format("{\"username\":\"%s\",\"password\":\"%s\",\"csrf\":\"%s\"}", user, pass, csrf);
                        }))
                        .check(status().in(200, 302))
                        .check(bodyString().saveAs("loginResponseBody"))
                        .check(header("Location").optional().saveAs("loginLocation"))
                        .check(header("Set-Cookie").optional().saveAs("sessionCookie"))
        ).exec(session -> {
            String loc = session.getString("loginLocation");
            if (loc != null && !loc.isEmpty()) {
                return session.set("pendingLocation", loc);
            }
            return session;
        }).doIf(session -> session.contains("pendingLocation")).then(
                exec(
                        http("GET login redirect location")
                                .get(session -> session.getString("pendingLocation"))
                                .check(status().is(200))
                                .check(bodyString().saveAs("loginResponseBody"))
                                .check(header("Set-Cookie").optional().saveAs("sessionCookie"))
                )
        ).exec(session -> {
            String body = session.getString("loginResponseBody");
            if (body != null && !body.isEmpty()) {
                try {
                    // Try to parse JSON for csrf
                    String csrf = extractJsonString(body, "csrf");
                    if (csrf != null) {
                        return session.set("csrfToken", csrf);
                    }
                } catch (Exception e) {
                    // ignore
                }
            }
            return session;
        });
    }

    private static String extractJsonString(String json, String key) {
        Pattern p = Pattern.compile("\"" + key + "\"\\s*:\\s*\"([^\"]+)\"");
        Matcher m = p.matcher(json);
        if (m.find()) return m.group(1);
        return null;
    }

    private static ChainBuilder getCatalog() {
        return exec(
                http("GET catalog")
                        .get("/v2/catalog")
                        .header("X-CSRF-Token", session -> session.getString("csrfToken"))
                        .check(status().is(200))
                        .check(jsonPath("$.data.products[0].id").saveAs("productId"))
                        .check(jsonPath("$.data.products[0].variants[0].id").saveAs("variantId"))
                        .check(jsonPath("$.data.products[0].variants[0].in_stock").saveAs("inStock"))
        );
    }

    private static ChainBuilder getCatalogPage() {
        return exec(
                http("GET catalog page")
                        .get("/v2/catalog/page")
                        .header("X-CSRF-Token", session -> session.getString("csrfToken"))
                        .check(status().is(200))
                        .check(jsonPath("$.data.products[0].id").optional().saveAs("pageProductId"))
                        .check(jsonPath("$.data.products[0].variants[0].id").optional().saveAs("pageVariantId"))
                        .check(jsonPath("$.data.products[0].variants[0].in_stock").optional().saveAs("pageInStock"))
                        .check(jsonPath("$.next").optional().saveAs("nextPage"))
        ).exec(session -> {
            String pid = session.getString("pageProductId");
            String vid = session.getString("pageVariantId");
            String stock = session.getString("pageInStock");
            if (pid != null && vid != null && "true".equals(stock)) {
                return session.set("productId", pid).set("variantId", vid);
            }
            return session;
        });
    }

    private static ChainBuilder createCart() {
        return exec(
                http("POST create cart")
                        .post("/v2/carts")
                        .header("X-CSRF-Token", session -> session.getString("csrfToken"))
                        .body(StringBody(session -> {
                            String pid = session.getString("productId");
                            String vid = session.getString("variantId");
                            String grantId = session.getString("grantId");
                            if (grantId != null && !grantId.isEmpty()) {
                                return String.format("{\"product_id\":\"%s\",\"variant_id\":\"%s\",\"grant_id\":\"%s\"}", pid, vid, grantId);
                            }
                            return String.format("{\"product_id\":\"%s\",\"variant_id\":\"%s\"}", pid, vid);
                        }))
                        .check(status().is(201))
                        .check(jsonPath("$.id").saveAs("cartId"))
                        .check(jsonPath("$.csrf").optional().saveAs("cartCsrf"))
                        .check(header("ETag").optional().saveAs("cartEtag"))
        ).exec(session -> {
            String csrf = session.getString("cartCsrf");
            if (csrf != null && !csrf.isEmpty()) {
                return session.set("csrfToken", csrf);
            }
            return session;
        });
    }

    private static ChainBuilder getCart() {
        return exec(
                http("GET cart")
                        .get(session -> "/v2/carts/" + session.getString("cartId"))
                        .header("X-CSRF-Token", session -> session.getString("csrfToken"))
                        .check(status().is(200))
                        .check(header("ETag").optional().saveAs("cartEtag"))
        );
    }

    private static ChainBuilder patchCart() {
        return exec(
                http("PATCH cart quantity")
                        .patch(session -> "/v2/carts/" + session.getString("cartId"))
                        .header("X-CSRF-Token", session -> session.getString("csrfToken"))
                        .header("If-Match", session -> session.getString("cartEtag"))
                        .body(StringBody("{\"quantity\":2}"))
                        .check(status().in(200, 412))
                        .check(jsonPath("$.csrf").optional().saveAs("patchCsrf"))
                        .check(header("ETag").optional().saveAs("newEtag"))
        ).exec(session -> {
            String csrf = session.getString("patchCsrf");
            if (csrf != null && !csrf.isEmpty()) {
                session = session.set("csrfToken", csrf);
            }
            String etag = session.getString("newEtag");
            if (etag != null && !etag.isEmpty()) {
                session = session.set("cartEtag", etag);
            }
            return session;
        }).doIf(session -> session.getInt("patchStatus") == 412).then(
                exec(getCart()).exec(
                        http("PATCH cart retry")
                                .patch(session -> "/v2/carts/" + session.getString("cartId"))
                                .header("X-CSRF-Token", session -> session.getString("csrfToken"))
                                .header("If-Match", session -> session.getString("cartEtag"))
                                .body(StringBody("{\"quantity\":2}"))
                                .check(status().is(200))
                                .check(jsonPath("$.csrf").optional().saveAs("patchCsrf2"))
                                .check(header("ETag").optional().saveAs("newEtag2"))
                ).exec(session -> {
                    String csrf = session.getString("patchCsrf2");
                    if (csrf != null && !csrf.isEmpty()) {
                        session = session.set("csrfToken", csrf);
                    }
                    String etag = session.getString("newEtag2");
                    if (etag != null && !etag.isEmpty()) {
                        session = session.set("cartEtag", etag);
                    }
                    return session;
                })
        );
    }

    private static ChainBuilder getChallengeForm() {
        return exec(
                http("GET challenge-form")
                        .get("/v2/challenge-form")
                        .header("X-CSRF-Token", session -> session.getString("csrfToken"))
                        .check(status().is(200))
                        .check(bodyString().saveAs("challengeFormHtml"))
        ).exec(session -> {
            String html = session.getString("challengeFormHtml");
            String action = extractChallengeAction(html);
            String challenge = extractChallengeValue(html);
            return session.set("challengeAction", action).set("challengeValue", challenge);
        });
    }

    private static ChainBuilder postChallenge() {
        return exec(
                http("POST challenge")
                        .post(session -> session.getString("challengeAction"))
                        .header("X-CSRF-Token", session -> session.getString("csrfToken"))
                        .body(StringBody(session -> String.format("{\"challenge\":\"%s\"}", session.getString("challengeValue"))))
                        .check(status().is(302))
                        .check(header("Location").saveAs("challengeLocation"))
        ).exec(
                http("GET challenge grant")
                        .get(session -> session.getString("challengeLocation"))
                        .header("X-CSRF-Token", session -> session.getString("csrfToken"))
                        .check(status().is(200))
                        .check(jsonPath("$.grant_id").saveAs("grantId"))
                        .check(jsonPath("$.csrf").optional().saveAs("grantCsrf"))
        ).exec(session -> {
            String csrf = session.getString("grantCsrf");
            if (csrf != null && !csrf.isEmpty()) {
                return session.set("csrfToken", csrf);
            }
            return session;
        });
    }

    private static ChainBuilder createReservation() {
        return exec(
