                        .post("/v2/reservations")
                        .header("X-CSRF-Token", session -> session.getString("csrfToken"))
                        .body(StringBody(session -> String.format("{\"cart_id\":\"%s\"}", session.getString("cartId"))))
                        .check(status().is(202))
                        .check(jsonPath("$.status_url").saveAs("statusUrl"))
                        .check(jsonPath("$.csrf").optional().saveAs("reservationCsrf"))
        ).exec(session -> {
            String csrf = session.getString("reservationCsrf");
            if (csrf != null && !csrf.isEmpty()) {
                session = session.set("csrfToken", csrf);
            }
            return session.set("pollCount", 0);
        }).asLongAs(session -> session.getInt("pollCount") < 5 && !"ready".equals(session.getString("reservationStatus"))).on(
                exec(session -> session.set("pollCount", session.getInt("pollCount") + 1))
                        .pause(Duration.ofMillis(60))
