                                        .check(jsonPath("$.csrf").optional().saveAs("pollCsrf"))
                        ).exec(session -> {
                            String csrf = session.getString("pollCsrf");
                            if (csrf != null && !csrf.isEmpty()) {
                                session = session.set("csrfToken", csrf);
                            }
                            return session;
                        })
        ).doIf(session -> "ready".equals(session.getString("reservationStatus"))).then(
