                        .check(status().is(201))
                        .check(jsonPath("$.accepted").is("true"))
                        .check(jsonPath("$.id").saveAs("orderId"))
                        .check(jsonPath("$.csrf").optional().saveAs("orderCsrf"))
        ).exec(session -> {
            String csrf = session.getString("orderCsrf");
            if (csrf != null && !csrf.isEmpty()) {
                return session.set("csrfToken", csrf);
            }
            return session;
        });
    }

    private static ChainBuilder doWork() {
        return exec(
                http("POST work")
                        .post("/v2/work")
                        .header("X-CSRF-Token", session -> session.getString("csrfToken"))
                        .body(StringBody("{}"))
