                                .exec(
                                        http("POST work retry")
                                                .post("/v2/work")
                                                .header("X-CSRF-Token", session -> session.getString("csrfToken"))
                                                .body(StringBody("{}"))
                                                .check(status().in(200, 429))
                                                .check(jsonPath("$.ok").optional().is("true"))
                                )
                )
        );
    }

    private static ChainBuilder fullJourney() {
        return exec(doLogin())
                .exec(getCatalog())
                .exec(getCatalogPage())
                .exec(getChallengeForm())
                .exec(postChallenge())
                .exec(createCart())
                .exec(getCart())
                .exec(patchCart())
                .exec(createReservation())
                .exec(placeOrder())
                .exec(doWork());
    }

    private static final ScenarioBuilder userScenario = scenario("ShopFlow")
            .exec(fullJourney());

    {
        setUp(
                userScenario.injectOpen(atOnceUsers(2))
        ).protocols(httpProtocol);
    }
}
