import http from 'k6/http';
import { check, sleep, fail } from 'k6';
import { Rate, Trend } from 'k6/metrics';
import { randomIntBetween, randomItem } from 'https://jslib.k6.io/k6-utils/1.4.0/index.js';

const BASE_URL = __ENV.BASE_URL || 'http://127.0.0.1:8000';

const businessFailure = new Rate('business_failure');
const workLatency = new Trend('work_latency', true);

const PROFILES = [
  { login_csrf: true },
  { login_csrf: true, html_layout: 1, reverse_catalog: true }
];

const USERS = 2;
const ITERATIONS = 2;

export const options = {
  scenarios: {
    flow: {
      executor: 'per-vu-iterations',
      vus: USERS,
      iterations: ITERATIONS,
      maxDuration: '5m',
    },
  },
  thresholds: {
    business_failure: ['rate<0.5'],
  },
  noConnectionReuse: false,
  discardResponseBodies: false,
};

function getProfile(vuIndex) {
  return PROFILES[vuIndex % PROFILES.length];
}

function extractCsrfFromHtml(html) {
  const patterns = [
    /<input[^>]*name=["']csrf["'][^>]*value=["']([^"']+)["']/i,
    /<input[^>]*value=["']([^"']+)["'][^>]*name=["']csrf["']/i,
    /<input[^>]*name=["']csrf["'][^>]*>/i,
  ];
  for (const p of patterns) {
    const m = html.match(p);
    if (m && m[1]) return m[1];
  }
  // Try to find any input with name csrf and extract value attribute
  const inputMatch = html.match(/<input[^>]*name=["']csrf["'][^>]*>/i);
  if (inputMatch) {
    const tag = inputMatch[0];
    const valMatch = tag.match(/value=["']([^"']+)["']/i);
    if (valMatch) return valMatch[1];
    const valMatch2 = tag.match(/value=([^\s>]+)/i);
    if (valMatch2) return valMatch2[1].replace(/["']/g, '');
  }
  // Try attribute variants like data-csrf
  const dataMatch = html.match(/<input[^>]*name=["']csrf["'][^>]*data-value=["']([^"']+)["']/i);
  if (dataMatch) return dataMatch[1];
  const dataMatch2 = html.match(/<input[^>]*data-csrf=["']([^"']+)["'][^>]*name=["']csrf["']/i);
  if (dataMatch2) return dataMatch2[1];
  // Fallback: any hidden input with csrf in name
  const hiddenMatch = html.match(/<input[^>]*type=["']hidden["'][^>]*name=["'][^"']*csrf[^"']*["'][^>]*>/i);
  if (hiddenMatch) {
    const tag = hiddenMatch[0];
    const valMatch = tag.match(/value=["']([^"']+)["']/i);
    if (valMatch) return valMatch[1];
  }
  return null;
}

function getLoginForm(httpClient) {
  const res = httpClient.get(`${BASE_URL}/v2/login-form`, {
    redirects: 0,
    tags: { name: 'login-form' },
  });
  if (res.status !== 200) {
    fail(`login-form status ${res.status}`);
  }
  const csrf = extractCsrfFromHtml(res.body);
  if (!csrf) {
    fail('Could not extract CSRF from login form');
  }
  return { csrf, cookies: res.cookies };
}

function login(httpClient, username, password, csrf) {
  const payload = JSON.stringify({ username, password, csrf });
  const res = httpClient.post(`${BASE_URL}/v2/login`, payload, {
    headers: { 'Content-Type': 'application/json' },
    redirects: 0,
    tags: { name: 'login' },
  });
  if (res.status === 302) {
    const location = res.headers['Location'];
    if (!location) fail('302 without Location');
    const locRes = httpClient.get(location, {
      redirects: 0,
      tags: { name: 'login-redirect' },
    });
    if (locRes.status !== 200 && locRes.status !== 201) {
      fail(`login redirect status ${locRes.status}`);
    }
    let body = null;
    try { body = locRes.json(); } catch (e) { /* ignore */ }
    const newCsrf = body && body.csrf ? body.csrf : csrf;
    return { csrf: newCsrf, cookies: locRes.cookies, status: locRes.status };
  }
  if (res.status !== 200 && res.status !== 201) {
    fail(`login status ${res.status}`);
  }
  let body = null;
  try { body = res.json(); } catch (e) { /* ignore */ }
  const newCsrf = body && body.csrf ? body.csrf : csrf;
  return { csrf: newCsrf, cookies: res.cookies, status: res.status };
}

function getCatalog(httpClient, csrf, reverse) {
  const res = httpClient.get(`${BASE_URL}/v2/catalog`, {
    headers: { 'X-CSRF-Token': csrf },
    tags: { name: 'catalog' },
  });
  if (res.status !== 200) {
    fail(`catalog status ${res.status}`);
  }
  const body = res.json();
  const products = body.data && body.data.products ? body.data.products : [];
  if (reverse) {
    products.reverse();
  }
  return { products, next: body.next || null, csrf: body.csrf || csrf };
}

function getCatalogPage(httpClient, csrf, pageUrl) {
  const url = pageUrl.startsWith('http') ? pageUrl : `${BASE_URL}${pageUrl}`;
  const res = httpClient.get(url, {
    headers: { 'X-CSRF-Token': csrf },
    tags: { name: 'catalog-page' },
  });
  if (res.status !== 200) {
    fail(`catalog page status ${res.status}`);
  }
  const body = res.json();
  const product = body.data && body.data.product ? body.data.product : null;
  return { product, next: body.next || null, csrf: body.csrf || csrf };
}

function getChallengeForm(httpClient, csrf) {
  const res = httpClient.get(`${BASE_URL}/v2/challenge-form`, {
    headers: { 'X-CSRF-Token': csrf },
    tags: { name: 'challenge-form' },
  });
  if (res.status !== 200) {
    fail(`challenge-form status ${res.status}`);
  }
  const html = res.body;
  const actionMatch = html.match(/<form[^>]*action=["']([^"']+)["']/i);
  if (!actionMatch) fail('No form action in challenge-form');
  const action = actionMatch[1];
  const challengeMatch = html.match(/<input[^>]*name=["']challenge["'][^>]*>/i);
  if (!challengeMatch) fail('No challenge input');
  const challengeValMatch = challengeMatch[0].match(/value=["']([^"']+)["']/i);
  const challenge = challengeValMatch ? challengeValMatch[1] : '';
  return { action, challenge, csrf: body.csrf || csrf };
}

function postChallenge(httpClient, csrf, action, challenge) {
  const url = action.startsWith('http') ? action : `${BASE_URL}${action}`;
  const payload = JSON.stringify({ challenge });
  const res = httpClient.post(url, payload, {
    headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': csrf },
    redirects: 0,
    tags: { name: 'challenge-post' },
  });
  if (res.status === 302) {
    const location = res.headers['Location'];
    if (!location) fail('Challenge 302 without Location');
    const locRes = httpClient.get(location, {
      headers: { 'X-CSRF-Token': csrf },
      tags: { name: 'challenge-redirect' },
    });
    if (locRes.status !== 200) fail(`challenge redirect status ${locRes.status}`);
    const body = locRes.json();
    return { grantId: body.grant_id || null, csrf: body.csrf || csrf };
  }
  if (res.status !== 200 && res.status !== 201) {
    fail(`challenge post status ${res.status}`);
  }
  const body = res.json();
  return { grantId: body.grant_id || null, csrf: body.csrf || csrf };
}

function createCart(httpClient, csrf, productId, variantId, grantId) {
  const payload = { product_id: productId, variant_id: variantId };
  if (grantId) payload.grant_id = grantId;
  const res = httpClient.post(`${BASE_URL}/v2/carts`, JSON.stringify(payload), {
    headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': csrf },
    tags: { name: 'create-cart' },
