function patchCart(httpClient, csrf, cartId, quantity, etag) {
  const payload = JSON.stringify({ quantity });
  const headers = {
    'Content-Type': 'application/json',
    'X-CSRF-Token': csrf,
  };
  if (etag) headers['If-Match'] = etag;
  const res = httpClient.patch(`${BASE_URL}/v2/carts/${cartId}`, payload, {
    headers,
    tags: { name: 'patch-cart' },
  });
  if (res.status === 412) {
    // Re-read and retry once
    const reRead = getCart(httpClient, csrf, cartId);
    const retryHeaders = {
      'Content-Type': 'application/json',
      'X-CSRF-Token': reRead.csrf,
    };
    if (reRead.etag) retryHeaders['If-Match'] = reRead.etag;
    const retryRes = httpClient.patch(`${BASE_URL}/v2/carts/${cartId}`, payload, {
      headers: retryHeaders,
      tags: { name: 'patch-cart-retry' },
    });
    if (retryRes.status !== 200 && retryRes.status !== 201) {
      fail(`patch cart retry status ${retryRes.status}`);
    }
    const body = retryRes.json();
    return { csrf: body.csrf || reRead.csrf, etag: retryRes.headers['ETag'] || retryRes.headers['Etag'] || null };
  }
  if (res.status !== 200 && res.status !== 201) {
    fail(`patch cart status ${res.status}`);
  }
  const body = res.json();
  return { csrf: body.csrf || csrf, etag: res.headers['ETag'] || res.headers['Etag'] || null };
