    fail(`reservation status ${res.status}`);
  }
  const body = res.json();
  return { statusUrl: body.status_url, csrf: body.csrf || csrf };
}

function pollReservation(httpClient, csrf, statusUrl) {
  const url = statusUrl.startsWith('http') ? statusUrl : `${BASE_URL}${statusUrl}`;
  for (let i = 0; i < 5; i++) {
    sleep(0.05 + i * 0.01);
    const res = httpClient.get(url, {
      headers: { 'X-CSRF-Token': csrf },
      tags: { name: 'poll-reservation' },
    });
    if (res.status !== 200) {
      fail(`poll reservation status ${res.status}`);
    }
    const body = res.json();
    if (body.status === 'ready') {
      return { reservationId: body.reservation_id, csrf: body.csrf || csrf };
    }
    if (body.status === 'failed') {
      return { reservationId: null, csrf: body.csrf || csrf };
    }
    csrf = body.csrf || csrf;
  }
  return { reservationId: null, csrf };
