      const loginResult = login(httpClient, 'bench', 'bench', form.csrf);
      const recoverRes = httpClient.post(`${BASE_URL}/v2/carts/${cartId}/recover`, '{}', {
        headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': loginResult.csrf },
        tags: { name: 'recover-cart-revoked' },
      });
      if (recoverRes.status !== 200 && recoverRes.status !== 201) {
        fail(`recover cart revoked status ${recoverRes.status}`);
      }
      const recoverBody = recoverRes.json();
      const finalCsrf = recoverBody.csrf || loginResult.csrf;
