    fail(`create order status ${res.status}`);
  }
  const body = res.json();
  if (res.status === 200 && body.accepted === false) {
    fail('Order not accepted (business failure)');
  }
  return { accepted: true, orderId: body.id, csrf: body.csrf || csrf };
}

function doWork(httpClient, csrf) {
  const res = httpClient.post(`${BASE_URL}/v2/work`, '{}', {
    headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': csrf },
    tags: { name: 'work' },
  });
  if (res.status === 429) {
    // Scheduled 429 with Retry-After
    const retryAfter = parseInt(res.headers['Retry-After'] || '1', 10);
    for (let i = 0; i < 4; i++) {
      sleep(retryAfter);
      const retryRes = httpClient.post(`${BASE_URL}/v2/work`, '{}', {
        headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': csrf },
        tags: { name: 'work-retry' },
      });
      if (retryRes.status === 200) {
        const body = retryRes.json();
        if (body.ok === true) return;
      }
      if (retryRes.status !== 429) {
        businessFailure.add(1);
        return;
      }
    }
    businessFailure.add(1);
    return;
  }
  if (res.status === 200) {
    const body = res.json();
    if (body.ok === true) return;
    businessFailure.add(1);
    return;
  }
  if (res.status === 500) {
    businessFailure.add(1);
    return;
  }
  businessFailure.add(1);
}

function doBrowse(httpClient, csrf) {
