  try {
    const reservation = createReservation(httpClient, csrf, cartId);
    csrf = reservation.csrf;
    const pollResult = pollReservation(httpClient, csrf, reservation.statusUrl);
    csrf = pollResult.csrf;
    reservationId = pollResult.reservationId;
  } catch (e) {
    reservationId = null;
  }

  // Create order
  const idempotencyKey = `order-${cartId}-${Date.now()}-${__VU}-${__ITER}`;
  const orderResult = createOrder(httpClient, csrf, cartId, reservationId, idempotencyKey, etag);
  csrf = orderResult.csrf;

  // Do work and browse
  doWork(httpClient, csrf);
  doBrowse(httpClient, csrf);

  sleep(0.1);
}
