        with self.client.post(action, json={"challenge": challenge}, headers={"X-CSRF-Token": self.csrf}, catch_response=True) as r:
            if r.status_code == 401:
                if self.handle_401(r, "challenge"):
                    with self.client.post(action, json={"challenge": challenge}, headers={"X-CSRF-Token": self.csrf}, catch_response=True) as r2:
                        r = r2
                else:
                    return False
            if r.status_code != 302:
                r.failure(f"challenge post status {r.status_code}")
                return False
            loc = r.headers.get("Location")
            if not loc:
                r.failure("challenge 302 without Location")
                return False
            with self.client.get(urljoin(BASE, loc), catch_response=True) as r2:
                if r2.status_code != 200:
                    r2.failure(f"challenge redirect status {r2.status_code}")
                    return False
                try:
                    data = r2.json()
                    self.grant_id = data.get("grant_id")
                    self.csrf = data.get("csrf", self.csrf)
                except Exception as e:
                    r2.failure(f"challenge redirect parse: {e}")
                    return False
        return True

    def create_reservation(self):
        if not self.cart_id:
            return False
        with self.client.post("/v2/reservations", json={"cart_id": self.cart_id}, headers={"X-CSRF-Token": self.csrf}, catch_response=True) as r:
            if r.status_code == 401:
                if self.handle_401(r, "reservation"):
                    with self.client.post("/v2/reservations", json={"cart_id": self.cart_id}, headers={"X-CSRF-Token": self.csrf}, catch_response=True) as r2:
                        r = r2
                else:
                    return False
            if r.status_code != 202:
                r.failure(f"reservation status {r.status_code}")
                return False
            try:
                data = r.json()
                status_url = data.get("status_url")
                self.csrf = data.get("csrf", self.csrf)
            except Exception as e:
                r.failure(f"reservation parse: {e}")
                return False
        # poll
        for i in range(5):
            time.sleep(0.05)
            with self.client.get(status_url, catch_response=True) as r:
                if r.status_code != 200:
                    r.failure(f"reservation poll status {r.status_code}")
                    return False
                try:
                    data = r.json()
                    status = data.get("status")
                    self.csrf = data.get("csrf", self.csrf)
                    if status == "ready":
                        self.reservation_id = data.get("reservation_id")
                        return True
                    elif status == "failed":
                        r.failure("reservation failed")
                        return False
                    # pending - continue
                except Exception as e:
                    r.failure(f"reservation poll parse: {e}")
                    return False
        r.failure("reservation polling exhausted")
        return False

    def place_order(self):
        if not self.cart_id:
            return False
        if not self.idempotency_key:
            self.idempotency_key = f"bench-{self.cart_id}-{int(time.time()*1000)}"
        payload = {"cart_id": self.cart_id}
        if self.reservation_id:
            payload["reservation_id"] = self.reservation_id
        headers = {
            "X-CSRF-Token": self.csrf,
            "Idempotency-Key": self.idempotency_key,
        }
        if self.cart_etag:
            headers["If-Match"] = self.cart_etag
        with self.client.post("/v2/orders", json=payload, headers=headers, catch_response=True) as r:
            if r.status_code == 401:
                if self.handle_401(r, "order placement"):
                    headers = {
                        "X-CSRF-Token": self.csrf,
                        "Idempotency-Key": self.idempotency_key,
                    }
                    if self.cart_etag:
                        headers["If-Match"] = self.cart_etag
                    with self.client.post("/v2/orders", json=payload, headers=headers, catch_response=True) as r2:
                        r = r2
                else:
                    return False
            if r.status_code == 412:
                # re-read cart and retry once
                with self.client.get(f"/v2/carts/{self.cart_id}", catch_response=True) as gr:
                    if gr.status_code == 200:
                        self.cart_etag = gr.headers.get("ETag")
                        headers = {
                            "X-CSRF-Token": self.csrf,
                            "Idempotency-Key": self.idempotency_key,
                        }
                        if self.cart_etag:
                            headers["If-Match"] = self.cart_etag
                        with self.client.post("/v2/orders", json=payload, headers=headers, catch_response=True) as r2:
                            r = r2
                    else:
                        gr.failure(f"cart re-read before order status {gr.status_code}")
                        return False
            if r.status_code == 200:
                try:
                    data = r.json()
                    if data.get("accepted") is False:
                        r.failure("order accepted:false - business failure")
                        return False
                    self.csrf = data.get("csrf", self.csrf)
                    self.order_done = True
                    return True
                except Exception as e:
                    r.failure(f"order parse: {e}")
                    return False
            if r.status_code != 201:
                r.failure(f"order status {r.status_code}")
                return False
            try:
                data = r.json()
                if data.get("accepted") is False:
                    r.failure("order accepted:false - business failure")
                    return False
                self.csrf = data.get("csrf", self.csrf)
                self.order_done = True
                return True
            except Exception as e:
                r.failure(f"order parse: {e}")
                return False
        return False

    def do_work(self):
        with self.client.post("/v2/work", json={}, catch_response=True) as r:
            if r.status_code == 429:
                # scheduled 429 - retry with Retry-After
                retry_after = r.headers.get("Retry-After", "1")
                try:
                    wait = float(retry_after)
                except ValueError:
                    wait = 1.0
                for attempt in range(4):
                    time.sleep(wait)
                    with self.client.post("/v2/work", json={}, catch_response=True) as r2:
                        if r2.status_code == 200:
                            return
                        elif r2.status_code == 429:
                            retry_after = r2.headers.get("Retry-After", "1")
                            try:
                                wait = float(retry_after)
                            except ValueError:
                                wait = 1.0
                            continue
                        elif r2.status_code == 500:
                            r2.failure("work 500")
                            return
                        else:
                            r2.failure(f"work status {r2.status_code}")
                            return
                r.failure("work 429 retries exhausted")
                return
            elif r.status_code == 500:
                r.failure("work 500")
                return
            elif r.status_code != 200:
                r.failure(f"work status {r.status_code}")
                return

    @task
    def shop_flow(self):
        if self.iterations_done >= self.max_iterations:
            raise StopUser()
        self.iterations_done += 1
        # fresh login/cart per journey
        self.csrf = None
        self.cart_id = None
        self.cart_etag = None
        self.grant_id = None
        self.reservation_id = None
        self.idempotency_key = None
        self.order_done = False

        if not self.login():
            return

        # optional challenge
        self.get_challenge_grant()

        products = self.get_catalog_products()
        if not products:
            return
        product_id, variant_id = random.choice(products)

        if not self.create_cart(product_id, variant_id):
            return

        # update quantity
        self.update_cart_quantity(random.randint(1, 20))

        # optional reservation
        self.create_reservation()

        # place order
        self.place_order()

        # work
        self.do_work()


