    private static final Pattern CSRF_PATTERN = Pattern.compile("name=[\"']csrf[\"'][^>]*value=[\"']([^\"']+)[\"']");
    private static final Pattern CSRF_PATTERN_ALT = Pattern.compile("value=[\"']([^\"']+)[\"'][^>]*name=[\"']csrf[\"']");
    private static final Pattern CHALLENGE_ACTION_PATTERN = Pattern.compile("action=[\"']([^\"']*?/v2/challenges/[^\"']+)[\"']");
    private static final Pattern LOCATION_PATTERN = Pattern.compile("[Ll]ocation:\\s*(.+)");

    private static String extractCsrf(String html) {
        if (html == null) return null;
        Matcher m1 = CSRF_PATTERN.matcher(html);
        if (m1.find()) return m1.group(1);
        Matcher m2 = CSRF_PATTERN_ALT.matcher(html);
        if (m2.find()) return m2.group(1);
        // Fallback: find any input with name containing csrf (case-insensitive) and extract value
        Pattern fallback = Pattern.compile("<input[^>]*name=[\"']?csrf[\"']?[^>]*>", Pattern.CASE_INSENSITIVE);
        Matcher fm = fallback.matcher(html);
        if (fm.find()) {
            String tag = fm.group(0);
            Pattern valP = Pattern.compile("value=[\"']([^\"']+)[\"']", Pattern.CASE_INSENSITIVE);
            Matcher vm = valP.matcher(tag);
            if (vm.find()) return vm.group(1);
        }
        return null;
    }

    private static String extractChallengeAction(String html) {
