  return { success: false, response: null, error: 'Work retry limit exceeded' };
}

function handle401Expired(csrf, cartId, operationFn) {
  // Renew session
  const renewResult = renewSession(csrf);
  if (!renewResult.success) {
    return { success: false, response: renewResult.response };
  }

  let currentCsrf = renewResult.csrf;

  // Recover cart if exists
  if (cartId) {
    const recoverResult = recoverCart(currentCsrf, cartId);
    if (recoverResult.success) {
      currentCsrf = recoverResult.csrf;
    }
  }

  // Retry operation once
  return operationFn(currentCsrf);
}

function handle401Session(csrf, cartId, vuId, profile, operationFn) {
  // Get fresh form/login
  const formResponse = http.get(`${BASE_URL}/v2/login-form`, {
    redirects: 0,
    tags: { name: 'login_form_recovery' }
  });

  if (formResponse.status !== 200) {
    return { success: false, response: formResponse };
  }

  const newCsrf = extractCsrfFromHtml(formResponse.body);
  if (!newCsrf) {
    return { success: false, response: formResponse, error: 'Could not extract CSRF from recovery form' };
  }

  const username = `bench-${vuId}`;
  const password = 'bench';

  const loginPayload = JSON.stringify({
    username: username,
    password: password,
    csrf: newCsrf
  });

  const loginResponse = http.post(`${BASE_URL}/v2/login`, loginPayload, {
    headers: {
      'Content-Type': 'application/json'
    },
    redirects: 0,
    tags: { name: 'login_recovery' }
  });

  let sessionCsrf = newCsrf;

  if (loginResponse.status === 302) {
    const location = extractLocation(loginResponse.headers);
    if (location) {
      const redirectResponse = http.get(location, {
        redirects: 0,
        tags: { name: 'login_redirect_recovery' }
      });
      if (redirectResponse.status === 200) {
        const redirectCsrf = getCsrfFromResponse(redirectResponse);
        if (redirectCsrf) {
          sessionCsrf = redirectCsrf;
        }
      }
    }
  } else if (loginResponse.status === 200) {
    const responseCsrf = getCsrfFromResponse(loginResponse);
    if (responseCsrf) {
      sessionCsrf = responseCsrf;
    }
  }

  // Recover cart
  if (cartId) {
    const recoverResult = recoverCart(sessionCsrf, cartId);
    if (recoverResult.success) {
      sessionCsrf = recoverResult.csrf;
    }
  }

  // Retry operation once
  return operationFn(sessionCsrf);
}

