def _extract_csrf(html):
    """Extract the real CSRF token from login/challenge forms.

    The fixture may include decoy hidden fields and may reorder attributes.
    We look for an input whose name is exactly 'csrf' and whose value is
    non-empty.  We do not rely on attribute ordering or on the absence of
    other hidden inputs.
    """
    import re

    # Find all input tags
    for tag in re.findall(r"<input\b[^>]*>", html, flags=re.IGNORECASE):
        attrs = dict(
            re.findall(r'([a-zA-Z_][\w-]*)\s*=\s*("([^"]*)"|\'([^\']*)\'|([^\s>]+))', tag)
        )
        # Normalize attribute values
        normalized = {}
        for k, v in attrs.items():
            if v[1]:
                normalized[k.lower()] = v[1]
            elif v[2]:
                normalized[k.lower()] = v[2]
            else:
                normalized[k.lower()] = v[3]
        if normalized.get("name", "").lower() == "csrf" and normalized.get("value"):
            return normalized["value"]
    return None


