            if not challenge:
                # Try to find input named challenge
                for tag in re.findall(r"<input\b[^>]*>", resp.text, flags=re.IGNORECASE):
                    attrs = dict(
                        re.findall(r'([a-zA-Z_][\w-]*)\s*=\s*("([^"]*)"|\'([^\']*)\'|([^\s>]+))', tag)
                    )
                    normalized = {}
                    for k, v in attrs.items():
                        if v[1]:
                            normalized[k.lower()] = v[1]
                        elif v[2]:
                            normalized[k.lower()] = v[2]
                        else:
                            normalized[k.lower()] = v[3]
                    if normalized.get("name", "").lower() == "challenge" and normalized.get("value"):
                        challenge = normalized["value"]
                        break
            if not challenge:
                resp.failure("no challenge token found")
                return False

        with self.client.post(
            action,
            json={"challenge": challenge},
            headers={"X-CSRF-Token": self.csrf or ""},
            catch_response=True,
            allow_redirects=False,
        ) as resp:
            if resp.status_code == 302:
                location = resp.headers.get("Location")
                if not location:
                    resp.failure("challenge 302 without Location")
                    return False
                with self.client.get(
                    location,
                    catch_response=True,
                    allow_redirects=False,
                ) as loc_resp:
                    if loc_resp.status_code != 200:
                        loc_resp.failure(f"challenge redirect status {loc_resp.status_code}")
                        return False
                    try:
                        data = loc_resp.json()
                        self.grant_id = data.get("grant_id")
                        if data.get("csrf"):
                            self.csrf = data["csrf"]
                        return True
                    except Exception:
                        loc_resp.failure("challenge redirect parse error")
                        return False
            elif resp.status_code == 401:
                if self._handle_401(resp, None):
                    # Retry once
                    with self.client.post(
                        action,
                        json={"challenge": challenge},
                        headers={"X-CSRF-Token": self.csrf or ""},
                        catch_response=True,
                        allow_redirects=False,
                    ) as retry_resp:
                        if retry_resp.status_code == 302:
                            location = retry_resp.headers.get("Location")
                            if not location:
                                retry_resp.failure("challenge retry 302 without Location")
                                return False
                            with self.client.get(
                                location,
                                catch_response=True,
                                allow_redirects=False,
                            ) as loc2_resp:
                                if loc2_resp.status_code != 200:
                                    loc2_resp.failure(f"challenge retry redirect status {loc2_resp.status_code}")
                                    return False
                                try:
                                    data = loc2_resp.json()
                                    self.grant_id = data.get("grant_id")
                                    if data.get("csrf"):
                                        self.csrf = data["csrf"]
                                    return True
                                except Exception:
                                    loc2_resp.failure("challenge retry redirect parse error")
                                    return False
                        else:
                            retry_resp.failure(f"challenge retry status {retry_resp.status_code}")
                            return False
                return False
            else:
                resp.failure(f"challenge status {resp.status_code}")
                return False

    def _create_reservation(self):
        """Create reservation and poll for status."""
        with self.client.post(
            "/v2/reservations",
            json={"cart_id": self.cart_id},
            headers={"X-CSRF-Token": self.csrf or ""},
            catch_response=True,
            allow_redirects=False,
        ) as resp:
            if resp.status_code == 202:
                try:
                    data = resp.json()
                    status_url = data.get("status_url")
                    if data.get("csrf"):
                        self.csrf = data["csrf"]
                except Exception:
                    resp.failure("reservation parse error")
                    return False
            elif resp.status_code == 401:
                if self._handle_401(resp, None):
                    with self.client.post(
                        "/v2/reservations",
                        json={"cart_id": self.cart_id},
                        headers={"X-CSRF-Token": self.csrf or ""},
                        catch_response=True,
                        allow_redirects=False,
                    ) as retry_resp:
                        if retry_resp.status_code == 202:
                            try:
                                data = retry_resp.json()
                                status_url = data.get("status_url")
                                if data.get("csrf"):
                                    self.csrf = data["csrf"]
                            except Exception:
                                retry_resp.failure("reservation retry parse error")
                                return False
                        else:
                            retry_resp.failure(f"reservation retry status {retry_resp.status_code}")
                            return False
                else:
                    return False
            else:
                resp.failure(f"reservation status {resp.status_code}")
                return False

        # Poll status_url
        for _ in range(5):
            time.sleep(0.05)
            with self.client.get(
                status_url,
                catch_response=True,
                allow_redirects=False,
            ) as poll_resp:
                if poll_resp.status_code == 200:
                    try:
                        data = poll_resp.json()
                        status = data.get("status")
                        if status == "ready":
                            self.reservation_id = data.get("reservation_id")
                            if data.get("csrf"):
                                self.csrf = data["csrf"]
                            return True
                        elif status in ("pending",):
                            continue
                        else:
                            poll_resp.failure(f"reservation status={status}")
                            return False
                    except Exception:
                        poll_resp.failure("reservation poll parse error")
                        return False
                elif poll_resp.status_code == 401:
                    if self._handle_401(poll_resp, None):
                        continue
                    return False
                else:
                    poll_resp.failure(f"reservation poll status {poll_resp.status_code}")
                    return False
        return False

    def _place_order(self):
        """Place order with idempotency key."""
        payload = {"cart_id": self.cart_id}
        if self.reservation_id:
            payload["reservation_id"] = self.reservation_id
        headers = {
            "X-CSRF-Token": self.csrf or "",
            "Idempotency-Key": self.idempotency_key,
        }
        if self.cart_etag:
            headers["If-Match"] = self.cart_etag
        with self.client.post(
            "/v2/orders",
            json=payload,
            headers=headers,
            catch_response=True,
            allow_redirects=False,
        ) as resp:
            if resp.status_code == 201:
                try:
                    data = resp.json()
                    if data.get("accepted") is True:
                        if data.get("csrf"):
                            self.csrf = data["csrf"]
                        return True
                    else:
                        resp.failure("order accepted=false")
                        return False
                except Exception:
                    resp.failure("order parse error")
                    return False
            elif resp.status_code == 401:
                if self._handle_401(resp, None):
                    # Retry once with same idempotency key
                    headers = {
                        "X-CSRF-Token": self.csrf or "",
                        "Idempotency-Key": self.idempotency_key,
                    }
                    if self.cart_etag:
                        headers["If-Match"] = self.cart_etag
                    with self.client.post(
                        "/v2/orders",
                        json=payload,
                        headers=headers,
                        catch_response=True,
                        allow_redirects=False,
                    ) as retry_resp:
                        if retry_resp.status_code == 201:
                            try:
                                data = retry_resp.json()
                                if data.get("accepted") is True:
                                    if data.get("csrf"):
                                        self.csrf = data["csrf"]
                                    return True
                                else:
                                    retry_resp.failure("order retry accepted=false")
                                    return False
                            except Exception:
                                retry_resp.failure("order retry parse error")
                                return False
                        else:
                            retry_resp.failure(f"order retry status {retry_resp.status_code}")
                            return False
                return False
            else:
                resp.failure(f"order status {resp.status_code}")
                return False

    def _do_work(self):
        """Perform a work/browse call with retry on scheduled 429."""
        for attempt in range(4):
            with self.client.post(
                "/v2/work",
                json={},
                catch_response=True,
                allow_redirects=False,
            ) as resp:
                if resp.status_code == 200:
                    try:
                        data = resp.json()
                        if data.get("ok") is True:
                            return True
                        else:
                            resp.failure("work ok=false")
                            return False
                    except Exception:
                        resp.failure("work parse error")
                        return False
                elif resp.status_code == 429:
                    retry_after = resp.headers.get("Retry-After")
                    if retry_after:
                        try:
                            time.sleep(float(retry_after))
                        except ValueError:
                            time.sleep(1)
                    else:
                        time.sleep(1)
                    continue
                elif resp.status_code == 401:
                    if self._handle_401(resp, None):
                        continue
                    return False
                else:
                    resp.failure(f"work status {resp.status_code}")
                    return False
        resp.failure("work retries exhausted")
        return False

    @task
    def journey(self):
        if self.iterations_done >= self.max_iterations:
            raise StopUser()
        self.iterations_done += 1

        # Fresh login and cart each journey
        self.csrf = None
        self.cart_id = None
        self.cart_etag = None
        self.grant_id = None
        self.reservation_id = None
        self.idempotency_key = None

        if not self._login():
            return

        # Optional challenge to get grant_id
        self._get_challenge()

        product = self._get_catalog_product()
        if not product:
            return

        variants = product.get("variants", [])
        if not variants:
            return
        variant = variants[0]
        product_id = product.get("id")
        variant_id = variant.get("id")
        if not product_id or not variant_id:
            return

        if not self._create_cart(product_id, variant_id):
            return

        if not self._patch_cart(1):
            return

        # Try reservation (may fail if not needed, but we attempt)
        self._create_reservation()

        if not self._place_order():
            return

        # Do some work
        self._do_work()


class ShopLoadShape(LoadTestShape):
    def tick(self):
        run_time = self.get_run_time()
        if run_time < 60:
            return (2, 2)
        return None
