import io.gatling.javaapi.core.*;
import io.gatling.javaapi.http.*;
import io.gatling.javaapi.core.CoreDsl.*;
import io.gatling.javaapi.http.HttpDsl.*;

import java.time.Duration;
import java.util.*;
import java.util.concurrent.ThreadLocalRandom;

public class ModelSimulation extends Simulation {

    private static final String BASE_URL = System.getenv().getOrDefault("BASE_URL", "http://127.0.0.1:8000");
    private static final int MAX_PAGES = 3;
    private static final int MAX_POLLS = 5;
    private static final int MAX_WORK_RETRIES = 4;

    private static final HttpProtocolBuilder httpProtocol = http
            .baseUrl(BASE_URL)
            .disableAutoRedirect()
            .acceptHeader("application/json")
            .contentTypeHeader("application/json")
            .userAgentHeader("gatling-bench");

    private static String randomIdempotencyKey() {
        return "idem-" + UUID.randomUUID().toString();
    }

    private static ChainBuilder login = exec(
            http("GET login-form")
                    .get("/v2/login-form")
                    .check(
                            regex("name=\"csrf\" value=\"([^\"]+)\"").find().saveAs("loginCsrf"),
                            regex("name=\"login_nonce\" value=\"([^\"]+)\"").find().saveAs("loginNonce")
                    )
    ).exec(
            http("POST login")
                    .post("/v2/login")
                    .header("X-CSRF-Token", session -> session.getString("loginCsrf"))
                    .body(StringBody(session -> {
                        String csrf = session.getString("loginCsrf");
                        String nonce = session.getString("loginNonce");
                        return String.format("{\"username\":\"%s\",\"password\":\"bench\",\"csrf\":\"%s\",\"login_nonce\":\"%s\"}",
                                session.getString("username"), csrf, nonce);
                    }))
                    .check(
                            status().is(200),
                            jsonPath("$.csrf").optional().saveAs("csrf"),
                            jsonPath("$.user").optional().saveAs("user")
                    )
    ).exec(session -> {
        if (session.contains("csrf")) {
            return session;
        }
        return session.set("csrf", session.getString("loginCsrf"));
    });

    private static ChainBuilder fetchCatalog = exec(
            http("GET catalog")
                    .get("/v2/catalog")
                    .check(
                            status().is(200),
                            jsonPath("$.data.products[*]").findAll().saveAs("products"),
                            jsonPath("$.next").optional().saveAs("nextCursor")
                    )
    ).exec(session -> {
        List<Map<String, Object>> products = session.getList("products");
        List<Map<String, Object>> eligible = new ArrayList<>();
        for (Map<String, Object> p : products) {
            List<Map<String, Object>> variants = (List<Map<String, Object>>) p.get("variants");
            if (variants != null) {
                for (Map<String, Object> v : variants) {
                    if (Boolean.TRUE.equals(v.get("in_stock"))) {
                        Map<String, Object> entry = new HashMap<>();
                        entry.put("product_id", p.get("id"));
                        entry.put("variant_id", v.get("id"));
                        eligible.add(entry);
                    }
                }
            }
        }
        if (!eligible.isEmpty()) {
            Map<String, Object> chosen = eligible.get(ThreadLocalRandom.current().nextInt(eligible.size()));
            return session.set("selectedProductId", chosen.get("product_id"))
                    .set("selectedVariantId", chosen.get("variant_id"))
                    .set("catalogDone", true);
        }
        return session.set("catalogDone", false);
    });

    private static ChainBuilder traversePages = asLongAs(session -> !session.getBoolean("catalogDone") && session.getInt("pageCount") < MAX_PAGES)
            .on(
                    exec(session -> session.set("pageCount", session.getInt("pageCount") + 1))
                            .exec(
                                    http("GET catalog page")
                                            .get(session -> "/v2/catalog/page" + (session.contains("nextCursor") && session.getString("nextCursor") != null ? session.getString("nextCursor") : ""))
                                            .check(
                                                    status().is(200),
                                                    jsonPath("$.data.products[*]").findAll().optional().saveAs("pageProducts"),
                                                    jsonPath("$.next").optional().saveAs("nextCursor")
                                            )
                            )
                            .exec(session -> {
                                List<Map<String, Object>> products = session.getList("pageProducts");
                                if (products != null) {
                                    for (Map<String, Object> p : products) {
                                        List<Map<String, Object>> variants = (List<Map<String, Object>>) p.get("variants");
                                        if (variants != null) {
                                            for (Map<String, Object> v : variants) {
                                                if (Boolean.TRUE.equals(v.get("in_stock"))) {
                                                    return session.set("selectedProductId", p.get("id"))
                                                            .set("selectedVariantId", v.get("id"))
                                                            .set("catalogDone", true);
                                                }
                                            }
                                        }
                                    }
                                }
                                return session;
                            })
            );

    private static ChainBuilder selectProduct = exec(fetchCatalog)
            .exec(session -> session.set("pageCount", 0))
            .exec(traversePages)
            .exec(session -> {
                if (!session.getBoolean("catalogDone")) {
                    throw new RuntimeException("No in-stock product found in catalog");
                }
                return session;
            });

    private static ChainBuilder createCart = exec(
            http("POST create cart")
                    .post("/v2/carts")
                    .header("X-CSRF-Token", session -> session.getString("csrf"))
                    .body(StringBody(session -> {
                        String productId = session.getString("selectedProductId");
                        String variantId = session.getString("selectedVariantId");
                        return String.format("{\"product_id\":\"%s\",\"variant_id\":\"%s\"}", productId, variantId);
                    }))
                    .check(
                            status().is(201),
                            jsonPath("$.id").saveAs("cartId"),
                            jsonPath("$.csrf").optional().saveAs("csrf"),
                            header("ETag").optional().saveAs("etag")
                    )
    ).exec(session -> {
        if (session.contains("csrf")) {
            return session;
        }
        return session;
    });

    private static ChainBuilder getCart = exec(
            http("GET cart")
                    .get(session -> "/v2/carts/" + session.getString("cartId"))
                    .check(
                            status().is(200),
                            header("ETag").optional().saveAs("etag")
                    )
    );

    private static ChainBuilder patchCart = exec(
            http("PATCH cart quantity")
                    .patch(session -> "/v2/carts/" + session.getString("cartId"))
                    .header("X-CSRF-Token", session -> session.getString("csrf"))
                    .header("If-Match", session -> session.getString("etag"))
                    .body(StringBody("{\"quantity\":1}"))
                    .check(
                            status().is(200),
                            jsonPath("$.csrf").optional().saveAs("csrf"),
                            header("ETag").optional().saveAs("etag")
                    )
    ).exec(session -> {
        if (session.contains("csrf")) {
            return session;
        }
        return session;
    });

    private static ChainBuilder patchCartWithRetry = exec(patchCart)
            .asLongAs(session -> session.contains("patchRetry") && session.getBoolean("patchRetry"))
            .on(
                    exec(session -> session.set("patchRetry", false))
                            .exec(getCart)
                            .exec(patchCart)
            );

    private static ChainBuilder createReservation = exec(
            http("POST reservation")
                    .post("/v2/reservations")
                    .header("X-CSRF-Token", session -> session.getString("csrf"))
                    .body(StringBody(session -> String.format("{\"cart_id\":\"%s\"}", session.getString("cartId"))))
                    .check(
                            status().is(202),
                            jsonPath("$.status_url").saveAs("statusUrl"),
                            jsonPath("$.csrf").optional().saveAs("csrf")
                    )
    ).exec(session -> {
        if (session.contains("csrf")) {
            return session;
        }
        return session;
    });

    private static ChainBuilder pollReservation = asLongAs(session -> session.getInt("pollCount") < MAX_POLLS && !session.getBoolean("reservationReady"))
            .on(
                    exec(session -> session.set("pollCount", session.getInt("pollCount") + 1))
                            .pause(Duration.ofMillis(60))
                            .exec(
                                    http("GET reservation status")
                                            .get(session -> session.getString("statusUrl"))
                                            .check(
                                                    status().is(200),
                                                    jsonPath("$.status").saveAs("reservationStatus"),
                                                    jsonPath("$.reservation_id").optional().saveAs("reservationId"),
                                                    jsonPath("$.csrf").optional().saveAs("csrf")
                                            )
                            )
                            .exec(session -> {
                                String status = session.getString("reservationStatus");
                                if ("ready".equals(status)) {
                                    return session.set("reservationReady", true);
                                } else if ("failed".equals(status)) {
                                    throw new RuntimeException("Reservation failed");
                                }
                                return session;
                            })
            );

    private static ChainBuilder createOrder = exec(
            http("POST order")
                    .post("/v2/orders")
                    .header("X-CSRF-Token", session -> session.getString("csrf"))
                    .header("Idempotency-Key", session -> session.getString("idempotencyKey"))
                    .body(StringBody(session -> {
                        String cartId = session.getString("cartId");
                        String reservationId = session.getString("reservationId");
                        if (reservationId != null && !reservationId.isEmpty()) {
                            return String.format("{\"cart_id\":\"%s\",\"reservation_id\":\"%s\"}", cartId, reservationId);
                        }
                        return String.format("{\"cart_id\":\"%s\"}", cartId);
                    }))
                    .check(
                            status().is(201),
                            jsonPath("$.accepted").is("true"),
                            jsonPath("$.id").saveAs("orderId"),
                            jsonPath("$.csrf").optional().saveAs("csrf")
                    )
    ).exec(session -> {
        if (session.contains("csrf")) {
            return session;
        }
        return session;
    });

    private static ChainBuilder work = exec(
            http("POST work")
                    .post("/v2/work")
                    .header("X-CSRF-Token", session -> session.getString("csrf"))
                    .body(StringBody("{}"))
                    .check(
                            status().is(200),
                            jsonPath("$.ok").is("true")
                    )
    );

    private static ChainBuilder workWithRetry = exec(work)
            .asLongAs(session -> session.contains("workRetry") && session.getBoolean("workRetry"))
            .on(
                    exec(session -> session.set("workRetry", false))
                            .pause(Duration.ofSeconds(1))
                            .exec(work)
            );

    private static ChainBuilder journey = exec(login)
            .exec(selectProduct)
            .exec(createCart)
            .exec(getCart)
            .exec(patchCartWithRetry)
            .exec(createReservation)
            .exec(session -> session.set("pollCount", 0).set("reservationReady", false))
            .exec(pollReservation)
            .exec(session -> {
                if (!session.getBoolean("reservationReady")) {
                    throw new RuntimeException("Reservation not ready after polling");
                }
                return session;
            })
            .exec(session -> session.set("idempotencyKey", randomIdempotencyKey()))
            .exec(createOrder)
            .exec(workWithRetry);

    private static final ScenarioBuilder defaultScenario = scenario("default-profile")
            .exec(journey);

    private static final ScenarioBuilder htmlLayoutScenario = scenario("html-layout-profile")
            .exec(journey);

    {
        setUp(
                defaultScenario.injectOpen(atOnceUsers(1)).protocols(httpProtocol),
                htmlLayoutScenario.injectOpen(atOnceUsers(1)).protocols(httpProtocol)
        );
    }
}
