import http from 'k6/http';
import { check, sleep, group } from 'k6';
import { Rate, Trend } from 'k6/metrics';
import { URL } from 'https://jslib.k6.io/url/1.0.0/index.js';

const BASE_URL = __ENV.BASE_URL || 'http://127.0.0.1:8000';

const businessFailureRate = new Rate('business_failure');
const checkoutLatency = new Trend('checkout_latency', true);

const PROFILES = [
  {},
  { html_layout: 1, reverse_catalog: true }
];

function getProfile(vuId) {
  return PROFILES[(vuId - 1) % PROFILES.length];
}

function login(username, password) {
  const formRes = http.get(`${BASE_URL}/v2/login-form`, {
    redirects: 0,
    tags: { name: 'login_form' }
  });

  check(formRes, {
    'login form status 200': (r) => r.status === 200,
  });

  const csrfMatch = formRes.body.match(/name="csrf"[^>]*value="([^"]+)"/);
  if (!csrfMatch) {
    throw new Error('CSRF token not found in login form');
  }
  const csrf = csrfMatch[1];

  const loginRes = http.post(`${BASE_URL}/v2/login`, JSON.stringify({
    username: username,
    password: password,
    csrf: csrf
  }), {
    headers: { 'Content-Type': 'application/json' },
    redirects: 0,
    tags: { name: 'login' }
  });

  if (loginRes.status === 302) {
    const location = loginRes.headers['Location'];
    if (location) {
      const followRes = http.get(new URL(location, BASE_URL).toString(), {
        redirects: 0,
        tags: { name: 'login_redirect' }
      });
      check(followRes, {
        'login redirect status 200': (r) => r.status === 200,
      });
    }
  } else {
    check(loginRes, {
      'login status 200': (r) => r.status === 200,
    });
  }

  let loginData = null;
  try {
    loginData = loginRes.json();
  } catch (e) {
    // try to parse from redirect response
    try {
      const followRes = http.get(new URL(loginRes.headers['Location'], BASE_URL).toString(), {
        redirects: 0,
        tags: { name: 'login_redirect_parse' }
      });
      loginData = followRes.json();
    } catch (e2) {
      throw new Error('Failed to parse login response');
    }
  }

  return {
    csrf: loginData.csrf,
    user: loginData.user
  };
}

function renewSession(currentCsrf) {
  const renewRes = http.post(`${BASE_URL}/v2/session/renew`, JSON.stringify({}), {
    headers: {
      'Content-Type': 'application/json',
      'X-CSRF-Token': currentCsrf
    },
    tags: { name: 'session_renew' }
  });

  if (renewRes.status === 200) {
    const data = renewRes.json();
    return { csrf: data.csrf || currentCsrf, renewed: true };
  }
  return { csrf: currentCsrf, renewed: false };
}

function recoverCart(cartId, csrf) {
  const recoverRes = http.post(`${BASE_URL}/v2/carts/${cartId}/recover`, JSON.stringify({}), {
    headers: {
      'Content-Type': 'application/json',
      'X-CSRF-Token': csrf
    },
    tags: { name: 'cart_recover' }
  });
  return recoverRes.status === 200;
}

function getCatalog(profile) {
  const products = [];

  if (profile.reverse_catalog) {
    // Traverse pages in reverse order (up to 3 pages)
    const pageUrls = [];
    let nextUrl = '/v2/catalog/page';
    let pageCount = 0;

    while (nextUrl && pageCount < 3) {
      const pageRes = http.get(`${BASE_URL}${nextUrl}`, {
        tags: { name: 'catalog_page' }
      });

      if (pageRes.status !== 200) break;

      const pageData = pageRes.json();
      if (pageData.data && pageData.data.products) {
        products.push(...pageData.data.products);
      }

      nextUrl = pageData.next;
      pageCount++;
    }

    // Reverse the products array
    products.reverse();
  } else {
    // Get main catalog
    const catalogRes = http.get(`${BASE_URL}/v2/catalog`, {
      tags: { name: 'catalog' }
    });

    if (catalogRes.status === 200) {
      const catalogData = catalogRes.json();
      if (catalogData.data && catalogData.data.products) {
        products.push(...catalogData.data.products);
      }
    }
  }

  return products;
}

function selectEligibleParent(products) {
  // Find a product with at least one in-stock variant
  for (const product of products) {
    if (product.variants && product.variants.some(v => v.in_stock)) {
      return product;
    }
  }
  return null;
}

function createCart(productId, variantId, grantId, csrf) {
  const payload = {
    product_id: productId,
    variant_id: variantId
  };

  if (grantId) {
    payload.grant_id = grantId;
  }

  const cartRes = http.post(`${BASE_URL}/v2/carts`, JSON.stringify(payload), {
    headers: {
      'Content-Type': 'application/json',
      'X-CSRF-Token': csrf
    },
    tags: { name: 'create_cart' }
  });

  if (cartRes.status === 201) {
    const data = cartRes.json();
    return {
      cartId: data.id,
      csrf: data.csrf || csrf,
      etag: cartRes.headers['ETag']
    };
  }

  return null;
}

function getCart(cartId, csrf) {
  const cartRes = http.get(`${BASE_URL}/v2/carts/${cartId}`, {
    headers: {
      'X-CSRF-Token': csrf
    },
    tags: { name: 'get_cart' }
  });

  if (cartRes.status === 200) {
    return {
      etag: cartRes.headers['ETag'],
      data: cartRes.json()
    };
  }

  return null;
}

function updateCartQuantity(cartId, quantity, etag, csrf) {
  const updateRes = http.patch(`${BASE_URL}/v2/carts/${cartId}`, JSON.stringify({
    quantity: quantity
  }), {
    headers: {
      'Content-Type': 'application/json',
      'X-CSRF-Token': csrf,
      'If-Match': etag
    },
    tags: { name: 'update_cart' }
  });

  if (updateRes.status === 412) {
    // Re-read and retry once
    const cartData = getCart(cartId, csrf);
    if (cartData) {
      const retryRes = http.patch(`${BASE_URL}/v2/carts/${cartId}`, JSON.stringify({
        quantity: quantity
      }), {
        headers: {
          'Content-Type': 'application/json',
          'X-CSRF-Token': csrf,
          'If-Match': cartData.etag
        },
        tags: { name: 'update_cart_retry' }
      });

      if (retryRes.status === 200) {
        const data = retryRes.json();
        return {
          csrf: data.csrf || csrf,
          etag: retryRes.headers['ETag']
        };
      }
    }
    return null;
  }

  if (updateRes.status === 200) {
    const data = updateRes.json();
    return {
      csrf: data.csrf || csrf,
      etag: updateRes.headers['ETag']
    };
  }

  return null;
}

function solveChallenge(csrf) {
  const challengeFormRes = http.get(`${BASE_URL}/v2/challenge-form`, {
    tags: { name: 'challenge_form' }
  });

  if (challengeFormRes.status !== 200) return null;

  const actionMatch = challengeFormRes.body.match(/action="([^"]+)"/);
  const challengeMatch = challengeFormRes.body.match(/name="challenge"[^>]*value="([^"]+)"/);

  if (!actionMatch || !challengeMatch) return null;

  const actionUrl = actionMatch[1];
  const challengeValue = challengeMatch[1];

  const challengeRes = http.post(new URL(actionUrl, BASE_URL).toString(), JSON.stringify({
    challenge: challengeValue
  }), {
    headers: {
      'Content-Type': 'application/json',
      'X-CSRF-Token': csrf
    },
    redirects: 0,
    tags: { name: 'challenge_submit' }
  });

  if (challengeRes.status === 302) {
    const location = challengeRes.headers['Location'];
    if (location) {
      const grantRes = http.get(new URL(location, BASE_URL).toString(), {
        tags: { name: 'challenge_grant' }
      });

      if (grantRes.status === 200) {
        const data = grantRes.json();
        return {
          grantId: data.grant_id,
          csrf: data.csrf || csrf
        };
      }
    }
  }

  return null;
}

function createReservation(cartId, csrf) {
  const resvRes = http.post(`${BASE_URL}/v2/reservations`, JSON.stringify({
    cart_id: cartId
  }), {
    headers: {
      'Content-Type': 'application/json',
      'X-CSRF-Token': csrf
    },
    tags: { name: 'create_reservation' }
  });

  if (resvRes.status !== 202) return null;

  const data = resvRes.json();
  const statusUrl = data.status_url;
  let currentCsrf = data.csrf || csrf;

  // Poll at least 50ms apart, at most 5 times
  for (let i = 0; i < 5; i++) {
    sleep(0.06);

    const pollRes = http.get(new URL(statusUrl, BASE_URL).toString(), {
      headers: {
        'X-CSRF-Token': currentCsrf
      },
      tags: { name: 'poll_reservation' }
    });

    if (pollRes.status === 200) {
      const pollData = pollRes.json();
      currentCsrf = pollData.csrf || currentCsrf;

      if (pollData.status === 'ready') {
        return {
          reservationId: pollData.reservation_id,
          csrf: currentCsrf
        };
      } else if (pollData.status === 'failed') {
        return null;
      }
      // pending - continue polling
    }
  }

  return null;
}

function createOrder(cartId, reservationId, idempotencyKey, etag, csrf) {
  const payload = {
    cart_id: cartId
  };

  if (reservationId) {
    payload.reservation_id = reservationId;
  }

  const orderRes = http.post(`${BASE_URL}/v2/orders`, JSON.stringify(payload), {
    headers: {
      'Content-Type': 'application/json',
      'X-CSRF-Token': csrf,
      'Idempotency-Key': idempotencyKey,
      'If-Match': etag
    },
    tags: { name: 'create_order' }
  });

  if (orderRes.status === 201) {
    const data = orderRes.json();
    if (data.accepted === true) {
      return {
        orderId: data.id,
        csrf: data.csrf || csrf,
        success: true
      };
    }
    return { success: false, csrf: data.csrf || csrf };
  }

  return { success: false, csrf: csrf };
}

function doWork(csrf) {
  let attempts = 0;
  while (attempts < 4) {
    const workRes = http.post(`${BASE_URL}/v2/work`, JSON.stringify({}), {
      headers: {
        'Content-Type': 'application/json',
        'X-CSRF-Token': csrf
      },
      tags: { name: 'work' }
    });

    if (workRes.status === 200) {
      const data = workRes.json();
      if (data.ok === true) {
        return { csrf: data.csrf || csrf, success: true };
      }
      return { csrf: data.csrf || csrf, success: false };
    } else if (workRes.status === 429) {
      sleep(1);
      attempts++;
    } else {
      return { csrf: csrf, success: false };
    }
  }
  return { csrf: csrf, success: false };
}

