            # No eligible parent found - fail setup
            self.client.get(
                "/v2/catalog",
                name="/v2/catalog-setup-fail",
                catch_response=True,
            ).failure("no eligible parent found")
            return

        product_id = parent["id"]
        variant_id = variant["id"]

        # Create cart with selected variant
        if not self.create_cart(product_id, variant_id):
            return

        # Get cart to establish ETag
        if not self.get_cart():
            return

        # Patch quantity
        if not self.patch_cart_quantity(2):
            return

        # Create reservation
        if not self.create_reservation():
            return

        # Place order
        if not self.place_order():
            return

        # Do work
        self.do_work()


