import http from 'k6/http';
import { check, sleep, fail } from 'k6';
import { Rate, Counter } from 'k6/metrics';
import crypto from 'k6/crypto';

const BASE_URL = __ENV.BASE_URL || 'http://127.0.0.1:8000';

const businessFailure = new Rate('business_failure');
const workResponses = new Counter('work_responses');

const PROFILES = [
  { require_etag: true, dynamic_etag: true, etag_conflict_once: true },
  { require_etag: true, dynamic_etag: true, etag_conflict_once: true, html_layout: 1, reverse_catalog: true }
];

const USERS = 2;
const ITERATIONS = 2;
const QUANTITY = 2;

export const options = {
  scenarios: {
    main: {
      executor: 'per-vu-iterations',
      vus: USERS,
      iterations: ITERATIONS,
      maxDuration: '5m',
    },
  },
  thresholds: {},
};

function getProfile(vuId) {
  return PROFILES[(vuId - 1) % PROFILES.length];
}

function extractCsrf(html) {
  const patterns = [
    /name=["']csrf["'][^>]*value=["']([^"']+)["']/i,
    /value=["']([^"']+)["'][^>]*name=["']csrf["']/i,
    /name=["']csrf["']\s+value=["']([^"']+)["']/i,
    /value=["']([^"']+)["']\s+name=["']csrf["']/i,
    /name=csrf\s+value=([^\s>]+)/i,
    /value=([^\s>]+)\s+name=csrf/i,
    /name=["']csrf["'][^>]*value=([^\s>]+)/i,
    /value=([^\s>]+)[^>]*name=["']csrf["']/i,
    /name=["']csrf["']\s+value=["']([^"']+)["']/i,
    /value=["']([^"']+)["']\s+name=["']csrf["']/i,
  ];
  for (const p of patterns) {
    const m = html.match(p);
    if (m && m[1]) return m[1];
  }
  return null;
}

function extractFormAction(html) {
  const m = html.match(/<form[^>]*action=["']([^"']+)["']/i);
  return m ? m[1] : null;
}

function extractChallengeInput(html) {
  const m = html.match(/<input[^>]*name=["']challenge["'][^>]*>/i);
  return m ? m[0] : null;
}

function extractChallengeValue(inputTag) {
  if (!inputTag) return null;
  const m = inputTag.match(/value=["']([^"']+)["']/i);
  if (m) return m[1];
  const m2 = inputTag.match(/value=([^\s>]+)/i);
  return m2 ? m2[1] : null;
}

function extractLocation(response) {
  const loc = response.headers['Location'];
  if (loc) return loc;
  return null;
}

function getSessionCookie(jar) {
  const cookies = jar.cookiesForURL(BASE_URL);
  for (const key in cookies) {
    if (key.toLowerCase() === 'session' || key.toLowerCase().includes('session')) {
      return cookies[key];
    }
  }
  return null;
}

function login(jar, username, password) {
  let res = http.get(`${BASE_URL}/v2/login-form`, { redirects: 0, jar });
  if (res.status === 302) {
    const loc = extractLocation(res);
    if (loc) {
      res = http.get(loc.startsWith('http') ? loc : `${BASE_URL}${loc}`, { redirects: 0, jar });
    }
  }
  check(res, { 'login form loads': (r) => r.status === 200 });
  const csrf = extractCsrf(res.body);
  if (!csrf) {
    fail(`No CSRF found in login form. Body: ${res.body.substring(0, 500)}`);
  }
  const loginRes = http.post(`${BASE_URL}/v2/login`, JSON.stringify({ username, password, csrf }), {
    headers: { 'Content-Type': 'application/json' },
    redirects: 0,
    jar,
  });
  if (loginRes.status === 302) {
    const loc = extractLocation(loginRes);
    if (loc) {
      const followRes = http.get(loc.startsWith('http') ? loc : `${BASE_URL}${loc}`, { redirects: 0, jar });
      check(followRes, { 'login follow 200': (r) => r.status === 200 });
      const followCsrf = extractCsrf(followRes.body);
      if (followCsrf) return followCsrf;
    }
  }
  check(loginRes, { 'login succeeds': (r) => r.status === 200 || r.status === 201 || r.status === 302 });
  let loginBody = null;
  try { loginBody = JSON.parse(loginRes.body); } catch (e) { /* ignore */ }
  if (loginBody && loginBody.csrf) return loginBody.csrf;
  const bodyCsrf = extractCsrf(loginRes.body);
  if (bodyCsrf) return bodyCsrf;
  return csrf;
}

function getCatalog(jar, csrf, profile) {
  let products = [];
  let res = http.get(`${BASE_URL}/v2/catalog`, { jar });
  check(res, { 'catalog loads': (r) => r.status === 200 });
  let body = null;
  try { body = JSON.parse(res.body); } catch (e) { fail('Catalog not JSON'); }
  if (body && body.data && body.data.products) {
    products = products.concat(body.data.products);
  }
  let next = body && body.next ? body.next : null;
  let pages = 0;
  while (next && pages < 3) {
    const url = next.startsWith('http') ? next : `${BASE_URL}${next}`;
    res = http.get(url, { jar });
    check(res, { 'catalog page loads': (r) => r.status === 200 });
    try { body = JSON.parse(res.body); } catch (e) { fail('Catalog page not JSON'); }
    if (body && body.data && body.data.products) {
      products = products.concat(body.data.products);
    }
    next = body && body.next ? body.next : null;
    pages++;
  }
  if (profile.reverse_catalog) {
    products = products.slice().reverse();
  }
  return products;
}

function getChallenge(jar, csrf) {
  let res = http.get(`${BASE_URL}/v2/challenge-form`, { jar });
  check(res, { 'challenge form loads': (r) => r.status === 200 });
  const action = extractFormAction(res.body);
  if (!action) {
    fail('No challenge form action found');
  }
  const inputTag = extractChallengeInput(res.body);
  const challengeValue = extractChallengeValue(inputTag);
  if (!challengeValue) {
    fail('No challenge value found');
  }
  const actionUrl = action.startsWith('http') ? action : `${BASE_URL}${action}`;
  res = http.post(actionUrl, JSON.stringify({ challenge: challengeValue }), {
    headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': csrf },
    redirects: 0,
    jar,
  });
  check(res, { 'challenge post 302': (r) => r.status === 302 });
  const loc = extractLocation(res);
  if (!loc) {
    fail('No Location after challenge');
  }
  const locUrl = loc.startsWith('http') ? loc : `${BASE_URL}${loc}`;
  res = http.get(locUrl, { jar });
  check(res, { 'challenge grant 200': (r) => r.status === 200 });
  let body = null;
  try { body = JSON.parse(res.body); } catch (e) { fail('Challenge grant not JSON'); }
  return body;
}

function createCart(jar, csrf, productId, variantId, grantId) {
  const payload = { product_id: productId, variant_id: variantId };
  if (grantId) payload.grant_id = grantId;
  const res = http.post(`${BASE_URL}/v2/carts`, JSON.stringify(payload), {
    headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': csrf },
    jar,
  });
  check(res, { 'cart created 201': (r) => r.status === 201 });
  let body = null;
  try { body = JSON.parse(res.body); } catch (e) { fail('Cart create not JSON'); }
  return body;
}

function getCart(jar, cartId) {
  const res = http.get(`${BASE_URL}/v2/carts/${cartId}`, { jar });
  check(res, { 'cart get 200': (r) => r.status === 200 });
  return res;
}

function patchCart(jar, csrf, cartId, quantity, etag) {
  const headers = { 'Content-Type': 'application/json', 'X-CSRF-Token': csrf };
  if (etag) headers['If-Match'] = etag;
  const res = http.patch(`${BASE_URL}/v2/carts/${cartId}`, JSON.stringify({ quantity }), {
    headers,
    jar,
  });
  return res;
}

function createReservation(jar, csrf, cartId) {
  const res = http.post(`${BASE_URL}/v2/reservations`, JSON.stringify({ cart_id: cartId }), {
    headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': csrf },
    jar,
  });
  check(res, { 'reservation 202': (r) => r.status === 202 });
  let body = null;
  try { body = JSON.parse(res.body); } catch (e) { fail('Reservation not JSON'); }
  return body;
}

function pollReservation(jar, csrf, statusUrl) {
  const url = statusUrl.startsWith('http') ? statusUrl : `${BASE_URL}${statusUrl}`;
  for (let i = 0; i < 5; i++) {
    sleep(0.06);
    const res = http.get(url, { jar });
    check(res, { 'reservation poll 200': (r) => r.status === 200 });
    let body = null;
    try { body = JSON.parse(res.body); } catch (e) { continue; }
    if (body.status === 'ready') {
      return body;
    }
    if (body.status === 'failed') {
      return body;
    }
  }
  return { status: 'pending' };
}

function createOrder(jar, csrf, cartId, reservationId, idempotencyKey, etag) {
  const payload = { cart_id: cartId };
  if (reservationId) payload.reservation_id = reservationId;
  const headers = {
    'Content-Type': 'application/json',
    'X-CSRF-Token': csrf,
    'Idempotency-Key': idempotencyKey,
  };
  if (etag) headers['If-Match'] = etag;
  const res = http.post(`${BASE_URL}/v2/orders`, JSON.stringify(payload), {
    headers,
    jar,
  });
  return res;
}

function renewSession(jar, csrf) {
  const res = http.post(`${BASE_URL}/v2/session/renew`, JSON.stringify({}), {
    headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': csrf },
    jar,
  });
  check(res, { 'renew 200': (r) => r.status === 200 });
  let body = null;
  try { body = JSON.parse(res.body); } catch (e) { return csrf; }
  return body.csrf || csrf;
}

function recoverCart(jar, csrf, cartId) {
  const res = http.post(`${BASE_URL}/v2/carts/${cartId}/recover`, JSON.stringify({}), {
    headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': csrf },
    jar,
  });
  check(res, { 'recover 200': (r) => r.status === 200 });
  return res;
}

function doWork(jar, csrf) {
  let res = http.post(`${BASE_URL}/v2/work`, JSON.stringify({}), {
    headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': csrf },
    jar,
  });
  workResponses.add(1);
  let retries = 0;
  while (res.status === 429 && retries < 4) {
    const retryAfter = res.headers['Retry-After'];
    const wait = retryAfter ? parseFloat(retryAfter) : 1;
    sleep(wait);
    res = http.post(`${BASE_URL}/v2/work`, JSON.stringify({}), {
      headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': csrf },
      jar,
    });
    workResponses.add(1);
    retries++;
  }
  if (res.status !== 200) {
    businessFailure.add(1);
    return false;
  }
  return true;
}

function handle401(res, jar, csrf, cartId, operation) {
  let body = null;
  try { body = JSON.parse(res.body); } catch (e) { /* ignore */ }
  const error = body && body.error ? body.error : '';
  if (error === 'expired') {
    const newCsrf = renewSession(jar, csrf);
    if (cartId) {
      recoverCart(jar, newCsrf, cartId);
    }
    return { csrf: newCsrf, recovered: true };
  } else if (error === 'session') {
    const newCsrf = login(jar, 'bench', 'bench');
    if (cartId) {
      recoverCart(jar, newCsrf, cartId);
    }
    return { csrf: newCsrf, recovered: true };
  } else if (error === 'denied') {
    fail('401 denied is not expiry');
  }
  return { csrf, recovered: false };
}

export default function () {
  const vuId = __VU;
  const profile = getProfile(vuId);
  const username = `bench-${((vuId - 1) % 16) + 1}`;
  const jar = http.cookieJar();
  jar.clear(BASE_URL);

  let csrf = login(jar, username, 'bench');

  const products = getCatalog(jar, csrf, profile);
  if (!products || products.length === 0) {
    fail('No products in catalog');
  }

  let selectedProduct = null;
  let selectedVariant = null;
  for (const product of products) {
    if (product.variants && product.variants.length > 0) {
      for (const variant of product.variants) {
        if (variant.in_stock) {
          selectedProduct = product;
          selectedVariant = variant;
          break;
        }
      }
      if (selectedProduct) break;
    }
  }
  if (!selectedProduct) {
    fail('No in-stock product found');
  }

  let grantId = null;
  const challengeGrant = getChallenge(jar, csrf);
  if (challengeGrant && challengeGrant.grant_id) {
    grantId = challengeGrant.grant_id;
    if (challengeGrant.csrf) csrf = challengeGrant.csrf;
  }

  const cartBody = createCart(jar, csrf, selectedProduct.id, selectedVariant.id, grantId);
  const cartId = cartBody.id;
  if (cartBody.csrf) csrf = cartBody.csrf;
  let etag = cartBody.ETag || cartBody.etag || null;

  if (!etag) {
    const cartGetRes = getCart(jar, cartId);
    etag = cartGetRes.headers['ETag'] || cartGetRes.headers['Etag'] || cartGetRes.headers['etag'] || null;
    if (cartGetRes.body) {
      try {
        const cartGetBody = JSON.parse(cartGetRes.body);
        if (cartGetBody.csrf) csrf = cartGetBody.csrf;
        if (cartGetBody.ETag) etag = cartGetBody.ETag;
        if (cartGetBody.etag) etag = cartGetBody.etag;
      } catch (e) { /* ignore */ }
    }
  }

  check(etag, { 'initial ETag extracted': (e) => e !== null && e !== undefined && e !== '' });

  let patchRes = patchCart(jar, csrf, cartId, QUANTITY, etag);
  let patchRetried = false;

  if (patchRes.status === 401) {
    const handled = handle401(patchRes, jar, csrf, cartId, 'patch');
    csrf = handled.csrf;
    patchRes = patchCart(jar, csrf, cartId, QUANTITY, etag);
  }

  if (patchRes.status === 412) {
    const cartGetRes = getCart(jar, cartId);
    etag = cartGetRes.headers['ETag'] || cartGetRes.headers['Etag'] || cartGetRes.headers['etag'] || null;
    if (cartGetRes.body) {
      try {
        const cartGetBody = JSON.parse(cartGetRes.body);
        if (cartGetBody.csrf) csrf = cartGetBody.csrf;
        if (cartGetBody.ETag) etag = cartGetBody.ETag;
        if (cartGetBody.etag) etag = cartGetBody.etag;
      } catch (e) { /* ignore */ }
    }
    patchRes = patchCart(jar, csrf, cartId, QUANTITY, etag);
    patchRetried = true;
    if (patchRes.status === 401) {
      const handled = handle401(patchRes, jar, csrf, cartId, 'patch');
      csrf = handled.csrf;
      patchRes = patchCart(jar, csrf, cartId, QUANTITY, etag);
    }
  }

  check(patchRes, { 'patch succeeds': (r) => r.status === 200 || r.status === 201 });
  if (patchRes.body) {
    try {
      const patchBody = JSON.parse(patchRes.body);
      if (patchBody.csrf) csrf = patchBody.csrf;
      if (patchBody.ETag) etag = patchBody.ETag;
      if (patchBody.etag) etag = patchBody.etag;
    } catch (e) { /* ignore */ }
  }

  const reservationBody = createReservation(jar, csrf, cartId);
  if (reservationBody.csrf) csrf = reservationBody.csrf;
  let reservationId = null;
  if (reservationBody.status_url) {
    const pollResult = pollReservation(jar, csrf, reservationBody.status_url);
    if (pollResult.status === 'ready' && pollResult.reservation_id) {
      reservationId = pollResult.reservation_id;
      if (pollResult.csrf) csrf = pollResult.csrf;
    } else if (pollResult.status === 'failed') {
      fail('Reservation failed');
    } else {
      fail('Reservation never ready');
    }
  }

  const idempotencyKey = `order-${cartId}-${Date.now()}-${vuId}`;
  let orderRes = createOrder(jar, csrf, cartId, reservationId, idempotencyKey, etag);
  let orderRetried = false;

  if (orderRes.status === 401) {
    const handled = handle401(orderRes, jar, csrf, cartId, 'order');
    csrf = handled.csrf;
    orderRes = createOrder(jar, csrf, cartId, reservationId, idempotencyKey, etag);
  }

  if (orderRes.status === 412) {
    const cartGetRes = getCart(jar, cartId);
    etag = cartGetRes.headers['ETag'] || cartGetRes.headers['Etag'] || cartGetRes.headers['etag'] || null;
    if (cartGetRes.body) {
      try {
        const cartGetBody = JSON.parse(cartGetRes.body);
        if (cartGetBody.csrf) csrf = cartGetBody.csrf;
        if (cartGetBody.ETag) etag = cartGetBody.ETag;
        if (cartGetBody.etag) etag = cartGetBody.etag;
      } catch (e) { /* ignore */ }
    }
    orderRes = createOrder(jar, csrf, cartId, reservationId, idempotencyKey, etag);
    orderRetried = true;
    if (orderRes.status === 401) {
      const handled = handle401(orderRes, jar, csrf, cartId, 'order');
      csrf = handled.csrf;
      orderRes = createOrder(jar, csrf, cartId, reservationId, idempotencyKey, etag);
    }
  }

  check(orderRes, { 'order accepted': (r) => r.status === 201 });
  if (orderRes.status === 200) {
    let orderBody = null;
    try { orderBody = JSON.parse(orderRes.body); } catch (e) { /* ignore */ }
    if (orderBody && orderBody.accepted === false) {
      fail('Order business failure: accepted=false');
    }
  }
  if (orderRes.body) {
    try {
      const orderBody = JSON.parse(orderRes.body);
      if (orderBody.csrf) csrf = orderBody.csrf;
    } catch (e) { /* ignore */ }
  }

  doWork(jar, csrf);

  sleep(0.1);
}
