from locust import HttpUser, LoadTestShape, between, task
from locust.exception import StopUser


BASE = os.environ.get("BASE_URL", "http://127.0.0.1:8000")


def rel_url(base, rel):
    if rel is None:
        return None
    return urljoin(base, rel)


class ShopUser(HttpUser):
    wait_time = between(0.05, 0.2)

    def on_start(self):
        self.iterations_left = 2
        self.csrf = None
        self.session_user = None
        self.cart_id = None
        self.cart_etag = None
        self.grant_id = None
        self.order_key = None
        self.login()

    def login(self):
        with self.client.get(
            "/v2/login-form",
            catch_response=True,
            allow_redirects=False,
        ) as r:
            if r.status_code != 200:
                r.failure(f"login-form status {r.status_code}")
                return
            import re
            m = re.search(r'name=["\']csrf["\'][^>]*value=["\']([^"\']+)', r.text)
            if not m:
                m = re.search(r'value=["\']([^"\']+)["\'][^>]*name=["\']csrf', r.text)
            if not m:
                r.failure("no csrf in login form")
                return
            self.csrf = m.group(1)

        with self.client.post(
            "/v2/login",
            json={"username": "bench", "password": "bench", "csrf": self.csrf},
            catch_response=True,
            allow_redirects=False,
        ) as r:
            if r.status_code in (200, 302):
                if r.status_code == 302:
                    loc = r.headers.get("Location")
                    if not loc:
                        r.failure("302 without Location")
                        return
                    with self.client.get(
                        rel_url(BASE, loc),
                        catch_response=True,
                        allow_redirects=False,
                    ) as r2:
                        if r2.status_code != 200:
                            r2.failure(f"login redirect status {r2.status_code}")
                            return
                        r = r2
                try:
                    data = r.json()
                except Exception:
                    r.failure("login response not json")
                    return
                self.csrf = data.get("csrf", self.csrf)
                self.session_user = data.get("user")
            else:
                r.failure(f"login status {r.status_code}")

    def renew_session(self):
        with self.client.post(
            "/v2/session/renew",
            json={},
            headers={"X-CSRF-Token": self.csrf},
            catch_response=True,
            allow_redirects=False,
        ) as r:
            if r.status_code == 200:
                try:
                    data = r.json()
                except Exception:
                    r.failure("renew not json")
                    return False
                self.csrf = data.get("csrf", self.csrf)
                return True
            r.failure(f"renew status {r.status_code}")
            return False

    def recover_cart(self):
        if not self.cart_id:
            return False
        with self.client.post(
            f"/v2/carts/{self.cart_id}/recover",
            json={},
            headers={"X-CSRF-Token": self.csrf},
            catch_response=True,
            allow_redirects=False,
        ) as r:
            if r.status_code == 200:
                try:
                    data = r.json()
                except Exception:
                    r.failure("recover not json")
                    return False
                self.csrf = data.get("csrf", self.csrf)
                return True
            r.failure(f"recover status {r.status_code}")
            return False

    def handle_401(self, r, op_label):
        try:
            err = r.json().get("error", "")
        except Exception:
            err = ""
        if err == "expired":
            if self.renew_session():
                if self.cart_id:
                    self.recover_cart()
                return "retry"
            return "fail"
        if err == "session":
            self.login()
            if self.cart_id:
                self.recover_cart()
            return "retry"
        if err == "denied":
            r.failure(f"{op_label} denied")
            return "fail"
        r.failure(f"{op_label} unexpected 401 {err}")
        return "fail"

    def get_catalog_product(self):
        with self.client.get(
            "/v2/catalog/page",
            catch_response=True,
            allow_redirects=False,
        ) as r:
            if r.status_code != 200:
                r.failure(f"catalog page status {r.status_code}")
                return None
            try:
                data = r.json()
            except Exception:
                r.failure("catalog page not json")
                return None
            products = data.get("data", {}).get("products", [])
            if not products:
                r.failure("catalog page empty")
                return None
            product = products[0]
            variants = product.get("variants", [])
            if not variants:
                r.failure("no variants")
                return None
            variant = variants[0]
            return {
                "product_id": product.get("id"),
                "variant_id": variant.get("id"),
                "in_stock": variant.get("in_stock", False),
            }

    def create_cart(self, product_id, variant_id):
        payload = {"product_id": product_id, "variant_id": variant_id}
        if self.grant_id:
            payload["grant_id"] = self.grant_id
        with self.client.post(
            "/v2/carts",
            json=payload,
            headers={"X-CSRF-Token": self.csrf},
            catch_response=True,
            allow_redirects=False,
        ) as r:
            if r.status_code == 401:
                action = self.handle_401(r, "cart create")
                if action == "retry":
                    return self.create_cart(product_id, variant_id)
                return False
            if r.status_code != 201:
                r.failure(f"cart create status {r.status_code}")
                return False
            try:
                data = r.json()
            except Exception:
                r.failure("cart create not json")
                return False
            self.cart_id = data.get("id")
            self.csrf = data.get("csrf", self.csrf)
            self.cart_etag = r.headers.get("ETag")
            self.order_key = f"order-{self.cart_id}-{int(time.time()*1000)}"
            return True

    def get_cart(self):
        with self.client.get(
            f"/v2/carts/{self.cart_id}",
            catch_response=True,
            allow_redirects=False,
        ) as r:
            if r.status_code == 401:
                action = self.handle_401(r, "cart get")
                if action == "retry":
                    return self.get_cart()
                return False
            if r.status_code != 200:
                r.failure(f"cart get status {r.status_code}")
                return False
            self.cart_etag = r.headers.get("ETag")
            return True

    def patch_cart(self, quantity):
        payload = {"quantity": quantity}
        headers = {
            "X-CSRF-Token": self.csrf,
            "If-Match": self.cart_etag or "",
        }
        with self.client.patch(
            f"/v2/carts/{self.cart_id}",
            json=payload,
            headers=headers,
            catch_response=True,
            allow_redirects=False,
        ) as r:
            if r.status_code == 401:
                action = self.handle_401(r, "cart patch")
                if action == "retry":
                    return self.patch_cart(quantity)
                return False
            if r.status_code == 412:
                # Re-read and retry once with same payload
                if not self.get_cart():
                    return False
                headers = {
                    "X-CSRF-Token": self.csrf,
                    "If-Match": self.cart_etag or "",
                }
                with self.client.patch(
                    f"/v2/carts/{self.cart_id}",
                    json=payload,
                    headers=headers,
                    catch_response=True,
                    allow_redirects=False,
                ) as r2:
                    if r2.status_code == 401:
                        action = self.handle_401(r2, "cart patch retry")
                        if action == "retry":
                            return self.patch_cart(quantity)
                        return False
                    if r2.status_code != 200:
                        r2.failure(f"cart patch retry status {r2.status_code}")
                        return False
                    try:
                        data = r2.json()
                    except Exception:
                        r2.failure("cart patch retry not json")
                        return False
                    self.csrf = data.get("csrf", self.csrf)
                    self.cart_etag = r2.headers.get("ETag", self.cart_etag)
                    return True
            if r.status_code != 200:
                r.failure(f"cart patch status {r.status_code}")
                return False
            try:
                data = r.json()
            except Exception:
                r.failure("cart patch not json")
                return False
            self.csrf = data.get("csrf", self.csrf)
            self.cart_etag = r.headers.get("ETag", self.cart_etag)
            return True

    def create_order(self):
        headers = {
            "X-CSRF-Token": self.csrf,
            "Idempotency-Key": self.order_key,
        }
        if self.cart_etag:
            headers["If-Match"] = self.cart_etag
        payload = {"cart_id": self.cart_id}
        with self.client.post(
            "/v2/orders",
            json=payload,
            headers=headers,
            catch_response=True,
            allow_redirects=False,
        ) as r:
            if r.status_code == 401:
                action = self.handle_401(r, "order create")
                if action == "retry":
                    return self.create_order()
                return False
            if r.status_code == 201:
                try:
                    data = r.json()
                except Exception:
                    r.failure("order create not json")
                    return False
                if not data.get("accepted", False):
                    r.failure("order accepted false")
                    return False
                self.csrf = data.get("csrf", self.csrf)
                return True
            if r.status_code == 200:
                try:
                    data = r.json()
                except Exception:
                    r.failure("order 200 not json")
                    return False
                if data.get("accepted", False):
                    self.csrf = data.get("csrf", self.csrf)
                    return True
                r.failure("order 200 accepted false")
                return False
            r.failure(f"order create status {r.status_code}")
            return False

    def do_work(self):
        with self.client.post(
            "/v2/work",
            json={},
            catch_response=True,
            allow_redirects=False,
        ) as r:
            if r.status_code == 429:
                retry_after = r.headers.get("Retry-After", "1")
                try:
                    delay = float(retry_after)
                except Exception:
                    delay = 1.0
                time.sleep(delay)
                return "retry"
            if r.status_code == 200:
                try:
                    data = r.json()
                except Exception:
                    r.failure("work not json")
                    return "fail"
                if data.get("ok"):
                    return "ok"
                r.failure("work ok false")
                return "fail"
            if r.status_code == 500:
                r.failure("work 500")
                return "fail"
            r.failure(f"work status {r.status_code}")
            return "fail"

    def run_journey(self):
        # Optional work with retry
        for _ in range(4):
            result = self.do_work()
            if result == "ok":
                break
            if result == "fail":
                return

        product = self.get_catalog_product()
        if not product:
            return
        if not self.create_cart(product["product_id"], product["variant_id"]):
            return
        if not self.get_cart():
            return
        if not self.patch_cart(2):
            return
        if not self.create_order():
            return

    @task
    def journey(self):
        if self.iterations_left <= 0:
            raise StopUser()
        self.iterations_left -= 1
        self.run_journey()


class Shape(LoadTestShape):
    def tick(self):
        run_time = self.get_run_time()
        if run_time < 60:
            return (2, 2)
        return None
