  { rotate_csrf: true, html_layout: 1, reverse_catalog: true }
];

const USERS = 2;
const ITERATIONS = 2;

function getLoginForm(httpClient) {
  const res = httpClient.get(`${BASE_URL}/v2/login-form`, {
    redirects: 0,
    tags: { name: 'login-form' }
  });
  check(res, {
    'login-form status 200': (r) => r.status === 200,
  });
  const body = res.body;
  const csrfMatch = body.match(/name=["']csrf["'][^>]*value=["']([^"']+)["']/i) ||
                    body.match(/value=["']([^"']+)["'][^>]*name=["']csrf["']/i) ||
                    body.match(/name=["']csrf["'][^>]*value=["']([^"']+)["']/i);
  if (!csrfMatch) {
    fail('login-form: csrf token not found');
  }
  return csrfMatch[1];
}

function login(httpClient, username, password) {
  const csrf = getLoginForm(httpClient);
  const payload = JSON.stringify({ username, password, csrf });
  const res = httpClient.post(`${BASE_URL}/v2/login`, payload, {
    headers: { 'Content-Type': 'application/json' },
    redirects: 0,
    tags: { name: 'login' }
  });

  if (res.status === 302) {
    const location = res.headers['Location'];
    if (!location) {
      fail('login 302 without Location');
    }
    const followRes = httpClient.get(location.startsWith('http') ? location : `${BASE_URL}${location}`, {
      redirects: 0,
      tags: { name: 'login-follow' }
    });
    check(followRes, {
      'login follow status 200': (r) => r.status === 200,
    });
    const body = followRes.body;
    const csrfMatch = body.match(/["']csrf["']\s*:\s*["']([^"']+)["']/i) ||
                      body.match(/name=["']csrf["'][^>]*value=["']([^"']+)["']/i);
    if (!csrfMatch) {
      fail('login follow: csrf not found');
    }
    return { csrf: csrfMatch[1], user: username };
  }

  check(res, {
    'login status 200': (r) => r.status === 200,
  });
  const body = res.body;
  const csrfMatch = body.match(/["']csrf["']\s*:\s*["']([^"']+)["']/i) ||
                    body.match(/name=["']csrf["'][^>]*value=["']([^"']+)["']/i);
  if (!csrfMatch) {
    fail('login: csrf not found in response');
  }
  return { csrf: csrfMatch[1], user: username };
}

function getCatalog(httpClient, csrf, reverse) {
  const res = httpClient.get(`${BASE_URL}/v2/catalog`, {
    tags: { name: 'catalog' }
  });
  check(res, {
    'catalog status 200': (r) => r.status === 200,
  });
  const data = res.json();
  let products = data.data.products || [];

  if (reverse) {
    products = [...products].reverse();
  }

  return products;
}

function getCatalogPage(httpClient, csrf, pageUrl) {
  const url = pageUrl.startsWith('http') ? pageUrl : `${BASE_URL}${pageUrl}`;
  const res = httpClient.get(url, {
    tags: { name: 'catalog-page' }
  });
  check(res, {
    'catalog page status 200': (r) => r.status === 200,
  });
  return res.json();
}

function createCart(httpClient, csrf, productId, variantId, grantId) {
  const payload = { product_id: productId, variant_id: variantId };
  if (grantId) {
    payload.grant_id = grantId;
  }
  const res = httpClient.post(`${BASE_URL}/v2/carts`, JSON.stringify(payload), {
    headers: {
      'Content-Type': 'application/json',
      'X-CSRF-Token': csrf
    },
    tags: { name: 'create-cart' }
  });
  check(res, {
    'create cart status 201': (r) => r.status === 201,
  });
  const body = res.json();
  return {
    id: body.id,
    csrf: body.csrf || csrf,
    etag: res.headers['ETag'] || res.headers['Etag'] || res.headers['etag']
  };
}

function getCart(httpClient, csrf, cartId) {
  const res = httpClient.get(`${BASE_URL}/v2/carts/${cartId}`, {
    tags: { name: 'get-cart' }
  });
  check(res, {
    'get cart status 200': (r) => r.status === 200,
  });
  return {
    etag: res.headers['ETag'] || res.headers['Etag'] || res.headers['etag'],
    csrf: csrf
  };
}

function updateCart(httpClient, csrf, cartId, etag, quantity) {
  const payload = JSON.stringify({ quantity });
  const res = httpClient.patch(`${BASE_URL}/v2/carts/${cartId}`, payload, {
    headers: {
      'Content-Type': 'application/json',
      'X-CSRF-Token': csrf,
      'If-Match': etag
    },
    tags: { name: 'update-cart' }
  });

  if (res.status === 412) {
    const fresh = getCart(httpClient, csrf, cartId);
    const retryRes = httpClient.patch(`${BASE_URL}/v2/carts/${cartId}`, payload, {
      headers: {
        'Content-Type': 'application/json',
        'X-CSRF-Token': csrf,
        'If-Match': fresh.etag
      },
      tags: { name: 'update-cart-retry' }
    });
    check(retryRes, {
      'update cart retry status 200': (r) => r.status === 200,
    });
    const body = retryRes.json();
    return {
      csrf: body.csrf || csrf,
      etag: retryRes.headers['ETag'] || retryRes.headers['Etag'] || retryRes.headers['etag']
    };
  }

  check(res, {
    'update cart status 200': (r) => r.status === 200,
  });
  const body = res.json();
  return {
    csrf: body.csrf || csrf,
    etag: res.headers['ETag'] || res.headers['Etag'] || res.headers['etag']
  };
}

function createOrder(httpClient, csrf, cartId, etag, idempotencyKey) {
  const payload = JSON.stringify({ cart_id: cartId });
  const res = httpClient.post(`${BASE_URL}/v2/orders`, payload, {
    headers: {
      'Content-Type': 'application/json',
      'X-CSRF-Token': csrf,
      'If-Match': etag,
      'Idempotency-Key': idempotencyKey
    },
    tags: { name: 'create-order' }
  });

  if (res.status === 401) {
    const body = res.json();
    if (body.error === 'expired') {
      const renewRes = httpClient.post(`${BASE_URL}/v2/session/renew`, '{}', {
        headers: {
          'Content-Type': 'application/json',
          'X-CSRF-Token': csrf
        },
        tags: { name: 'session-renew' }
      });
      check(renewRes, {
        'session renew status 200': (r) => r.status === 200,
      });
      const renewBody = renewRes.json();
      const newCsrf = renewBody.csrf || csrf;

      const recoverRes = httpClient.post(`${BASE_URL}/v2/carts/${cartId}/recover`, '{}', {
        headers: {
          'Content-Type': 'application/json',
          'X-CSRF-Token': newCsrf
        },
        tags: { name: 'cart-recover' }
      });
      check(recoverRes, {
        'cart recover status 200': (r) => r.status === 200,
      });

      const retryRes = httpClient.post(`${BASE_URL}/v2/orders`, payload, {
        headers: {
          'Content-Type': 'application/json',
          'X-CSRF-Token': newCsrf,
          'If-Match': etag,
          'Idempotency-Key': idempotencyKey
        },
        tags: { name: 'create-order-retry' }
      });
      check(retryRes, {
        'create order retry status 201': (r) => r.status === 201,
      });
      const retryBody = retryRes.json();
      return {
        accepted: retryBody.accepted === true,
        csrf: retryBody.csrf || newCsrf,
        id: retryBody.id
      };
    } else if (body.error === 'session') {
      const newCsrf = getLoginForm(httpClient);
      const loginRes = login(httpClient, 'bench', 'bench');
      const recoverRes = httpClient.post(`${BASE_URL}/v2/carts/${cartId}/recover`, '{}', {
        headers: {
          'Content-Type': 'application/json',
          'X-CSRF-Token': loginRes.csrf
        },
        tags: { name: 'cart-recover-session' }
      });
      check(recoverRes, {
        'cart recover session status 200': (r) => r.status === 200,
      });

      const retryRes = httpClient.post(`${BASE_URL}/v2/orders`, payload, {
        headers: {
          'Content-Type': 'application/json',
          'X-CSRF-Token': loginRes.csrf,
          'If-Match': etag,
          'Idempotency-Key': idempotencyKey
        },
        tags: { name: 'create-order-retry-session' }
      });
      check(retryRes, {
        'create order retry session status 201': (r) => r.status === 201,
      });
      const retryBody = retryRes.json();
      return {
        accepted: retryBody.accepted === true,
        csrf: retryBody.csrf || loginRes.csrf,
        id: retryBody.id
      };
    } else {
      fail(`create order denied: ${body.error}`);
    }
  }

  check(res, {
    'create order status 201': (r) => r.status === 201,
  });
  const body = res.json();
  if (body.accepted !== true) {
    fail('order not accepted');
  }
  return {
    accepted: true,
    csrf: body.csrf || csrf,
    id: body.id
  };
}

function doWork(httpClient, csrf) {
  const res = httpClient.post(`${BASE_URL}/v2/work`, '{}', {
    headers: {
      'Content-Type': 'application/json',
      'X-CSRF-Token': csrf
    },
    tags: { name: 'work' }
  });

  workResponses.add(1);

  if (res.status === 429) {
    const retryAfter = parseInt(res.headers['Retry-After'] || '1', 10);
    sleep(retryAfter);
    let retries = 0;
    while (retries < 4) {
      const retryRes = httpClient.post(`${BASE_URL}/v2/work`, '{}', {
        headers: {
          'Content-Type': 'application/json',
          'X-CSRF-Token': csrf
        },
        tags: { name: 'work-retry' }
      });
      workResponses.add(1);
      if (retryRes.status === 200) {
        check(retryRes, {
          'work retry status 200': (r) => r.status === 200,
        });
        return;
      }
      if (retryRes.status === 429) {
        const ra = parseInt(retryRes.headers['Retry-After'] || '1', 10);
        sleep(ra);
        retries++;
        continue;
      }
      workFailures.add(1);
      return;
    }
    workFailures.add(1);
    return;
  }

  if (res.status !== 200) {
    workFailures.add(1);
    return;
  }

  check(res, {
    'work status 200': (r) => r.status === 200,
  });
}

function getChallengeForm(httpClient, csrf) {
  const res = httpClient.get(`${BASE_URL}/v2/challenge-form`, {
    tags: { name: 'challenge-form' }
  });
  check(res, {
    'challenge form status 200': (r) => r.status === 200,
  });
  const body = res.body;
  const actionMatch = body.match(/action=["']([^"']+)["']/i);
  const challengeMatch = body.match(/name=["']challenge["'][^>]*value=["']([^"']+)["']/i) ||
                          body.match(/value=["']([^"']+)["'][^>]*name=["']challenge["']/i);
  if (!actionMatch || !challengeMatch) {
    fail('challenge form: action or challenge not found');
  }
  return {
    action: actionMatch[1],
    challenge: challengeMatch[1]
  };
}

function postChallenge(httpClient, csrf, action, challenge) {
  const url = action.startsWith('http') ? action : `${BASE_URL}${action}`;
  const res = httpClient.post(url, JSON.stringify({ challenge }), {
    headers: {
      'Content-Type': 'application/json',
      'X-CSRF-Token': csrf
    },
    redirects: 0,
    tags: { name: 'post-challenge' }
  });
  check(res, {
    'post challenge status 302': (r) => r.status === 302,
  });
  const location = res.headers['Location'];
  if (!location) {
    fail('post challenge 302 without Location');
  }
  const followRes = httpClient.get(location.startsWith('http') ? location : `${BASE_URL}${location}`, {
    tags: { name: 'challenge-follow' }
  });
  check(followRes, {
    'challenge follow status 200': (r) => r.status === 200,
  });
  const body = followRes.json();
  return {
    grantId: body.grant_id,
    csrf: body.csrf || csrf
  };
}

function createReservation(httpClient, csrf, cartId) {
  const res = httpClient.post(`${BASE_URL}/v2/reservations`, JSON.stringify({ cart_id: cartId }), {
    headers: {
      'Content-Type': 'application/json',
      'X-CSRF-Token': csrf
    },
    tags: { name: 'create-reservation' }
  });
  check(res, {
    'create reservation status 202': (r) => r.status === 202,
  });
  const body = res.json();
  return {
    statusUrl: body.status_url,
    csrf: body.csrf || csrf
  };
}

function pollReservation(httpClient, csrf, statusUrl) {
  let reservationId = null;
  let currentCsrf = csrf;
  for (let i = 0; i < 5; i++) {
    sleep(0.05);
    const url = statusUrl.startsWith('http') ? statusUrl : `${BASE_URL}${statusUrl}`;
    const res = httpClient.get(url, {
      tags: { name: 'poll-reservation' }
    });
    check(res, {
      'poll reservation status 200': (r) => r.status === 200,
    });
    const body = res.json();
    if (body.csrf) {
      currentCsrf = body.csrf;
    }
    if (body.status === 'ready') {
      reservationId = body.reservation_id;
      break;
    }
    if (body.status === 'failed') {
      break;
    }
  }
  return { reservationId, csrf: currentCsrf };
}

function journey(httpClient, profile, username, iteration) {
  // Fresh login
  const loginResult = login(httpClient, username, 'bench');
  let csrf = loginResult.csrf;

  // Get catalog
  let products = getCatalog(httpClient, csrf, profile.reverse_catalog || false);

  // Traverse at most 3 pages if needed
  let pageUrl = null;
  let pageCount = 0;
  while (products.length === 0 && pageCount < 3) {
    const pageRes = getCatalogPage(httpClient, csrf, '/v2/catalog/page');
    if (pageRes.data && pageRes.data.products && pageRes.data.products.length > 0) {
      products = pageRes.data.products;
    }
    pageUrl = pageRes.next;
    if (!pageUrl) break;
    pageCount++;
  }

  if (products.length === 0) {
    fail('no products found in catalog');
  }

  // Pick first product with in-stock variant
  let selectedProduct = null;
  let selectedVariant = null;
  for (const product of products) {
    if (product.variants && product.variants.length > 0) {
      for (const variant of product.variants) {
        if (variant.in_stock) {
          selectedProduct = product;
          selectedVariant = variant;
          break;
        }
      }
    }
    if (selectedProduct) break;
  }

  if (!selectedProduct) {
    fail('no in-stock product found');
  }

  // Optional challenge flow
  let grantId = null;
  const challengeForm = getChallengeForm(httpClient, csrf);
  const challengeResult = postChallenge(httpClient, csrf, challengeForm.action, challengeForm.challenge);
  grantId = challengeResult.grantId;
  csrf = challengeResult.csrf;

  // Create cart
  const cartResult = createCart(httpClient, csrf, selectedProduct.id, selectedVariant.id, grantId);
  csrf = cartResult.csrf;
  let cartId = cartResult.id;
  let etag = cartResult.etag;

  // Update cart quantity
  const updateResult = updateCart(httpClient, csrf, cartId, etag, 2);
  csrf = updateResult.csrf;
  etag = updateResult.etag;

  // Create reservation
  const reservationResult = createReservation(httpClient, csrf, cartId);
  csrf = reservationResult.csrf;

  // Poll reservation
  const pollResult = pollReservation(httpClient, csrf, reservationResult.statusUrl);
  csrf = pollResult.csrf;
  const reservationId = pollResult.reservationId;

  // Create order
  const idempotencyKey = `order-${username}-${iteration}-${Date.now()}`;
  const orderPayload = { cart_id: cartId };
  if (reservationId) {
    orderPayload.reservation_id = reservationId;
  }

  const orderRes = httpClient.post(`${BASE_URL}/v2/orders`, JSON.stringify(orderPayload), {
    headers: {
      'Content-Type': 'application/json',
      'X-CSRF-Token': csrf,
      'If-Match': etag,
      'Idempotency-Key': idempotencyKey
    },
    tags: { name: 'create-order-final' }
  });

  if (orderRes.status === 401) {
    const body = orderRes.json();
    if (body.error === 'expired') {
      const renewRes = httpClient.post(`${BASE_URL}/v2/session/renew`, '{}', {
        headers: {
          'Content-Type': 'application/json',
          'X-CSRF-Token': csrf
        },
        tags: { name: 'session-renew-final' }
      });
      check(renewRes, {
        'session renew final status 200': (r) => r.status === 200,
      });
      const renewBody = renewRes.json();
      csrf = renewBody.csrf || csrf;

      const recoverRes = httpClient.post(`${BASE_URL}/v2/carts/${cartId}/recover`, '{}', {
        headers: {
          'Content-Type': 'application/json',
          'X-CSRF-Token': csrf
        },
        tags: { name: 'cart-recover-final' }
      });
      check(recoverRes, {
        'cart recover final status 200': (r) => r.status === 200,
      });

      const retryRes = httpClient.post(`${BASE_URL}/v2/orders`, JSON.stringify(orderPayload), {
        headers: {
          'Content-Type': 'application/json',
          'X-CSRF-Token': csrf,
          'If-Match': etag,
          'Idempotency-Key': idempotencyKey
        },
        tags: { name: 'create-order-final-retry' }
      });
      check(retryRes, {
        'create order final retry status 201': (r) => r.status === 201,
      });
      const retryBody = retryRes.json();
      if (retryBody.accepted !== true) {
        fail('order not accepted on retry');
      }
      csrf = retryBody.csrf || csrf;
    } else if (body.error === 'session') {
      const newCsrf = getLoginForm(httpClient);
      const newLogin = login(httpClient, username, 'bench');
      csrf = newLogin.csrf;

      const recoverRes = httpClient.post(`${BASE_URL}/v2/carts/${cartId}/recover`, '{}', {
        headers: {
          'Content-Type': 'application/json',
          'X-CSRF-Token': csrf
        },
        tags: { name: 'cart-recover-final-session' }
      });
      check(recoverRes, {
        'cart recover final session status 200': (r) => r.status === 200,
      });

      const retryRes = httpClient.post(`${BASE_URL}/v2/orders`, JSON.stringify(orderPayload), {
        headers: {
          'Content-Type': 'application/json',
          'X-CSRF-Token': csrf,
          'If-Match': etag,
          'Idempotency-Key': idempotencyKey
        },
        tags: { name: 'create-order-final-retry-session' }
      });
      check(retryRes, {
        'create order final retry session status 201': (r) => r.status === 201,
      });
      const retryBody = retryRes.json();
      if (retryBody.accepted !== true) {
        fail('order not accepted on session retry');
      }
      csrf = retryBody.csrf || csrf;
    } else {
      fail(`create order final denied: ${body.error}`);
    }
  } else {
    check(orderRes, {
      'create order final status 201': (r) => r.status === 201,
    });
    const body = orderRes.json();
    if (body.accepted !== true) {
      fail('order not accepted');
    }
    csrf = body.csrf || csrf;
  }

  // Do work
  doWork(httpClient, csrf);

  // Update business failure rate
  if (workResponses.value > 0) {
    businessFailureRate.add(workFailures.value / workResponses.value);
  }
}

export const options = {
  scenarios: {
    flow: {
      executor: 'per-vu-iterations',
      vus: USERS,
      iterations: ITERATIONS,
      maxDuration: '5m',
    },
  },
  thresholds: {
    business_failure: ['rate<0.1'],
  },
};

export default function () {
  const vuId = __VU;
  const iterId = __ITER;
  const profile = PROFILES[(vuId - 1) % PROFILES.length];
  const username = `bench-${((vuId - 1) % 16) + 1}`;

  const httpClient = http;

  journey(httpClient, profile, username, iterId);

  sleep(0.1);
}
