from urllib.parse import urljoin

from locust import HttpUser, LoadTestShape, between, task
from locust.exception import StopUser


BASE = os.environ.get("BASE_URL", "http://127.0.0.1:8000")


class ShopUser(HttpUser):
    wait_time = between(0.1, 0.3)

    def __init__(self, *args, **kwargs):
        super().__init__(*args, **kwargs)
        self.csrf = None
        self.cart_id = None
        self.cart_etag = None
        self.grant_id = None
        self.reservation_id = None
        self.idempotency_key = None
        self.iterations_done = 0
        self.max_iterations = 2
        self.rotate_csrf = True
        self.html_layout = 0
        self.reverse_catalog = False

    def on_start(self):
        self.client.redirect_enabled = False
        self.login()

    def login(self):
        # GET login form
        with self.client.get("/v2/login-form", catch_response=True) as r:
            if r.status_code != 200:
                r.failure(f"login-form status {r.status_code}")
                return
            csrf = self._extract_csrf(r.text)
            if not csrf:
                r.failure("no csrf in login form")
                return
            self.csrf = csrf

        # POST login
        with self.client.post(
            "/v2/login",
            json={"username": "bench", "password": "bench", "csrf": self.csrf},
            catch_response=True,
        ) as r:
            if r.status_code == 302:
                loc = r.headers.get("Location")
                if not loc:
                    r.failure("302 without Location")
                    return
                with self.client.get(urljoin(BASE, loc), catch_response=True) as r2:
                    if r2.status_code != 200:
                        r2.failure(f"login redirect status {r2.status_code}")
                        return
                    self._update_csrf_from_json(r2)
            elif r.status_code == 200:
                self._update_csrf_from_json(r)
            else:
                r.failure(f"login status {r.status_code}")
                return

    def _extract_csrf(self, html):
        import re
        # match input name=csrf with optional attribute variants
        patterns = [
            r'<input[^>]*name=["\']csrf["\'][^>]*>',
            r'<input[^>]*name=["\']CSRF["\'][^>]*>',
            r'<input[^>]*name=["\']_csrf["\'][^>]*>',
        ]
        for p in patterns:
            m = re.search(p, html, re.IGNORECASE)
            if m:
                tag = m.group(0)
                vm = re.search(r'value=["\']([^"\']*)["\']', tag, re.IGNORECASE)
                if vm:
                    return vm.group(1)
        return None

    def _update_csrf_from_json(self, response):
        try:
            data = response.json()
        except Exception:
            return
        if isinstance(data, dict) and "csrf" in data and data["csrf"]:
            self.csrf = data["csrf"]

    def _update_csrf_from_headers(self, response):
        csrf = response.headers.get("X-CSRF-Token")
        if csrf:
            self.csrf = csrf

    def _headers(self):
        h = {}
        if self.csrf:
            h["X-CSRF-Token"] = self.csrf
        return h

    def _handle_401(self, response, operation_retry_fn):
        """Handle 401 expiry/session. Returns True if retry was attempted."""
        try:
            err = response.json().get("error", "")
        except Exception:
            err = ""
        if err == "expired":
            # renew session
            with self.client.post(
                "/v2/session/renew",
                json={},
                headers=self._headers(),
                catch_response=True,
            ) as rr:
                if rr.status_code == 200:
                    self._update_csrf_from_json(rr)
                elif rr.status_code == 302:
                    loc = rr.headers.get("Location")
                    if loc:
                        with self.client.get(urljoin(BASE, loc), catch_response=True) as rr2:
                            self._update_csrf_from_json(rr2)
                else:
                    rr.failure(f"renew status {rr.status_code}")
                    return False
            # recover cart if exists
            if self.cart_id:
                with self.client.post(
                    f"/v2/carts/{self.cart_id}/recover",
                    json={},
                    headers=self._headers(),
                    catch_response=True,
                ) as rc:
                    if rc.status_code == 200:
                        self._update_csrf_from_json(rc)
                    elif rc.status_code == 302:
                        loc = rc.headers.get("Location")
                        if loc:
                            with self.client.get(urljoin(BASE, loc), catch_response=True) as rc2:
                                self._update_csrf_from_json(rc2)
            # retry operation once
            if operation_retry_fn:
                return operation_retry_fn()
            return True
        elif err == "session":
            # revoked: fresh login, recover cart
            self.login()
            if self.cart_id:
                with self.client.post(
                    f"/v2/carts/{self.cart_id}/recover",
                    json={},
                    headers=self._headers(),
                    catch_response=True,
                ) as rc:
                    if rc.status_code == 200:
                        self._update_csrf_from_json(rc)
                    elif rc.status_code == 302:
                        loc = rc.headers.get("Location")
                        if loc:
                            with self.client.get(urljoin(BASE, loc), catch_response=True) as rc2:
                                self._update_csrf_from_json(rc2)
            if operation_retry_fn:
                return operation_retry_fn()
            return True
        elif err == "denied":
            response.failure("401 denied - assertion failure")
            return False
        else:
            response.failure(f"401 unknown error={err}")
            return False

    def _get_catalog(self):
        products = []
        with self.client.get("/v2/catalog", catch_response=True) as r:
            if r.status_code != 200:
                r.failure(f"catalog status {r.status_code}")
                return products
            try:
                data = r.json()
                products = data.get("data", {}).get("products", [])
            except Exception:
                r.failure("catalog json parse")
        return products

    def _get_catalog_page(self, url="/v2/catalog/page"):
        with self.client.get(url, catch_response=True) as r:
            if r.status_code != 200:
                r.failure(f"catalog page status {r.status_code}")
                return None, None
            try:
                data = r.json()
                product = data.get("data", {}).get("product")
                nxt = data.get("next")
                return product, nxt
            except Exception:
                r.failure("catalog page json parse")
                return None, None

    def _select_product(self):
        products = self._get_catalog()
        if products:
            return random.choice(products)
        # fallback to page traversal
        product = None
        nxt = "/v2/catalog/page"
        for _ in range(3):
            product, nxt = self._get_catalog_page(nxt)
            if product:
                return product
            if not nxt:
                break
        return None

    def _create_cart(self, product):
        if not product:
            return False
        variants = product.get("variants", [])
        if not variants:
            return False
        variant = random.choice(variants)
        payload = {
            "product_id": product["id"],
            "variant_id": variant["id"],
        }
        if self.grant_id:
            payload["grant_id"] = self.grant_id
        with self.client.post(
            "/v2/carts",
            json=payload,
            headers=self._headers(),
            catch_response=True,
        ) as r:
            if r.status_code == 201:
                self._update_csrf_from_json(r)
                self.cart_id = r.json().get("id")
                self.cart_etag = r.headers.get("ETag")
                return True
            elif r.status_code == 401:
                return self._handle_401(r, lambda: self._create_cart(product))
            else:
                r.failure(f"create cart status {r.status_code}")
                return False

    def _get_cart(self):
        if not self.cart_id:
            return False
        with self.client.get(f"/v2/carts/{self.cart_id}", catch_response=True) as r:
            if r.status_code == 200:
                self.cart_etag = r.headers.get("ETag")
                return True
            elif r.status_code == 401:
                return self._handle_401(r, lambda: self._get_cart())
            else:
                r.failure(f"get cart status {r.status_code}")
                return False

    def _patch_cart(self, quantity):
        if not self.cart_id:
            return False
        headers = self._headers()
        if self.cart_etag:
            headers["If-Match"] = self.cart_etag
        with self.client.patch(
            f"/v2/carts/{self.cart_id}",
            json={"quantity": quantity},
            headers=headers,
            catch_response=True,
        ) as r:
            if r.status_code == 200:
                self._update_csrf_from_json(r)
                self.cart_etag = r.headers.get("ETag")
                return True
            elif r.status_code == 412:
                # re-read and retry once
                if self._get_cart():
                    headers = self._headers()
                    if self.cart_etag:
                        headers["If-Match"] = self.cart_etag
                    with self.client.patch(
                        f"/v2/carts/{self.cart_id}",
                        json={"quantity": quantity},
                        headers=headers,
                        catch_response=True,
                    ) as r2:
                        if r2.status_code == 200:
                            self._update_csrf_from_json(r2)
                            self.cart_etag = r2.headers.get("ETag")
                            return True
                        elif r2.status_code == 401:
                            return self._handle_401(r2, lambda: self._patch_cart(quantity))
                        else:
                            r2.failure(f"patch retry status {r2.status_code}")
                            return False
                return False
            elif r.status_code == 401:
                return self._handle_401(r, lambda: self._patch_cart(quantity))
            else:
                r.failure(f"patch cart status {r.status_code}")
                return False

    def _get_challenge(self):
        with self.client.get("/v2/challenge-form", catch_response=True) as r:
            if r.status_code != 200:
                r.failure(f"challenge-form status {r.status_code}")
                return False
            import re
            m = re.search(r'<form[^>]*action=["\']([^"\']*)["\']', r.text, re.IGNORECASE)
            if not m:
                r.failure("no challenge form action")
                return False
            action = m.group(1)
            cm = re.search(r'<input[^>]*name=["\']challenge["\'][^>]*>', r.text, re.IGNORECASE)
            if not cm:
                r.failure("no challenge input")
                return False
            vm = re.search(r'value=["\']([^"\']*)["\']', cm.group(0), re.IGNORECASE)
            challenge = vm.group(1) if vm else ""
            with self.client.post(
                urljoin(BASE, action),
                json={"challenge": challenge},
                headers=self._headers(),
                catch_response=True,
            ) as r2:
                if r2.status_code == 302:
                    loc = r2.headers.get("Location")
                    if not loc:
                        r2.failure("challenge 302 without Location")
                        return False
                    with self.client.get(urljoin(BASE, loc), catch_response=True) as r3:
                        if r3.status_code == 200:
                            self._update_csrf_from_json(r3)
                            self.grant_id = r3.json().get("grant_id")
                            return True
                        else:
                            r3.failure(f"challenge redirect status {r3.status_code}")
                            return False
                elif r2.status_code == 401:
                    return self._handle_401(r2, lambda: self._get_challenge())
                else:
                    r2.failure(f"challenge post status {r2.status_code}")
                    return False

    def _create_reservation(self):
        if not self.cart_id:
            return False
        with self.client.post(
            "/v2/reservations",
            json={"cart_id": self.cart_id},
            headers=self._headers(),
            catch_response=True,
        ) as r:
            if r.status_code == 202:
                self._update_csrf_from_json(r)
                status_url = r.json().get("status_url")
                if not status_url:
                    r.failure("no status_url")
                    return False
                for _ in range(5):
                    time.sleep(0.05)
                    with self.client.get(urljoin(BASE, status_url), catch_response=True) as sr:
                        if sr.status_code == 200:
                            self._update_csrf_from_json(sr)
                            status = sr.json().get("status")
                            if status == "ready":
                                self.reservation_id = sr.json().get("reservation_id")
                                return True
                            elif status in ("pending", "failed"):
                                if status == "failed":
                                    return False
                                continue
                            else:
                                sr.failure(f"unknown reservation status {status}")
                                return False
                        elif sr.status_code == 401:
                            return self._handle_401(sr, lambda: self._create_reservation())
                        else:
                            sr.failure(f"reservation poll status {sr.status_code}")
                            return False
                return False
            elif r.status_code == 401:
                return self._handle_401(r, lambda: self._create_reservation())
            else:
                r.failure(f"reservation status {r.status_code}")
                return False

    def _place_order(self):
        if not self.cart_id:
            return False
        if not self.idempotency_key:
            self.idempotency_key = f"order-{self.cart_id}-{int(time.time()*1000)}"
        payload = {"cart_id": self.cart_id}
        if self.reservation_id:
            payload["reservation_id"] = self.reservation_id
        headers = self._headers()
        headers["Idempotency-Key"] = self.idempotency_key
        if self.cart_etag:
            headers["If-Match"] = self.cart_etag
        with self.client.post(
            "/v2/orders",
            json=payload,
            headers=headers,
            catch_response=True,
        ) as r:
            if r.status_code == 201:
                self._update_csrf_from_json(r)
                data = r.json()
                if data.get("accepted") is True:
                    return True
                else:
                    r.failure("order accepted false")
                    return False
            elif r.status_code == 200:
                data = r.json()
                if data.get("accepted") is False:
                    r.failure("business failure accepted=false")
                    return False
                else:
                    self._update_csrf_from_json(r)
                    return True
            elif r.status_code == 401:
                return self._handle_401(r, lambda: self._place_order())
            else:
                r.failure(f"order status {r.status_code}")
                return False

    def _do_work(self):
        with self.client.post("/v2/work", json={}, catch_response=True) as r:
            if r.status_code == 200:
                return True
            elif r.status_code == 429:
                retry_after = r.headers.get("Retry-After")
                wait = 1.0
                if retry_after:
                    try:
                        wait = float(retry_after)
                    except ValueError:
                        wait = 1.0
                for _ in range(4):
                    time.sleep(wait)
                    with self.client.post("/v2/work", json={}, catch_response=True) as r2:
                        if r2.status_code == 200:
                            return True
                        elif r2.status_code == 429:
                            continue
                        else:
                            r2.failure(f"work retry status {r2.status_code}")
                            return False
                r.failure("work 429 exhausted")
                return False
            elif r.status_code == 500:
                r.failure("work 500 unexpected")
                return False
            else:
                r.failure(f"work status {r.status_code}")
                return False

    def journey(self):
        # Fresh login and cart each journey
        self.login()
        self.cart_id = None
        self.cart_etag = None
        self.grant_id = None
        self.reservation_id = None
        self.idempotency_key = None

        # Optional challenge
        if random.random() < 0.5:
            self._get_challenge()

        product = self._select_product()
        if not product:
            return False

        if not self._create_cart(product):
            return False

        if not self._get_cart():
            return False

        quantity = random.randint(1, 20)
        if not self._patch_cart(quantity):
            return False

        if random.random() < 0.5:
            if not self._create_reservation():
                return False

        if not self._place_order():
            return False

        self._do_work()
        return True

    @task
    def run_journey(self):
        if self.iterations_done >= self.max_iterations:
            raise StopUser()
        self.iterations_done += 1
        self.journey()


class ShopLoadShape(LoadTestShape):
