    private static final Pattern IN_STOCK_PATTERN = Pattern.compile("\"in_stock\"\\s*:\\s*(true|false)");
    private static final Pattern GRANT_ID_PATTERN = Pattern.compile("\"grant_id\"\\s*:\\s*\"([^\"]+)\"");
    private static final Pattern RESERVATION_ID_PATTERN = Pattern.compile("\"reservation_id\"\\s*:\\s*\"([^\"]+)\"");
    private static final Pattern STATUS_URL_PATTERN = Pattern.compile("\"status_url\"\\s*:\\s*\"([^\"]+)\"");
    private static final Pattern STATUS_PATTERN = Pattern.compile("\"status\"\\s*:\\s*\"([^\"]+)\"");
    private static final Pattern ERROR_PATTERN = Pattern.compile("\"error\"\\s*:\\s*\"([^\"]+)\"");
    private static final Pattern ACCEPTED_PATTERN = Pattern.compile("\"accepted\"\\s*:\\s*(true|false)");
    private static final Pattern ORDER_ID_PATTERN = Pattern.compile("\"id\"\\s*:\\s*(\\d+)");
    private static final Pattern CART_ID_PATTERN = Pattern.compile("\"id\"\\s*:\\s*(\\d+)");
    private static final Pattern CSRF_JSON_PATTERN = Pattern.compile("\"csrf\"\\s*:\\s*\"([^\"]+)\"");
    private static final Pattern USER_JSON_PATTERN = Pattern.compile("\"user\"\\s*:\\s*\"([^\"]+)\"");
    private static final Pattern OK_PATTERN = Pattern.compile("\"ok\"\\s*:\\s*(true|false)");
    private static final Pattern RETRY_AFTER_PATTERN = Pattern.compile("(?i)retry-after:\\s*(\\d+)");

    // ---------- Helper: extract with multiple patterns ----------
    private static String extractFirst(String body, Pattern... patterns) {
        if (body == null) return null;
        for (Pattern p : patterns) {
            Matcher m = p.matcher(body);
            if (m.find()) {
                return m.group(1);
            }
        }
        return null;
    }

    private static String extractHeader(Map<String, String> headers, String name) {
        if (headers == null) return null;
        for (Map.Entry<String, String> e : headers.entrySet()) {
            if (e.getKey().equalsIgnoreCase(name)) {
                return e.getValue();
            }
        }
        return null;
    }

    // ---------- ChainBuilder: Login ----------
    private static ChainBuilder doLogin = exec(session -> {
        String username = session.getString("username");
        String password = session.getString("password");
        return session.set("login_username", username).set("login_password", password);
    })
    .exec(
        http("GET /v2/login-form")
            .get("/v2/login-form")
            .check(
                status().is(200),
                regex(CSRF_INPUT_PATTERN.pattern()).find().exists().saveAs("login_csrf_raw"),
                regex(NONCE_PATTERN.pattern()).find().exists().saveAs("login_nonce_raw")
            )
    )
    .exec(session -> {
        String csrfRaw = session.getString("login_csrf_raw");
        String nonceRaw = session.getString("login_nonce_raw");
        String csrf = null;
        String nonce = null;
        if (csrfRaw != null) {
            csrf = extractFirst(csrfRaw, CSRF_INPUT_PATTERN, CSRF_INPUT_PATTERN2, CSRF_INPUT_PATTERN3, CSRF_INPUT_PATTERN4);
        }
        if (nonceRaw != null) {
            nonce = extractFirst(nonceRaw, NONCE_PATTERN, NONCE_PATTERN2, NONCE_PATTERN3, NONCE_PATTERN4);
        }
        if (csrf == null) {
            // Try to find any input with name csrf in the raw body
            String body = session.getString("login_csrf_raw");
            if (body != null) {
                Matcher m = Pattern.compile("name\\s*=\\s*[\"']csrf[\"']", Pattern.CASE_INSENSITIVE).matcher(body);
                if (m.find()) {
                    // Try to extract value after this position
                    int pos = m.end();
                    String rest = body.substring(pos);
                    Matcher vm = Pattern.compile("value\\s*=\\s*[\"']([^\"']+)[\"']", Pattern.CASE_INSENSITIVE).matcher(rest);
                    if (vm.find()) {
                        csrf = vm.group(1);
                    }
                }
            }
        }
        if (nonce == null) {
            String body = session.getString("login_nonce_raw");
            if (body != null) {
                Matcher m = Pattern.compile("name\\s*=\\s*[\"']login_nonce[\"']", Pattern.CASE_INSENSITIVE).matcher(body);
                if (m.find()) {
                    int pos = m.end();
                    String rest = body.substring(pos);
                    Matcher vm = Pattern.compile("value\\s*=\\s*[\"']([^\"']+)[\"']", Pattern.CASE_INSENSITIVE).matcher(rest);
                    if (vm.find()) {
                        nonce = vm.group(1);
                    }
                }
            }
        }
        return session.set(CSRF_TOKEN, csrf).set(LOGIN_NONCE, nonce);
    })
    .exec(session -> {
        String csrf = session.getString(CSRF_TOKEN);
        String nonce = session.getString(LOGIN_NONCE);
        String username = session.getString("login_username");
        String password = session.getString("login_password");
        String json = String.format("{\"username\":\"%s\",\"password\":\"%s\",\"csrf\":\"%s\"}", username, password, csrf == null ? "" : csrf);
        return session.set("login_json", json);
    })
    .exec(
        http("POST /v2/login")
            .post("/v2/login")
            .header("X-CSRF-Token", session -> session.getString(CSRF_TOKEN))
            .body(StringBody(session -> session.getString("login_json")))
            .check(
                status().in(200, 302),
                header("Location").optional().saveAs("login_location"),
                header("Set-Cookie").optional().saveAs("login_set_cookie"),
                bodyString().optional().saveAs("login_response_body")
            )
    )
    .exec(session -> {
        String location = session.getString("login_location");
        if (location != null && !location.isEmpty()) {
            return session.set("login_redirect_url", location);
        }
        return session.set("login_redirect_url", null);
    })
    .doIf(session -> session.getString("login_redirect_url") != null && !session.getString("login_redirect_url").isEmpty())
    .exec(
        http("GET login redirect")
            .get(session -> session.getString("login_redirect_url"))
            .check(
                status().in(200, 302),
                header("Set-Cookie").optional().saveAs("login_set_cookie2"),
                bodyString().optional().saveAs("login_response_body2")
            )
    )
    .exec(session -> {
        String setCookie = session.getString("login_set_cookie");
        if (setCookie == null) setCookie = session.getString("login_set_cookie2");
        String body = session.getString("login_response_body");
        if (body == null) body = session.getString("login_response_body2");
        String csrf = null;
        if (body != null) {
            csrf = extractFirst(body, CSRF_JSON_PATTERN);
        }
        if (csrf == null) {
            // Try to extract from set-cookie or body
            if (body != null) {
                Matcher m = Pattern.compile("\"csrf\"\\s*:\\s*\"([^\"]+)\"").matcher(body);
                if (m.find()) csrf = m.group(1);
            }
        }
        if (csrf != null) {
            session = session.set(CSRF_TOKEN, csrf);
        }
        if (setCookie != null) {
            // Extract session cookie value
            String[] parts = setCookie.split(";");
            for (String part : parts) {
                String trimmed = part.trim();
                if (trimmed.toLowerCase().startsWith("session=") || trimmed.toLowerCase().startsWith("sessionid=") || trimmed.toLowerCase().startsWith("sid=")) {
                    String cookieValue = trimmed.substring(trimmed.indexOf('=') + 1);
                    session = session.set(SESSION_COOKIE, cookieValue);
                    break;
                }
            }
            if (session.getString(SESSION_COOKIE) == null) {
                // Just store the whole set-cookie
                session = session.set(SESSION_COOKIE, setCookie);
            }
        }
        return session;
    })
    .exec(session -> {
        // Ensure we have a CSRF token; if not, try to get from a fresh form
        if (session.getString(CSRF_TOKEN) == null) {
            return session.set("need_fresh_csrf", true);
        }
        return session.set("need_fresh_csrf", false);
    })
    .doIf(session -> session.getBoolean("need_fresh_csrf"))
    .exec(
        http("GET /v2/login-form again for csrf")
            .get("/v2/login-form")
            .check(
                status().is(200),
                bodyString().saveAs("csrf_form_body")
            )
    )
    .exec(session -> {
        String body = session.getString("csrf_form_body");
        String csrf = null;
        if (body != null) {
            csrf = extractFirst(body, CSRF_INPUT_PATTERN, CSRF_INPUT_PATTERN2, CSRF_INPUT_PATTERN3, CSRF_INPUT_PATTERN4);
            if (csrf == null) {
                Matcher m = Pattern.compile("name\\s*=\\s*[\"']csrf[\"']", Pattern.CASE_INSENSITIVE).matcher(body);
                if (m.find()) {
                    int pos = m.end();
                    String rest = body.substring(pos);
                    Matcher vm = Pattern.compile("value\\s*=\\s*[\"']([^\"']+)[\"']", Pattern.CASE_INSENSITIVE).matcher(rest);
                    if (vm.find()) csrf = vm.group(1);
                }
            }
        }
        if (csrf != null) {
            session = session.set(CSRF_TOKEN, csrf);
        }
        return session;
    });

