    .exec(
        http("PATCH /v2/carts/{id}")
            .patch(session -> session.getString("patch_cart_url"))
            .header("X-CSRF-Token", session -> session.getString(CSRF_TOKEN))
            .header("If-Match", session -> session.getString("patch_cart_etag"))
            .body(StringBody(session -> session.getString("patch_cart_json")))
            .check(
                status().in(200, 412),
                header("ETag").optional().saveAs("patch_etag_header"),
                bodyString().optional().saveAs("patch_cart_body")
