        return session;
    })
    .doIf(session -> session.getInt("patch_cart_status") == 412 && !session.getBoolean(PATCH_RETRY_DONE))
    .exec(session -> session.set(PATCH_RETRY_DONE, true))
    .exec(getCart)
    .exec(session -> {
