    // ---------- ChainBuilder: Reservation ----------
    private static ChainBuilder doReservation = exec(session -> {
        String cartId = session.getString(CART_ID);
        String json = String.format("{\"cart_id\":%s}", cartId);
        return session.set("reservation_json", json);
    })
    .exec(
        http("POST /v2/reservations")
            .post("/v2/reservations")
            .header("X-CSRF-Token", session -> session.getString(CSRF_TOKEN))
            .body(StringBody(session -> session.getString("reservation_json")))
            .check(
                status().is(202),
                bodyString().saveAs("reservation_body")
            )
    )
    .exec(session -> {
        String body = session.getString("reservation_body");
        String statusUrl = null;
        String csrf = null;
        if (body != null) {
            statusUrl = extractFirst(body, STATUS_URL_PATTERN);
            csrf = extractFirst(body, CSRF_JSON_PATTERN);
        }
        if (statusUrl != null) session = session.set(LAST_STATUS_URL, statusUrl);
        if (csrf != null) session = session.set(CSRF_TOKEN, csrf);
        session = session.set(RESERVATION_POLL_COUNT, 0);
        return session;
    })
    .exec(session -> {
        String statusUrl = session.getString(LAST_STATUS_URL);
        return session.set("reservation_status_url", statusUrl);
    })
    .asLongAs(session -> {
        int count = session.getInt(RESERVATION_POLL_COUNT);
        String status = session.getString("reservation_status");
        return count < 5 && !"ready".equals(status);
    })
    .on(
        exec(session -> {
            int count = session.getInt(RESERVATION_POLL_COUNT);
            return session.set(RESERVATION_POLL_COUNT, count + 1);
        })
        .pause(Duration.ofMillis(60))
        .exec(
            http("GET reservation status")
                .get(session -> session.getString("reservation_status_url"))
                .check(
                    status().is(200),
                    bodyString().saveAs("reservation_status_body")
                )
        )
        .exec(session -> {
            String body = session.getString("reservation_status_body");
            String status = null;
            String reservationId = null;
            String csrf = null;
            if (body != null) {
                status = extractFirst(body, STATUS_PATTERN);
                reservationId = extractFirst(body, RESERVATION_ID_PATTERN);
                csrf = extractFirst(body, CSRF_JSON_PATTERN);
            }
            if (status != null) session = session.set("reservation_status", status);
            if (reservationId != null) session = session.set(RESERVATION_ID, reservationId);
            if (csrf != null) session = session.set(CSRF_TOKEN, csrf);
            return session;
        })
    )
    .exec(session -> {
        String status = session.getString("reservation_status");
        if ("ready".equals(status) && session.getString(RESERVATION_ID) != null) {
            return session.set(RESERVATION_READY, true);
        }
