import os
import time
import random
from locust import HttpUser, task, between, LoadTestShape, StopUser
from locust.exception import StopUser


class ShopUser(HttpUser):
    wait_time = between(0.1, 0.3)

    def __init__(self, *args, **kwargs):
        super().__init__(*args, **kwargs)
        self.session_csrf = None
        self.cart_id = None
        self.cart_etag = None
        self.grant_id = None
        self.iterations_done = 0
        self.max_iterations = 2
        self.profile = None
        self.expire_after = 2
        self.html_layout = 0
        self.reverse_catalog = False
        self.order_committed = False
        self.recovery_attempts = 0
        self.max_recovery_attempts = 3

    def on_start(self):
        self.client.trust_env = False
        self.client.headers.update({"Accept": "application/json"})
        self.profile = self._get_profile()
        self.expire_after = self.profile.get("expire_after", 2)
        self.html_layout = self.profile.get("html_layout", 0)
        self.reverse_catalog = self.profile.get("reverse_catalog", False)

    def _get_profile(self):
        # Profiles are assigned by the harness; default to first profile
        profiles = [{"expire_after": 2}, {"expire_after": 2, "html_layout": 1, "reverse_catalog": True}]
        # Use user index to assign profile
        user_index = getattr(self, "user_index", 0)
        return profiles[user_index % len(profiles)]

    def _get_csrf_from_form(self, html):
        import re
        # Look for input[name=csrf] with value
        match = re.search(r'<input[^>]*name=["\']csrf["\'][^>]*value=["\']([^"\']+)["\']', html, re.IGNORECASE)
        if match:
            return match.group(1)
        # Try reversed attribute order
        match = re.search(r'<input[^>]*value=["\']([^"\']+)["\'][^>]*name=["\']csrf["\']', html, re.IGNORECASE)
        if match:
            return match.group(1)
        return None

    def _get_login_nonce(self):
        with self.client.get("/v2/login-form", catch_response=True) as resp:
            if resp.status_code == 200:
                csrf = self._get_csrf_from_form(resp.text)
                if csrf:
                    self.session_csrf = csrf
                    return True
                else:
                    resp.failure("No CSRF token found in login form")
                    return False
            else:
                resp.failure(f"Login form failed: {resp.status_code}")
                return False

    def _login(self):
        if not self._get_login_nonce():
            return False
        with self.client.post("/v2/login", 
                             json={"username": "bench-1", "password": "bench", "csrf": self.session_csrf},
                             headers={"X-CSRF-Token": self.session_csrf},
                             catch_response=True) as resp:
            if resp.status_code == 200:
                data = resp.json()
                self.session_csrf = data.get("csrf", self.session_csrf)
                return True
            elif resp.status_code == 302:
                # Disable auto redirects, get Location manually
                location = resp.headers.get("Location")
                if location:
                    with self.client.get(location, catch_response=True) as resp2:
                        if resp2.status_code == 200:
                            data = resp2.json()
                            self.session_csrf = data.get("csrf", self.session_csrf)
                            return True
                        else:
                            resp2.failure(f"Login redirect failed: {resp2.status_code}")
                            return False
                else:
                    resp.failure("302 without Location")
                    return False
            else:
                resp.failure(f"Login failed: {resp.status_code}")
                return False

    def _get_catalog_product(self):
        """Get a product from catalog, optionally traversing pages."""
        products = []
        with self.client.get("/v2/catalog", catch_response=True) as resp:
            if resp.status_code == 200:
                data = resp.json()
                products.extend(data.get("data", {}).get("products", []))
            else:
                resp.failure(f"Catalog failed: {resp.status_code}")
                return None

        # Traverse at most 3 pages
        for _ in range(3):
            if not products:
                break
            with self.client.get("/v2/catalog/page", catch_response=True) as resp:
                if resp.status_code == 200:
                    data = resp.json()
                    if "product" in data:
                        products.append(data["product"])
                    next_url = data.get("next")
                    if not next_url:
                        break
                else:
                    resp.failure(f"Catalog page failed: {resp.status_code}")
                    break

        if not products:
            return None

        if self.reverse_catalog:
            products.reverse()

        for product in products:
            for variant in product.get("variants", []):
                if variant.get("in_stock", False):
                    return product["id"], variant["id"]
        return None

    def _get_challenge_grant(self):
        """Complete challenge to get grant_id."""
        with self.client.get("/v2/challenge-form", catch_response=True) as resp:
            if resp.status_code != 200:
                resp.failure(f"Challenge form failed: {resp.status_code}")
                return False
            html = resp.text
            import re
            action_match = re.search(r'<form[^>]*action=["\']([^"\']+)["\']', html, re.IGNORECASE)
            challenge_match = re.search(r'<input[^>]*name=["\']challenge["\'][^>]*>', html, re.IGNORECASE)
            if not action_match or not challenge_match:
                resp.failure("Challenge form missing action or challenge input")
                return False
            action = action_match.group(1)

        with self.client.post(action, 
                             json={"challenge": "bench"},
                             headers={"X-CSRF-Token": self.session_csrf},
                             catch_response=True) as resp:
            if resp.status_code == 302:
                location = resp.headers.get("Location")
                if not location:
                    resp.failure("Challenge 302 without Location")
                    return False
                with self.client.get(location, catch_response=True) as resp2:
                    if resp2.status_code == 200:
                        data = resp2.json()
                        self.grant_id = data.get("grant_id")
                        self.session_csrf = data.get("csrf", self.session_csrf)
                        return self.grant_id is not None
                    else:
                        resp2.failure(f"Challenge redirect failed: {resp2.status_code}")
                        return False
            elif resp.status_code == 200:
                data = resp.json()
                self.grant_id = data.get("grant_id")
                self.session_csrf = data.get("csrf", self.session_csrf)
                return self.grant_id is not None
            else:
                resp.failure(f"Challenge failed: {resp.status_code}")
                return False

    def _create_cart(self, product_id, variant_id):
        payload = {"product_id": product_id, "variant_id": variant_id}
        if self.grant_id:
            payload["grant_id"] = self.grant_id
        with self.client.post("/v2/carts",
                             json=payload,
                             headers={"X-CSRF-Token": self.session_csrf},
                             catch_response=True) as resp:
            if resp.status_code == 201:
                data = resp.json()
                self.cart_id = data.get("id")
                self.session_csrf = data.get("csrf", self.session_csrf)
                self.cart_etag = resp.headers.get("ETag")
                return True
            elif resp.status_code == 401:
                error = resp.json().get("error", "")
                if error == "expired":
                    return self._handle_expiry("create_cart", product_id, variant_id)
                elif error == "session":
                    return self._handle_session_revoked("create_cart", product_id, variant_id)
                elif error == "denied":
                    resp.failure("Denied error on cart creation")
                    return False
                else:
                    resp.failure(f"Unknown 401 error: {error}")
                    return False
            else:
                resp.failure(f"Cart creation failed: {resp.status_code}")
                return False

    def _handle_expiry(self, operation, *args):
        """Handle session expiry: renew session and retry operation."""
        if self.recovery_attempts >= self.max_recovery_attempts:
            return False
        self.recovery_attempts += 1

        # Renew session
        with self.client.post("/v2/session/renew",
                             json={},
                             headers={"X-CSRF-Token": self.session_csrf},
                             catch_response=True) as resp:
            if resp.status_code == 200:
                data = resp.json()
                self.session_csrf = data.get("csrf", self.session_csrf)
            elif resp.status_code == 401:
                error = resp.json().get("error", "")
                if error == "session":
                    # Session revoked, need full re-login
                    if not self._login():
                        resp.failure("Re-login failed after session revoked")
                        return False
                else:
                    resp.failure(f"Session renew failed: {resp.status_code}")
                    return False
            else:
                resp.failure(f"Session renew failed: {resp.status_code}")
                return False

        # Recover cart if it exists
        if self.cart_id:
            with self.client.post(f"/v2/carts/{self.cart_id}/recover",
                                 json={},
                                 headers={"X-CSRF-Token": self.session_csrf},
                                 catch_response=True) as resp:
                if resp.status_code == 200:
                    data = resp.json()
                    self.session_csrf = data.get("csrf", self.session_csrf)
                    self.cart_etag = resp.headers.get("ETag", self.cart_etag)
                elif resp.status_code == 401:
                    error = resp.json().get("error", "")
                    if error == "session":
                        if not self._login():
                            resp.failure("Re-login failed during cart recovery")
                            return False
                        # Retry recovery once
                        with self.client.post(f"/v2/carts/{self.cart_id}/recover",
                                             json={},
                                             headers={"X-CSRF-Token": self.session_csrf},
                                             catch_response=True) as resp2:
                            if resp2.status_code == 200:
                                data = resp2.json()
                                self.session_csrf = data.get("csrf", self.session_csrf)
                                self.cart_etag = resp2.headers.get("ETag", self.cart_etag)
                            else:
                                resp2.failure(f"Cart recovery retry failed: {resp2.status_code}")
                                return False
                    else:
                        resp.failure(f"Cart recovery failed with 401: {error}")
                        return False
                elif resp.status_code != 200:
                    resp.failure(f"Cart recovery failed: {resp.status_code}")
                    return False

        # Retry the interrupted operation
        if operation == "create_cart":
            return self._create_cart(*args)
        elif operation == "update_cart":
            return self._update_cart(*args)
        elif operation == "create_order":
            return self._create_order(*args)
        elif operation == "create_reservation":
            return self._create_reservation(*args)
        return False

    def _handle_session_revoked(self, operation, *args):
        """Handle revoked session: full re-login and recover cart."""
        if self.recovery_attempts >= self.max_recovery_attempts:
            return False
        self.recovery_attempts += 1

        if not self._login():
            return False

        # Recover cart if it exists
        if self.cart_id:
            with self.client.post(f"/v2/carts/{self.cart_id}/recover",
                                 json={},
                                 headers={"X-CSRF-Token": self.session_csrf},
                                 catch_response=True) as resp:
                if resp.status_code == 200:
                    data = resp.json()
                    self.session_csrf = data.get("csrf", self.session_csrf)
                    self.cart_etag = resp.headers.get("ETag", self.cart_etag)
                else:
                    resp.failure(f"Cart recovery after re-login failed: {resp.status_code}")
                    return False

        # Retry the interrupted operation
        if operation == "create_cart":
            return self._create_cart(*args)
        elif operation == "update_cart":
            return self._update_cart(*args)
        elif operation == "create_order":
            return self._create_order(*args)
        elif operation == "create_reservation":
            return self._create_reservation(*args)
        return False

    def _update_cart(self, quantity):
        if not self.cart_id:
            return False
        headers = {"X-CSRF-Token": self.session_csrf}
        if self.cart_etag:
            headers["If-Match"] = self.cart_etag
        with self.client.patch(f"/v2/carts/{self.cart_id}",
                              json={"quantity": quantity},
                              headers=headers,
                              catch_response=True) as resp:
            if resp.status_code == 200:
                data = resp.json()
                self.session_csrf = data.get("csrf", self.session_csrf)
                self.cart_etag = resp.headers.get("ETag", self.cart_etag)
                return True
            elif resp.status_code == 412:
                # Re-read and retry once
                with self.client.get(f"/v2/carts/{self.cart_id}", catch_response=True) as resp2:
                    if resp2.status_code == 200:
                        self.cart_etag = resp2.headers.get("ETag")
                        headers["If-Match"] = self.cart_etag
                        with self.client.patch(f"/v2/carts/{self.cart_id}",
                                              json={"quantity": quantity},
                                              headers=headers,
                                              catch_response=True) as resp3:
                            if resp3.status_code == 200:
                                data = resp3.json()
                                self.session_csrf = data.get("csrf", self.session_csrf)
                                self.cart_etag = resp3.headers.get("ETag", self.cart_etag)
                                return True
                            elif resp3.status_code == 401:
                                error = resp3.json().get("error", "")
                                if error == "expired":
                                    return self._handle_expiry("update_cart", quantity)
                                elif error == "session":
                                    return self._handle_session_revoked("update_cart", quantity)
                                else:
                                    resp3.failure(f"Cart update retry failed: {resp3.status_code}")
                                    return False
                            else:
                                resp3.failure(f"Cart update retry failed: {resp3.status_code}")
                                return False
                    else:
                        resp2.failure(f"Cart re-read failed: {resp2.status_code}")
                        return False
            elif resp.status_code == 401:
                error = resp.json().get("error", "")
                if error == "expired":
                    return self._handle_expiry("update_cart", quantity)
                elif error == "session":
                    return self._handle_session_revoked("update_cart", quantity)
                elif error == "denied":
                    resp.failure("Denied error on cart update")
                    return False
                else:
                    resp.failure(f"Unknown 401 error on cart update: {error}")
                    return False
            else:
                resp.failure(f"Cart update failed: {resp.status_code}")
                return False

    def _create_reservation(self):
        if not self.cart_id:
            return False
        with self.client.post("/v2/reservations",
                             json={"cart_id": self.cart_id},
                             headers={"X-CSRF-Token": self.session_csrf},
                             catch_response=True) as resp:
            if resp.status_code == 202:
                data = resp.json()
                status_url = data.get("status_url")
                self.session_csrf = data.get("csrf", self.session_csrf)
                if not status_url:
                    resp.failure("No status_url in reservation response")
                    return False
                # Poll at least 50ms apart, at most 5 times
                for _ in range(5):
                    time.sleep(0.05)
                    with self.client.get(status_url, catch_response=True) as resp2:
                        if resp2.status_code == 200:
                            status_data = resp2.json()
                            status = status_data.get("status")
                            if status == "ready":
                                self.reservation_id = status_data.get("reservation_id")
                                self.session_csrf = status_data.get("csrf", self.session_csrf)
                                return self.reservation_id is not None
                            elif status == "pending":
                                continue
                            elif status == "failed":
                                resp2.failure("Reservation failed")
                                return False
                        else:
                            resp2.failure(f"Reservation poll failed: {resp2.status_code}")
                            return False
                resp.failure("Reservation polling exhausted")
                return False
            elif resp.status_code == 401:
                error = resp.json().get("error", "")
                if error == "expired":
                    return self._handle_expiry("create_reservation")
                elif error == "session":
                    return self._handle_session_revoked("create_reservation")
                else:
                    resp.failure(f"Reservation 401: {error}")
                    return False
            else:
                resp.failure(f"Reservation failed: {resp.status_code}")
                return False

    def _create_order(self, idempotency_key):
        if not self.cart_id:
            return False
        payload = {"cart_id": self.cart_id}
        if hasattr(self, "reservation_id") and self.reservation_id:
            payload["reservation_id"] = self.reservation_id
        headers = {
            "X-CSRF-Token": self.session_csrf,
            "Idempotency-Key": idempotency_key
        }
        if self.cart_etag:
            headers["If-Match"] = self.cart_etag
        with self.client.post("/v2/orders",
                             json=payload,
                             headers=headers,
                             catch_response=True) as resp:
            if resp.status_code == 201:
                data = resp.json()
                if data.get("accepted", False):
                    self.session_csrf = data.get("csrf", self.session_csrf)
                    self.order_committed = True
                    return True
                else:
                    resp.failure("Order not accepted (accepted: false)")
                    return False
            elif resp.status_code == 200:
                data = resp.json()
                if data.get("accepted", False):
                    self.session_csrf = data.get("csrf", self.session_csrf)
                    self.order_committed = True
                    return True
                else:
                    resp.failure("Order not accepted (200 accepted: false)")
                    return False
            elif resp.status_code == 401:
                error = resp.json().get("error", "")
                if error == "expired":
                    return self._handle_expiry("create_order", idempotency_key)
                elif error == "session":
                    return self._handle_session_revoked("create_order", idempotency_key)
                elif error == "denied":
                    resp.failure("Denied error on order creation")
                    return False
                else:
                    resp.failure(f"Unknown 401 error on order: {error}")
                    return False
            else:
                resp.failure(f"Order creation failed: {resp.status_code}")
                return False

    def _do_work(self):
        """Perform scheduled work."""
        for _ in range(4):
            with self.client.post("/v2/work",
                                 json={},
                                 headers={"X-CSRF-Token": self.session_csrf},
                                 catch_response=True) as resp:
                if resp.status_code == 200:
                    return True
                elif resp.status_code == 429:
                    retry_after = int(resp.headers.get("Retry-After", "1"))
                    time.sleep(retry_after)
                    continue
                elif resp.status_code == 401:
                    error = resp.json().get("error", "")
                    if error == "expired":
                        if not self._handle_expiry("work"):
                            resp.failure("Work expiry recovery failed")
                            return False
                        continue
                    elif error == "session":
                        if not self._handle_session_revoked("work"):
                            resp.failure("Work session recovery failed")
                            return False
                        continue
                    else:
                        resp.failure(f"Work 401: {error}")
                        return False
                else:
                    resp.failure(f"Work failed: {resp.status_code}")
                    return False
        resp.failure("Work retries exhausted")
        return False

    def _journey(self):
        """Complete one business journey: login, cart, order."""
        self.order_committed = False
        self.recovery_attempts = 0
        self.cart_id = None
        self.cart_etag = None
        self.grant_id = None
        self.reservation_id = None

        # Fresh login
        if not self._login():
            return False

        # Get challenge grant
        if not self._get_challenge_grant():
            return False

        # Get catalog product
        product_info = self._get_catalog_product()
        if not product_info:
            return False
        product_id, variant_id = product_info

        # Create cart
        if not self._create_cart(product_id, variant_id):
            return False

        # Update cart quantity
        if not self._update_cart(1):
            return False

        # Create reservation
        if not self._create_reservation():
            return False

        # Create order with unique idempotency key
        idempotency_key = f"order-{self.cart_id}-{int(time.time() * 1000)}"
        if not self._create_order(idempotency_key):
            return False

        # Do work
        if not self._do_work():
            return False

        return self.order_committed

    @task
    def shop_journey(self):
        if self.iterations_done >= self.max_iterations:
            raise StopUser()

        self.iterations_done += 1
        success = self._journey()
        if not success:
            # Mark as failed sample
            with self.client.post("/v2/work",
                                 json={},
                                 headers={"X-CSRF-Token": self.session_csrf or ""},
                                 catch_response=True) as resp:
                resp.failure("Journey failed to complete")

        if self.iterations_done >= self.max_iterations:
            raise StopUser()


class ShopLoadShape(LoadTestShape):
    def tick(self):
        run_time = self.get_run_time()
        if run_time < 60:
            return (2, 2)
        else:
            return None
