package default;

import io.gatling.javaapi.core.*;
import io.gatling.javaapi.http.*;
import io.gatling.javaapi.core.CoreDsl.*;
import io.gatling.javaapi.http.HttpDsl.*;

import java.time.Duration;
import java.util.*;
import java.util.concurrent.ThreadLocalRandom;

public class ModelSimulation extends Simulation {

    private static final String BASE_URL = System.getenv().getOrDefault("BASE_URL", "http://127.0.0.1:8000");

    private static final Map<String, String> OWNER_SEEDS = new LinkedHashMap<>();

    private static final HttpProtocolBuilder httpProtocol =
            http.baseUrl(BASE_URL)
                    .disableAutoRedirect()
                    .acceptHeader("application/json")
                    .contentTypeHeader("application/json")
                    .userAgentHeader("gatling-bench");

    private static String randomAccount() {
        int idx = ThreadLocalRandom.current().nextInt(1, 17);
        return "bench-" + idx;
    }

    private static String uniqueIdempotencyKey(String cartId) {
        return "idem-" + cartId + "-" + UUID.randomUUID();
    }

    private static ChainBuilder loginJourney() {
        return exec(session -> session.set("username", randomAccount()))
                .exec(http("GET login form")
                        .get("/v2/login-form")
                        .check(status().is(200))
                        .check(regex("name=\"csrf\" value=\"([^\"]+)\"").find().saveAs("loginCsrf"))
                        .check(regex("name=\"csrf\" value=\"([^\"]+)\"").find().saveAs("csrf"))
                        .check(regex("name=\"csrf\" value=\"([^\"]+)\"").find().saveAs("currentCsrf")))
                .exec(session -> {
                    String csrf = session.getString("loginCsrf");
                    String username = session.getString("username");
                    return session.set("loginBody", String.format("{\"username\":\"%s\",\"password\":\"bench\",\"csrf\":\"%s\"}", username, csrf));
                })
                .exec(http("POST login")
                        .post("/v2/login")
                        .body(StringBody(session -> session.getString("loginBody")))
                        .check(status().is(200))
                        .check(jsonPath("$.csrf").optional().saveAs("csrf"))
                        .check(jsonPath("$.csrf").optional().saveAs("currentCsrf"))
                        .check(jsonPath("$.user").exists()))
                .exec(session -> {
                    String csrf = session.getString("csrf");
                    if (csrf == null || csrf.isEmpty()) {
                        csrf = session.getString("loginCsrf");
                    }
                    return session.set("csrf", csrf).set("currentCsrf", csrf);
                });
    }

    private static ChainBuilder createCart() {
        return exec(session -> session.set("cartCreated", false))
                .exec(http("GET catalog")
                        .get("/v2/catalog")
                        .header("X-CSRF-Token", session -> session.getString("currentCsrf"))
                        .check(status().is(200))
                        .check(jsonPath("$.data.products[0].id").saveAs("productId"))
                        .check(jsonPath("$.data.products[0].variants[0].id").saveAs("variantId"))
                        .check(jsonPath("$.data.products[0].variants[0].in_stock").saveAs("inStock")))
                .exec(session -> {
                    String inStock = session.getString("inStock");
                    if (!"true".equals(inStock)) {
                        throw new RuntimeException("First variant not in stock");
                    }
                    return session;
                })
                .exec(http("POST create cart")
                        .post("/v2/carts")
                        .header("X-CSRF-Token", session -> session.getString("currentCsrf"))
                        .body(StringBody(session -> {
                            String productId = session.getString("productId");
                            String variantId = session.getString("variantId");
                            return String.format("{\"product_id\":\"%s\",\"variant_id\":\"%s\"}", productId, variantId);
                        }))
                        .check(status().is(201))
                        .check(jsonPath("$.id").saveAs("cartId"))
                        .check(jsonPath("$.csrf").optional().saveAs("csrf"))
                        .check(jsonPath("$.csrf").optional().saveAs("currentCsrf"))
                        .check(header("ETag").optional().saveAs("etag")))
                .exec(session -> {
                    String csrf = session.getString("csrf");
                    if (csrf != null && !csrf.isEmpty()) {
                        session = session.set("currentCsrf", csrf);
                    }
                    return session.set("cartCreated", true);
                });
    }

    private static ChainBuilder createReservation(int maxPolls, double pollIntervalSeconds) {
        return exec(http("POST reservation")
                .post("/v2/reservations")
                .header("X-CSRF-Token", session -> session.getString("currentCsrf"))
                .body(StringBody(session -> String.format("{\"cart_id\":\"%s\"}", session.getString("cartId"))))
                .check(status().is(202))
                .check(jsonPath("$.status_url").saveAs("statusUrl"))
                .check(jsonPath("$.csrf").optional().saveAs("csrf"))
                .check(jsonPath("$.csrf").optional().saveAs("currentCsrf")))
                .exec(session -> {
                    String csrf = session.getString("csrf");
                    if (csrf != null && !csrf.isEmpty()) {
                        session = session.set("currentCsrf", csrf);
                    }
                    return session.set("pollCount", 0)
                            .set("reservationReady", false)
                            .set("reservationId", "")
                            .set("jobFailed", false);
                })
                .asLongAs(session -> {
                    int polls = session.getInt("pollCount");
                    boolean ready = session.getBoolean("reservationReady");
                    boolean failed = session.getBoolean("jobFailed");
                    return polls < maxPolls && !ready && !failed;
                }).on(
                        pause(Duration.ofMillis((long) (pollIntervalSeconds * 1000)))
                                .exec(session -> session.set("pollCount", session.getInt("pollCount") + 1))
                                .exec(http("GET reservation status")
                                        .get(session -> session.getString("statusUrl"))
                                        .header("X-CSRF-Token", session -> session.getString("currentCsrf"))
                                        .check(status().is(200))
                                        .check(jsonPath("$.status").saveAs("jobStatus"))
                                        .check(jsonPath("$.reservation_id").optional().saveAs("reservationId"))
                                        .check(jsonPath("$.csrf").optional().saveAs("csrf"))
                                        .check(jsonPath("$.csrf").optional().saveAs("currentCsrf")))
                                .exec(session -> {
                                    String csrf = session.getString("csrf");
                                    if (csrf != null && !csrf.isEmpty()) {
                                        session = session.set("currentCsrf", csrf);
                                    }
                                    String status = session.getString("jobStatus");
                                    if ("ready".equals(status)) {
                                        String reservationId = session.getString("reservationId");
                                        if (reservationId == null || reservationId.isEmpty()) {
                                            throw new RuntimeException("ready status without reservation_id");
                                        }
                                        return session.set("reservationReady", true);
                                    } else if ("failed".equals(status)) {
                                        return session.set("jobFailed", true);
                                    } else if ("pending".equals(status)) {
                                        return session;
                                    } else {
                                        throw new RuntimeException("Unexpected reservation status: " + status);
                                    }
                                })
                );
    }

    private static ChainBuilder checkoutWithReservation() {
        return exec(session -> session.set("idempotencyKey", uniqueIdempotencyKey(session.getString("cartId"))))
                .exec(http("POST order with reservation")
                        .post("/v2/orders")
                        .header("X-CSRF-Token", session -> session.getString("currentCsrf"))
                        .header("Idempotency-Key", session -> session.getString("idempotencyKey"))
                        .body(StringBody(session -> {
                            String cartId = session.getString("cartId");
                            String reservationId = session.getString("reservationId");
                            return String.format("{\"cart_id\":\"%s\",\"reservation_id\":\"%s\"}", cartId, reservationId);
                        }))
                        .check(status().is(201))
                        .check(jsonPath("$.accepted").is("true"))
                        .check(jsonPath("$.id").saveAs("orderId"))
                        .check(jsonPath("$.csrf").optional().saveAs("csrf"))
                        .check(jsonPath("$.csrf").optional().saveAs("currentCsrf")))
                .exec(session -> {
                    String csrf = session.getString("csrf");
                    if (csrf != null && !csrf.isEmpty()) {
                        session = session.set("currentCsrf", csrf);
                    }
                    return session;
                });
    }

    private static ChainBuilder workSample() {
        return exec(http("POST work")
                .post("/v2/work")
                .header("X-CSRF-Token", session -> session.getString("currentCsrf"))
                .body(StringBody("{}"))
                .check(status().is(200))
                .check(jsonPath("$.ok").is("true")));
    }

    private static ChainBuilder fullJourney(int maxPolls, double pollIntervalSeconds, boolean negativeControl) {
        ChainBuilder chain = exec(loginJourney())
                .exec(createCart());

        if (negativeControl) {
            chain = chain.exec(createReservation(maxPolls, pollIntervalSeconds))
                    .exec(session -> {
                        boolean ready = session.getBoolean("reservationReady");
                        if (ready) {
                            throw new RuntimeException("Negative control: job unexpectedly succeeded");
                        }
                        return session;
                    });
        } else {
            chain = chain.exec(createReservation(maxPolls, pollIntervalSeconds))
                    .exec(session -> {
                        boolean ready = session.getBoolean("reservationReady");
                        if (!ready) {
                            throw new RuntimeException("Reservation never became ready");
                        }
                        return session;
                    })
                    .exec(checkoutWithReservation());
        }

        return chain.exec(workSample());
    }

    private static ChainBuilder profile1Journey() {
        return fullJourney(2, 0.02, false);
    }

    private static ChainBuilder profile2Journey() {
        return fullJourney(3, 0.02, false);
    }

    private static ChainBuilder negativeControlJourney() {
        return fullJourney(2, 0.02, true);
    }

    {
        Map<String, ChainBuilder> journeys = new LinkedHashMap<>();
        journeys.put("profile1", profile1Journey());
        journeys.put("profile2", profile2Journey());
        journeys.put("negativeControl", negativeControlJourney());

        setUp(
                journeys.get("profile1").injectOpen(atOnceUsers(1)),
                journeys.get("profile2").injectOpen(atOnceUsers(1)),
                journeys.get("negativeControl").injectOpen(atOnceUsers(1))
        ).protocols(httpProtocol);

        afterSimulation(() -> {
            System.out.println("OWNER_SEEDS=" + OWNER_SEEDS);
        });
    }
}

