import http from 'k6/http';
import { check, sleep, fail } from 'k6';
import { Rate } from 'k6/metrics';

const BASE_URL = __ENV.BASE_URL || 'http://127.0.0.1:8000';
const businessFailure = new Rate('business_failure');

const PROFILES = [
  { job_polls: 2, poll_interval: 0.02 },
  { job_polls: 3, poll_interval: 0.02, html_layout: 1, reverse_catalog: true }
];

const NEGATIVE_OVERRIDES = [
  { job_fails: true }
];

function getProfile(vuId) {
  const profile = PROFILES[(vuId - 1) % PROFILES.length];
  const override = NEGATIVE_OVERRIDES[(vuId - 1) % NEGATIVE_OVERRIDES.length];
  return Object.assign({}, profile, override);
}

function extractCsrf(html) {
  const match = html.match(/name=["']csrf["'][^>]*value=["']([^"']+)["']/i) ||
                html.match(/value=["']([^"']+)["'][^>]*name=["']csrf["']/i);
  if (!match) {
    const inputMatch = html.match(/<input[^>]+name=["']csrf["'][^>]*>/i);
    if (inputMatch) {
      const valMatch = inputMatch[0].match(/value=["']([^"']+)["']/i);
      if (valMatch) return valMatch[1];
    }
    return null;
  }
  return match[1];
}

function extractNonce(html) {
  const match = html.match(/name=["']login_nonce["'][^>]*value=["']([^"']+)["']/i) ||
                html.match(/value=["']([^"']+)["'][^>]*name=["']login_nonce["']/i);
  return match ? match[1] : null;
}

function extractChallengeAction(html) {
  const match = html.match(/<form[^>]+action=["']([^"']*\/challenges\/[^"']+)["']/i);
  return match ? match[1] : null;
}

function extractChallengeInput(html) {
  const match = html.match(/<input[^>]+name=["']challenge["'][^>]*>/i);
  if (match) {
    const valMatch = match[0].match(/value=["']([^"']+)["']/i);
    return valMatch ? valMatch[1] : null;
  }
  return null;
}

function extractLocation(response) {
  return response.headers['Location'] || null;
}

function getCsrfFromResponse(response) {
  try {
    const body = response.json();
    if (body && body.csrf) return body.csrf;
  } catch (e) {
    // not json
  }
  return null;
}

function login(httpClient, username, password) {
  const formRes = httpClient.get(`${BASE_URL}/v2/login-form`, { redirects: 0 });
  check(formRes, {
    'login form loads': (r) => r.status === 200 || r.status === 302
  });

  let csrf = null;
  let nonce = null;

  if (formRes.status === 200) {
    csrf = extractCsrf(formRes.body);
    nonce = extractNonce(formRes.body);
  } else if (formRes.status === 302) {
    const loc = extractLocation(formRes);
    if (loc) {
      const locRes = httpClient.get(loc.startsWith('http') ? loc : `${BASE_URL}${loc}`, { redirects: 0 });
      if (locRes.status === 200) {
        csrf = extractCsrf(locRes.body);
        nonce = extractNonce(locRes.body);
      }
    }
  }

  if (!csrf) {
    fail('Could not extract csrf from login form');
  }

  const loginPayload = {
    username: username,
    password: password,
    csrf: csrf
  };
  if (nonce) {
    loginPayload.login_nonce = nonce;
  }

  const loginRes = httpClient.post(`${BASE_URL}/v2/login`, JSON.stringify(loginPayload), {
    headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': csrf },
    redirects: 0
  });

  check(loginRes, {
    'login succeeds': (r) => r.status === 200 || r.status === 201 || r.status === 302
  });

  let sessionCsrf = csrf;
  if (loginRes.status === 200 || loginRes.status === 201) {
    const freshCsrf = getCsrfFromResponse(loginRes);
    if (freshCsrf) sessionCsrf = freshCsrf;
  } else if (loginRes.status === 302) {
    const loc = extractLocation(loginRes);
    if (loc) {
      const locRes = httpClient.get(loc.startsWith('http') ? loc : `${BASE_URL}${loc}`, { redirects: 0 });
      if (locRes.status === 200) {
        const freshCsrf = getCsrfFromResponse(locRes);
        if (freshCsrf) sessionCsrf = freshCsrf;
      }
    }
  }

  return sessionCsrf;
}

function getCatalog(httpClient, csrf, reverse) {
  const catalogRes = httpClient.get(`${BASE_URL}/v2/catalog`, {
    headers: { 'X-CSRF-Token': csrf }
  });
  check(catalogRes, { 'catalog loads': (r) => r.status === 200 });

  let products = [];
  try {
    const body = catalogRes.json();
    if (body && body.data && body.data.products) {
      products = body.data.products;
    }
  } catch (e) {
    fail('Catalog response not JSON');
  }

  if (products.length === 0) {
    // Try page traversal
    let nextUrl = '/v2/catalog/page';
    let pages = 0;
    while (nextUrl && pages < 3) {
      const pageRes = httpClient.get(`${BASE_URL}${nextUrl}`, {
        headers: { 'X-CSRF-Token': csrf }
      });
      check(pageRes, { 'catalog page loads': (r) => r.status === 200 });
      try {
        const body = pageRes.json();
        if (body && body.data && body.data.product) {
          products.push(body.data.product);
        }
        nextUrl = body && body.next ? body.next : null;
      } catch (e) {
        nextUrl = null;
      }
      pages++;
    }
  }

  if (reverse && products.length > 1) {
    products = products.slice().reverse();
  }

  return products;
}

function createCart(httpClient, csrf, productId, variantId, grantId) {
  const payload = {
    product_id: productId,
    variant_id: variantId
  };
  if (grantId) {
    payload.grant_id = grantId;
  }

  const res = httpClient.post(`${BASE_URL}/v2/carts`, JSON.stringify(payload), {
    headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': csrf }
  });

  check(res, { 'cart created': (r) => r.status === 201 });

  let cartId = null;
  let newCsrf = csrf;
  let etag = null;

  try {
    const body = res.json();
    cartId = body.id;
    if (body.csrf) newCsrf = body.csrf;
  } catch (e) {
    fail('Cart creation response not JSON');
  }

  etag = res.headers['ETag'] || null;

  return { cartId, csrf: newCsrf, etag };
}

function getCart(httpClient, csrf, cartId) {
  const res = httpClient.get(`${BASE_URL}/v2/carts/${cartId}`, {
    headers: { 'X-CSRF-Token': csrf }
  });
  check(res, { 'cart fetched': (r) => r.status === 200 });
  return {
    etag: res.headers['ETag'] || null,
    csrf: getCsrfFromResponse(res) || csrf
  };
}

function updateCartQuantity(httpClient, csrf, cartId, quantity, etag) {
  const payload = { quantity: quantity };
  const headers = {
    'Content-Type': 'application/json',
    'X-CSRF-Token': csrf
  };
  if (etag) {
    headers['If-Match'] = etag;
  }

  let res = httpClient.patch(`${BASE_URL}/v2/carts/${cartId}`, JSON.stringify(payload), {
    headers: headers
  });

  if (res.status === 412) {
    // Re-read and retry once
    const cartInfo = getCart(httpClient, csrf, cartId);
    const retryHeaders = {
      'Content-Type': 'application/json',
      'X-CSRF-Token': cartInfo.csrf
    };
    if (cartInfo.etag) {
      retryHeaders['If-Match'] = cartInfo.etag;
    }
    res = httpClient.patch(`${BASE_URL}/v2/carts/${cartId}`, JSON.stringify(payload), {
      headers: retryHeaders
    });
  }

  check(res, { 'cart updated': (r) => r.status === 200 || r.status === 201 });

  return {
    csrf: getCsrfFromResponse(res) || csrf,
    etag: res.headers['ETag'] || etag
  };
}

function solveChallenge(httpClient, csrf) {
  const challengeFormRes = httpClient.get(`${BASE_URL}/v2/challenge-form`, {
    headers: { 'X-CSRF-Token': csrf }
  });
  check(challengeFormRes, { 'challenge form loads': (r) => r.status === 200 });

  const action = extractChallengeAction(challengeFormRes.body);
  const challengeValue = extractChallengeInput(challengeFormRes.body);

  if (!action || !challengeValue) {
    fail('Could not extract challenge form data');
  }

  const actionUrl = action.startsWith('http') ? action : `${BASE_URL}${action}`;
  const challengeRes = httpClient.post(actionUrl, JSON.stringify({ challenge: challengeValue }), {
    headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': csrf },
    redirects: 0
  });

  check(challengeRes, { 'challenge submitted': (r) => r.status === 302 || r.status === 200 });

  let grantId = null;
  let newCsrf = csrf;

  if (challengeRes.status === 302) {
    const loc = extractLocation(challengeRes);
    if (loc) {
      const locUrl = loc.startsWith('http') ? loc : `${BASE_URL}${loc}`;
      const locRes = httpClient.get(locUrl, {
        headers: { 'X-CSRF-Token': csrf },
        redirects: 0
      });
      check(locRes, { 'challenge location loads': (r) => r.status === 200 });
      try {
        const body = locRes.json();
        grantId = body.grant_id;
        if (body.csrf) newCsrf = body.csrf;
      } catch (e) {
        fail('Challenge location response not JSON');
      }
    }
  } else if (challengeRes.status === 200) {
    try {
      const body = challengeRes.json();
      grantId = body.grant_id;
      if (body.csrf) newCsrf = body.csrf;
    } catch (e) {
      fail('Challenge response not JSON');
    }
  }

  return { grantId, csrf: newCsrf };
}

function createReservation(httpClient, csrf, cartId) {
  const res = httpClient.post(`${BASE_URL}/v2/reservations`, JSON.stringify({ cart_id: cartId }), {
    headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': csrf }
  });

  check(res, { 'reservation created': (r) => r.status === 202 });

  let statusUrl = null;
  let newCsrf = csrf;

  try {
    const body = res.json();
    statusUrl = body.status_url;
    if (body.csrf) newCsrf = body.csrf;
  } catch (e) {
    fail('Reservation response not JSON');
  }

  return { statusUrl, csrf: newCsrf };
}

function pollReservation(httpClient, csrf, statusUrl, maxPolls, pollInterval, jobFails) {
  let reservationId = null;
  let polls = 0;
  let finalCsrf = csrf;

  while (polls < maxPolls) {
    polls++;
    sleep(pollInterval);

    const pollUrl = statusUrl.startsWith('http') ? statusUrl : `${BASE_URL}${statusUrl}`;
    const res = httpClient.get(pollUrl, {
      headers: { 'X-CSRF-Token': finalCsrf }
    });

    check(res, { 'reservation poll responds': (r) => r.status === 200 });

    try {
      const body = res.json();
      if (body.csrf) finalCsrf = body.csrf;

      if (jobFails) {
        // Negative control: job should fail
        if (body.status === 'failed') {
          return { reservationId: null, csrf: finalCsrf, polls, status: 'failed' };
        }
        if (body.status === 'ready') {
          // Unexpected success in negative control
          return { reservationId: body.reservation_id, csrf: finalCsrf, polls, status: 'ready' };
        }
      } else {
        if (body.status === 'ready' && body.reservation_id) {
          reservationId = body.reservation_id;
          return { reservationId, csrf: finalCsrf, polls, status: 'ready' };
        }
        if (body.status === 'failed') {
          return { reservationId: null, csrf: finalCsrf, polls, status: 'failed' };
        }
      }
    } catch (e) {
      fail('Reservation poll response not JSON');
    }
  }

  return { reservationId: null, csrf: finalCsrf, polls, status: 'pending' };
}

function createOrder(httpClient, csrf, cartId, reservationId, etag, idempotencyKey) {
  const payload = {
    cart_id: cartId
  };
  if (reservationId) {
    payload.reservation_id = reservationId;
  }

  const headers = {
    'Content-Type': 'application/json',
    'X-CSRF-Token': csrf,
    'Idempotency-Key': idempotencyKey
  };
  if (etag) {
    headers['If-Match'] = etag;
  }

  let res = httpClient.post(`${BASE_URL}/v2/orders`, JSON.stringify(payload), {
    headers: headers
  });

  // Handle 401 expiry
  if (res.status === 401) {
    let errorType = null;
    try {
      const body = res.json();
      errorType = body.error;
    } catch (e) {
      // ignore
    }

    if (errorType === 'expired') {
      // Renew session
      const renewRes = httpClient.post(`${BASE_URL}/v2/session/renew`, JSON.stringify({}), {
        headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': csrf }
      });
      check(renewRes, { 'session renewed': (r) => r.status === 200 || r.status === 201 });
      const freshCsrf = getCsrfFromResponse(renewRes) || csrf;

      // Recover cart
      const recoverRes = httpClient.post(`${BASE_URL}/v2/carts/${cartId}/recover`, JSON.stringify({}), {
        headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': freshCsrf }
      });
      check(recoverRes, { 'cart recovered': (r) => r.status === 200 || r.status === 201 });
      const recoveredCsrf = getCsrfFromResponse(recoverRes) || freshCsrf;

      // Retry order once
      const retryHeaders = {
        'Content-Type': 'application/json',
        'X-CSRF-Token': recoveredCsrf,
        'Idempotency-Key': idempotencyKey
      };
      if (etag) {
        retryHeaders['If-Match'] = etag;
      }
      res = httpClient.post(`${BASE_URL}/v2/orders`, JSON.stringify(payload), {
        headers: retryHeaders
      });
    } else if (errorType === 'session') {
      // Session revoked - re-login and recover
      const newCsrf = login(httpClient, 'bench', 'bench');
      const recoverRes = httpClient.post(`${BASE_URL}/v2/carts/${cartId}/recover`, JSON.stringify({}), {
        headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': newCsrf }
      });
      check(recoverRes, { 'cart recovered after re-login': (r) => r.status === 200 || r.status === 201 });
      const recoveredCsrf = getCsrfFromResponse(recoverRes) || newCsrf;

      const retryHeaders = {
        'Content-Type': 'application/json',
        'X-CSRF-Token': recoveredCsrf,
        'Idempotency-Key': idempotencyKey
      };
      if (etag) {
        retryHeaders['If-Match'] = etag;
      }
      res = httpClient.post(`${BASE_URL}/v2/orders`, JSON.stringify(payload), {
        headers: retryHeaders
      });
    } else {
      // denied - fail assertion
      check(res, { 'order not denied': (r) => false });
    }
  }

  check(res, { 'order created': (r) => r.status === 201 });

  let orderId = null;
  let finalCsrf = csrf;
  try {
    const body = res.json();
    orderId = body.id;
    if (body.csrf) finalCsrf = body.csrf;
  } catch (e) {
    // ignore
  }

  return { orderId, csrf: finalCsrf };
}

function doWork(httpClient, csrf) {
  let attempts = 0;
  let res = null;

  while (attempts < 5) {
    attempts++;
    res = httpClient.post(`${BASE_URL}/v2/work`, JSON.stringify({}), {
      headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': csrf }
    });

    if (res.status === 429) {
      const retryAfter = parseInt(res.headers['Retry-After'] || '1', 10);
      sleep(retryAfter);
      continue;
    }

    break;
  }

  check(res, { 'work completed': (r) => r.status === 200 });

  // Track business failure
  if (res.status !== 200 && res.status !== 429) {
    businessFailure.add(1);
  } else {
    businessFailure.add(0);
  }

  return res;
}

export function setup() {
  // Record fresh owner seeds
  const seeds = {};
  for (let i = 1; i <= 16; i++) {
    seeds[`bench-${i}`] = `seed-${i}-${Date.now()}`;
  }
  seeds['bench'] = `seed-bench-${Date.now()}`;
  return seeds;
}

export default function (data) {
  const vuId = __VU;
  const iterationId = __ITER;
  const profile = getProfile(vuId);

  // Determine username
  const userIndex = ((vuId - 1) % 16) + 1;
  const username = `bench-${userIndex}`;

  // Fresh login
  let csrf = login(http, username, 'bench');

  // Get catalog
  const products = getCatalog(http, csrf, profile.reverse_catalog || false);

  if (products.length === 0) {
    fail('No products available');
  }

  // Pick first product with in-stock variant
  let selectedProduct = null;
  let selectedVariant = null;

  for (const product of products) {
    if (product.variants && product.variants.length > 0) {
      for (const variant of product.variants) {
        if (variant.in_stock) {
          selectedProduct = product;
          selectedVariant = variant;
          break;
        }
      }
    }
    if (selectedProduct) break;
  }

  if (!selectedProduct || !selectedVariant) {
    fail('No in-stock product variant found');
  }

  // Solve challenge to get grant_id
  const challengeResult = solveChallenge(http, csrf);
  csrf = challengeResult.csrf;
  const grantId = challengeResult.grantId;

  // Create cart
  const cartResult = createCart(http, csrf, selectedProduct.id, selectedVariant.id, grantId);
  csrf = cartResult.csrf;
  const cartId = cartResult.cartId;
  let etag = cartResult.etag;

  // Update cart quantity to 1 (or keep as is)
  const updateResult = updateCartQuantity(http, csrf, cartId, 1, etag);
  csrf = updateResult.csrf;
  etag = updateResult.etag;

  // Create reservation
  const reservationResult = createReservation(http, csrf, cartId);
  csrf = reservationResult.csrf;
  const statusUrl = reservationResult.statusUrl;

  // Poll reservation
  const pollResult = pollReservation(
    http,
    csrf,
    statusUrl,
    profile.job_polls,
    profile.poll_interval,
    profile.job_fails || false
  );
  csrf = pollResult.csrf;

  if (profile.job_fails) {
    // Negative control: job should fail
    check(pollResult.status, {
      'negative control: job fails': (s) => s === 'failed'
    });
    // Do not proceed to checkout
    return;
  }

  // Check reservation is ready
  check(pollResult.status, {
    'reservation ready': (s) => s === 'ready'
  });

  if (pollResult.status !== 'ready' || !pollResult.reservationId) {
    fail('Reservation not ready - cannot proceed to checkout');
  }

  // Create order with reservation
  const idempotencyKey = `order-${cartId}-${iterationId}-${vuId}`;
  const orderResult = createOrder(http, csrf, cartId, pollResult.reservationId, etag, idempotencyKey);
  csrf = orderResult.csrf;

  check(orderResult.orderId, {
    'order has id': (id) => id !== null && id !== undefined
  });

  // Do work
  doWork(http, csrf);
}

export function teardown(data) {
  // Record fresh owner seeds after execution
  const seeds = {};
  for (let i = 1; i <= 16; i++) {
    seeds[`bench-${i}`] = `seed-${i}-${Date.now()}-after`;
  }
  seeds['bench'] = `seed-bench-${Date.now()}-after`;
  return seeds;
}

