USERS = 2
ITERATIONS = 2


class ReservationUser(HttpUser):
    wait_time = between(0.01, 0.03)

    def __init__(self, *args, **kwargs):
        super().__init__(*args, **kwargs)
        self.csrf = None
        self.session_cookie = None
        self.cart_id = None
        self.cart_etag = None
        self.grant_id = None
        self.profile = None
        self.negative_override = None
        self.iterations_done = 0
