        self.profile = random.choice(PROFILES)
        self.negative_override = random.choice(NEGATIVE_OVERRIDES) if random.random() < 0.5 else None
        self.login()

    def login(self):
        with self.client.get(
            "/v2/login-form",
            catch_response=True,
            allow_redirects=False,
        ) as resp:
            if resp.status_code != 200:
                resp.failure(f"login-form failed: {resp.status_code}")
                return
            # Extract csrf from input[name=csrf]
            import re
            m = re.search(r'name="csrf"\s+value="([^"]+)"', resp.text)
            if not m:
                m = re.search(r"name='csrf'\s+value='([^']+)'", resp.text)
            if not m:
                resp.failure("no csrf in login form")
                return
            self.csrf = m.group(1)

        with self.client.post(
            "/v2/login",
            json={"username": "bench", "password": "bench", "csrf": self.csrf},
            headers={"X-CSRF-Token": self.csrf},
            catch_response=True,
            allow_redirects=False,
        ) as resp:
            if resp.status_code in (200, 302):
                if resp.status_code == 302:
                    loc = resp.headers.get("Location")
                    if loc:
                        with self.client.get(
                            urljoin(BASE, loc),
                            catch_response=True,
                            allow_redirects=False,
                        ) as r2:
                            if r2.status_code != 200:
                                r2.failure(f"login redirect failed: {r2.status_code}")
                                return
                            data = r2.json()
                            self.csrf = data.get("csrf", self.csrf)
                            self.session_cookie = r2.cookies.get("session")
                else:
                    data = resp.json()
                    self.csrf = data.get("csrf", self.csrf)
                    self.session_cookie = resp.cookies.get("session")
                resp.success()
            else:
                resp.failure(f"login failed: {resp.status_code} {resp.text[:200]}")

    def get_csrf_headers(self):
        return {"X-CSRF-Token": self.csrf or ""}

    def update_csrf(self, data):
        if isinstance(data, dict) and data.get("csrf"):
            self.csrf = data["csrf"]

    def create_cart(self):
        # Get catalog
        products = []
        with self.client.get("/v2/catalog", catch_response=True) as resp:
            if resp.status_code != 200:
                resp.failure(f"catalog failed: {resp.status_code}")
                return False
            data = resp.json()
            products = data.get("data", {}).get("products", [])

        if not products:
            # Try page
            with self.client.get("/v2/catalog/page", catch_response=True) as resp:
                if resp.status_code != 200:
                    resp.failure(f"catalog page failed: {resp.status_code}")
                    return False
                data = resp.json()
                products = [data.get("data", {}).get("product")] if data.get("data", {}).get("product") else []

        if not products:
            return False

        product = products[0]
        variants = product.get("variants", [])
        if not variants:
            return False
        variant = variants[0]
        if not variant.get("in_stock", False):
            # find in-stock variant
            for v in variants:
                if v.get("in_stock", False):
                    variant = v
                    break
            else:
                return False

        payload = {
            "product_id": product["id"],
            "variant_id": variant["id"],
        }
        if self.grant_id:
            payload["grant_id"] = self.grant_id

        with self.client.post(
            "/v2/carts",
            json=payload,
            headers=self.get_csrf_headers(),
            catch_response=True,
        ) as resp:
