    def patch_cart_quantity(self, quantity):
        if not self.cart_etag:
            if not self.get_cart():
                return False
        with self.client.patch(
            f"/v2/carts/{self.cart_id}",
            json={"quantity": quantity},
            headers={
                **self.get_csrf_headers(),
                "If-Match": self.cart_etag,
            },
            catch_response=True,
        ) as resp:
            if resp.status_code == 200:
                data = resp.json()
                self.cart_etag = resp.headers.get("ETag")
                self.update_csrf(data)
                resp.success()
                return True
            elif resp.status_code == 412:
                # re-read and retry once
                if not self.get_cart():
                    return False
                with self.client.patch(
                    f"/v2/carts/{self.cart_id}",
                    json={"quantity": quantity},
                    headers={
                        **self.get_csrf_headers(),
                        "If-Match": self.cart_etag,
                    },
                    catch_response=True,
                ) as resp2:
                    if resp2.status_code == 200:
                        data = resp2.json()
                        self.cart_etag = resp2.headers.get("ETag")
                        self.update_csrf(data)
                        resp2.success()
                        return True
                    else:
                        resp2.failure(f"patch retry failed: {resp2.status_code}")
                        return False
            else:
                resp.failure(f"patch failed: {resp.status_code}")
                return False

    def create_reservation(self):
        with self.client.post(
            "/v2/reservations",
            json={"cart_id": self.cart_id},
            headers=self.get_csrf_headers(),
            catch_response=True,
        ) as resp:
            if resp.status_code == 202:
                data = resp.json()
                self.update_csrf(data)
                status_url = data.get("status_url")
                if not status_url:
                    resp.failure("no status_url in reservation response")
                    return None
                resp.success()
                return status_url
            else:
                resp.failure(f"reservation failed: {resp.status_code} {resp.text[:200]}")
                return None

    def poll_reservation(self, status_url, max_polls, poll_interval):
        reservation_id = None
        polls = 0
        while polls < max_polls:
            polls += 1
            time.sleep(poll_interval)
            with self.client.get(
                urljoin(BASE, status_url),
                catch_response=True,
            ) as resp:
                if resp.status_code != 200:
                    resp.failure(f"poll failed: {resp.status_code}")
                    return None
                data = resp.json()
                status = data.get("status")
                if status == "ready":
                    reservation_id = data.get("reservation_id")
                    if not reservation_id:
                        resp.failure("ready but no reservation_id")
                        return None
                    resp.success()
                    return reservation_id
                elif status in ("pending", "failed"):
                    if status == "failed":
                        resp.failure("reservation failed")
                        return None
                    # pending: continue polling
                    resp.success()
                else:
                    resp.failure(f"unknown status: {status}")
                    return None
        # exhausted polls
        return None

    def checkout(self, reservation_id):
        idempotency_key = f"cart-{self.cart_id}-{self.user_seed}"
        headers = {
            **self.get_csrf_headers(),
            "Idempotency-Key": idempotency_key,
        }
        if self.cart_etag:
            headers["If-Match"] = self.cart_etag

        payload = {"cart_id": self.cart_id}
        if reservation_id:
            payload["reservation_id"] = reservation_id

        with self.client.post(
            "/v2/orders",
            json=payload,
            headers=headers,
            catch_response=True,
        ) as resp:
            if resp.status_code == 201:
                data = resp.json()
                if data.get("accepted") is True:
                    self.update_csrf(data)
                    resp.success()
                    return True
                else:
                    resp.failure("order accepted:false")
                    return False
            elif resp.status_code == 200:
                data = resp.json()
                if data.get("accepted") is False:
                    resp.failure("business failure: accepted:false")
                    return False
                else:
                    resp.failure(f"unexpected 200: {resp.text[:200]}")
                    return False
            else:
                resp.failure(f"order failed: {resp.status_code} {resp.text[:200]}")
                return False

    def handle_401(self, resp, operation_retry_fn):
        """Handle 401 errors. Returns True if retry was attempted and succeeded."""
        try:
            data = resp.json()
        except Exception:
            return False
        error = data.get("error")
        if error == "expired":
            # renew session
            with self.client.post(
                "/v2/session/renew",
                json={},
                headers=self.get_csrf_headers(),
                catch_response=True,
            ) as r:
                if r.status_code == 200:
                    rdata = r.json()
                    self.update_csrf(rdata)
                    r.success()
                else:
                    r.failure(f"renew failed: {r.status_code}")
                    return False
            # recover cart if exists
            if self.cart_id:
                with self.client.post(
                    f"/v2/carts/{self.cart_id}/recover",
                    json={},
                    headers=self.get_csrf_headers(),
                    catch_response=True,
                ) as r2:
                    if r2.status_code == 200:
                        rdata = r2.json()
                        self.update_csrf(rdata)
                        r2.success()
                    else:
                        r2.failure(f"recover failed: {r2.status_code}")
                        return False
            # retry operation once
            return operation_retry_fn()
        elif error == "session":
            # revoked: fresh login, recover cart
            self.login()
            if self.cart_id:
                with self.client.post(
                    f"/v2/carts/{self.cart_id}/recover",
                    json={},
                    headers=self.get_csrf_headers(),
                    catch_response=True,
                ) as r:
                    if r.status_code == 200:
                        rdata = r.json()
                        self.update_csrf(rdata)
                        r.success()
                    else:
                        r.failure(f"recover after session failed: {r.status_code}")
                        return False
            return operation_retry_fn()
        elif error == "denied":
            resp.failure("401 denied")
            return False
        return False

    def do_work(self):
        with self.client.post(
            "/v2/work",
            json={},
            catch_response=True,
        ) as resp:
            if resp.status_code == 200:
                data = resp.json()
                if data.get("ok") is True:
                    resp.success()
                    return True
                else:
                    resp.failure("work not ok")
                    return False
            elif resp.status_code == 429:
                # scheduled 429, retry after 1s up to 4 times
                for attempt in range(4):
                    time.sleep(1)
                    with self.client.post(
                        "/v2/work",
                        json={},
                        catch_response=True,
                    ) as r2:
                        if r2.status_code == 200:
                            data = r2.json()
                            if data.get("ok") is True:
                                r2.success()
                                return True
                            else:
                                r2.failure("work not ok after retry")
                                return False
                        elif r2.status_code == 429:
                            continue
                        else:
                            r2.failure(f"work retry failed: {r2.status_code}")
                            return False
                resp.failure("work 429 exhausted")
                return False
            else:
                resp.failure(f"work failed: {resp.status_code}")
                return False

    def do_browse(self):
        with self.client.post(
            "/v2/browse",
            json={},
            catch_response=True,
        ) as resp:
            if resp.status_code == 200:
                data = resp.json()
                if data.get("ok") is True:
                    resp.success()
                    return True
                else:
                    resp.failure("browse not ok")
                    return False
            elif resp.status_code == 429:
                for attempt in range(4):
                    time.sleep(1)
                    with self.client.post(
                        "/v2/browse",
                        json={},
                        catch_response=True,
                    ) as r2:
                        if r2.status_code == 200:
                            data = r2.json()
                            if data.get("ok") is True:
                                r2.success()
                                return True
                            else:
                                r2.failure("browse not ok after retry")
                                return False
                        elif r2.status_code == 429:
                            continue
                        else:
                            r2.failure(f"browse retry failed: {r2.status_code}")
                            return False
                resp.failure("browse 429 exhausted")
                return False
            else:
                resp.failure(f"browse failed: {resp.status_code}")
                return False

    def complete_challenge(self):
        """Complete challenge to get grant_id."""
        with self.client.get(
            "/v2/challenge-form",
            catch_response=True,
        ) as resp:
            if resp.status_code != 200:
                resp.failure(f"challenge-form failed: {resp.status_code}")
                return False
            import re
            m = re.search(r'action="([^"]*challenges/[^"]*)"', resp.text)
            if not m:
                m = re.search(r"action='([^']*challenges/[^']*)'", resp.text)
            if not m:
                resp.failure("no challenge action found")
                return False
            action = m.group(1)
            m2 = re.search(r'name="challenge"\s+value="([^"]+)"', resp.text)
            if not m2:
                m2 = re.search(r"name='challenge'\s+value='([^']+)'", resp.text)
            if not m2:
                resp.failure("no challenge input found")
                return False
            challenge_value = m2.group(1)

        with self.client.post(
            urljoin(BASE, action),
            json={"challenge": challenge_value},
            headers=self.get_csrf_headers(),
            catch_response=True,
            allow_redirects=False,
        ) as resp:
            if resp.status_code == 302:
                loc = resp.headers.get("Location")
                if not loc:
                    resp.failure("no location after challenge")
                    return False
                with self.client.get(
                    urljoin(BASE, loc),
                    catch_response=True,
                    allow_redirects=False,
                ) as r2:
                    if r2.status_code == 200:
                        data = r2.json()
                        self.grant_id = data.get("grant_id")
                        self.update_csrf(data)
                        r2.success()
                        return True
                    else:
                        r2.failure(f"challenge location failed: {r2.status_code}")
                        return False
            else:
                resp.failure(f"challenge post failed: {resp.status_code}")
                return False

    @task
    def journey(self):
        if self.iterations_done >= ITERATIONS:
            raise StopUser()

        self.iterations_done += 1

        # Fresh login and cart for each journey
        self.login()
        self.cart_id = None
        self.cart_etag = None
        self.grant_id = None

        # Optionally complete challenge to get grant_id
        if random.random() < 0.3:
            self.complete_challenge()

        if not self.create_cart():
            return

        # Patch quantity
        quantity = random.randint(1, 20)
        if not self.patch_cart_quantity(quantity):
            return

        # Create reservation
        status_url = self.create_reservation()
        if not status_url:
            return

        # Poll reservation
        max_polls = self.profile.get("job_polls", 2)
        poll_interval = self.profile.get("poll_interval", 0.02)

        if self.negative_override and self.negative_override.get("job_fails"):
            # Negative control: job will fail, we should not checkout
            reservation_id = self.poll_reservation(status_url, max_polls, poll_interval)
            if reservation_id is not None:
                # Should not happen in negative control
                self.environment.events.request.fire(
                    request_type="ASSERT",
                    name="negative_control_job_fails",
                    response_time=0,
                    response_length=0,
                    exception=Exception("Negative control: job should have failed but got reservation_id"),
                )
            return

        reservation_id = self.poll_reservation(status_url, max_polls, poll_interval)
        if not reservation_id:
            return

        # Checkout with reservation_id
        self.checkout(reservation_id)

        # Do some work
        if random.random() < 0.5:
            self.do_work()
        else:
            self.do_browse()


class ReservationShape(LoadTestShape):
    def tick(self):
        run_time = self.get_run_time()
        if run_time < 60:
            return (USERS, USERS)
        return None
