    const page = getCatalogPage(csrf, pageUrl);
    if (page.status !== 200 || !page.product) break;
    if (page.product.variants && page.product.variants.length > 0) {
      for (const variant of page.product.variants) {
        if (variant.in_stock) {
          selectedProduct = page.product;
          selectedVariant = variant;
          break;
        }
      }
    }
    pageUrl = page.next;
