  if (reservationRes.status !== 202) {
    fail(`reservation failed: ${reservationRes.status}`);
  }
  const reservationCsrf = extractCsrfFromJson(reservationRes.body);
  if (reservationCsrf) csrf = reservationCsrf;
  const statusUrl = extractStatusUrl(reservationRes.body);
  if (!statusUrl) {
