    sleep(0.05);
    const pollRes = pollReservation(csrf, statusUrl);
    if (pollRes.status === 200) {
      const status = extractStatus(pollRes.body);
      if (status === 'ready') {
        reservationId = extractReservationId(pollRes.body);
        const pollCsrf = extractCsrfFromJson(pollRes.body);
        if (pollCsrf) csrf = pollCsrf;
