      const recoverRes = recoverCart(csrf, cartId);
      if (recoverRes.status === 200) {
        const recoverCsrf = extractCsrfFromJson(recoverRes.body) || csrf;
        csrf = recoverCsrf;
      }
      orderRes = createOrder(csrf, cartId, reservationId, idempotencyKey, etag);
    } else if (err === 'denied') {
      fail('Order denied unexpectedly');
    }
  }
  if (orderRes.status !== 201 && orderRes.status !== 200) {
    fail(`order failed: ${orderRes.status}`);
  }
  const accepted = extractAccepted(orderRes.body);
  if (accepted === false) {
    fail('Order not accepted');
  }
  if (orderRes.status === 200 && accepted !== true) {
    fail('Order 200 but not accepted');
  }

  // Do work
  const workRes = doWork(csrf);
  workResponses.add(1);
  if (workRes.status === 429) {
    const retryAfter = extractRetryAfter(workRes.headers);
    sleep(retryAfter);
    let retryCount = 0;
    let workRetryRes = workRes;
    while (workRetryRes.status === 429 && retryCount < 4) {
      sleep(1);
      workRetryRes = doWork(csrf);
      workResponses.add(1);
      retryCount++;
    }
    if (workRetryRes.status !== 200) {
      unexpectedFailures.add(1);
      businessFailureRate.add(1);
    }
  } else if (workRes.status !== 200) {
    unexpectedFailures.add(1);
    businessFailureRate.add(1);
  }

  // Browse
  const browseRes = doBrowse(csrf);
  if (browseRes.status !== 200) {
    unexpectedFailures.add(1);
    businessFailureRate.add(1);
  }

  return {
    cartId,
    orderAccepted: accepted,
    grantId,
    csrf
  };
}

export const options = {
  scenarios: {
    challenge: {
      executor: 'per-vu-iterations',
      vus: USERS,
      iterations: ITERATIONS,
      maxDuration: '5m',
    },
  },
  thresholds: {
    business_failure: ['rate<0.1'],
  },
};

export default function () {
  const vuId = __VU;
  const result = journey(vuId);
  // Record fresh owner seeds after execution
  // This is a no-op in k6 but documents the requirement
  const ownerSeed = {
    vu: vuId,
    cartId: result.cartId,
    grantId: result.grantId,
    csrf: result.csrf,
    timestamp: Date.now(),
  };
  // Store in a global array for potential post-processing
  if (!globalThis.__ownerSeeds) {
    globalThis.__ownerSeeds = [];
  }
  globalThis.__ownerSeeds.push(ownerSeed);
}

export function teardown() {
  // Output owner seeds to stderr for recording
  if (globalThis.__ownerSeeds) {
    console.error('OWNER_SEEDS:' + JSON.stringify(globalThis.__ownerSeeds));
  }
}
