BASE = os.environ.get("BASE_URL", "http://127.0.0.1:8000")


class ShopUser(HttpUser):
    wait_time = between(0.05, 0.15)

    def on_start(self):
        self.username = None
        self.password = "bench"
        self.csrf = None
        self.session_cookie = None
        self.cart_id = None
        self.cart_etag = None
        self.grant_id = None
        self.reservation_id = None
        self.idempotency_key = None
        self.iterations_done = 0
        self.require_challenge = True
        self.html_layout = 0
        self.reverse_catalog = False
        self.expected_iterations = 2

    def _fresh_login(self):
        """Get login form, extract csrf, login."""
        with self.client.get(
            "/v2/login-form",
            catch_response=True,
            name="/v2/login-form",
        ) as r:
            if r.status_code != 200:
                r.failure(f"login-form status {r.status_code}")
                return False
            # Extract csrf from input[name=csrf]
            import re
            m = re.search(r'name=["\']csrf["\'][^>]*value=["\']([^"\']+)["\']', r.text)
            if not m:
                m = re.search(r'value=["\']([^"\']+)["\'][^>]*name=["\']csrf["\']', r.text)
            if not m:
                r.failure("no csrf in login form")
                return False
            self.csrf = m.group(1)

        with self.client.post(
            "/v2/login",
            json={"username": self.username, "password": self.password, "csrf": self.csrf},
            catch_response=True,
            name="/v2/login",
            allow_redirects=False,
        ) as r:
            if r.status_code in (200, 302):
                if r.status_code == 302:
                    loc = r.headers.get("Location")
                    if not loc:
                        r.failure("302 without Location")
                        return False
                    with self.client.get(
                        loc,
                        catch_response=True,
                        name="/v2/login-redirect",
                        allow_redirects=False,
                    ) as r2:
                        if r2.status_code != 200:
                            r2.failure(f"login redirect status {r2.status_code}")
                            return False
                        r = r2
                try:
                    data = r.json()
                except Exception:
                    r.failure("login response not JSON")
                    return False
                if "csrf" in data:
                    self.csrf = data["csrf"]
                if "user" in data:
                    pass
                return True
            else:
                r.failure(f"login status {r.status_code}")
                return False

    def _get_challenge(self):
        """GET challenge form, extract action and challenge input, POST challenge, follow redirect."""
        with self.client.get(
            "/v2/challenge-form",
            catch_response=True,
            name="/v2/challenge-form",
        ) as r:
            if r.status_code != 200:
                r.failure(f"challenge-form status {r.status_code}")
                return False
            import re
            m = re.search(r'<form[^>]*action=["\']([^"\']+)["\']', r.text)
            if not m:
                r.failure("no form action in challenge-form")
                return False
            action = m.group(1)
            m2 = re.search(r'name=["\']challenge["\'][^>]*value=["\']([^"\']+)["\']', r.text)
            if not m2:
                m2 = re.search(r'value=["\']([^"\']+)["\'][^>]*name=["\']challenge["\']', r.text)
            if not m2:
                r.failure("no challenge input")
                return False
            challenge_value = m2.group(1)

        with self.client.post(
            action,
            json={"challenge": challenge_value},
            headers={"X-CSRF-Token": self.csrf},
            catch_response=True,
            name="/v2/challenge-submit",
            allow_redirects=False,
        ) as r:
            if r.status_code != 302:
                r.failure(f"challenge submit status {r.status_code}")
                return False
            loc = r.headers.get("Location")
            if not loc:
                r.failure("challenge submit 302 without Location")
                return False

        with self.client.get(
            loc,
            catch_response=True,
            name="/v2/challenge-result",
            allow_redirects=False,
        ) as r:
            if r.status_code != 200:
                r.failure(f"challenge result status {r.status_code}")
                return False
            try:
                data = r.json()
            except Exception:
                r.failure("challenge result not JSON")
                return False
            if "grant_id" not in data:
                r.failure("no grant_id in challenge result")
                return False
            self.grant_id = data["grant_id"]
            if "csrf" in data:
                self.csrf = data["csrf"]
            return True

    def _create_cart(self):
        """Create cart with product/variant from catalog."""
        # Get catalog
        with self.client.get(
            "/v2/catalog",
            catch_response=True,
            name="/v2/catalog",
        ) as r:
            if r.status_code != 200:
                r.failure(f"catalog status {r.status_code}")
                return False
            try:
                data = r.json()
            except Exception:
                r.failure("catalog not JSON")
                return False
            products = data.get("data", {}).get("products", [])
            if not products:
                r.failure("no products in catalog")
                return False

        # Optionally traverse pages
        if self.reverse_catalog:
            # Traverse at most 3 pages
            next_url = "/v2/catalog/page"
            for _ in range(3):
                if not next_url:
                    break
                with self.client.get(
                    next_url,
                    catch_response=True,
                    name="/v2/catalog/page",
                ) as r:
                    if r.status_code != 200:
                        r.failure(f"catalog page status {r.status_code}")
                        return False
                    try:
                        pdata = r.json()
                    except Exception:
                        r.failure("catalog page not JSON")
                        return False
                    if "data" in pdata and "products" in pdata["data"]:
                        products = pdata["data"]["products"]
                    next_url = pdata.get("next")

        # Pick first product with in_stock variant
        product_id = None
        variant_id = None
        for p in products:
            for v in p.get("variants", []):
                if v.get("in_stock"):
                    product_id = p["id"]
                    variant_id = v["id"]
                    break
            if product_id:
                break
        if not product_id:
            # Try page traversal
            next_url = "/v2/catalog/page"
            for _ in range(3):
                if not next_url:
                    break
                with self.client.get(
                    next_url,
                    catch_response=True,
                    name="/v2/catalog/page",
                ) as r:
                    if r.status_code != 200:
                        r.failure(f"catalog page status {r.status_code}")
                        return False
                    try:
                        pdata = r.json()
                    except Exception:
                        r.failure("catalog page not JSON")
                        return False
                    if "data" in pdata and "products" in pdata["data"]:
                        for p in pdata["data"]["products"]:
                            for v in p.get("variants", []):
                                if v.get("in_stock"):
                                    product_id = p["id"]
                                    variant_id = v["id"]
                                    break
                            if product_id:
                                break
                    if product_id:
                        break
                    next_url = pdata.get("next")
            if not product_id:
                # Last resort: use first product
                if products:
                    product_id = products[0]["id"]
                    variant_id = products[0]["variants"][0]["id"]

        payload = {"product_id": product_id, "variant_id": variant_id}
        if self.grant_id:
            payload["grant_id"] = self.grant_id

        with self.client.post(
            "/v2/carts",
            json=payload,
            headers={"X-CSRF-Token": self.csrf},
            catch_response=True,
            name="/v2/carts",
        ) as r:
            if r.status_code != 201:
                r.failure(f"cart create status {r.status_code}")
                return False
            try:
                data = r.json()
            except Exception:
                r.failure("cart create not JSON")
                return False
            self.cart_id = data.get("id")
            if not self.cart_id:
                r.failure("no cart id")
                return False
            if "csrf" in data:
                self.csrf = data["csrf"]
            self.cart_etag = r.headers.get("ETag")
            return True

    def _update_cart(self):
        """PATCH cart quantity with If-Match, retry once on 412."""
        if not self.cart_id:
            return False
        payload = {"quantity": random.randint(1, 20)}
        headers = {"X-CSRF-Token": self.csrf}
        if self.cart_etag:
            headers["If-Match"] = self.cart_etag

        with self.client.patch(
            f"/v2/carts/{self.cart_id}",
            json=payload,
            headers=headers,
            catch_response=True,
            name="/v2/carts/{id}",
        ) as r:
            if r.status_code == 412:
                # Re-read and retry once
                with self.client.get(
                    f"/v2/carts/{self.cart_id}",
                    catch_response=True,
                    name="/v2/carts/{id}",
                ) as r2:
                    if r2.status_code != 200:
                        r2.failure(f"cart re-read status {r2.status_code}")
                        return False
                    self.cart_etag = r2.headers.get("ETag")
                    if "csrf" in r2.json() if isinstance(r2.json(), dict) else {}:
                        self.csrf = r2.json()["csrf"]
                headers2 = {"X-CSRF-Token": self.csrf}
                if self.cart_etag:
                    headers2["If-Match"] = self.cart_etag
                with self.client.patch(
                    f"/v2/carts/{self.cart_id}",
                    json=payload,
                    headers=headers2,
                    catch_response=True,
                    name="/v2/carts/{id}",
                ) as r3:
                    if r3.status_code != 200:
                        r3.failure(f"cart patch retry status {r3.status_code}")
                        return False
                    if "csrf" in r3.json() if isinstance(r3.json(), dict) else {}:
                        self.csrf = r3.json()["csrf"]
                    self.cart_etag = r3.headers.get("ETag")
                    return True
            elif r.status_code == 200:
                try:
                    data = r.json()
                except Exception:
                    r.failure("cart patch not JSON")
                    return False
                if "csrf" in data:
                    self.csrf = data["csrf"]
                self.cart_etag = r.headers.get("ETag")
                return True
            else:
                r.failure(f"cart patch status {r.status_code}")
                return False

    def _create_reservation(self):
        """POST /v2/reservations, poll status_url."""
        if not self.cart_id:
            return False
        with self.client.post(
            "/v2/reservations",
            json={"cart_id": self.cart_id},
            headers={"X-CSRF-Token": self.csrf},
            catch_response=True,
            name="/v2/reservations",
        ) as r:
            if r.status_code != 202:
                r.failure(f"reservation status {r.status_code}")
                return False
            try:
                data = r.json()
            except Exception:
                r.failure("reservation not JSON")
                return False
            status_url = data.get("status_url")
            if not status_url:
                r.failure("no status_url")
                return False
            if "csrf" in data:
                self.csrf = data["csrf"]

        # Poll at least 50ms apart, at most 5 times
        for i in range(5):
            time.sleep(0.05)
            with self.client.get(
                status_url,
                catch_response=True,
                name="/v2/reservations/status",
            ) as r:
                if r.status_code != 200:
                    r.failure(f"reservation poll status {r.status_code}")
                    return False
                try:
                    pdata = r.json()
                except Exception:
                    r.failure("reservation poll not JSON")
                    return False
                if "csrf" in pdata:
                    self.csrf = pdata["csrf"]
                status = pdata.get("status")
                if status == "ready":
                    self.reservation_id = pdata.get("reservation_id")
                    if not self.reservation_id:
                        r.failure("ready but no reservation_id")
                        return False
                    return True
                elif status == "pending":
                    continue
                elif status == "failed":
                    r.failure("reservation failed")
                    return False
                else:
                    r.failure(f"unknown reservation status {status}")
                    return False
        r.failure("reservation polling exhausted")
        return False

    def _place_order(self):
        """POST /v2/orders with Idempotency-Key and If-Match."""
        if not self.cart_id:
            return False
        if not self.idempotency_key:
            self.idempotency_key = f"idem-{self.username}-{self.cart_id}-{int(time.time()*1000)}"
        payload = {"cart_id": self.cart_id}
        if self.reservation_id:
            payload["reservation_id"] = self.reservation_id
        headers = {
            "X-CSRF-Token": self.csrf,
            "Idempotency-Key": self.idempotency_key,
        }
        if self.cart_etag:
            headers["If-Match"] = self.cart_etag

        with self.client.post(
            "/v2/orders",
            json=payload,
            headers=headers,
            catch_response=True,
            name="/v2/orders",
        ) as r:
            if r.status_code == 201:
                try:
                    data = r.json()
                except Exception:
                    r.failure("order not JSON")
                    return False
                if data.get("accepted") is True:
                    if "csrf" in data:
                        self.csrf = data["csrf"]
                    return True
                else:
                    r.failure("order accepted false")
                    return False
            elif r.status_code == 200:
                try:
                    data = r.json()
                except Exception:
                    r.failure("order 200 not JSON")
                    return False
                if data.get("accepted") is False:
                    r.failure("business failure: accepted false")
                    return False
                else:
                    r.failure("unexpected 200 accepted true")
                    return False
            else:
                r.failure(f"order status {r.status_code}")
                return False

    def _recover_cart(self):
        """POST /v2/carts/{id}/recover after session renewal."""
        if not self.cart_id:
            return False
        with self.client.post(
            f"/v2/carts/{self.cart_id}/recover",
            json={},
            headers={"X-CSRF-Token": self.csrf},
            catch_response=True,
            name="/v2/carts/{id}/recover",
        ) as r:
            if r.status_code == 200:
                try:
                    data = r.json()
                except Exception:
                    r.failure("recover not JSON")
                    return False
                if "csrf" in data:
                    self.csrf = data["csrf"]
                self.cart_etag = r.headers.get("ETag")
                return True
            else:
                r.failure(f"recover status {r.status_code}")
                return False

    def _renew_session(self):
        """POST /v2/session/renew with current CSRF."""
        with self.client.post(
            "/v2/session/renew",
            json={},
            headers={"X-CSRF-Token": self.csrf},
            catch_response=True,
            name="/v2/session/renew",
        ) as r:
            if r.status_code == 200:
                try:
                    data = r.json()
                except Exception:
                    r.failure("renew not JSON")
                    return False
                if "csrf" in data:
                    self.csrf = data["csrf"]
                return True
            else:
                r.failure(f"renew status {r.status_code}")
                return False

    def _handle_401(self, response, operation_name):
        """Handle 401 error=expired or error=session."""
        try:
            err_data = response.json()
        except Exception:
            response.failure("401 not JSON")
            return False
        error = err_data.get("error")
        if error == "expired":
            # Renew session, recover cart, retry operation once
            if not self._renew_session():
                return False
            if self.cart_id:
                if not self._recover_cart():
                    return False
            return True  # signal retry
        elif error == "session":
            # Fresh login, recover cart
            if not self._fresh_login():
                return False
            if self.cart_id:
                if not self._recover_cart():
                    return False
            return True
        elif error == "denied":
            response.failure("401 denied - assertion failure")
            return False
        else:
            response.failure(f"unknown 401 error {error}")
            return False

    def _do_work(self):
        """POST /v2/work or /v2/browse with retry on 429."""
        url = "/v2/work" if random.random() < 0.5 else "/v2/browse"
        for attempt in range(5):
            with self.client.post(
                url,
                json={},
                headers={"X-CSRF-Token": self.csrf},
                catch_response=True,
                name=url,
            ) as r:
                if r.status_code == 200:
                    try:
                        data = r.json()
                    except Exception:
                        r.failure("work not JSON")
                        return False
                    if data.get("ok") is True:
                        return True
                    else:
                        r.failure("work ok false")
                        return False
                elif r.status_code == 429:
                    retry_after = r.headers.get("Retry-After")
                    if retry_after:
                        try:
                            time.sleep(float(retry_after))
                        except ValueError:
                            time.sleep(1)
                    else:
                        time.sleep(1)
                    if attempt < 4:
                        continue
                    else:
                        r.failure("429 retries exhausted")
                        return False
                elif r.status_code == 401:
                    retry = self._handle_401(r, "work")
                    if retry and attempt < 4:
                        continue
                    else:
                        return False
                elif r.status_code == 500:
                    r.failure("500 unexpected")
                    return False
                else:
                    r.failure(f"work status {r.status_code}")
                    return False
        return False

    def _journey(self):
        """Complete one full journey."""
        # Fresh login
        if not self._fresh_login():
            return False

        # Challenge if required
        if self.require_challenge:
            if not self._get_challenge():
                return False

        # Create cart
        if not self._create_cart():
            return False

        # Update cart
        if not self._update_cart():
            return False

        # Create reservation
        if not self._create_reservation():
            return False

        # Place order
        if not self._place_order():
            return False

        # Do work
        if not self._do_work():
            return False

        return True

    @task
    def run_iteration(self):
        if self.iterations_done >= self.expected_iterations:
            raise StopUser()
        self.iterations_done += 1
        # Reset per-journey state
        self.csrf = None
        self.cart_id = None
        self.cart_etag = None
        self.grant_id = None
        self.reservation_id = None
        self.idempotency_key = None
        self._journey()


class ChallengeUser(ShopUser):
    def on_start(self):
        super().on_start()
        self.username = f"bench-{random.randint(1, 16)}"
        self.require_challenge = True
        self.html_layout = 0
        self.reverse_catalog = False


class ChallengeLayoutReverseUser(ShopUser):
    def on_start(self):
        super().on_start()
        self.username = f"bench-{random.randint(1, 16)}"
        self.require_challenge = True
        self.html_layout = 1
        self.reverse_catalog = True


class LoadShape(LoadTestShape):
    def __init__(self):
        super().__init__()
        self.start_time = time.time()
        self.total_users = 2
        self.iterations_per_user = 2
        self.user_classes = [ChallengeUser, ChallengeLayoutReverseUser]
        self.current_user_index = 0
        self.users_spawned = 0
        self.users_completed = 0
        self.phase = "spawning"

    def tick(self):
        current_time = time.time()
        elapsed = current_time - self.start_time

        if self.phase == "spawning":
            if self.users_spawned < self.total_users:
                self.users_spawned += 1
                user_class = self.user_classes[self.users_spawned - 1]
                return (self.users_spawned, user_class)
            else:
                self.phase = "running"
                return (self.total_users, None)

        if self.phase == "running":
            # Check if all users have completed their iterations
            # We can't directly know, but we can wait a reasonable time
            # Each user does 2 iterations with wait_time 0.05-0.15
            # Estimate max time per iteration: ~2 seconds
            # Total: 2 users * 2 iterations * 2s = 8s
            if elapsed > 30:
                return None
            return (self.total_users, None)

        return None
