    // Chain: recovery flow after 401 error=session
    private static ChainBuilder recoverFromRevocation() {
        return exec(session -> session.set(RECOVERY_NEEDED_KEY, true))
                .exec(fullLogin())
                .exec(postCartRecover())
                .exec(session -> session.set(RECOVERY_NEEDED_KEY, false));
    }

    // Chain: recovery flow after 401 error=expired
    private static ChainBuilder recoverFromExpiry() {
        return exec(postSessionRenew())
                .exec(postCartRecover());
