    // Chain: handle 401 on authenticated operation
    private static ChainBuilder handle401AndRetry(ChainBuilder operation) {
        return exec(session -> session.set("retryNeeded", false))
                .exec(operation)
                .exec(session -> {
                    // Check if last request failed with 401
                    String lastStatus = session.getString("lastStatus");
                    if ("401".equals(lastStatus)) {
                        String errorType = session.getString("lastErrorType");
                        if ("expired".equals(errorType)) {
                            return session.set("retryNeeded", true).set("errorType", "expired");
                        } else if ("session".equals(errorType)) {
                            return session.set("retryNeeded", true).set("errorType", "session");
                        } else if ("denied".equals(errorType)) {
                            // fail assertion
                            return session.markAsFailed();
                        }
                    }
                    return session;
                })
                .doIf(session -> session.getBoolean("retryNeeded"))
                .exec(session -> {
                    String errorType = session.getString("errorType");
                    if ("expired".equals(errorType)) {
                        return recoverFromExpiry();
                    } else {
                        return recoverFromRevocation();
                    }
                })
                .exec(operation);
    }

    // Scenario: user journey with deliberate account sharing
    private static ScenarioBuilder userScenario = scenario("ConcurrentAccountSessions")
            .feed(accountFeeder)
            .exec(session -> session.set(LOGIN_COUNT_KEY, 0))
            .exec(session -> session.set(COMMIT_COUNT_KEY, 0))
            .exec(session -> session.set(RECOVERY_NEEDED_KEY, false))
            .exec(session -> session.set(OWNER_SEED_KEY, generateOwnerSeed()))
            // Initial login for both users
            .exec(fullLogin())
            // Synchronize after initial logins - both users have logged in with same account
            // The second login invalidates the first session
            .exec(session -> {
                // Record owner seed after initial login
                return session.set("initialOwnerSeed", session.getString(OWNER_SEED_KEY));
            })
            // Now detect revocation - try an authenticated operation
            .exec(session -> session.set("detectedRevocation", false))
            .exec(
                    http("Detect revocation - GET catalog")
                            .get("/v2/catalog")
                            .header("X-CSRF-Token", session -> session.getString(CSRF_KEY))
                            .check(status().saveAs("detectStatus"))
                            .check(bodyString().saveAs("detectBody"))
            )
            .exec(session -> {
                String status = session.getString("detectStatus");
                if ("401".equals(status)) {
                    String body = session.getString("detectBody");
                    if (body != null && body.contains("error=session")) {
                        return session.set("detectedRevocation", true).set("errorType", "session");
                    } else if (body != null && body.contains("error=expired")) {
                        return session.set("detectedRevocation", true).set("errorType", "expired");
                    } else if (body != null && body.contains("error=denied")) {
                        return session.markAsFailed();
                    }
                }
                return session;
            })
            // Recover deliberately if revocation detected
            .doIf(session -> session.getBoolean("detectedRevocation"))
            .exec(session -> {
                String errorType = session.getString("errorType");
                if ("expired".equals(errorType)) {
                    return recoverFromExpiry();
                } else {
                    return recoverFromRevocation();
                }
            })
            // Now proceed with full journey
            .exec(session -> session.set(IDEMPOTENCY_KEY, generateIdempotencyKey()))
            .exec(getCatalog())
            .exec(getChallengeForm())
            .exec(postChallenge())
            .exec(postCart())
            .exec(getCart())
            .exec(patchCart())
            .exec(postReservation())
            .exec(pollReservation())
            .exec(session -> {
                String status = session.getString("reservationStatus");
                if ("ready".equals(status)) {
                    return session;
                } else {
                    // poll again
                    return session;
                }
            })
            .exec(postOrder())
            .exec(session -> session.set(COMMIT_COUNT_KEY, session.getInt(COMMIT_COUNT_KEY) + 1))
            // Record fresh owner seed after execution
            .exec(session -> session.set("finalOwnerSeed", generateOwnerSeed()))
            .exec(session -> {
                System.out.println("USER " + session.userId() + " - Login count: " + session.getInt(LOGIN_COUNT_KEY) + ", Commit count: " + session.getInt(COMMIT_COUNT_KEY) + ", Owner seed: " + session.getString("finalOwnerSeed"));
                return session;
            });

    {
        setUp(
                userScenario.injectOpen(atOnceUsers(2))
        ).protocols(httpProtocol)
                .assertions(
                        global().successfulRequests().percent().gte(90.0)
                );
    }
