// Helper: get CSRF from login form
function getLoginForm() {
  const res = http.get(`${BASE_URL}/v2/login-form`, { redirects: 0 });
  if (res.status !== 200) {
    fail(`login-form failed: ${res.status}`);
  }
  const body = res.body;
  // Extract csrf from input[name=csrf]
  const csrfMatch = body.match(/name=["']csrf["'][^>]*value=["']([^"']+)["']/i) ||
                    body.match(/value=["']([^"']+)["'][^>]*name=["']csrf["']/i);
  if (!csrfMatch) {
    fail('Could not find csrf in login form');
  }
  return { csrf: csrfMatch[1], cookies: res.cookies };
}

// Helper: login
function login(username, password) {
  const form = getLoginForm();
  const payload = JSON.stringify({ username, password, csrf: form.csrf });
  const res = http.post(`${BASE_URL}/v2/login`, payload, {
    headers: { 'Content-Type': 'application/json' },
    redirects: 0
  });

  if (res.status === 302) {
    const location = res.headers['Location'];
    if (!location) fail('302 without Location');
    const followRes = http.get(`${BASE_URL}${location}`, { redirects: 0 });
    if (followRes.status !== 200 && followRes.status !== 302) {
      fail(`login follow failed: ${followRes.status}`);
    }
    // Parse response for csrf and user
    let csrf = null;
    let user = null;
    try {
      const data = followRes.json();
      csrf = data.csrf;
      user = data.user;
    } catch (e) {
      // Try to extract from body
      const csrfMatch = followRes.body.match(/["']csrf["']\s*:\s*["']([^"']+)["']/);
      if (csrfMatch) csrf = csrfMatch[1];
    }
    return { csrf, user, cookies: followRes.cookies };
  } else if (res.status === 200) {
    let csrf = null;
    let user = null;
    try {
      const data = res.json();
      csrf = data.csrf;
      user = data.user;
    } catch (e) {
      const csrfMatch = res.body.match(/["']csrf["']\s*:\s*["']([^"']+)["']/);
      if (csrfMatch) csrf = csrfMatch[1];
    }
    return { csrf, user, cookies: res.cookies };
  } else {
    fail(`login failed: ${res.status}`);
  }
}

