// Helper: patch cart
function patchCart(csrf, cartId, quantity, etag) {
  const res = http.patch(`${BASE_URL}/v2/carts/${cartId}`, JSON.stringify({ quantity: quantity }), {
    headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': csrf, 'If-Match': etag }
  });
  if (res.status === 412) {
    // Re-read and retry once
    const cartInfo = getCart(csrf, cartId);
    if (cartInfo) {
      const retryRes = http.patch(`${BASE_URL}/v2/carts/${cartId}`, JSON.stringify({ quantity: quantity }), {
        headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': csrf, 'If-Match': cartInfo.etag }
      });
      return retryRes;
    }
  }
  return res;
}

