      headers: { 'X-CSRF-Token': csrf }
    });
    if (res.status === 200) {
      const data = res.json();
      if (data.status === 'ready') {
        return { reservationId: data.reservation_id, csrf: data.csrf || csrf };
      } else if (data.status === 'failed') {
        return null;
      }
