    }
  }
  return null;
}

// Helper: create order
function createOrder(csrf, cartId, reservationId, idempotencyKey, etag) {
  const payload = { cart_id: cartId };
  if (reservationId) payload.reservation_id = reservationId;
  const headers = {
    'Content-Type': 'application/json',
    'X-CSRF-Token': csrf,
    'Idempotency-Key': idempotencyKey
  };
  if (etag) headers['If-Match'] = etag;

  const res = http.post(`${BASE_URL}/v2/orders`, JSON.stringify(payload), { headers });
  orderAttempts.add(1);
  if (res.status === 201) {
    const data = res.json();
    if (data.accepted === true) {
      committedOrders.add(1);
      return { success: true, csrf: data.csrf || csrf };
    }
  } else if (res.status === 200) {
    const data = res.json();
    if (data.accepted === false) {
      return { success: false, businessFailure: true, csrf: data.csrf || csrf };
    }
  }
  return { success: false, csrf: csrf };
}

