// Helper: do work
function doWork(csrf) {
  const res = http.post(`${BASE_URL}/v2/work`, JSON.stringify({}), {
    headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': csrf }
  });
  businessResponses.add(1);
  if (res.status === 200) {
    return { ok: true, csrf: csrf };
  } else if (res.status === 429) {
    // Scheduled 429 - retry with Retry-After
    for (let i = 0; i < 4; i++) {
      sleep(1);
      const retryRes = http.post(`${BASE_URL}/v2/work`, JSON.stringify({}), {
        headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': csrf }
      });
      businessResponses.add(1);
      if (retryRes.status === 200) {
        return { ok: true, csrf: csrf };
      }
    }
    return { ok: false, csrf: csrf };
  } else if (res.status === 401) {
    const data = res.json();
    if (data.error === 'expired') {
      return { expired: true, csrf: csrf };
    } else if (data.error === 'session') {
      return { revoked: true, csrf: csrf };
    }
  }
  return { ok: false, csrf: csrf };
}

