// Helper: handle 401 recovery
function handle401(csrf, cartId, errorType) {
  if (errorType === 'expired') {
    // Try renew
    const renewResult = renewSession(csrf);
    if (renewResult.success) {
      // Recover cart if exists
      if (cartId) {
        const recoverResult = recoverCart(renewResult.csrf, cartId);
        if (recoverResult.success) {
          return { csrf: recoverResult.csrf, recovered: true };
        }
      }
      return { csrf: renewResult.csrf, recovered: true };
    }
    // Renew failed - try fresh login
    const loginResult = login('bench', 'bench');
    if (loginResult.csrf) {
      if (cartId) {
        const recoverResult = recoverCart(loginResult.csrf, cartId);
        if (recoverResult.success) {
          return { csrf: recoverResult.csrf, recovered: true };
        }
      }
      return { csrf: loginResult.csrf, recovered: true };
    }
  } else if (errorType === 'session') {
    // Session revoked - fresh login
    const loginResult = login('bench', 'bench');
    if (loginResult.csrf) {
      if (cartId) {
        const recoverResult = recoverCart(loginResult.csrf, cartId);
        if (recoverResult.success) {
          return { csrf: recoverResult.csrf, recovered: true };
        }
      }
      return { csrf: loginResult.csrf, recovered: true };
    }
  }
  return { csrf: csrf, recovered: false };
}

// Helper: complete journey
function completeJourney(profile, delayMs) {
  // Fresh login
  let loginResult = login('bench', 'bench');
  let csrf = loginResult.csrf;

  // Get catalog
  let products = getCatalog(csrf, profile.reverse_catalog || false);
  if (!products || products.length === 0) {
    fail('No products in catalog');
  }

  // Pick first product with in-stock variant
  let selectedProduct = null;
  let selectedVariant = null;
  for (const product of products) {
    for (const variant of product.variants) {
      if (variant.in_stock) {
        selectedProduct = product;
        selectedVariant = variant;
        break;
      }
    }
    if (selectedProduct) break;
  }

  if (!selectedProduct) {
    // Try catalog pages
    let pageUrl = '/v2/catalog/page';
    for (let i = 0; i < 3; i++) {
      const pageData = getCatalogPage(csrf, pageUrl);
      if (pageData.data && pageData.data.products) {
        for (const product of pageData.data.products) {
          for (const variant of product.variants) {
            if (variant.in_stock) {
              selectedProduct = product;
              selectedVariant = variant;
              break;
            }
          }
          if (selectedProduct) break;
        }
      }
      if (selectedProduct) break;
      if (pageData.next) {
        pageUrl = pageData.next;
      } else {
        break;
      }
    }
  }

  if (!selectedProduct) {
    fail('No in-stock products found');
  }

  // Try to get grant_id from challenge
  let grantId = null;
  const challengeForm = getChallengeForm(csrf);
  if (challengeForm) {
    const challengeResult = postChallenge(csrf, challengeForm.action, challengeForm.challenge);
    if (challengeResult) {
      grantId = challengeResult.grantId;
      csrf = challengeResult.csrf;
    }
  }

  // Create cart
  let cartResult = createCart(csrf, selectedProduct.id, selectedVariant.id, grantId);
  if (!cartResult) {
    fail('Failed to create cart');
  }
  let cartId = cartResult.id;
  csrf = cartResult.csrf;
  let etag = cartResult.etag;

  // Patch cart quantity
  const patchRes = patchCart(csrf, cartId, 1, etag);
  if (patchRes.status === 200 || patchRes.status === 201) {
    const data = patchRes.json();
    csrf = data.csrf || csrf;
    etag = patchRes.headers['ETag'] || etag;
  } else if (patchRes.status === 401) {
    const data = patchRes.json();
    const recovery = handle401(csrf, cartId, data.error);
    csrf = recovery.csrf;
    if (recovery.recovered) {
      // Retry patch
      const cartInfo = getCart(csrf, cartId);
      if (cartInfo) {
        etag = cartInfo.etag;
        const retryPatch = patchCart(csrf, cartId, 1, etag);
        if (retryPatch.status === 200 || retryPatch.status === 201) {
          const retryData = retryPatch.json();
          csrf = retryData.csrf || csrf;
          etag = retryPatch.headers['ETag'] || etag;
        }
      }
    }
  }

  // Create reservation
  let reservationId = null;
  const reservationResult = createReservation(csrf, cartId);
  if (reservationResult) {
    csrf = reservationResult.csrf;
    const pollResult = pollReservation(csrf, reservationResult.statusUrl);
    if (pollResult) {
      reservationId = pollResult.reservationId;
      csrf = pollResult.csrf;
    }
  }

  // Create order
  const idempotencyKey = `order-${cartId}-${Date.now()}`;
  let orderResult = createOrder(csrf, cartId, reservationId, idempotencyKey, etag);
  csrf = orderResult.csrf;

  if (!orderResult.success) {
    // Check if 401 occurred
    // We need to check the actual response - let's re-attempt with recovery
    const orderRes = http.post(`${BASE_URL}/v2/orders`, JSON.stringify({ cart_id: cartId, reservation_id: reservationId }), {
      headers: {
        'Content-Type': 'application/json',
        'X-CSRF-Token': csrf,
        'Idempotency-Key': idempotencyKey,
        'If-Match': etag
      }
    });
    orderAttempts.add(1);
    if (orderRes.status === 401) {
      const data = orderRes.json();
      const recovery = handle401(csrf, cartId, data.error);
      csrf = recovery.csrf;
      if (recovery.recovered) {
        // Retry order once
        const retryOrder = createOrder(csrf, cartId, reservationId, idempotencyKey, etag);
        csrf = retryOrder.csrf;
        if (!retryOrder.success && retryOrder.businessFailure) {
          businessFailures.add(1);
        }
      }
    } else if (orderRes.status === 200) {
      const data = orderRes.json();
      if (data.accepted === false) {
        businessFailures.add(1);
      }
    }
  }

  // Do work
  const workResult = doWork(csrf);
  csrf = workResult.csrf;
  if (workResult.expired || workResult.revoked) {
    const recovery = handle401(csrf, cartId, workResult.expired ? 'expired' : 'session');
    csrf = recovery.csrf;
  }

  // Apply delay
  if (delayMs > 0) {
    sleep(delayMs / 1000);
  }
}

