    def get_csrf_from_form(self, html):
        """Extract CSRF token from login form HTML."""
        match = re.search(r'name=["\']csrf["\'][^>]*value=["\']([^"\']+)["\']', html)
        if match:
            return match.group(1)
        match = re.search(r'value=["\']([^"\']+)["\'][^>]*name=["\']csrf["\']', html)
        if match:
            return match.group(1)
        match = re.search(r'name=["\']csrf["\'][^>]*>', html)
        if match:
            # Try to find value in the same tag
            tag = match.group(0)
            val_match = re.search(r'value=["\']([^"\']+)["\']', tag)
            if val_match:
                return val_match.group(1)
        # Try attribute variants
        match = re.search(r'name\s*=\s*["\']csrf["\'][^>]*value\s*=\s*["\']([^"\']+)["\']', html)
        if match:
            return match.group(1)
        match = re.search(r'value\s*=\s*["\']([^"\']+)["\'][^>]*name\s*=\s*["\']csrf["\']', html)
        if match:
            return match.group(1)
