                return False
            csrf = self.get_csrf_from_form(resp.text)
            if not csrf:
                resp.failure("No CSRF token in login form")
                return False
            self.csrf_token = csrf

        with self.client.post("/v2/login", 
                             json={"username": SHARED_ACCOUNT["username"], 
                                   "password": SHARED_ACCOUNT["password"], 
