        return False

    def renew_session(self):
        """Renew expired session."""
        with self.client.post("/v2/session/renew", 
                             json={},
                             headers={"X-CSRF-Token": self.csrf_token},
                             catch_response=True) as resp:
            if resp.status_code == 200:
                data = resp.json()
                if "csrf" in data:
                    self.csrf_token = data["csrf"]
                return True
            elif resp.status_code == 401:
                error_data = resp.json() if resp.text else {}
                if error_data.get("error") == "session":
                    return False  # Revoked
                elif error_data.get("error") == "expired":
                    # Should not happen here
                    return True
                else:
                    resp.failure(f"Renew failed with 401: {error_data}")
                    return False
            else:
                resp.failure(f"Renew failed: {resp.status_code}")
                return False

    def recover_cart(self):
        """Recover cart after session renewal."""
        if not self.cart_id:
            return True
        with self.client.post(f"/v2/carts/{self.cart_id}/recover",
                             json={},
                             headers={"X-CSRF-Token": self.csrf_token},
                             catch_response=True) as resp:
            if resp.status_code == 200:
                data = resp.json()
                if "csrf" in data:
                    self.csrf_token = data["csrf"]
                if "ETag" in resp.headers:
                    self.cart_etag = resp.headers["ETag"]
                return True
            elif resp.status_code == 401:
                error_data = resp.json() if resp.text else {}
                if error_data.get("error") == "session":
                    return False
                elif error_data.get("error") == "expired":
                    # Try renew again
                    if self.renew_session():
                        return self.recover_cart()
                    return False
                else:
                    resp.failure(f"Recover failed with 401: {error_data}")
                    return False
            else:
                resp.failure(f"Recover failed: {resp.status_code}")
                return False

    def get_catalog(self):
        """Get catalog products."""
        with self.client.get("/v2/catalog", catch_response=True) as resp:
            if resp.status_code != 200:
                resp.failure(f"Catalog failed: {resp.status_code}")
                return None
            data = resp.json()
            products = data.get("data", {}).get("products", [])
            if self.reverse_catalog:
                products = list(reversed(products))
            return products

    def get_catalog_page(self, page_url=None):
        """Get catalog page."""
        url = page_url or "/v2/catalog/page"
        with self.client.get(url, catch_response=True) as resp:
            if resp.status_code != 200:
                resp.failure(f"Catalog page failed: {resp.status_code}")
                return None, None
            data = resp.json()
            product = data.get("data", {}).get("product") or data.get("data", {})
            next_url = data.get("next")
            return product, next_url

    def create_cart(self, product_id, variant_id):
        """Create a cart."""
        payload = {"product_id": product_id, "variant_id": variant_id}
        if self.grant_id:
            payload["grant_id"] = self.grant_id
        with self.client.post("/v2/carts",
                             json=payload,
                             headers={"X-CSRF-Token": self.csrf_token},
                             catch_response=True) as resp:
            if resp.status_code == 201:
                data = resp.json()
                self.cart_id = data.get("id")
                if "csrf" in data:
                    self.csrf_token = data["csrf"]
                if "ETag" in resp.headers:
                    self.cart_etag = resp.headers["ETag"]
                return True
            elif resp.status_code == 401:
                error_data = resp.json() if resp.text else {}
                if error_data.get("error") == "expired":
                    if self.renew_session():
                        if self.recover_cart():
                            return self.create_cart(product_id, variant_id)
                    return False
                elif error_data.get("error") == "session":
                    # Revoked - need fresh login
                    if self.login():
                        if self.recover_cart():
                            return self.create_cart(product_id, variant_id)
                    return False
                else:
                    resp.failure(f"Create cart 401: {error_data}")
                    return False
            else:
                resp.failure(f"Create cart failed: {resp.status_code}")
                return False

    def get_cart(self):
        """Get cart details."""
        with self.client.get(f"/v2/carts/{self.cart_id}", catch_response=True) as resp:
            if resp.status_code == 200:
                if "ETag" in resp.headers:
                    self.cart_etag = resp.headers["ETag"]
                return True
            elif resp.status_code == 401:
                error_data = resp.json() if resp.text else {}
                if error_data.get("error") == "expired":
                    if self.renew_session():
                        if self.recover_cart():
                            return self.get_cart()
                    return False
                elif error_data.get("error") == "session":
                    if self.login():
                        if self.recover_cart():
                            return self.get_cart()
                    return False
                else:
                    resp.failure(f"Get cart 401: {error_data}")
                    return False
            else:
                resp.failure(f"Get cart failed: {resp.status_code}")
                return False

    def update_cart_quantity(self, quantity):
        """Update cart quantity."""
        headers = {"X-CSRF-Token": self.csrf_token}
        if self.cart_etag:
            headers["If-Match"] = self.cart_etag
        with self.client.patch(f"/v2/carts/{self.cart_id}",
                              json={"quantity": quantity},
                              headers=headers,
                              catch_response=True) as resp:
            if resp.status_code == 200:
                data = resp.json()
                if "csrf" in data:
                    self.csrf_token = data["csrf"]
                if "ETag" in resp.headers:
                    self.cart_etag = resp.headers["ETag"]
                return True
            elif resp.status_code == 412:
                # Re-read and retry once
                if self.get_cart():
                    headers = {"X-CSRF-Token": self.csrf_token}
                    if self.cart_etag:
                        headers["If-Match"] = self.cart_etag
                    with self.client.patch(f"/v2/carts/{self.cart_id}",
                                          json={"quantity": quantity},
                                          headers=headers,
                                          catch_response=True) as retry_resp:
                        if retry_resp.status_code == 200:
                            data = retry_resp.json()
                            if "csrf" in data:
                                self.csrf_token = data["csrf"]
                            if "ETag" in retry_resp.headers:
                                self.cart_etag = retry_resp.headers["ETag"]
                            return True
                        elif retry_resp.status_code == 401:
                            error_data = retry_resp.json() if retry_resp.text else {}
                            if error_data.get("error") == "expired":
                                if self.renew_session():
                                    if self.recover_cart():
                                        return self.update_cart_quantity(quantity)
                                return False
                            elif error_data.get("error") == "session":
                                if self.login():
                                    if self.recover_cart():
                                        return self.update_cart_quantity(quantity)
                                return False
                            else:
                                retry_resp.failure(f"Retry PATCH 401: {error_data}")
                                return False
                        else:
                            retry_resp.failure(f"Retry PATCH failed: {retry_resp.status_code}")
                            return False
                return False
            elif resp.status_code == 401:
                error_data = resp.json() if resp.text else {}
                if error_data.get("error") == "expired":
                    if self.renew_session():
                        if self.recover_cart():
                            return self.update_cart_quantity(quantity)
                    return False
                elif error_data.get("error") == "session":
                    if self.login():
                        if self.recover_cart():
                            return self.update_cart_quantity(quantity)
                    return False
                else:
                    resp.failure(f"PATCH 401: {error_data}")
                    return False
            else:
                resp.failure(f"PATCH failed: {resp.status_code}")
                return False

    def create_reservation(self):
        """Create reservation for cart."""
        with self.client.post("/v2/reservations",
                             json={"cart_id": self.cart_id},
                             headers={"X-CSRF-Token": self.csrf_token},
                             catch_response=True) as resp:
            if resp.status_code == 202:
                data = resp.json()
                status_url = data.get("status_url")
                if "csrf" in data:
                    self.csrf_token = data["csrf"]
                # Poll status
                for i in range(5):
                    time.sleep(0.05)
                    with self.client.get(status_url, catch_response=True) as poll_resp:
                        if poll_resp.status_code == 200:
                            poll_data = poll_resp.json()
                            status = poll_data.get("status")
                            if status == "ready":
                                self.reservation_id = poll_data.get("reservation_id")
                                if "csrf" in poll_data:
                                    self.csrf_token = poll_data["csrf"]
                                return True
                            elif status == "failed":
                                poll_resp.failure("Reservation failed")
                                return False
                            elif status == "pending":
                                continue
                            else:
                                poll_resp.failure(f"Unknown reservation status: {status}")
                                return False
                        elif poll_resp.status_code == 401:
                            error_data = poll_resp.json() if poll_resp.text else {}
                            if error_data.get("error") == "expired":
                                if self.renew_session():
                                    if self.recover_cart():
                                        return self.create_reservation()
                                return False
                            elif error_data.get("error") == "session":
                                if self.login():
                                    if self.recover_cart():
                                        return self.create_reservation()
                                return False
                            else:
                                poll_resp.failure(f"Poll 401: {error_data}")
                                return False
                        else:
                            poll_resp.failure(f"Poll failed: {poll_resp.status_code}")
                            return False
                resp.failure("Reservation polling exhausted")
                return False
            elif resp.status_code == 401:
                error_data = resp.json() if resp.text else {}
                if error_data.get("error") == "expired":
                    if self.renew_session():
                        if self.recover_cart():
                            return self.create_reservation()
                    return False
                elif error_data.get("error") == "session":
                    if self.login():
                        if self.recover_cart():
                            return self.create_reservation()
                    return False
                else:
                    resp.failure(f"Reservation 401: {error_data}")
                    return False
            else:
                resp.failure(f"Reservation failed: {resp.status_code}")
                return False

    def place_order(self):
        """Place order for cart."""
        headers = {"X-CSRF-Token": self.csrf_token, 
                   "Idempotency-Key": f"order-{self.cart_id}-{self.user_id}"}
        if self.cart_etag:
            headers["If-Match"] = self.cart_etag
        payload = {"cart_id": self.cart_id}
        if self.reservation_id:
            payload["reservation_id"] = self.reservation_id
        with self.client.post("/v2/orders",
                             json=payload,
                             headers=headers,
                             catch_response=True) as resp:
            if resp.status_code == 201:
                data = resp.json()
                if data.get("accepted") == True:
                    if "csrf" in data:
                        self.csrf_token = data["csrf"]
                    self.order_committed = True
                    return True
                else:
                    resp.failure("Order not accepted")
                    return False
            elif resp.status_code == 200:
                data = resp.json()
                if data.get("accepted") == False:
                    resp.failure("Order business failure (accepted:false)")
                    return False
                else:
                    if "csrf" in data:
                        self.csrf_token = data["csrf"]
                    self.order_committed = True
                    return True
            elif resp.status_code == 401:
                error_data = resp.json() if resp.text else {}
                if error_data.get("error") == "expired":
                    if self.renew_session():
                        if self.recover_cart():
                            return self.place_order()
                    return False
                elif error_data.get("error") == "session":
                    if self.login():
                        if self.recover_cart():
                            return self.place_order()
                    return False
                elif error_data.get("error") == "denied":
                    resp.failure("Order denied - assertion failure")
                    return False
                else:
                    resp.failure(f"Order 401: {error_data}")
                    return False
            else:
                resp.failure(f"Order failed: {resp.status_code}")
                return False

    def do_work(self):
        """Perform work endpoint."""
        with self.client.post("/v2/work", json={}, catch_response=True) as resp:
            if resp.status_code == 200:
                return True
            elif resp.status_code == 429:
                # Scheduled 429 - retry with Retry-After
                retry_after = resp.headers.get("Retry-After", "1")
                try:
                    wait = float(retry_after)
                except:
                    wait = 1.0
                for i in range(4):
                    time.sleep(wait)
                    with self.client.post("/v2/work", json={}, catch_response=True) as retry_resp:
                        if retry_resp.status_code == 200:
                            return True
                        elif retry_resp.status_code == 429:
                            retry_after = retry_resp.headers.get("Retry-After", "1")
                            try:
                                wait = float(retry_after)
                            except:
                                wait = 1.0
                            continue
                        else:
                            retry_resp.failure(f"Work retry failed: {retry_resp.status_code}")
                            return False
                resp.failure("Work 429 retries exhausted")
                return False
            elif resp.status_code == 500:
                resp.failure("Work 500 error")
                return False
            else:
                resp.failure(f"Work failed: {resp.status_code}")
                return False

    def complete_journey(self):
        """Complete one full order journey."""
        # Get catalog
        products = self.get_catalog()
        if not products:
            return False

        # Pick first product with in-stock variant
        product = None
        variant = None
        for p in products:
            for v in p.get("variants", []):
                if v.get("in_stock"):
                    product = p
                    variant = v
                    break
            if product:
                break

        if not product or not variant:
            # Try catalog pages
            next_url = None
            for i in range(3):
                page_product, next_url = self.get_catalog_page(next_url)
                if page_product:
                    for v in page_product.get("variants", []):
                        if v.get("in_stock"):
                            product = page_product
                            variant = v
                            break
                if product:
                    break
                if not next_url:
                    break

        if not product or not variant:
            return False

        # Create cart
        if not self.create_cart(product["id"], variant["id"]):
            return False

        # Update quantity
        if not self.update_cart_quantity(2):
            return False

        # Create reservation
        if not self.create_reservation():
            return False

        # Place order
        if not self.place_order():
            return False

        return True

    def wait_for_sync(self):
        """Wait for both users to complete initial login."""
        LOGIN_SYNC_POINT["count"] += 1
        if LOGIN_SYNC_POINT["count"] >= 2:
            LOGIN_SYNC_POINT["ready"] = True
        # Wait until both logged in
        timeout = time.time() + 10
        while not LOGIN_SYNC_POINT["ready"] and time.time() < timeout:
            time.sleep(0.05)
        return LOGIN_SYNC_POINT["ready"]

    def detect_revocation(self):
        """Detect session revocation by making a request."""
        with self.client.get("/v2/catalog", catch_response=True) as resp:
            if resp.status_code == 401:
                error_data = resp.json() if resp.text else {}
                if error_data.get("error") == "session":
                    REVOCATION_DETECTED["flag"] = True
                    return True
                elif error_data.get("error") == "expired":
                    return False
            elif resp.status_code == 200:
                return False
            else:
                return False

    def recover_from_revocation(self):
        """Recover from session revocation."""
        # Fresh login
        if not self.login():
            return False
        # Recover cart
        if self.cart_id:
            if not self.recover_cart():
                return False
        self.recovered = True
        return True

    @task
    def run_journey(self):
        if self.iterations_done >= self.max_iterations:
            raise StopUser()

        # Initial login
        if not self.login():
            return

        # Wait for both users to login
        if not self.wait_for_sync():
            return

        # Apply per-user delay stagger
        if self.delay_ms > 0:
            time.sleep(self.delay_ms / 1000.0)

        # User 1 (first to login) will have their session revoked by User 2's login
        # Both users share the same account
        # After sync, User 2 logs in again (or User 1 detects revocation)

        # Check if we need to detect revocation
        # The second login by the other user invalidates this session
        # We detect this by making a request and checking for 401 session error

        # Simulate: after sync, one user's session is revoked
        # Both users try to detect and recover

        # First, try to detect revocation
        revoked = self.detect_revocation()

        if revoked:
            # Recover from revocation
            if not self.recover_from_revocation():
                return
        else:
            # Maybe our session is still valid, but the other user's login
            # might have revoked it. Let's check again.
            time.sleep(0.1)
            revoked = self.detect_revocation()
            if revoked:
                if not self.recover_from_revocation():
                    return

        # Now complete the journey
        if not self.complete_journey():
            return

        # Do work
        self.do_work()

        self.iterations_done += 1
        if self.iterations_done >= self.max_iterations:
            raise StopUser()


class TestShape(LoadTestShape):
    """Load test shape that runs exactly 2 users for 1 iteration each."""

    def __init__(self):
        super().__init__()
        self.start_time = time.time()
        self.users_spawned = False
        self.done = False

    def tick(self):
        if self.done:
            return None

        run_time = time.time() - self.start_time

        if not self.users_spawned:
            self.users_spawned = True
            return (2, 2)  # Spawn 2 users

        # Check if all users are done
        all_done = True
        for uid, state in USER_STATE.items():
            if state.iterations_done < state.max_iterations:
                all_done = False
                break

        if all_done and len(USER_STATE) >= 2:
            self.done = True
            return None

        # Timeout after 60 seconds
        if run_time > 60:
            self.done = True
            return None

        return (2, 2)  # Maintain 2 users
