public class ModelSimulation extends Simulation {

    private static final String BASE_URL = System.getenv().getOrDefault("BASE_URL", "http://127.0.0.1:8000");

    private static final Pattern CSRF_INPUT_PATTERN = Pattern.compile(
        "<input(?=[^>]*\\bname=[\"']csrf[\"'])(?=[^>]*\\bvalue=[\"']([^\"']+)[\"'])[^>]*>"
    );
    private static final Pattern ERROR_EXPIRED_SESSION_PATTERN = Pattern.compile(
        "\"error\"\\s*:\\s*\"(?:expired|session)\""
    );
    private static final Pattern ETAG_HEADER_PATTERN = Pattern.compile(
        "(?im)^ETag:\\s*([^\\r\\n]+)"
    );
    private static final Pattern LOCATION_HEADER_PATTERN = Pattern.compile(
        "(?im)^Location:\\s*([^\\r\\n]+)"
    );
    private static final Pattern LOCATION_HEADER_PRESENT_PATTERN = Pattern.compile(
        "(?im)^Location:"
    );
    private static final Pattern CART_ID_PATTERN = Pattern.compile(
        "\"id\"\\s*:\\s*\"cart-"
    );
    private static final Pattern ACCEPTED_TRUE_PATTERN = Pattern.compile(
        "\"accepted\"\\s*:\\s*true"
    );
    private static final Pattern CSRF_JSON_PATTERN = Pattern.compile(
        "\"csrf\"\\s*:"
    );

    private static String extractFirst(Pattern pattern, String input, String defaultValue) {
        Matcher matcher = pattern.matcher(input);
        if (matcher.find()) {
            if (matcher.groupCount() >= 1) {
                return matcher.group(1);
            }
            return "true";
        }
        return defaultValue;
    }

    private static boolean matches(Pattern pattern, String input) {
        return pattern.matcher(input).find();
    }

    private static String extractCsrfFromForm(String body) {
        Matcher matcher = CSRF_INPUT_PATTERN.matcher(body);
        if (matcher.find()) {
            return matcher.group(1);
        }
        return "MISSING";
    }

    private static String extractJsonString(String body, String key, String defaultValue) {
        Pattern p = Pattern.compile("\"" + Pattern.quote(key) + "\"\\s*:\\s*\"([^\"]+)\"");
        Matcher m = p.matcher(body);
        if (m.find()) {
            return m.group(1);
        }
        return defaultValue;
    }

    private static String extractJsonNumberAsString(String body, String key, String defaultValue) {
        Pattern p = Pattern.compile("\"" + Pattern.quote(key) + "\"\\s*:\\s*(\\d+)");
        Matcher m = p.matcher(body);
        if (m.find()) {
            return m.group(1);
        }
        return defaultValue;
    }

    private static String extractJsonBooleanAsString(String body, String key, String defaultValue) {
        Pattern p = Pattern.compile("\"" + Pattern.quote(key) + "\"\\s*:\\s*(true|false)");
        Matcher m = p.matcher(body);
        if (m.find()) {
            return m.group(1);
        }
        return defaultValue;
    }

    private static String extractProductIdFromCatalog(String body) {
        Pattern p = Pattern.compile("\"products\"\\s*:\\s*\\[(.*?)\\]", Pattern.DOTALL);
        Matcher m = p.matcher(body);
        if (!m.find()) {
            return "MISSING";
        }
        String productsBlock = m.group(1);
        Pattern productPattern = Pattern.compile("\\{[^{}]*?\"id\"\\s*:\\s*\"([^\"]+)\"[^{}]*?\"variants\"\\s*:\\s*\\[(.*?)\\]", Pattern.DOTALL);
        Matcher pm = productPattern.matcher(productsBlock);
        while (pm.find()) {
            String productId = pm.group(1);
            String variantsBlock = pm.group(2);
            Pattern variantPattern = Pattern.compile("\\{[^{}]*?\"id\"\\s*:\\s*\"([^\"]+)\"[^{}]*?\"in_stock\"\\s*:\\s*true[^{}]*?\\}");
            Matcher vm = variantPattern.matcher(variantsBlock);
            if (vm.find()) {
                return productId;
            }
        }
        return "MISSING";
    }

    private static String extractVariantIdFromCatalog(String body) {
        Pattern p = Pattern.compile("\"products\"\\s*:\\s*\\[(.*?)\\]", Pattern.DOTALL);
        Matcher m = p.matcher(body);
        if (!m.find()) {
            return "MISSING";
        }
        String productsBlock = m.group(1);
        Pattern productPattern = Pattern.compile("\\{[^{}]*?\"id\"\\s*:\\s*\"([^\"]+)\"[^{}]*?\"variants\"\\s*:\\s*\\[(.*?)\\]", Pattern.DOTALL);
        Matcher pm = productPattern.matcher(productsBlock);
        while (pm.find()) {
            String variantsBlock = pm.group(2);
            Pattern variantPattern = Pattern.compile("\\{[^{}]*?\"id\"\\s*:\\s*\"([^\"]+)\"[^{}]*?\"in_stock\"\\s*:\\s*true[^{}]*?\\}");
            Matcher vm = variantPattern.matcher(variantsBlock);
            if (vm.find()) {
                return vm.group(1);
            }
        }
        return "MISSING";
    }

    private static ChainBuilder loginAndCatalog() {
