                .check(status().is(200))
                .check(bodyString().transform(body -> matches(CSRF_JSON_PATTERN, body) ? "true" : "false").saveAs("loginCsrfPresent"))
                .check(bodyString().transform(body -> extractJsonString(body, "csrf", session -> session.getString("csrf"))).saveAs("csrf"))
                .check(headerRegex("Location").optional().saveAs("loginLocation"))
        )
