                    .check(bodyString().transform(body -> extractJsonString(body, "grant_id", session -> session.getString("grant"))).saveAs("grant"))
            )
        )
        .exec(
            http("GET /v2/catalog")
                .get("/v2/catalog")
                .check(status().is(200))
                .check(bodyString().transform(body -> extractJsonString(body, "csrf", session -> session.getString("csrf"))).saveAs("csrf"))
                .check(bodyString().transform(body -> extractProductIdFromCatalog(body)).saveAs("product"))
                .check(bodyString().transform(body -> extractVariantIdFromCatalog(body)).saveAs("variant"))
        );
    }

    private static ChainBuilder createCart() {
        return exec(session -> {
            String product = session.getString("product");
            String variant = session.getString("variant");
            String grant = session.getString("grant");
            String body = "{\"product_id\":\"" + product + "\",\"variant_id\":\"" + variant + "\",\"grant_id\":\"" + grant + "\"}";
            return session.set("cartBody", body);
        })
        .exec(
            http("POST /v2/carts")
                .post("/v2/carts")
                .header("Content-Type", "application/json")
                .header("X-CSRF-Token", session -> session.getString("csrf"))
                .body(StringBody(session -> session.getString("cartBody")))
                .check(status().is(201))
                .check(bodyString().transform(body -> matches(CART_ID_PATTERN, body) ? "true" : "false").saveAs("cartCreated"))
                .check(bodyString().transform(body -> extractJsonString(body, "csrf", session -> session.getString("csrf"))).saveAs("csrf"))
                .check(bodyString().transform(body -> extractJsonString(body, "id", session -> session.getString("cart"))).saveAs("cart"))
                .check(headerRegex("ETag").optional().saveAs("etag"))
        )
        .exec(session -> {
            String cart = session.getString("cart");
            if (cart != null && !cart.equals("MISSING")) {
                return session.set("hasCart", "true");
            }
            return session.set("hasCart", "false");
        });
    }

    private static ChainBuilder placeOrder() {
        return exec(session -> {
            String cart = session.getString("cart");
            String body = "{\"cart_id\":\"" + cart + "\"}";
            return session.set("orderBody", body);
        })
        .exec(
            http("POST /v2/orders")
                .post("/v2/orders")
                .header("Content-Type", "application/json")
                .header("X-CSRF-Token", session -> session.getString("csrf"))
                .header("Idempotency-Key", session -> session.getString("cart"))
                .body(StringBody(session -> session.getString("orderBody")))
                .check(status().is(201))
                .check(bodyString().transform(body -> matches(ACCEPTED_TRUE_PATTERN, body) ? "true" : "false").saveAs("orderAccepted"))
                .check(bodyString().transform(body -> extractJsonString(body, "csrf", session -> session.getString("csrf"))).saveAs("csrf"))
        );
    }

    private static ChainBuilder journey() {
        return exec(loginAndCatalog())
            .exec(createCart())
            .exec(placeOrder());
    }

    private final HttpProtocolBuilder httpProtocol = http
        .baseUrl(BASE_URL)
        .disableAutoReferer()
        .disableCaching()
        .disableFollowRedirect()
        .shareConnections()
        .contentTypeHeader("application/json")
        .acceptHeader("application/json");

    {
        setUp(
            scenario("ModelScenario")
                .exec(journey())
                .injectOpen(atOnceUsers(2))
        ).protocols(httpProtocol)
        .assertions(
            global().successfulRequests().percent().gte(100.0)
        );
    }
}
