```javascript
import http from 'k6/http';
import { check, fail } from 'k6';
import { Counter, Rate } from 'k6/metrics';

const BASE_URL = __ENV.BASE_URL || 'http://127.0.0.1:8000';

const businessFailure = new Rate('business_failure');

export const options = {
  scenarios: {
    flow: {
      executor: 'shared-iterations',
      vus: 2,
      iterations: 4,
      maxDuration: '5m',
    },
  },
};

function extractCsrfFromForm(html) {
  const regex = /<input(?=[^>]*\bname=["']csrf["'])(?=[^>]*\bvalue=["']([^"']+)["'])[^>]*>/;
  const match = html.match(regex);
  return match ? match[1] : null;
}

function extractLocation(headers) {
  const loc = headers['Location'];
  return loc ? loc : null;
}

function extractETag(headers) {
  const etag = headers['ETag'];
  return etag ? etag : null;
}

function extractError(body) {
  const match = body.match(/"error"\s*:\s*"(expired|session|denied)"/);
  return match ? match[1] : null;
}

function renewSession(httpClient, csrf) {
  const res = httpClient.post(`${BASE_URL}/v2/session/renew`, JSON.stringify({}), {
    headers: {
      'Content-Type': 'application/json',
      'X-CSRF-Token': csrf,
    },
  });
  if (res.status === 200) {
    try {
      const data = res.json();
      if (data.csrf) return { csrf: data.csrf, ok: true };
    } catch (e) {
      // ignore
    }
  }
  return { csrf, ok: false };
}

function recoverCart(httpClient, cartId, csrf) {
  if (!cartId || cartId === 'MISSING') return { ok: false, csrf };
  const res = httpClient.post(`${BASE_URL}/v2/carts/${cartId}/recover`, JSON.stringify({}), {
    headers: {
      'Content-Type': 'application/json',
      'X-CSRF-Token': csrf,
    },
  });
  if (res.status === 200) {
    try {
      const data = res.json();
      if (data.csrf) return { ok: true, csrf: data.csrf };
    } catch (e) {
      // ignore
    }
  }
  return { ok: false, csrf };
}

function freshLogin(httpClient, username) {
  // GET login form
  const formRes = httpClient.get(`${BASE_URL}/v2/login-form`, {
    headers: { 'Content-Type': 'application/json' },
  });
  check(formRes, { 'login form status 200': (r) => r.status === 200 });
  const formCsrf = extractCsrfFromForm(formRes.body);
  if (!formCsrf) {
    fail('No CSRF token found in login form');
  }

  // POST login
  const loginRes = httpClient.post(
    `${BASE_URL}/v2/login`,
    JSON.stringify({ username, password: 'bench', csrf: formCsrf }),
    {
      headers: {
        'Content-Type': 'application/json',
        'X-CSRF-Token': formCsrf,
      },
    }
  );

  let csrf = formCsrf;
  if (loginRes.status === 200) {
    try {
      const data = loginRes.json();
      if (data.csrf) csrf = data.csrf;
    } catch (e) {
      // ignore
    }
  } else if (loginRes.status === 302) {
    const location = extractLocation(loginRes.headers);
    if (location) {
      const redirectRes = httpClient.get(`${BASE_URL}${location}`, {
        headers: { 'Content-Type': 'application/json' },
      });
      if (redirectRes.status === 200) {
        try {
          const data = redirectRes.json();
          if (data.csrf) csrf = data.csrf;
        } catch (e) {
          // ignore
        }
      }
    }
  }

  return { csrf, loginRes };
}

function getCatalog(httpClient, csrf) {
  const res = httpClient.get(`${BASE_URL}/v2/catalog`, {
    headers: {
      'Content-Type': 'application/json',
      'X-CSRF-Token': csrf,
    },
  });
  check(res, { 'catalog status 200': (r) => r.status === 200 });
  let product = 'MISSING';
  let variant = 'MISSING';
  let newCsrf = csrf;
  try {
    const data = res.json();
    if (data.csrf) newCsrf = data.csrf;
    const products = data.data && data.data.products ? data.data.products : [];
    for (const p of products) {
      if (p.variants && p.variants.length > 0 && p.variants[0].in_stock === true) {
        product = p.id;
        variant = p.variants[0].id;
        break;
      }
    }
  } catch (e) {
    // ignore
  }
  return { product, variant, csrf: newCsrf };
}

function createCart(httpClient, csrf, product, variant, grant) {
  const body = {
    product_id: product,
    variant_id: variant,
  };
  if (grant && grant !== 'MISSING') {
    body.grant_id = grant;
  }
  const res = httpClient.post(`${BASE_URL}/v2/carts`, JSON.stringify(body), {
    headers: {
      'Content-Type': 'application/json',
      'X-CSRF-Token': csrf,
    },
  });
  check(res, { 'cart creation status 201': (r) => r.status === 201 });
  let cartId = 'MISSING';
  let newCsrf = csrf;
  let etag = null;
  try {
    const data = res.json();
    if (data.csrf) newCsrf = data.csrf;
    if (data.id) cartId = data.id;
  } catch (e) {
    // ignore
  }
  etag = extractETag(res.headers);
  return { cartId, csrf: newCsrf, etag, res };
}

function getCart(httpClient, cartId, csrf) {
  const res = httpClient.get(`${BASE_URL}/v2/carts/${cartId}`, {
    headers: {
      'Content-Type': 'application/json',
      'X-CSRF-Token': csrf,
    },
  });
  let newCsrf = csrf;
  try {
    const data = res.json();
    if (data.csrf) newCsrf = data.csrf;
  } catch (e) {
    // ignore
  }
  const etag = extractETag(res.headers);
  return { csrf: newCsrf, etag, res };
}

function patchCart(httpClient, cartId, csrf, etag, quantity) {
  const res = httpClient.patch(
    `${BASE_URL}/v2/carts/${cartId}`,
    JSON.stringify({ quantity }),
    {
      headers: {
        'Content-Type': 'application/json',
        'X-CSRF-Token': csrf,
        'If-Match': etag,
      },
    }
  );
  let newCsrf = csrf;
  try {
    const data = res.json();
    if (data.csrf) newCsrf = data.csrf;
  } catch (e) {
    // ignore
  }
  const newEtag = extractETag(res.headers);
  return { csrf: newCsrf, etag: newEtag || etag, res };
}

function createOrder(httpClient, cartId, csrf, etag, idempotencyKey) {
  const headers = {
    'Content-Type': 'application/json',
    'X-CSRF-Token': csrf,
    'Idempotency-Key': idempotencyKey,
  };
  if (etag) {
    headers['If-Match'] = etag;
  }
  const res = httpClient.post(`${BASE_URL}/v2/orders`, JSON.stringify({ cart_id: cartId }), {
    headers,
  });
  let newCsrf = csrf;
  try {
    const data = res.json();
    if (data.csrf) newCsrf = data.csrf;
  } catch (e) {
    // ignore
  }
  return { csrf: newCsrf, res };
}

function handleExpiredOrSession(httpClient, errorType, csrf, cartId) {
  let currentCsrf = csrf;
  if (errorType === 'expired') {
    const renewResult = renewSession(httpClient, currentCsrf);
    currentCsrf = renewResult.csrf;
    if (cartId && cartId !== 'MISSING') {
      const recoverResult = recoverCart(httpClient, cartId, currentCsrf);
      currentCsrf = recoverResult.csrf;
    }
    return { csrf: currentCsrf, recovered: true };
  } else if (errorType === 'session') {
    // Session revoked: get fresh form/login, recover cart
    const fresh = freshLogin(httpClient, `bench-${__VU}`);
    currentCsrf = fresh.csrf;
    if (cartId && cartId !== 'MISSING') {
      const recoverResult = recoverCart(httpClient, cartId, currentCsrf);
      currentCsrf = recoverResult.csrf;
    }
    return { csrf: currentCsrf, recovered: true };
  }
  return { csrf: currentCsrf, recovered: false };
}

export default function () {
  const username = `bench-${__VU}`;
  const httpClient = http;

  // Fresh login
  const loginResult = freshLogin(httpClient, username);
  let csrf = loginResult.csrf;
  let cartId = 'MISSING';
  let etag = null;
  let grant = 'MISSING';
  let hasCart = false;

  // Catalog
  const catalogResult = getCatalog(httpClient, csrf);
  csrf = catalogResult.csrf;
  const product = catalogResult.product;
  const variant = catalogResult.variant;

  if (product === 'MISSING' || variant === 'MISSING') {
    fail('No in-stock product found in catalog');
  }

  // Create cart
  let cartResult = createCart(httpClient, csrf, product, variant, grant);
  csrf = cartResult.csrf;
  cartId = cartResult.cartId;
  etag = cartResult.etag;
  hasCart = cartId !== 'MISSING';

  if (!hasCart) {
    fail('Cart creation failed');
  }

  // Get cart to obtain ETag
  const getCartResult = getCart(httpClient, cartId, csrf);
  csrf = getCartResult.csrf;
  etag = getCartResult.etag || etag;

  // Patch cart quantity
  let patchResult = patchCart(httpClient, cartId, csrf, etag, 2);
  csrf = patchResult.csrf;
  etag = patchResult.etag;

  if (patchResult.res.status === 412) {
    // Re-read and retry once
    const reRead = getCart(httpClient, cartId, csrf);
    csrf = reRead.csrf;
    etag = reRead.etag || etag;
    patchResult = patchCart(httpClient, cartId, csrf, etag, 2);
    csrf = patchResult.csrf;
    etag = patchResult.etag;
  }

  // Create order
  const idempotencyKey = `order-${cartId}`;
  let orderResult = createOrder(httpClient, cartId, csrf, etag, idempotencyKey);
  csrf = orderResult.csrf;

  // Handle 401 expiry/session for order
  if (orderResult.res.status === 401) {
    const errorType = extractError(orderResult.res.body);
    if (errorType === 'expired' || errorType === 'session') {
      const recovery = handleExpiredOrSession(httpClient, errorType, csrf, cartId);
      csrf = recovery.csrf;
      // Retry order once
      orderResult = createOrder(httpClient, cartId, csrf, etag, idempotencyKey);
      csrf = orderResult.csrf;
    }
  }

  // Check order accepted
  check(orderResult.res, {
    'order accepted': (r) => {
      if (r.status === 201) {
        try {
          const data = r.json();
          return data.accepted === true;
        } catch (e) {
          return false;
        }
      }
      return false;
    },
  });

  // Business failure tracking
  if (orderResult.res.status !== 201) {
    businessFailure.add(1);
  }
}
