import os
import re
import time
import json
import random
from urllib.parse import urljoin

from locust import HttpUser, task, between, LoadTestShape, events
from locust.exception import StopUser


BASE_URL = os.environ.get("BASE_URL", "http://127.0.0.1:8000")


class ShopUser(HttpUser):
    wait_time = between(0, 0)

    def __init__(self, *args, **kwargs):
        super().__init__(*args, **kwargs)
        self.username = None
        self.csrf = "MISSING"
        self.cart = "MISSING"
        self.etag = "MISSING"
        self.has_cart = False
        self.grant = "MISSING"
        self.product = "MISSING"
        self.variant = "MISSING"
        self.quantity = 2
        self.iterations_done = 0
        self.max_iterations = 2

    def _extract_csrf(self, response):
        try:
            data = response.json()
            if isinstance(data, dict) and "csrf" in data:
                self.csrf = data["csrf"]
        except Exception:
            pass

    def _extract_etag(self, response):
        etag = response.headers.get("ETag")
        if etag:
            self.etag = etag

    def _extract_location(self, response):
        return response.headers.get("Location")

    def _extract_form_csrf(self, response):
        match = re.search(
            r'<input(?=[^>]*\bname=["\']csrf["\'])(?=[^>]*\bvalue=["\']([^"\']+)["\'])[^>]*>',
            response.text,
            re.IGNORECASE,
        )
        if match:
            return match.group(1)
        return None

    def _handle_401_recovery(self, response, operation_func, *args, **kwargs):
        """Handle 401 expired/session recovery for an operation."""
        try:
            body = response.json()
            error = body.get("error", "")
        except Exception:
            return False

        if error in ("expired", "session"):
            # Try renew
            with self.client.post(
                "/v2/session/renew",
                json={},
                headers={"X-CSRF-Token": self.csrf, "Content-Type": "application/json"},
                catch_response=True,
            ) as renew_resp:
                if renew_resp.status_code == 200:
                    self._extract_csrf(renew_resp)
                    # Recover cart if exists
                    if self.has_cart and self.cart != "MISSING":
                        with self.client.post(
                            f"/v2/carts/{self.cart}/recover",
                            json={},
                            headers={"X-CSRF-Token": self.csrf, "Content-Type": "application/json"},
                            catch_response=True,
                        ) as recover_resp:
                            self._extract_csrf(recover_resp)
                            self._extract_etag(recover_resp)
                    # Retry operation once
                    return operation_func(*args, **kwargs)
                else:
                    # Session revoked - fresh login
                    self._fresh_login()
                    if self.has_cart and self.cart != "MISSING":
                        with self.client.post(
                            f"/v2/carts/{self.cart}/recover",
                            json={},
                            headers={"X-CSRF-Token": self.csrf, "Content-Type": "application/json"},
                            catch_response=True,
                        ) as recover_resp:
                            self._extract_csrf(recover_resp)
                            self._extract_etag(recover_resp)
                    return operation_func(*args, **kwargs)
        return False

    def _fresh_login(self):
        """Perform fresh login form + login."""
        with self.client.get("/v2/login-form", catch_response=True) as resp:
            if resp.status_code != 200:
                resp.failure(f"login-form failed: {resp.status_code}")
                return False
            form_csrf = self._extract_form_csrf(resp)
            if form_csrf:
                self.csrf = form_csrf

        with self.client.post(
            "/v2/login",
            json={"username": self.username, "password": "bench", "csrf": self.csrf},
            headers={"Content-Type": "application/json", "X-CSRF-Token": self.csrf},
            catch_response=True,
        ) as resp:
            if resp.status_code == 302:
                location = self._extract_location(resp)
                if location:
                    with self.client.get(
                        urljoin(BASE_URL, location),
                        headers={"X-CSRF-Token": self.csrf},
                        catch_response=True,
                    ) as redirect_resp:
                        self._extract_csrf(redirect_resp)
                        self._extract_etag(redirect_resp)
                        if redirect_resp.status_code != 200:
                            redirect_resp.failure(f"redirect failed: {redirect_resp.status_code}")
                            return False
                else:
                    resp.failure("302 without Location")
                    return False
            elif resp.status_code == 200:
                self._extract_csrf(resp)
                self._extract_etag(resp)
                if '"csrf"' not in resp.text:
                    resp.failure("login response missing csrf")
                    return False
            else:
                resp.failure(f"login failed: {resp.status_code}")
                return False
        return True

    def _do_login(self):
        self.username = f"bench-{self._user_id}"
        return self._fresh_login()

    def _do_catalog(self):
        with self.client.get("/v2/catalog", catch_response=True) as resp:
            if resp.status_code != 200:
                resp.failure(f"catalog failed: {resp.status_code}")
                return False
            self._extract_csrf(resp)
            self._extract_etag(resp)
            try:
                data = resp.json()
                products = data.get("data", {}).get("products", [])
                for p in products:
                    variants = p.get("variants", [])
                    if variants and variants[0].get("in_stock"):
                        self.product = p["id"]
                        self.variant = variants[0]["id"]
                        return True
                resp.failure("no in-stock product found")
                return False
            except Exception as e:
                resp.failure(f"catalog parse error: {e}")
                return False

    def _do_create_cart(self):
        payload = {"product_id": self.product, "variant_id": self.variant}
        if self.grant != "MISSING":
            payload["grant_id"] = self.grant

        with self.client.post(
            "/v2/carts",
            json=payload,
            headers={"Content-Type": "application/json", "X-CSRF-Token": self.csrf},
            catch_response=True,
        ) as resp:
            if resp.status_code == 401:
                if self._handle_401_recovery(resp, self._do_create_cart):
                    return True
                resp.failure("cart creation 401 not recovered")
                return False
            if resp.status_code != 201:
                resp.failure(f"cart creation failed: {resp.status_code}")
                return False
            self._extract_csrf(resp)
            self._extract_etag(resp)
            try:
                data = resp.json()
                cart_id = data.get("id")
                if cart_id and "cart-" in str(cart_id):
                    self.cart = cart_id
                    self.has_cart = True
                    return True
                resp.failure("cart creation missing cart id")
                return False
            except Exception as e:
                resp.failure(f"cart creation parse error: {e}")
                return False

    def _do_order(self):
        headers = {
            "Content-Type": "application/json",
            "X-CSRF-Token": self.csrf,
            "Idempotency-Key": self.cart,
        }
        if self.etag != "MISSING":
            headers["If-Match"] = self.etag

        with self.client.post(
            "/v2/orders",
            json={"cart_id": self.cart},
            headers=headers,
            catch_response=True,
        ) as resp:
            if resp.status_code == 401:
                if self._handle_401_recovery(resp, self._do_order):
                    return True
                resp.failure("order 401 not recovered")
                return False
            if resp.status_code != 201:
                resp.failure(f"order failed: {resp.status_code}")
                return False
            self._extract_csrf(resp)
            self._extract_etag(resp)
            if '"accepted"\s*:\s*true' not in resp.text:
                resp.failure("order not accepted")
                return False
            return True

    @task
    def shop_journey(self):
        if self.iterations_done >= self.max_iterations:
            raise StopUser()

        self.iterations_done += 1

        # Reset per-iteration state
        self.csrf = "MISSING"
        self.cart = "MISSING"
        self.etag = "MISSING"
        self.has_cart = False
        self.grant = "MISSING"
        self.product = "MISSING"
        self.variant = "MISSING"

        if not self._do_login():
            return
        if not self._do_catalog():
            return
        if not self._do_create_cart():
            return
        self._do_order()


class LoadShape(LoadTestShape):
    def tick(self):
        run_time = self.get_run_time()
        if run_time < 60:
            return (2, 2)
        return None
