import io.gatling.javaapi.core.*;
import io.gatling.javaapi.http.*;
import io.gatling.javaapi.core.CoreDsl.*;
import io.gatling.javaapi.http.HttpDsl.*;

import java.time.Duration;
import java.util.*;
import java.util.concurrent.atomic.AtomicInteger;

public class ModelSimulation extends Simulation {

    private static final String BASE_URL = System.getenv().getOrDefault("BASE_URL", "http://127.0.0.1:8000");
    private static final AtomicInteger USER_SEQ = new AtomicInteger(0);

    private static final Map<String, String> SESSION_HEADERS = Map.of(
        "Content-Type", "application/json",
        "X-CSRF-Token", "#{csrf}",
        "If-Match", "#{etag}",
        "Idempotency-Key", "#{cart}"
    );

    private static String nextUsername() {
        int idx = USER_SEQ.incrementAndGet();
        return "bench-" + (((idx - 1) % 16) + 1);
    }

    private static ChainBuilder loginForm() {
        return exec(
            http("GET /v2/login-form")
                .get("/v2/login-form")
                .headers(Map.of("Content-Type", "application/json"))
                .check(
                    regex("<input(?=[^>]*\\bname=[\"']csrf[\"'])(?=[^>]*\\bvalue=[\"']([^\"']+)[\"'])[^>]*>")
                        .find(0)
                        .saveAs("form"),
                    header("Set-Cookie").optional().saveAs("loginCookie")
                )
        );
    }

    private static ChainBuilder login() {
        return exec(
            http("POST /v2/login")
                .post("/v2/login")
                .headers(Map.of(
                    "Content-Type", "application/json",
                    "X-CSRF-Token", "#{csrf}"
                ))
                .body(StringBody("{\"username\":\"#{username}\",\"password\":\"bench\",\"csrf\":\"#{form}\"}"))
                .check(
                    status().is(200),
                    jsonPath("$.csrf").saveAs("csrf"),
                    header("Location").optional().saveAs("location"),
                    header("Location").exists().transform(s -> s != null && !s.isEmpty()).saveAs("redirect")
                )
        );
    }

    private static ChainBuilder followRedirect() {
        return doIf(session -> session.getBoolean("redirect"))
            .then(
                exec(
                    http("GET redirect location")
                        .get("#{location}")
                        .headers(Map.of(
                            "Content-Type", "application/json",
                            "X-CSRF-Token", "#{csrf}"
                        ))
                        .check(
                            status().is(200),
                            jsonPath("$.csrf").optional().saveAs("csrf"),
                            jsonPath("$.grant_id").optional().saveAs("grant")
                        )
                )
            );
    }

    private static ChainBuilder catalog() {
        return exec(
            http("GET /v2/catalog")
                .get("/v2/catalog")
                .headers(Map.of(
                    "Content-Type", "application/json",
                    "X-CSRF-Token", "#{csrf}"
                ))
                .check(
                    status().is(200),
                    jsonPath("$.data.products[?(@.variants[0].in_stock == true)].id")
                        .find(0)
                        .saveAs("product"),
                    jsonPath("$.data.products[?(@.variants[0].in_stock == true)].variants[0].id")
                        .find(0)
                        .saveAs("variant")
                )
        );
    }

    private static ChainBuilder createCart() {
        return exec(
            http("POST /v2/carts")
                .post("/v2/carts")
                .headers(Map.of(
                    "Content-Type", "application/json",
                    "X-CSRF-Token", "#{csrf}"
                ))
                .body(StringBody("{\"product_id\":\"#{product}\",\"variant_id\":\"#{variant}\",\"grant_id\":\"#{grant}\"}"))
                .check(
                    status().is(201),
                    jsonPath("$.id").saveAs("cart"),
                    jsonPath("$.csrf").optional().saveAs("csrf"),
                    regex("\"id\"\\s*:\\s*\"cart-").exists()
                )
        );
    }

    private static ChainBuilder createOrder() {
        return exec(
            http("POST /v2/orders")
                .post("/v2/orders")
                .headers(Map.of(
                    "Content-Type", "application/json",
                    "X-CSRF-Token", "#{csrf}",
                    "Idempotency-Key", "#{cart}"
                ))
                .body(StringBody("{\"cart_id\":\"#{cart}\"}"))
                .check(
                    status().is(201),
                    jsonPath("$.accepted").is("true"),
                    jsonPath("$.csrf").optional().saveAs("csrf")
                )
        );
    }

    private static ChainBuilder journey() {
        return exec(session -> session
                .set("csrf", "MISSING")
                .set("cart", "MISSING")
                .set("etag", "MISSING")
                .set("grant", "MISSING")
                .set("product", "MISSING")
                .set("variant", "MISSING")
                .set("form", "MISSING")
                .set("location", "")
                .set("redirect", false)
                .set("username", nextUsername()))
            .exec(loginForm())
            .exec(login())
            .exec(followRedirect())
            .exec(catalog())
            .exec(createCart())
            .exec(createOrder());
    }

    private static final HttpProtocolBuilder httpProtocol =
        http.baseUrl(BASE_URL)
            .disableAutoReferer()
            .disableCaching()
            .disableFollowRedirect()
            .shareConnections()
            .acceptHeader("application/json")
            .userAgentHeader("Gatling/3.15");

    {
        setUp(
            scenario("ModelScenario")
                .exec(journey())
                .injectOpen(atOnceUsers(2))
        ).protocols(httpProtocol)
         .assertions(
            global().successfulRequests().percent().gte(100.0)
         );
    }
}
