function extractCsrfFromHtml(html) {
  const patterns = [
    /<input[^>]*\bname=["']csrf["'][^>]*\bvalue=["']([^"']+)["'][^>]*>/i,
    /<input[^>]*\bvalue=["']([^"']+)["'][^>]*\bname=["']csrf["'][^>]*>/i,
  ];
  for (const re of patterns) {
    const m = html.match(re);
    if (m) return m[1];
  }
  return null;
}

function extractLocation(headers) {
  const loc = headers['Location'];
  if (!loc) return null;
  return loc;
}

function parseJsonSafely(res) {
  try {
    return res.json();
  } catch (e) {
    return null;
  }
}

function handleExpiry(res, state) {
  if (res.status !== 401) return false;
  let body = null;
  try {
    body = res.json();
  } catch (e) {
    body = null;
  }
  const err = body && body.error;
  if (err === 'expired' || err === 'session') {
    const renewRes = http.post(`${BASE_URL}/v2/session/renew`, '{}', {
      headers: {
        'Content-Type': 'application/json',
        'X-CSRF-Token': state.csrf,
      },
      redirects: 0,
    });
    if (renewRes.status === 200) {
      const renewBody = parseJsonSafely(renewRes);
      if (renewBody && renewBody.csrf) state.csrf = renewBody.csrf;
      if (state.cartId) {
        http.post(
          `${BASE_URL}/v2/carts/${state.cartId}/recover`,
          '{}',
          {
            headers: {
              'Content-Type': 'application/json',
              'X-CSRF-Token': state.csrf,
            },
            redirects: 0,
          }
        );
      }
      return true;
    }
    // session revoked: fresh login
    const formRes = http.get(`${BASE_URL}/v2/login-form`, { redirects: 0 });
    const formCsrf = extractCsrfFromHtml(formRes.body);
    if (!formCsrf) fail('login form csrf missing during recovery');
    const loginRes = http.post(
      `${BASE_URL}/v2/login`,
      JSON.stringify({
        username: state.username,
        password: 'bench',
        csrf: formCsrf,
      }),
      {
        headers: { 'Content-Type': 'application/json' },
        redirects: 0,
      }
    );
    if (loginRes.status === 302) {
      const loc = extractLocation(loginRes.headers);
      if (loc) {
        const followRes = http.get(new URL(loc, BASE_URL).toString(), {
          redirects: 0,
        });
        const followBody = parseJsonSafely(followRes);
        if (followBody && followBody.csrf) state.csrf = followBody.csrf;
      }
    } else {
      const loginBody = parseJsonSafely(loginRes);
      if (loginBody && loginBody.csrf) state.csrf = loginBody.csrf;
    }
    if (state.cartId) {
      http.post(
        `${BASE_URL}/v2/carts/${state.cartId}/recover`,
        '{}',
        {
          headers: {
            'Content-Type': 'application/json',
            'X-CSRF-Token': state.csrf,
          },
          redirects: 0,
        }
      );
    }
    return true;
  }
  return false;
}

function login(state) {
  const formRes = http.get(`${BASE_URL}/v2/login-form`, { redirects: 0 });
  check(formRes, { 'login form status 200': (r) => r.status === 200 });
  const formCsrf = extractCsrfFromHtml(formRes.body);
  if (!formCsrf) fail('login form csrf missing');

  const loginRes = http.post(
    `${BASE_URL}/v2/login`,
    JSON.stringify({
      username: state.username,
      password: 'bench',
      csrf: formCsrf,
    }),
    {
      headers: { 'Content-Type': 'application/json' },
      redirects: 0,
    }
  );

  if (loginRes.status === 302) {
    const loc = extractLocation(loginRes.headers);
    if (!loc) fail('login 302 missing Location');
    const followRes = http.get(new URL(loc, BASE_URL).toString(), {
      redirects: 0,
    });
    check(followRes, { 'redirect follow status 200': (r) => r.status === 200 });
    const followBody = parseJsonSafely(followRes);
    if (followBody && followBody.csrf) state.csrf = followBody.csrf;
    if (followBody && followBody.grant_id) state.grantId = followBody.grant_id;
  } else {
    check(loginRes, { 'login status 200': (r) => r.status === 200 });
    const loginBody = parseJsonSafely(loginRes);
    if (loginBody && loginBody.csrf) state.csrf = loginBody.csrf;
  }
}

function getCatalogProduct(state) {
  const catalogRes = http.get(`${BASE_URL}/v2/catalog`, { redirects: 0 });
  check(catalogRes, { 'catalog status 200': (r) => r.status === 200 });
  const catalogBody = parseJsonSafely(catalogRes);
  if (!catalogBody || !catalogBody.data || !catalogBody.data.products) {
    fail('catalog missing products');
  }
  const products = catalogBody.data.products;
  for (const product of products) {
    if (product.variants && product.variants.length > 0 && product.variants[0].in_stock) {
      state.productId = product.id;
      state.variantId = product.variants[0].id;
      return;
    }
  }
  fail('no in-stock product found');
}

function createCart(state) {
  const payload = {
    product_id: state.productId,
    variant_id: state.variantId,
  };
  if (state.grantId) payload.grant_id = state.grantId;

  const cartRes = http.post(`${BASE_URL}/v2/carts`, JSON.stringify(payload), {
    headers: {
      'Content-Type': 'application/json',
      'X-CSRF-Token': state.csrf,
    },
    redirects: 0,
  });

  if (cartRes.status === 401 && handleExpiry(cartRes, state)) {
    const retryRes = http.post(`${BASE_URL}/v2/carts`, JSON.stringify(payload), {
      headers: {
        'Content-Type': 'application/json',
        'X-CSRF-Token': state.csrf,
      },
      redirects: 0,
    });
    check(retryRes, { 'cart retry status 201': (r) => r.status === 201 });
    const retryBody = parseJsonSafely(retryRes);
    if (retryBody && retryBody.csrf) state.csrf = retryBody.csrf;
    if (retryBody && retryBody.id) state.cartId = retryBody.id;
    return;
  }

  check(cartRes, { 'cart status 201': (r) => r.status === 201 });
  const cartBody = parseJsonSafely(cartRes);
  if (cartBody && cartBody.csrf) state.csrf = cartBody.csrf;
  if (cartBody && cartBody.id) state.cartId = cartBody.id;
}

function placeOrder(state) {
  const idempotencyKey = `order-${state.cartId}`;
  const payload = { cart_id: state.cartId };

  const orderRes = http.post(`${BASE_URL}/v2/orders`, JSON.stringify(payload), {
    headers: {
      'Content-Type': 'application/json',
      'X-CSRF-Token': state.csrf,
      'Idempotency-Key': idempotencyKey,
    },
    redirects: 0,
  });

  if (orderRes.status === 401 && handleExpiry(orderRes, state)) {
    const retryRes = http.post(`${BASE_URL}/v2/orders`, JSON.stringify(payload), {
      headers: {
        'Content-Type': 'application/json',
        'X-CSRF-Token': state.csrf,
        'Idempotency-Key': idempotencyKey,
      },
      redirects: 0,
    });
    check(retryRes, { 'order retry accepted': (r) => r.status === 201 });
    const retryBody = parseJsonSafely(retryRes);
    if (retryBody && retryBody.csrf) state.csrf = retryBody.csrf;
    return;
  }

  check(orderRes, { 'order status 201': (r) => r.status === 201 });
  const orderBody = parseJsonSafely(orderRes);
  if (orderBody && orderBody.csrf) state.csrf = orderBody.csrf;
  check(orderBody, {
    'order accepted true': (b) => b && b.accepted === true,
  });
}

export default function () {
  const vuId = __VU;
  const state = {
    username: `bench-${vuId}`,
    csrf: 'MISSING',
    cartId: null,
    grantId: null,
    productId: null,
    variantId: null,
  };

  login(state);
  getCatalogProduct(state);
  createCart(state);
  placeOrder(state);
}
