import os
import re
import time
import json
from locust import HttpUser, task, between, LoadTestShape, events
from locust.exception import StopUser

BASE = os.environ.get("BASE_URL", "http://127.0.0.1:8000")
USERS = 2
ITERATIONS = 2


class ShopUser(HttpUser):
    host = BASE
    wait_time = between(0, 0)

    def __init__(self, *args, **kwargs):
        super().__init__(*args, **kwargs)
        self.csrf = "MISSING"
        self.cart_id = None
        self.etag = None
        self.grant_id = None
        self.product_id = None
        self.variant_id = None
        self.iterations_done = 0
        self.username = None

    def on_start(self):
        self.username = f"bench-{self._user_id()}"
        self._login()

    def _user_id(self):
        # bench-1..bench-16 based on environment; fallback to worker id
        return (self.environment.runner.user_count % 16) + 1 if self.environment.runner else 1

    def _login(self):
        # GET login form
        with self.client.get(
            "/v2/login-form",
            catch_response=True,
            allow_redirects=False,
        ) as resp:
            if resp.status_code != 200:
                resp.failure(f"login-form status {resp.status_code}")
                return
            match = re.search(
                r'<input(?=[^>]*\bname=["\']csrf["\'])(?=[^>]*\bvalue=["\']([^"\']+)["\'])[^>]*>',
                resp.text,
            )
            if not match:
                resp.failure("csrf input not found")
                return
            form_csrf = match.group(1)

        # POST login
        with self.client.post(
            "/v2/login",
            json={"username": self.username, "password": "bench", "csrf": form_csrf},
            headers={"X-CSRF-Token": self.csrf},
            catch_response=True,
            allow_redirects=False,
        ) as resp:
            if resp.status_code in (301, 302, 303, 307, 308):
                location = resp.headers.get("Location")
                if not location:
                    resp.failure("redirect without Location")
                    return
                # Follow dynamic Location exactly once
                with self.client.get(
                    location,
                    headers={"X-CSRF-Token": self.csrf},
                    catch_response=True,
                    allow_redirects=False,
                ) as redir_resp:
                    if redir_resp.status_code != 200:
                        redir_resp.failure(f"redirect GET status {redir_resp.status_code}")
                        return
                    self._extract_csrf_grant(redir_resp)
            elif resp.status_code == 200:
                self._extract_csrf_grant(resp)
            else:
                resp.failure(f"login status {resp.status_code}")

    def _extract_csrf_grant(self, resp):
        try:
            data = resp.json()
        except Exception:
            resp.failure("invalid JSON")
            return
        if "csrf" in data:
            self.csrf = data["csrf"]
        if "grant_id" in data:
            self.grant_id = data["grant_id"]

    def _handle_401(self, resp, operation_retry):
        """Handle 401 expiry/session recovery. Returns True if retry should be attempted."""
        try:
            body = resp.json()
        except Exception:
            return False
        error = body.get("error", "")
        if error == "expired":
            # renew session
            with self.client.post(
                "/v2/session/renew",
                json={},
                headers={"X-CSRF-Token": self.csrf},
                catch_response=True,
                allow_redirects=False,
            ) as renew_resp:
                if renew_resp.status_code == 200:
                    try:
                        renew_data = renew_resp.json()
                        if "csrf" in renew_data:
                            self.csrf = renew_data["csrf"]
                    except Exception:
                        pass
                else:
                    renew_resp.failure(f"renew status {renew_resp.status_code}")
                    return False
            if self.cart_id:
                with self.client.post(
                    f"/v2/carts/{self.cart_id}/recover",
                    json={},
                    headers={"X-CSRF-Token": self.csrf},
                    catch_response=True,
                    allow_redirects=False,
                ) as rec_resp:
                    if rec_resp.status_code != 200:
                        rec_resp.failure(f"recover status {rec_resp.status_code}")
                        return False
            return True
        elif error == "session":
            # session revoked: fresh login, recover cart
            self._login()
            if self.cart_id:
                with self.client.post(
                    f"/v2/carts/{self.cart_id}/recover",
                    json={},
                    headers={"X-CSRF-Token": self.csrf},
                    catch_response=True,
                    allow_redirects=False,
                ) as rec_resp:
                    if rec_resp.status_code != 200:
                        rec_resp.failure(f"recover status {rec_resp.status_code}")
                        return False
            return True
        elif error == "denied":
            resp.failure("denied error")
            return False
        return False

    def _get_catalog(self):
        with self.client.get(
            "/v2/catalog",
            headers={"X-CSRF-Token": self.csrf},
            catch_response=True,
            allow_redirects=False,
        ) as resp:
            if resp.status_code == 401:
                if self._handle_401(resp, None):
                    return self._get_catalog()
                return False
            if resp.status_code != 200:
                resp.failure(f"catalog status {resp.status_code}")
                return False
            try:
                data = resp.json()
            except Exception:
                resp.failure("catalog invalid JSON")
                return False
            products = data.get("data", {}).get("products", [])
            for p in products:
                variants = p.get("variants", [])
                if variants and variants[0].get("in_stock"):
                    self.product_id = p["id"]
                    self.variant_id = variants[0]["id"]
                    return True
            # traverse pages
            next_url = data.get("next")
            pages = 0
            while next_url and pages < 3:
                pages += 1
                with self.client.get(
                    next_url,
                    headers={"X-CSRF-Token": self.csrf},
                    catch_response=True,
                    allow_redirects=False,
                ) as page_resp:
                    if page_resp.status_code == 401:
                        if self._handle_401(page_resp, None):
                            continue
                        return False
                    if page_resp.status_code != 200:
                        page_resp.failure(f"catalog page status {page_resp.status_code}")
                        return False
                    try:
                        page_data = page_resp.json()
                    except Exception:
                        page_resp.failure("catalog page invalid JSON")
                        return False
                    product = page_data.get("data", {}).get("product")
                    if product:
                        variants = product.get("variants", [])
                        if variants and variants[0].get("in_stock"):
                            self.product_id = product["id"]
                            self.variant_id = variants[0]["id"]
                            return True
                    next_url = page_data.get("next")
            resp.failure("no in-stock product found")
            return False

    def _create_cart(self):
        payload = {
            "product_id": self.product_id,
            "variant_id": self.variant_id,
        }
        if self.grant_id:
            payload["grant_id"] = self.grant_id
        with self.client.post(
            "/v2/carts",
            json=payload,
            headers={"X-CSRF-Token": self.csrf},
            catch_response=True,
            allow_redirects=False,
        ) as resp:
            if resp.status_code == 401:
                if self._handle_401(resp, None):
                    return self._create_cart()
                return False
            if resp.status_code != 201:
                resp.failure(f"cart create status {resp.status_code}")
                return False
            try:
                data = resp.json()
            except Exception:
                resp.failure("cart create invalid JSON")
                return False
            if "id" not in data or not str(data["id"]).startswith("cart-"):
                resp.failure("cart id missing")
                return False
            self.cart_id = data["id"]
            if "csrf" in data:
                self.csrf = data["csrf"]
            if "ETag" in resp.headers:
                self.etag = resp.headers["ETag"]
            return True

    def _place_order(self):
        headers = {
            "X-CSRF-Token": self.csrf,
            "Idempotency-Key": self.cart_id,
        }
        if self.etag:
            headers["If-Match"] = self.etag
        with self.client.post(
            "/v2/orders",
            json={"cart_id": self.cart_id},
            headers=headers,
            catch_response=True,
            allow_redirects=False,
        ) as resp:
            if resp.status_code == 401:
                if self._handle_401(resp, None):
                    return self._place_order()
                return False
            if resp.status_code != 201:
                resp.failure(f"order status {resp.status_code}")
                return False
            try:
                data = resp.json()
            except Exception:
                resp.failure("order invalid JSON")
                return False
            if not data.get("accepted"):
                resp.failure("order not accepted")
                return False
            if "csrf" in data:
                self.csrf = data["csrf"]
            return True

    @task
    def journey(self):
        if self.iterations_done >= ITERATIONS:
            raise StopUser()
        self.iterations_done += 1

        # Fresh login per journey
        self.csrf = "MISSING"
        self.cart_id = None
        self.etag = None
        self.grant_id = None
        self.product_id = None
        self.variant_id = None
        self._login()

        if not self._get_catalog():
            return
        if not self._create_cart():
            return
        self._place_order()


class TestShape(LoadTestShape):
    def tick(self):
        run_time = self.get_run_time()
        if run_time < 1:
            return (USERS, USERS)
        return None
