                    return False
                self.csrf = form_csrf
            with self.client.post(
                "/v2/login",
                json={
                    "username": self.account["username"],
                    "password": "bench",
                    "csrf": self.csrf,
                },
                headers=self._get_headers(),
                catch_response=True,
                name="/v2/login",
            ) as r:
                self._update_csrf_from_response(r)
                if r.status_code in (301, 302, 303, 307, 308):
                    location = r.headers.get("Location")
                    if location:
                        with self.client.get(
                            location,
                            headers=self._get_headers(),
                            catch_response=True,
                            name="GET login redirect",
                        ) as rr:
                            self._update_csrf_from_response(rr)
                            if rr.status_code >= 400:
                                rr.failure(f"redirect failed: {rr.status_code}")
                                return False
                elif r.status_code >= 400:
                    r.failure(f"login failed: {r.status_code}")
                    return False
            if self.cart_id:
                with self.client.post(
                    f"/v2/carts/{self.cart_id}/recover",
                    json={},
                    headers=self._get_headers(),
                    catch_response=True,
                    name="/v2/carts/{id}/recover",
                ) as r:
                    self._update_csrf_from_response(r)
                    if r.status_code >= 400:
                        r.failure(f"recover failed: {r.status_code}")
                        return False
            return True
        else:
            return False

    def _retry_with_recovery(self, method, url, json_body, name, success_check):
        for attempt in range(2):
            with self.client.request(
                method,
                url,
                json=json_body,
                headers=self._get_headers(),
                catch_response=True,
                name=name,
            ) as r:
                self._update_csrf_from_response(r)
                if r.status_code == 401:
                    if self._handle_401(r, name):
                        continue
                    else:
                        r.failure(f"401 denied on {name}")
                        return None
                if success_check(r):
                    return r
                if r.status_code == 412 and attempt == 0:
                    with self.client.get(
                        f"/v2/carts/{self.cart_id}",
                        headers=self._get_headers(),
                        catch_response=True,
                        name="/v2/carts/{id}",
                    ) as rr:
                        self._update_csrf_from_response(rr)
                        if rr.status_code >= 400:
                            rr.failure(f"cart get failed: {rr.status_code}")
                            return None
                    continue
                r.failure(f"{name} failed: {r.status_code} {r.text[:200]}")
                return None
        return None

    def _login(self):
        with self.client.get(
            "/v2/login-form",
            headers={"Content-Type": "application/json"},
            catch_response=True,
            name="/v2/login-form",
        ) as r:
            if r.status_code != 200:
                r.failure(f"login-form failed: {r.status_code}")
                return False
            form_csrf = extract_csrf_from_html(r.text)
            if not form_csrf:
                r.failure("no csrf in login form")
                return False
            self.csrf = form_csrf

        with self.client.post(
            "/v2/login",
            json={
                "username": self.account["username"],
                "password": "bench",
                "csrf": self.csrf,
            },
            headers=self._get_headers(),
            catch_response=True,
            name="/v2/login",
        ) as r:
            self._update_csrf_from_response(r)
            if r.status_code in (301, 302, 303, 307, 308):
                location = r.headers.get("Location")
                if location:
                    with self.client.get(
                        location,
                        headers=self._get_headers(),
                        catch_response=True,
                        name="GET login redirect",
                    ) as rr:
                        self._update_csrf_from_response(rr)
                        if rr.status_code >= 400:
                            rr.failure(f"redirect failed: {rr.status_code}")
                            return False
                else:
                    r.failure("redirect without Location")
                    return False
            elif r.status_code >= 400:
                r.failure(f"login failed: {r.status_code}")
                return False
            if not self.csrf or self.csrf == "MISSING":
                r.failure("no csrf after login")
                return False
        return True

    def _get_catalog_product(self):
        with self.client.get(
            "/v2/catalog",
            headers=self._get_headers(),
            catch_response=True,
            name="/v2/catalog",
        ) as r:
            self._update_csrf_from_response(r)
            if r.status_code != 200:
                r.failure(f"catalog failed: {r.status_code}")
                return None, None
            try:
                data = r.json()
                products = data.get("data", {}).get("products", [])
                for p in products:
                    for v in p.get("variants", []):
                        if v.get("in_stock"):
                            return p["id"], v["id"]
            except Exception:
                r.failure("catalog parse failed")
                return None, None

        for _ in range(3):
            with self.client.get(
                "/v2/catalog/page",
                headers=self._get_headers(),
                catch_response=True,
                name="/v2/catalog/page",
            ) as r:
                self._update_csrf_from_response(r)
                if r.status_code != 200:
                    r.failure(f"catalog page failed: {r.status_code}")
                    return None, None
                try:
                    data = r.json()
                    product = data.get("data", {}).get("product")
                    if product:
                        for v in product.get("variants", []):
                            if v.get("in_stock"):
                                return product["id"], v["id"]
                    next_url = data.get("next")
                    if not next_url:
                        break
                except Exception:
                    r.failure("catalog page parse failed")
                    return None, None
        return None, None

    def _create_cart(self, product_id, variant_id):
        payload = {"product_id": product_id, "variant_id": variant_id}
        if self.grant_id:
            payload["grant_id"] = self.grant_id
        with self.client.post(
            "/v2/carts",
            json=payload,
            headers=self._get_headers(),
            catch_response=True,
            name="/v2/carts",
        ) as r:
            self._update_csrf_from_response(r)
            if r.status_code == 401:
                if self._handle_401(r, "create cart"):
                    return self._create_cart(product_id, variant_id)
                r.failure("401 denied on create cart")
                return False
            if r.status_code != 201:
                r.failure(f"create cart failed: {r.status_code} {r.text[:200]}")
                return False
            try:
                data = r.json()
                self.cart_id = data.get("id")
                if not self.cart_id:
                    r.failure("no cart id")
                    return False
                if "csrf" in data:
                    self.csrf = data["csrf"]
                self.has_cart = True
                return True
            except Exception:
                r.failure("create cart parse failed")
                return False

    def _patch_cart(self, quantity):
        url = f"/v2/carts/{self.cart_id}"
        payload = {"quantity": quantity}
        for attempt in range(2):
            with self.client.patch(
                url,
                json=payload,
                headers=self._get_headers(),
                catch_response=True,
                name="/v2/carts/{id}",
            ) as r:
                self._update_csrf_from_response(r)
                if r.status_code == 401:
                    if self._handle_401(r, "patch cart"):
                        continue
                    r.failure("401 denied on patch cart")
                    return False
                if r.status_code == 412 and attempt == 0:
                    with self.client.get(
                        url,
                        headers=self._get_headers(),
                        catch_response=True,
                        name="/v2/carts/{id}",
                    ) as rr:
                        self._update_csrf_from_response(rr)
                        if rr.status_code >= 400:
                            rr.failure(f"cart get failed: {rr.status_code}")
                            return False
                    continue
                if r.status_code >= 400:
                    r.failure(f"patch cart failed: {r.status_code} {r.text[:200]}")
                    return False
                return True
        return False

    def _create_order(self):
        url = "/v2/orders"
        payload = {"cart_id": self.cart_id}
        for attempt in range(2):
            with self.client.post(
                url,
                json=payload,
                headers=self._get_headers(),
                catch_response=True,
                name="/v2/orders",
            ) as r:
                self._update_csrf_from_response(r)
                if r.status_code == 401:
                    if self._handle_401(r, "create order"):
                        continue
                    r.failure("401 denied on create order")
                    return False
                if r.status_code == 412 and attempt == 0:
                    with self.client.get(
                        f"/v2/carts/{self.cart_id}",
                        headers=self._get_headers(),
                        catch_response=True,
                        name="/v2/carts/{id}",
                    ) as rr:
                        self._update_csrf_from_response(rr)
                        if rr.status_code >= 400:
                            rr.failure(f"cart get failed: {rr.status_code}")
                            return False
                    continue
                if r.status_code != 201:
                    r.failure(f"create order failed: {r.status_code} {r.text[:200]}")
                    return False
                try:
                    data = r.json()
                    if not data.get("accepted"):
                        r.failure("order not accepted")
                        return False
                    return True
                except Exception:
                    r.failure("order parse failed")
                    return False
        return False

    @task
    def shop_journey(self):
        if self.iteration >= ITERATIONS:
            raise StopUser()

        user_num = self.user_index + 1
        if user_num == 1:
            account_row = CSV_1[0] if CSV_1 else ACCOUNTS[0]
        else:
            account_row = CSV_2[0] if CSV_2 else ACCOUNTS[1]
        self.account = account_row
        self.profile = PROFILES[(self.user_index + self.iteration) % len(PROFILES)]

        self.csrf = "MISSING"
        self.cart_id = None
        self.etag = None
        self.grant_id = None
        self.has_cart = False

        if not self._login():
            self.iteration += 1
            return

        product_id, variant_id = self._get_catalog_product()
        if not product_id:
            self.iteration += 1
            return

        if not self._create_cart(product_id, variant_id):
            self.iteration += 1
            return

        quantity = int(self.account.get("quantity", 2))
        if not self._patch_cart(quantity):
            self.iteration += 1
            return

        if not self._create_order():
            self.iteration += 1
            return

        self.iteration += 1
        if self.iteration >= ITERATIONS:
            raise StopUser()


class ShopLoadShape(LoadTestShape):
    def __init__(self):
        super().__init__()
        self.user_count = USERS
        self.spawn_rate = USERS
        self._tick_count = 0

    def tick(self):
        if self._tick_count == 0:
            self._tick_count += 1
            return (self.user_count, self.spawn_rate)
        run_time = self.get_run_time()
        if run_time > 120:
            return None
        return None
