import io.gatling.javaapi.core.*;
import io.gatling.javaapi.http.*;
import io.gatling.javaapi.core.CoreDsl.*;
import io.gatling.javaapi.http.HttpDsl.*;

import java.time.Duration;
import java.util.*;
import java.util.concurrent.atomic.AtomicInteger;

public class ModelSimulation extends Simulation {

    private static final String BASE_URL = System.getenv().getOrDefault("BASE_URL", "http://127.0.0.1:8000");
    private static final AtomicInteger USER_SEQ = new AtomicInteger(0);

    private static final HttpProtocolBuilder httpProtocol = http
            .baseUrl(BASE_URL)
            .disableAutoRedirect()
            .disableCaching()
            .acceptHeader("application/json")
            .contentTypeHeader("application/json")
            .userAgentHeader("gatling")
            .shareConnections();

    private static String extractCsrf(String body) {
        if (body == null) return null;
        java.util.regex.Matcher m = java.util.regex.Pattern.compile("\"csrf\"\\s*:\\s*\"([^\"]+)\"").matcher(body);
        return m.find() ? m.group(1) : null;
    }

    private static String extractGrantId(String body) {
        if (body == null) return null;
        java.util.regex.Matcher m = java.util.regex.Pattern.compile("\"grant_id\"\\s*:\\s*\"([^\"]+)\"").matcher(body);
        return m.find() ? m.group(1) : null;
    }

    private static String extractCartId(String body) {
        if (body == null) return null;
        java.util.regex.Matcher m = java.util.regex.Pattern.compile("\"id\"\\s*:\\s*\"(cart-[^\"]+)\"").matcher(body);
        return m.find() ? m.group(1) : null;
    }

    private static String extractProductId(String body) {
        if (body == null) return null;
        java.util.regex.Matcher m = java.util.regex.Pattern.compile("\"id\"\\s*:\\s*\"(prod-[^\"]+)\"[^}]*\"variants\"\\s*:\\s*\\[[^]]*\"in_stock\"\\s*:\\s*true").matcher(body);
        if (m.find()) return m.group(1);
        m = java.util.regex.Pattern.compile("\"products\"\\s*:\\s*\\[[^]]*?\\{\\s*\"id\"\\s*:\\s*\"(prod-[^\"]+)\"[^}]*?\"variants\"\\s*:\\s*\\[[^]]*?\"in_stock\"\\s*:\\s*true").matcher(body);
        return m.find() ? m.group(1) : null;
    }

    private static String extractVariantId(String body) {
        if (body == null) return null;
        java.util.regex.Matcher m = java.util.regex.Pattern.compile("\"variants\"\\s*:\\s*\\[\\s*\\{\\s*\"id\"\\s*:\\s*\"(var-[^\"]+)\"[^}]*\"in_stock\"\\s*:\\s*true").matcher(body);
        if (m.find()) return m.group(1);
        m = java.util.regex.Pattern.compile("\"products\"\\s*:\\s*\\[[^]]*?\\{\\s*\"id\"\\s*:\\s*\"prod-[^\"]+\"[^}]*?\"variants\"\\s*:\\s*\\[\\s*\\{\\s*\"id\"\\s*:\\s*\"(var-[^\"]+)\"[^}]*?\"in_stock\"\\s*:\\s*true").matcher(body);
        return m.find() ? m.group(1) : null;
    }

    private static String extractEtag(Map<String, String> headers) {
        String etag = headers.get("ETag");
        if (etag == null) etag = headers.get("etag");
        return etag;
    }

    private static String extractLocation(Map<String, String> headers) {
        String loc = headers.get("Location");
        if (loc == null) loc = headers.get("location");
        return loc;
    }

    private static ChainBuilder loginJourney() {
        return exec(session -> {
            int idx = USER_SEQ.incrementAndGet();
            String username = "bench-" + ((idx % 16 == 0) ? 16 : (idx % 16));
            return session.set("username", username)
                    .set("csrf", "MISSING")
                    .set("cart", "MISSING")
                    .set("etag", "MISSING")
                    .set("hasCart", false)
                    .set("grant", "MISSING")
                    .set("product", "MISSING")
                    .set("variant", "MISSING")
                    .set("quantity", 2)
                    .set("recover", false)
                    .set("redirect", false)
                    .set("location", "");
        })
        .exec(http("GET /v2/login-form")
                .get("/v2/login-form")
                .check(status().is(200))
                .check(regex("<input(?=[^>]*\\bname=[\"']csrf[\"'])(?=[^>]*\\bvalue=[\"']([^\"']+)[\"'])[^>]*>").find().saveAs("form_csrf"))
                .check(header("Set-Cookie").optional().saveAs("login_cookie"))
        )
        .exec(session -> session.set("csrf", session.getString("form_csrf")))
        .exec(http("POST /v2/login")
                .post("/v2/login")
                .header("X-CSRF-Token", session -> session.getString("csrf"))
                .body(StringBody(session -> "{\"username\":\"" + session.getString("username") + "\",\"password\":\"bench\",\"csrf\":\"" + session.getString("csrf") + "\"}"))
                .check(status().in(200, 302))
                .check(bodyString().transform(ModelSimulation::extractCsrf).optional().saveAs("login_csrf"))
                .check(header("Location").optional().saveAs("login_location"))
        )
        .exec(session -> {
            String csrf = session.getString("login_csrf");
            if (csrf != null && !csrf.isEmpty()) session = session.set("csrf", csrf);
            String loc = session.getString("login_location");
            if (loc != null && !loc.isEmpty()) session = session.set("redirect", true).set("location", loc);
            return session;
        })
        .doIf(session -> session.getBoolean("redirect")).then(
                exec(http("GET login redirect")
                        .get(session -> session.getString("location"))
                        .check(status().is(200))
                        .check(bodyString().transform(ModelSimulation::extractCsrf).optional().saveAs("redirect_csrf"))
                        .check(bodyString().transform(ModelSimulation::extractGrantId).optional().saveAs("redirect_grant"))
                )
                .exec(session -> {
                    String csrf = session.getString("redirect_csrf");
                    if (csrf != null && !csrf.isEmpty()) session = session.set("csrf", csrf);
                    String grant = session.getString("redirect_grant");
                    if (grant != null && !grant.isEmpty()) session = session.set("grant", grant);
                    return session;
                })
        );
    }

    private static ChainBuilder catalogAndCart() {
        return exec(http("GET /v2/catalog")
                .get("/v2/catalog")
                .header("X-CSRF-Token", session -> session.getString("csrf"))
                .check(status().is(200))
                .check(bodyString().saveAs("catalog_body"))
        )
        .exec(session -> {
            String body = session.getString("catalog_body");
            String product = extractProductId(body);
            String variant = extractVariantId(body);
            if (product != null) session = session.set("product", product);
            if (variant != null) session = session.set("variant", variant);
            return session;
        })
        .doIf(session -> "MISSING".equals(session.getString("product")) || "MISSING".equals(session.getString("variant"))).then(
                exec(http("GET /v2/catalog/page")
                        .get("/v2/catalog/page")
                        .header("X-CSRF-Token", session -> session.getString("csrf"))
                        .check(status().is(200))
                        .check(bodyString().saveAs("catalog_page_body"))
                )
                .exec(session -> {
                    String body = session.getString("catalog_page_body");
                    String product = extractProductId(body);
                    String variant = extractVariantId(body);
                    if (product != null) session = session.set("product", product);
                    if (variant != null) session = session.set("variant", variant);
                    return session;
                })
        )
        .exec(http("POST /v2/carts")
                .post("/v2/carts")
                .header("X-CSRF-Token", session -> session.getString("csrf"))
                .body(StringBody(session -> {
                    String grant = session.getString("grant");
                    String grantPart = "MISSING".equals(grant) ? "" : ",\"grant_id\":\"" + grant + "\"";
                    return "{\"product_id\":\"" + session.getString("product") + "\",\"variant_id\":\"" + session.getString("variant") + "\"" + grantPart + "}";
                }))
                .check(status().is(201))
                .check(bodyString().transform(ModelSimulation::extractCartId).saveAs("cart"))
                .check(bodyString().transform(ModelSimulation::extractCsrf).optional().saveAs("cart_csrf"))
                .check(header("ETag").optional().saveAs("cart_etag"))
        )
        .exec(session -> {
            String csrf = session.getString("cart_csrf");
            if (csrf != null && !csrf.isEmpty()) session = session.set("csrf", csrf);
            String etag = session.getString("cart_etag");
            if (etag != null && !etag.isEmpty()) session = session.set("etag", etag);
            session = session.set("hasCart", true);
            return session;
        });
    }

    private static ChainBuilder checkout() {
        return exec(http("POST /v2/orders")
                .post("/v2/orders")
                .header("X-CSRF-Token", session -> session.getString("csrf"))
                .header("Idempotency-Key", session -> session.getString("cart"))
                .header("If-Match", session -> session.getString("etag"))
                .body(StringBody(session -> "{\"cart_id\":\"" + session.getString("cart") + "\"}"))
                .check(status().is(201))
                .check(bodyString().transform(body -> body != null && body.contains("\"accepted\"\\s*:\\s*true")).is(true))
                .check(bodyString().transform(ModelSimulation::extractCsrf).optional().saveAs("order_csrf"))
        )
        .exec(session -> {
            String csrf = session.getString("order_csrf");
            if (csrf != null && !csrf.isEmpty()) session = session.set("csrf", csrf);
            return session;
        });
    }

    private static ChainBuilder journey() {
        return exec(loginJourney())
                .exec(catalogAndCart())
                .exec(checkout());
    }

    {
        setUp(
                scenario("ModelSimulation")
                        .exec(journey())
                        .injectOpen(
                                nothingFor(Duration.ofSeconds(5)),
                                atOnceUsers(2),
                                nothingFor(Duration.ofSeconds(10)),
                                atOnceUsers(2),
                                nothingFor(Duration.ofSeconds(10)),
                                atOnceUsers(2),
                                nothingFor(Duration.ofSeconds(10)),
                                atOnceUsers(2),
                                nothingFor(Duration.ofSeconds(5))
                        )
        ).protocols(httpProtocol)
         .maxDuration(Duration.ofSeconds(45))
         .assertions(
                global().failedRequests().percent().lt(1.0)
         );
    }
}
