import http from 'k6/http';
import { check, sleep } from 'k6';
import { Counter, Rate } from 'k6/metrics';

const BASE_URL = __ENV.BASE_URL || 'http://127.0.0.1:8000';

const committedStarts = new Counter('committed_checkout_starts');
const businessFailures = new Rate('business_failure');

const PROFILES = [
  {},
  { html_layout: 1, reverse_catalog: true },
];

function extractCsrfFromHtml(html) {
  const patterns = [
    /<input[^>]*\bname=["']csrf["'][^>]*\bvalue=["']([^"']+)["'][^>]*>/i,
    /<input[^>]*\bvalue=["']([^"']+)["'][^>]*\bname=["']csrf["'][^>]*>/i,
  ];
  for (const re of patterns) {
    const m = html.match(re);
    if (m) return m[1];
  }
  return null;
}

function extractLocation(headers) {
  const loc = headers['Location'];
  if (loc) return loc;
  return null;
}

function extractEtag(headers) {
  const etag = headers['ETag'];
  if (etag) return etag;
  return null;
}

function parseJsonSafely(res) {
  try {
    return res.json();
  } catch (e) {
    return null;
  }
}

function getErrorCode(res) {
  const body = parseJsonSafely(res);
  if (body && body.error) return body.error;
  return null;
}

function isExpiryError(res) {
  const code = getErrorCode(res);
  return code === 'expired' || code === 'session';
}

function isDeniedError(res) {
  return getErrorCode(res) === 'denied';
}

function renewSession(state) {
  const res = http.post(`${BASE_URL}/v2/session/renew`, '{}', {
    headers: {
      'Content-Type': 'application/json',
      'X-CSRF-Token': state.csrf,
    },
    redirects: 0,
  });
  if (res.status === 200) {
    const body = parseJsonSafely(res);
    if (body && body.csrf) state.csrf = body.csrf;
    return true;
  }
  return false;
}

function recoverCart(state) {
  if (!state.cartId) return false;
  const res = http.post(`${BASE_URL}/v2/carts/${state.cartId}/recover`, '{}', {
    headers: {
      'Content-Type': 'application/json',
      'X-CSRF-Token': state.csrf,
    },
    redirects: 0,
  });
  if (res.status === 200) {
    const body = parseJsonSafely(res);
    if (body && body.csrf) state.csrf = body.csrf;
    const etag = extractEtag(res.headers);
    if (etag) state.etag = etag;
    return true;
  }
  return false;
}

function freshLogin(state, username) {
  const formRes = http.get(`${BASE_URL}/v2/login-form`, { redirects: 0 });
  if (formRes.status !== 200) return false;
  const csrf = extractCsrfFromHtml(formRes.body);
  if (!csrf) return false;
  state.csrf = csrf;

  const loginRes = http.post(
    `${BASE_URL}/v2/login`,
    JSON.stringify({ username, password: 'bench', csrf }),
    {
      headers: {
        'Content-Type': 'application/json',
        'X-CSRF-Token': csrf,
      },
      redirects: 0,
    }
  );

  if (loginRes.status === 302) {
    const loc = extractLocation(loginRes.headers);
    if (!loc) return false;
    const followRes = http.get(`${BASE_URL}${loc}`, { redirects: 0 });
    if (followRes.status !== 200) return false;
    const body = parseJsonSafely(followRes);
    if (body && body.csrf) state.csrf = body.csrf;
    return true;
  }

  if (loginRes.status === 200) {
    const body = parseJsonSafely(loginRes);
    if (body && body.csrf) state.csrf = body.csrf;
    return true;
  }

  return false;
}

function handleChallenge(state) {
  const challengeRes = http.get(`${BASE_URL}/v2/challenge-form`, { redirects: 0 });
  if (challengeRes.status !== 200) return false;
  const html = challengeRes.body;
  const actionMatch = html.match(/<form[^>]*\baction=["']([^"']+)["'][^>]*>/i);
  const challengeMatch = html.match(/<input[^>]*\bname=["']challenge["'][^>]*>/i);
  if (!actionMatch || !challengeMatch) return false;
  const action = actionMatch[1];
  const postRes = http.post(
    `${BASE_URL}${action}`,
    JSON.stringify({ challenge: 'bench' }),
    {
      headers: {
        'Content-Type': 'application/json',
        'X-CSRF-Token': state.csrf,
      },
      redirects: 0,
    }
  );
  if (postRes.status !== 302) return false;
  const loc = extractLocation(postRes.headers);
  if (!loc) return false;
  const grantRes = http.get(`${BASE_URL}${loc}`, { redirects: 0 });
  if (grantRes.status !== 200) return false;
  const body = parseJsonSafely(grantRes);
  if (!body) return false;
  if (body.csrf) state.csrf = body.csrf;
  if (body.grant_id) state.grantId = body.grant_id;
  return true;
}

function selectProduct(state, profile) {
  const catalogRes = http.get(`${BASE_URL}/v2/catalog`, { redirects: 0 });
  if (catalogRes.status !== 200) return false;
  const body = parseJsonSafely(catalogRes);
  if (!body || !body.data || !body.data.products) return false;

  let products = body.data.products;
  if (profile.reverse_catalog) {
    products = [...products].reverse();
  }

  for (const product of products) {
    if (product.variants && product.variants.length > 0) {
      const variant = product.variants[0];
      if (variant.in_stock) {
        state.productId = product.id;
        state.variantId = variant.id;
        return true;
      }
    }
  }

  // Traverse up to 3 pages
  let next = body.next;
  for (let page = 0; page < 3 && next; page++) {
    const pageRes = http.get(`${BASE_URL}${next}`, { redirects: 0 });
    if (pageRes.status !== 200) return false;
    const pageBody = parseJsonSafely(pageRes);
    if (!pageBody || !pageBody.data) return false;
    const product = pageBody.data;
    if (product.variants && product.variants.length > 0) {
      const variant = product.variants[0];
      if (variant.in_stock) {
        state.productId = product.id;
        state.variantId = variant.id;
        return true;
      }
    }
    next = pageBody.next;
  }

  return false;
}

function createCart(state) {
  const payload = {
    product_id: state.productId,
    variant_id: state.variantId,
  };
  if (state.grantId) {
    payload.grant_id = state.grantId;
  }

  const res = http.post(`${BASE_URL}/v2/carts`, JSON.stringify(payload), {
    headers: {
      'Content-Type': 'application/json',
      'X-CSRF-Token': state.csrf,
    },
    redirects: 0,
  });

  if (res.status === 201) {
    const body = parseJsonSafely(res);
    if (!body || !body.id) return false;
    state.cartId = body.id;
    if (body.csrf) state.csrf = body.csrf;
    const etag = extractEtag(res.headers);
    if (etag) state.etag = etag;
    return true;
  }

  return false;
}

function updateCartQuantity(state, quantity) {
  const res = http.patch(
    `${BASE_URL}/v2/carts/${state.cartId}`,
    JSON.stringify({ quantity }),
    {
      headers: {
        'Content-Type': 'application/json',
