    if (etag) state.etag = etag;
    const retryRes = http.patch(
      `${BASE_URL}/v2/carts/${state.cartId}`,
      JSON.stringify({ quantity }),
      {
        headers: {
          'Content-Type': 'application/json',
          'X-CSRF-Token': state.csrf,
          'If-Match': state.etag || '',
        },
        redirects: 0,
      }
    );
    if (retryRes.status !== 200) return false;
    const body = parseJsonSafely(retryRes);
    if (body && body.csrf) state.csrf = body.csrf;
    const newEtag = extractEtag(retryRes.headers);
    if (newEtag) state.etag = newEtag;
    return true;
  }

  if (res.status === 200) {
    const body = parseJsonSafely(res);
    if (body && body.csrf) state.csrf = body.csrf;
    const etag = extractEtag(res.headers);
    if (etag) state.etag = etag;
    return true;
  }

  return false;
}

function createReservation(state) {
  const res = http.post(
    `${BASE_URL}/v2/reservations`,
    JSON.stringify({ cart_id: state.cartId }),
    {
      headers: {
        'Content-Type': 'application/json',
        'X-CSRF-Token': state.csrf,
      },
      redirects: 0,
    }
  );

