            self._fresh_login()
            if self.cart_id:
                self._request("POST", f"/v2/carts/{self.cart_id}/recover", json_body={}, headers={"X-CSRF-Token": self.csrf or ""})
            return True
        return False

    def _fresh_login(self):
        resp = self._request("GET", "/v2/login-form")
        if resp.status_code == 200:
            csrf = extract_csrf_from_html(resp.text)
            if csrf:
                self.csrf = csrf
        login = self._request(
            "POST",
            "/v2/login",
            json_body={"username": self.username, "password": PASSWORD, "csrf": self.csrf or ""},
            headers={"X-CSRF-Token": self.csrf or ""},
        )
        if login.status_code in (301, 302, 303, 307, 308):
            loc = login.headers.get("Location")
            if loc:
                self._request("GET", urljoin(BASE, loc))
        self._update_csrf_from_json(login)

    def _get_catalog_product(self):
        resp = self._request("GET", "/v2/catalog")
        if resp.status_code != 200:
            return None, None
        try:
            products = resp.json()["data"]["products"]
        except Exception:
            return None, None
        for p in products:
            for v in p.get("variants", []):
                if v.get("in_stock"):
                    return p["id"], v["id"]
        for _ in range(3):
            nxt = None
            try:
                nxt = resp.json().get("next")
            except Exception:
                pass
            if not nxt:
                break
            resp = self._request("GET", urljoin(BASE, nxt))
            if resp.status_code != 200:
                break
            try:
                data = resp.json()["data"]
                p = data["products"][0]
                for v in p.get("variants", []):
                    if v.get("in_stock"):
                        return p["id"], v["id"]
            except Exception:
                break
        return None, None

    def _create_cart(self, product_id, variant_id):
        body = {"product_id": product_id, "variant_id": variant_id}
        if self.grant_id:
            body["grant_id"] = self.grant_id
        resp = self._request("POST", "/v2/carts", json_body=body, headers={"X-CSRF-Token": self.csrf or ""})
        if resp.status_code == 201:
            try:
                data = resp.json()
                self.cart_id = data["id"]
                self._update_csrf_from_json(resp)
                self.etag = resp.headers.get("ETag")
                return True
            except Exception:
                return False
        return False

    def _checkout(self):
        if not self.cart_id:
            return False
        self.idempotency_key = f"idem-{self.cart_id}-{int(time.time()*1000)}"
        headers = {"X-CSRF-Token": self.csrf or "", "Idempotency-Key": self.idempotency_key}
        if self.etag:
            headers["If-Match"] = self.etag
        resp = self._request("POST", "/v2/orders", json_body={"cart_id": self.cart_id}, headers=headers)
        if resp.status_code == 401:
            if self._handle_401(resp, "checkout"):
                headers = {"X-CSRF-Token": self.csrf or "", "Idempotency-Key": self.idempotency_key}
                if self.etag:
                    headers["If-Match"] = self.etag
                resp = self._request("POST", "/v2/orders", json_body={"cart_id": self.cart_id}, headers=headers)
        if resp.status_code == 201:
            try:
                data = resp.json()
                if data.get("accepted") is True:
                    self._update_csrf_from_json(resp)
                    return True
            except Exception:
                pass
        return False

    def _journey(self):
        self._fresh_login()
        product_id, variant_id = self._get_catalog_product()
        if not product_id:
            return
        if not self._create_cart(product_id, variant_id):
            return
        self._checkout()

    @task
    def run_journey(self):
        if self.iterations_done >= self.max_iterations:
            raise StopUser()
        self.iterations_done += 1
        self._journey()


class JourneyShape(LoadTestShape):
    def tick(self):
        run_time = self.get_run_time()
        if run_time < 5:
            return (2, 2)
        if run_time < 35:
            return (2, 2)
        if run_time < 40:
            return (2, 2)
        return None
