    private static String extractFirstInStockProductId(String body) {
        // Find products array and look for first product with variants[0].in_stock == true
        Pattern productBlock = Pattern.compile("\"products\"\\s*:\\s*\\[(.*?)\\]\\s*\\}", Pattern.DOTALL);
        java.util.regex.Matcher blockMatcher = productBlock.matcher(body);
        if (blockMatcher.find()) {
            String productsSection = blockMatcher.group(1);
            // Split by product objects - look for "id":"..." followed by variants with in_stock true
            Pattern productPattern = Pattern.compile(
                "\\{[^{}]*?\"id\"\\s*:\\s*\"([^\"]+)\"[^{}]*?\"variants\"\\s*:\\s*\\[[^\\]]*?\"in_stock\"\\s*:\\s*true[^\\]]*?\\][^{}]*?\\}",
                Pattern.DOTALL
            );
            java.util.regex.Matcher pm = productPattern.matcher(productsSection);
            if (pm.find()) {
                return pm.group(1);
            }
            // Fallback: try simpler pattern
            Pattern simpleProduct = Pattern.compile("\"id\"\\s*:\\s*\"([^\"]+)\"[^{}]*?\"in_stock\"\\s*:\\s*true", Pattern.DOTALL);
            java.util.regex.Matcher sm = simpleProduct.matcher(productsSection);
            if (sm.find()) {
