            Pattern.DOTALL
        );
        java.util.regex.Matcher vm = variantPattern.matcher(body);
        if (vm.find()) {
            return vm.group(1);
        }
        // Fallback: find any variant with in_stock true
        Pattern simpleVariant = Pattern.compile("\"id\"\\s*:\\s*\"([^\"]+)\"[^{}]*?\"in_stock\"\\s*:\\s*true", Pattern.DOTALL);
        java.util.regex.Matcher sm = simpleVariant.matcher(body);
        if (sm.find()) {
            return sm.group(1);
        }
        return "MISSING";
