import http from 'k6/http';
import { check, sleep } from 'k6';
import { Rate, Trend } from 'k6/metrics';
import { randomString } from 'https://jslib.k6.io/k6-utils/1.4.0/index.js';

const BASE_URL = __ENV.BASE_URL || 'http://127.0.0.1:8000';

const businessFailure = new Rate('business_failure');
const unexpectedFailure = new Rate('unexpected_failure');
const businessResponses = new Rate('business_responses');

const profiles = [
  {},
  { html_layout: 1, reverse_catalog: true },
];

const negativeControls = [
  { decline_orders: true },
];

function getProfile(scenarioIndex) {
  const profileIndex = scenarioIndex % profiles.length;
  return profiles[profileIndex];
}

function getNegativeControl(scenarioIndex) {
  const controlIndex = Math.floor(scenarioIndex / profiles.length) % negativeControls.length;
  return negativeControls[controlIndex];
}

function extractCsrfFromForm(body) {
  const patterns = [
    /<input[^>]*name=["']csrf["'][^>]*value=["']([^"']+)["'][^>]*>/i,
    /<input[^>]*value=["']([^"']+)["'][^>]*name=["']csrf["'][^>]*>/i,
    /<input[^>]*name=["']csrf["'][^>]*>/i,
  ];
  for (const pattern of patterns) {
    const match = body.match(pattern);
    if (match) {
      if (match[1]) return match[1];
      const valueMatch = body.match(/<input[^>]*name=["']csrf["'][^>]*value=["']([^"']+)["'][^>]*>/i);
      if (valueMatch) return valueMatch[1];
    }
  }
  const valueMatch = body.match(/<input[^>]*value=["']([^"']+)["'][^>]*name=["']csrf["'][^>]*>/i);
  if (valueMatch) return valueMatch[1];
  return null;
}

function extractLocation(headers) {
  const location = headers['Location'];
  if (location) return location;
  return null;
}

function extractEtag(headers) {
  const etag = headers['ETag'] || headers['Etag'] || headers['etag'];
  if (etag) return etag;
  return null;
}

function parseJsonSafely(body) {
  try {
    return JSON.parse(body);
  } catch (e) {
    return null;
  }
}

function getErrorMessage(body) {
  const data = parseJsonSafely(body);
  if (data && data.error) return data.error;
  const match = body.match(/"error"\s*:\s*"([^"]+)"/);
  return match ? match[1] : null;
}

function isExpiryError(error) {
  return error === 'expired' || error === 'session';
}

function isDeniedError(error) {
  return error === 'denied';
}

function handle401(response, state, operationName) {
  const error = getErrorMessage(response.body);
  if (error === 'expired') {
    const renewResponse = http.post(`${BASE_URL}/v2/session/renew`, '{}', {
      headers: {
        'Content-Type': 'application/json',
        'X-CSRF-Token': state.csrf,
      },
      redirects: 0,
    });
    if (renewResponse.status === 200) {
      const data = parseJsonSafely(renewResponse.body);
      if (data && data.csrf) {
        state.csrf = data.csrf;
      }
      if (state.cartId) {
        http.post(`${BASE_URL}/v2/carts/${state.cartId}/recover`, '{}', {
          headers: {
            'Content-Type': 'application/json',
            'X-CSRF-Token': state.csrf,
          },
          redirects: 0,
        });
      }
      return true;
    }
  } else if (error === 'session') {
    const formResponse = http.get(`${BASE_URL}/v2/login-form`, { redirects: 0 });
    if (formResponse.status === 200) {
      const formCsrf = extractCsrfFromForm(formResponse.body);
      if (formCsrf) {
        state.csrf = formCsrf;
        const loginResponse = http.post(`${BASE_URL}/v2/login`, JSON.stringify({
          username: state.username,
          password: 'bench',
          csrf: state.csrf,
        }), {
          headers: {
            'Content-Type': 'application/json',
            'X-CSRF-Token': state.csrf,
          },
          redirects: 0,
        });
        if (loginResponse.status === 200 || loginResponse.status === 302) {
          const loginData = parseJsonSafely(loginResponse.body);
          if (loginData && loginData.csrf) {
            state.csrf = loginData.csrf;
          }
          if (state.cartId) {
            http.post(`${BASE_URL}/v2/carts/${state.cartId}/recover`, '{}', {
              headers: {
                'Content-Type': 'application/json',
                'X-CSRF-Token': state.csrf,
              },
              redirects: 0,
            });
          }
          return true;
        }
      }
    }
  }
  return false;
}

function login(state) {
  const formResponse = http.get(`${BASE_URL}/v2/login-form`, {
    redirects: 0,
    tags: { name: 'login-form' },
  });
  check(formResponse, {
    'login-form status is 200': (r) => r.status === 200,
  });
  if (formResponse.status !== 200) {
    return false;
  }
  const formCsrf = extractCsrfFromForm(formResponse.body);
  if (!formCsrf) {
    return false;
  }
  state.csrf = formCsrf;

  const loginResponse = http.post(`${BASE_URL}/v2/login`, JSON.stringify({
    username: state.username,
    password: 'bench',
    csrf: state.csrf,
  }), {
    headers: {
      'Content-Type': 'application/json',
      'X-CSRF-Token': state.csrf,
    },
    redirects: 0,
    tags: { name: 'login' },
  });
  check(loginResponse, {
    'login status is 200 or 302': (r) => r.status === 200 || r.status === 302,
    'login response contains csrf': (r) => {
      const data = parseJsonSafely(r.body);
      return data && data.csrf !== undefined;
    },
  });
  if (loginResponse.status !== 200 && loginResponse.status !== 302) {
    return false;
  }
  const loginData = parseJsonSafely(loginResponse.body);
  if (loginData && loginData.csrf) {
    state.csrf = loginData.csrf;
  }
  if (loginResponse.status === 302) {
    const location = extractLocation(loginResponse.headers);
    if (location) {
      const redirectResponse = http.get(`${BASE_URL}${location}`, {
        redirects: 0,
        tags: { name: 'login-redirect' },
      });
      if (redirectResponse.status === 200) {
        const redirectData = parseJsonSafely(redirectResponse.body);
        if (redirectData && redirectData.csrf) {
          state.csrf = redirectData.csrf;
        }
        if (redirectData && redirectData.grant_id) {
          state.grantId = redirectData.grant_id;
        }
      }
    }
  }
  return true;
}

function getCatalog(state) {
  const profile = state.profile;
  const catalogResponse = http.get(`${BASE_URL}/v2/catalog`, {
    redirects: 0,
    tags: { name: 'catalog' },
  });
  check(catalogResponse, {
    'catalog status is 200': (r) => r.status === 200,
  });
  if (catalogResponse.status !== 200) {
    return false;
  }
  const catalogData = parseJsonSafely(catalogResponse.body);
  if (!catalogData || !catalogData.data || !catalogData.data.products) {
    return false;
  }
  let products = catalogData.data.products;
  if (profile.reverse_catalog) {
    products = [...products].reverse();
  }
  for (const product of products) {
    if (product.variants && product.variants.length > 0) {
      const variant = product.variants[0];
      if (variant.in_stock === true) {
        state.productId = product.id;
        state.variantId = variant.id;
        return true;
      }
    }
  }
  return false;
}

function createCart(state) {
  const payload = {
    product_id: state.productId,
    variant_id: state.variantId,
  };
  if (state.grantId) {
    payload.grant_id = state.grantId;
  }
  const cartResponse = http.post(`${BASE_URL}/v2/carts`, JSON.stringify(payload), {
    headers: {
      'Content-Type': 'application/json',
      'X-CSRF-Token': state.csrf,
    },
    redirects: 0,
    tags: { name: 'create-cart' },
  });
  check(cartResponse, {
    'create-cart status is 201': (r) => r.status === 201,
    'create-cart response contains cart id': (r) => {
      const data = parseJsonSafely(r.body);
      return data && data.id && data.id.startsWith('cart-');
    },
  });
  if (cartResponse.status !== 201) {
    if (cartResponse.status === 401) {
      const recovered = handle401(cartResponse, state, 'create-cart');
      if (recovered) {
        const retryResponse = http.post(`${BASE_URL}/v2/carts`, JSON.stringify(payload), {
          headers: {
            'Content-Type': 'application/json',
            'X-CSRF-Token': state.csrf,
          },
          redirects: 0,
          tags: { name: 'create-cart-retry' },
        });
        if (retryResponse.status === 201) {
          const data = parseJsonSafely(retryResponse.body);
          if (data && data.id) {
            state.cartId = data.id;
            if (data.csrf) state.csrf = data.csrf;
            const etag = extractEtag(retryResponse.headers);
            if (etag) state.etag = etag;
            return true;
          }
        }
      }
    }
    return false;
  }
  const data = parseJsonSafely(cartResponse.body);
  if (!data || !data.id) {
    return false;
  }
  state.cartId = data.id;
  if (data.csrf) state.csrf = data.csrf;
  const etag = extractEtag(cartResponse.headers);
  if (etag) state.etag = etag;
  return true;
}

function createOrder(state) {
  const payload = {
    cart_id: state.cartId,
  };
  if (state.reservationId) {
    payload.reservation_id = state.reservationId;
  }
  const idempotencyKey = state.cartId;
  const orderResponse = http.post(`${BASE_URL}/v2/orders`, JSON.stringify(payload), {
    headers: {
      'Content-Type': 'application/json',
      'X-CSRF-Token': state.csrf,
      'Idempotency-Key': idempotencyKey,
    },
    redirects: 0,
    tags: { name: 'create-order' },
  });
  check(orderResponse, {
    'create-order status is 201': (r) => r.status === 201,
    'create-order response contains accepted true': (r) => {
      const data = parseJsonSafely(r.body);
