ITERATIONS = 2
MODE = "decline"

PROFILES = [{}, {"html_layout": 1, "reverse_catalog": True}]
NEGATIVE_OVERRIDES = [{"decline_orders": True}]

OWNER_SEEDS = []


class ShopUser(HttpUser):
    host = BASE
    wait_time = between(0, 0)

    def __init__(self, *args, **kwargs):
        super().__init__(*args, **kwargs)
        self.username = None
        self.csrf = "MISSING"
        self.cart = "MISSING"
        self.etag = "MISSING"
        self.has_cart = False
        self.grant = "MISSING"
        self.product = "MISSING"
        self.variant = "MISSING"
        self.quantity = 2
        self.iterations_done = 0
        self.profile = {}
        self.negative = {}
        self.owner_seed = None

    def on_start(self):
        # Assign profile and negative control based on user index
        user_index = int(self.username.split("-")[-1]) if self.username and self.username.startswith("bench-") else 0
        profile_idx = (user_index - 1) % len(PROFILES)
        self.profile = PROFILES[profile_idx]
        neg_idx = (user_index - 1) % len(NEGATIVE_OVERRIDES)
        self.negative = NEGATIVE_OVERRIDES[neg_idx]

    def _headers(self, extra=None):
        headers = {
            "Content-Type": "application/json",
            "X-CSRF-Token": self.csrf,
        }
        if self.etag != "MISSING":
            headers["If-Match"] = self.etag
        if self.cart != "MISSING":
            headers["Idempotency-Key"] = self.cart
        if extra:
            headers.update(extra)
        return headers

    def _extract_csrf(self, response):
        try:
            data = response.json()
            if isinstance(data, dict) and "csrf" in data:
                self.csrf = data["csrf"]
        except Exception:
            pass

    def _extract_etag(self, response):
        etag = response.headers.get("ETag")
        if etag:
            self.etag = etag

    def _handle_401(self, response, operation_name):
        """Handle 401 expiry/session recovery. Returns True if retry should happen."""
        try:
            body = response.json()
        except Exception:
            return False
        error = body.get("error", "")
        if error == "expired":
            # Renew session
            with self.client.post(
                "/v2/session/renew",
                json={},
                headers=self._headers(),
                catch_response=True,
                name="POST /v2/session/renew",
            ) as renew_resp:
                if renew_resp.status_code == 200:
                    self._extract_csrf(renew_resp)
                    if self.has_cart:
                        with self.client.post(
                            f"/v2/carts/{self.cart}/recover",
                            json={},
                            headers=self._headers(),
                            catch_response=True,
                            name="POST /v2/carts/{id}/recover",
                        ) as recover_resp:
                            if recover_resp.status_code == 200:
                                self._extract_csrf(recover_resp)
                                self._extract_etag(recover_resp)
                    return True
            return False
        elif error == "session":
            # Session revoked - get fresh login
            with self.client.get(
                "/v2/login-form",
                catch_response=True,
                name="GET /v2/login-form (recovery)",
            ) as form_resp:
                if form_resp.status_code == 200:
                    match = re.search(
                        r'<input(?=[^>]*\bname=["\']csrf["\'])(?=[^>]*\bvalue=["\']([^"\']+)["\'])[^>]*>',
                        form_resp.text,
                    )
                    if match:
                        form_csrf = match.group(1)
                        with self.client.post(
                            "/v2/login",
                            json={
                                "username": self.username,
                                "password": "bench",
                                "csrf": form_csrf,
                            },
                            headers={"Content-Type": "application/json", "X-CSRF-Token": self.csrf},
                            catch_response=True,
                            name="POST /v2/login (recovery)",
                        ) as login_resp:
                            if login_resp.status_code == 200:
                                self._extract_csrf(login_resp)
                                if self.has_cart:
                                    with self.client.post(
                                        f"/v2/carts/{self.cart}/recover",
                                        json={},
                                        headers=self._headers(),
                                        catch_response=True,
                                        name="POST /v2/carts/{id}/recover (session)",
                                    ) as recover_resp:
                                        if recover_resp.status_code == 200:
                                            self._extract_csrf(recover_resp)
                                            self._extract_etag(recover_resp)
                                return True
            return False
        return False

    def _login(self):
        """Perform login. Returns True if successful."""
        with self.client.get(
            "/v2/login-form",
            catch_response=True,
            name="GET /v2/login-form",
        ) as form_resp:
            if form_resp.status_code != 200:
                form_resp.failure("Login form failed")
                return False
            match = re.search(
                r'<input(?=[^>]*\bname=["\']csrf["\'])(?=[^>]*\bvalue=["\']([^"\']+)["\'])[^>]*>',
                form_resp.text,
            )
            if not match:
                form_resp.failure("CSRF input not found")
                return False
            form_csrf = match.group(1)

        with self.client.post(
            "/v2/login",
            json={
                "username": self.username,
                "password": "bench",
                "csrf": form_csrf,
            },
            headers={"Content-Type": "application/json", "X-CSRF-Token": self.csrf},
            catch_response=True,
            name="POST /v2/login",
        ) as login_resp:
            if login_resp.status_code == 302:
                location = login_resp.headers.get("Location")
                if location:
                    with self.client.get(
                        location,
                        catch_response=True,
                        name="GET /v2/login redirect",
                    ) as redirect_resp:
                        if redirect_resp.status_code == 200:
                            self._extract_csrf(redirect_resp)
                            if "grant_id" in redirect_resp.text:
                                try:
                                    data = redirect_resp.json()
                                    if "grant_id" in data:
                                        self.grant = data["grant_id"]
                                except Exception:
                                    pass
                            return True
                        else:
                            redirect_resp.failure("Login redirect failed")
                            return False
                else:
                    login_resp.failure("302 without Location")
                    return False
            elif login_resp.status_code == 200:
                if '"csrf"' not in login_resp.text:
                    login_resp.failure("Login response missing csrf")
                    return False
                self._extract_csrf(login_resp)
                return True
            else:
                login_resp.failure(f"Login failed with status {login_resp.status_code}")
                return False

    def _get_catalog(self):
        """Fetch catalog and select product/variant."""
        with self.client.get(
            "/v2/catalog",
            catch_response=True,
            name="GET /v2/catalog",
        ) as catalog_resp:
            if catalog_resp.status_code != 200:
                catalog_resp.failure("Catalog failed")
                return False
            try:
                data = catalog_resp.json()
                products = data.get("data", {}).get("products", [])
                if self.profile.get("reverse_catalog"):
                    products = list(reversed(products))
                for product in products:
                    variants = product.get("variants", [])
                    for variant in variants:
                        if variant.get("in_stock"):
                            self.product = product["id"]
                            self.variant = variant["id"]
                            return True
                catalog_resp.failure("No in-stock product found")
                return False
            except Exception as e:
                catalog_resp.failure(f"Catalog parse error: {e}")
                return False

    def _create_cart(self):
        """Create cart. Returns True if successful."""
        payload = {
            "product_id": self.product,
            "variant_id": self.variant,
        }
        if self.grant != "MISSING":
            payload["grant_id"] = self.grant

        with self.client.post(
            "/v2/carts",
            json=payload,
            headers=self._headers(),
            catch_response=True,
            name="POST /v2/carts",
        ) as cart_resp:
            if cart_resp.status_code == 201:
                if '"id"' not in cart_resp.text or "cart-" not in cart_resp.text:
                    cart_resp.failure("Cart creation missing id")
                    return False
                try:
                    data = cart_resp.json()
                    self.cart = data.get("id", self.cart)
                    if "csrf" in data:
                        self.csrf = data["csrf"]
                except Exception:
                    pass
                self._extract_etag(cart_resp)
                self.has_cart = True
                return True
            elif cart_resp.status_code == 401:
                if self._handle_401(cart_resp, "create_cart"):
                    # Retry once
                    with self.client.post(
                        "/v2/carts",
                        json=payload,
                        headers=self._headers(),
                        catch_response=True,
                        name="POST /v2/carts (retry)",
                    ) as retry_resp:
                        if retry_resp.status_code == 201:
                            if '"id"' not in retry_resp.text or "cart-" not in retry_resp.text:
                                retry_resp.failure("Cart creation retry missing id")
                                return False
                            try:
                                data = retry_resp.json()
                                self.cart = data.get("id", self.cart)
                                if "csrf" in data:
                                    self.csrf = data["csrf"]
                            except Exception:
                                pass
                            self._extract_etag(retry_resp)
                            self.has_cart = True
                            return True
                        else:
                            retry_resp.failure(f"Cart creation retry failed: {retry_resp.status_code}")
                            return False
                else:
                    cart_resp.failure("Cart creation 401 recovery failed")
                    return False
            else:
                cart_resp.failure(f"Cart creation failed: {cart_resp.status_code}")
                return False

    def _place_order(self):
        """Place order. Returns True if order accepted."""
        payload = {"cart_id": self.cart}
        if self.negative.get("decline_orders"):
            # Negative control: expect business failure
            with self.client.post(
                "/v2/orders",
                json=payload,
                headers=self._headers(),
                catch_response=True,
                name="POST /v2/orders (decline)",
            ) as order_resp:
                if order_resp.status_code == 200:
                    try:
                        data = order_resp.json()
                        if data.get("accepted") is False:
                            # Business failure as expected
                            order_resp.success()
                            return False
                        else:
                            order_resp.failure("Expected decline but order accepted")
                            return False
                    except Exception:
                        order_resp.failure("Decline response parse error")
                        return False
                elif order_resp.status_code == 401:
                    if self._handle_401(order_resp, "place_order_decline"):
                        with self.client.post(
                            "/v2/orders",
                            json=payload,
                            headers=self._headers(),
                            catch_response=True,
                            name="POST /v2/orders (decline retry)",
                        ) as retry_resp:
                            if retry_resp.status_code == 200:
                                try:
                                    data = retry_resp.json()
                                    if data.get("accepted") is False:
                                        retry_resp.success()
                                        return False
                                    else:
                                        retry_resp.failure("Expected decline but order accepted on retry")
                                        return False
                                except Exception:
                                    retry_resp.failure("Decline retry parse error")
                                    return False
                            else:
                                retry_resp.failure(f"Decline retry failed: {retry_resp.status_code}")
                                return False
                    else:
                        order_resp.failure("Decline 401 recovery failed")
                        return False
                else:
                    order_resp.failure(f"Decline order failed: {order_resp.status_code}")
                    return False
        else:
            with self.client.post(
                "/v2/orders",
                json=payload,
                headers=self._headers(),
                catch_response=True,
                name="POST /v2/orders",
            ) as order_resp:
                if order_resp.status_code == 201:
                    if '"accepted"' not in order_resp.text or '"accepted"\s*:\s*true' not in re.sub(r'\s+', '', order_resp.text):
                        order_resp.failure("Order response missing accepted:true")
                        return False
                    try:
                        data = order_resp.json()
                        if "csrf" in data:
                            self.csrf = data["csrf"]
                    except Exception:
                        pass
                    return True
                elif order_resp.status_code == 200:
                    try:
                        data = order_resp.json()
                        if data.get("accepted") is False:
                            order_resp.failure("Order business failure (accepted:false)")
                            return False
                        else:
                            order_resp.failure("Order 200 but not accepted:false")
                            return False
                    except Exception:
                        order_resp.failure("Order 200 parse error")
                        return False
                elif order_resp.status_code == 401:
                    if self._handle_401(order_resp, "place_order"):
                        with self.client.post(
                            "/v2/orders",
                            json=payload,
                            headers=self._headers(),
                            catch_response=True,
                            name="POST /v2/orders (retry)",
                        ) as retry_resp:
                            if retry_resp.status_code == 201:
                                if '"accepted"' not in retry_resp.text or '"accepted"\s*:\s*true' not in re.sub(r'\s+', '', retry_resp.text):
                                    retry_resp.failure("Order retry missing accepted:true")
                                    return False
                                try:
                                    data = retry_resp.json()
                                    if "csrf" in data:
                                        self.csrf = data["csrf"]
                                except Exception:
                                    pass
                                return True
                            elif retry_resp.status_code == 200:
                                try:
                                    data = retry_resp.json()
                                    if data.get("accepted") is False:
                                        retry_resp.failure("Order retry business failure")
                                        return False
                                    else:
                                        retry_resp.failure("Order retry 200 but not accepted:false")
                                        return False
                                except Exception:
                                    retry_resp.failure("Order retry 200 parse error")
                                    return False
                            else:
                                retry_resp.failure(f"Order retry failed: {retry_resp.status_code}")
                                return False
                    else:
                        order_resp.failure("Order 401 recovery failed")
                        return False
                else:
                    order_resp.failure(f"Order failed: {order_resp.status_code}")
                    return False

    @task
    def shop_journey(self):
        if self.iterations_done >= ITERATIONS:
            raise StopUser()

        self.iterations_done += 1

        # Fresh login and cart each journey
        self.csrf = "MISSING"
        self.cart = "MISSING"
        self.etag = "MISSING"
        self.has_cart = False
        self.grant = "MISSING"
        self.product = "MISSING"
        self.variant = "MISSING"

        # Assign username based on user index
        user_index = int(self.username.split("-")[-1]) if self.username and self.username.startswith("bench-") else 0
        self.username = f"bench-{user_index}"

        if not self._login():
            return

        if not self._get_catalog():
            return

        if not self._create_cart():
            return

        self._place_order()

        # Record owner seed after execution
        OWNER_SEEDS.append({
            "username": self.username,
            "cart": self.cart,
            "product": self.product,
            "variant": self.variant,
            "grant": self.grant,
            "profile": self.profile,
            "negative": self.negative,
        })


class ShopLoadShape(LoadTestShape):
    def __init__(self):
        super().__init__()
        self.start_time = time.time()

    def tick(self):
        run_time = time.time() - self.start_time
        if run_time > 120:  # Safety timeout
            return None
        return (USERS, 1)  # Spawn rate 1 user/sec
