import java.util.regex.Pattern;
import java.util.regex.Matcher;

public class ModelSimulation extends Simulation {

    private static final String BASE_URL = System.getenv().getOrDefault("BASE_URL", "http://127.0.0.1:8000");

    private static final Pattern CSRF_INPUT_PATTERN = Pattern.compile(
        "<input(?=[^>]*\\bname=[\"']csrf[\"'])(?=[^>]*\\bvalue=[\"']([^\"']+)[\"'])[^>]*>"
    );
    private static final Pattern ERROR_EXPIRED_SESSION_PATTERN = Pattern.compile("\"error\"\\s*:\\s*\"(?:expired|session)\"");
    private static final Pattern ETAG_HEADER_PATTERN = Pattern.compile("(?im)^ETag:\\s*([^\\r\\n]+)");
    private static final Pattern LOCATION_HEADER_PATTERN = Pattern.compile("(?im)^Location:\\s*([^\\r\\n]+)");
    private static final Pattern LOCATION_PRESENT_PATTERN = Pattern.compile("(?im)^Location:");
    private static final Pattern CART_ID_PATTERN = Pattern.compile("\"id\"\\s*:\\s*\"cart-");
    private static final Pattern CSRF_JSON_PATTERN = Pattern.compile("\"csrf\"\\s*:");
    private static final Pattern ACCEPTED_TRUE_PATTERN = Pattern.compile("\"accepted\"\\s*:\\s*true");

    private static String extractFirst(Pattern pattern, String input) {
        Matcher m = pattern.matcher(input);
        if (m.find()) {
            return m.groupCount() >= 1 ? m.group(1) : "true";
        }
        return null;
    }

    private static boolean matches(Pattern pattern, String input) {
        return pattern.matcher(input).find();
    }

    private static String extractCsrfFromForm(String body) {
        String csrf = extractFirst(CSRF_INPUT_PATTERN, body);
        return csrf != null ? csrf : "MISSING";
    }

    private static String extractJsonString(String body, String key) {
        Pattern p = Pattern.compile("\"" + key + "\"\\s*:\\s*\"([^\"]+)\"");
        Matcher m = p.matcher(body);
        if (m.find()) {
            return m.group(1);
        }
        return null;
    }

    private static String extractJsonNumberAsString(String body, String key) {
        Pattern p = Pattern.compile("\"" + key + "\"\\s*:\\s*(\\d+)");
        Matcher m = p.matcher(body);
        if (m.find()) {
            return m.group(1);
        }
        return null;
    }

    private static String extractJsonBooleanAsString(String body, String key) {
        Pattern p = Pattern.compile("\"" + key + "\"\\s*:\\s*(true|false)");
        Matcher m = p.matcher(body);
        if (m.find()) {
            return m.group(1);
        }
        return null;
    }

    private static String extractFirstProductId(String body) {
        Pattern p = Pattern.compile("\"products\"\\s*:\\s*\\[(.*?)\\]", Pattern.DOTALL);
        Matcher m = p.matcher(body);
        if (!m.find()) return null;
        String productsBlock = m.group(1);
        Pattern productPattern = Pattern.compile("\\{[^{}]*?\"id\"\\s*:\\s*\"([^\"]+)\"[^{}]*?\"variants\"\\s*:\\s*\\[(.*?)\\]", Pattern.DOTALL);
        Matcher pm = productPattern.matcher(productsBlock);
        while (pm.find()) {
            String productId = pm.group(1);
            String variantsBlock = pm.group(2);
            Pattern variantPattern = Pattern.compile("\\{[^{}]*?\"id\"\\s*:\\s*\"([^\"]+)\"[^{}]*?\"in_stock\"\\s*:\\s*true", Pattern.DOTALL);
            Matcher vm = variantPattern.matcher(variantsBlock);
            if (vm.find()) {
                return productId + "::" + vm.group(1);
            }
        }
        return null;
    }

    private static ChainBuilder doLogin(String usernameSessionKey) {
        return exec(session -> {
            String username = session.getString(usernameSessionKey);
            String formCsrf = session.getString("form");
            String body = String.format("{\"username\":\"%s\",\"password\":\"bench\",\"csrf\":\"%s\"}", username, formCsrf);
            return session.set("loginBody", body);
        })
        .exec(
            http("POST /v2/login")
                .post("/v2/login")
                .header("Content-Type", "application/json")
                .header("X-CSRF-Token", session -> session.getString("csrf"))
                .body(StringBody(session -> session.getString("loginBody")))
                .disableFollowRedirect()
                .check(
                    status().is(200),
                    bodyString().transform((body, session) -> {
                        String csrf = extractJsonString(body, "csrf");
                        if (csrf != null) session = session.set("csrf", csrf);
                        String location = extractFirst(LOCATION_HEADER_PATTERN, body);
                        if (location != null) session = session.set("location", location);
                        boolean redirect = matches(LOCATION_PRESENT_PATTERN, body);
                        session = session.set("redirect", redirect);
                        boolean recover = matches(ERROR_EXPIRED_SESSION_PATTERN, body);
                        session = session.set("recover", recover);
                        if (!matches(CSRF_JSON_PATTERN, body)) {
                            throw new RuntimeException("Login response missing csrf");
                        }
                        return session;
                    })
                )
        );
    }

