                        String csrf = extractJsonString(body, "csrf");
                        if (csrf != null) session = session.set("csrf", csrf);
                        String productVariant = extractFirstProductId(body);
                        if (productVariant != null) {
                            String[] parts = productVariant.split("::", 2);
                            session = session.set("product", parts[0]);
                            session = session.set("variant", parts[1]);
