    private static ChainBuilder doRecoverCart() {
        return exec(
            http("POST /v2/carts/{cart}/recover")
                .post(session -> "/v2/carts/" + session.getString("cart") + "/recover")
                .header("Content-Type", "application/json")
                .header("X-CSRF-Token", session -> session.getString("csrf"))
