                .then(exec(doGetLocation("location")))
            )
            .doIf(session -> session.getBoolean("hasCart"))
            .then(exec(doRecoverCart()));
    }

    private static ChainBuilder initialLogin() {
        return exec(session -> session.set("csrf", "MISSING"))
            .exec(session -> session.set("form", "MISSING"))
            .exec(session -> session.set("cart", "MISSING"))
            .exec(session -> session.set("etag", "MISSING"))
            .exec(session -> session.set("hasCart", false))
            .exec(session -> session.set("grant", "MISSING"))
            .exec(session -> session.set("product", "MISSING"))
            .exec(session -> session.set("variant", "MISSING"))
            .exec(session -> session.set("recover", false))
            .exec(session -> session.set("redirect", false))
            .exec(session -> session.set("location", "MISSING"))
            .exec(doGetLoginForm())
            .exec(doLogin("username"))
            .doIf(session -> session.getBoolean("redirect"))
            .then(exec(doGetLocation("location")));
    }

    private static ChainBuilder journey() {
        return exec(initialLogin())
            .exec(doCatalog())
            .exec(doCreateCart())
            .exec(doPostOrders("cart"))
            .doIf(session -> session.getBoolean("recover"))
            .then(
                exec(refreshAndRecover())
                .exec(doPostOrders("cart"))
            );
    }

    private static final HttpProtocolBuilder httpProtocol =
        http.baseUrl(BASE_URL)
            .acceptHeader("application/json")
            .contentTypeHeader("application/json")
            .userAgentHeader("Gatling/3.15")
            .disableAutoReferer()
            .disableCaching()
            .shareConnections();

    {
        setUp(
            scenario("ModelScenario")
                .exec(journey())
                .injectOpen(atOnceUsers(2))
        ).protocols(httpProtocol)
         .maxDuration(Duration.ofMinutes(5));
    }
