import http from 'k6/http';
import { check, sleep } from 'k6';
import { URL } from 'https://jslib.k6.io/url/1.0.0/index.js';

const BASE_URL = __ENV.BASE_URL || 'http://127.0.0.1:8000';

export const options = {
  scenarios: {
    expiry: {
      executor: 'per-vu-iterations',
      vus: 2,
      iterations: 2,
      maxDuration: '120s',
    },
  },
  thresholds: {},
};

function extractCsrfFromHtml(html) {
  const regex = /<input(?=[^>]*\bname=["']csrf["'])(?=[^>]*\bvalue=["']([^"']+)["'])[^>]*>/;
  const match = html.match(regex);
  return match ? match[1] : null;
}

function extractLocation(headers) {
  const loc = headers['Location'];
  return loc ? loc : null;
}

function extractEtag(headers) {
  const etag = headers['ETag'];
  return etag ? etag : null;
}

function parseJsonResponse(res) {
  try {
    return res.json();
  } catch (e) {
    return null;
  }
}

function isExpiryError(body) {
  if (!body) return false;
  const error = body.error;
  return error === 'expired' || error === 'session';
}

function isDeniedError(body) {
  if (!body) return false;
  return body.error === 'denied';
}

function getHeaders(csrf, etag, cartId) {
  const headers = {
    'Content-Type': 'application/json',
  };
  if (csrf && csrf !== 'MISSING') headers['X-CSRF-Token'] = csrf;
  if (etag && etag !== 'MISSING') headers['If-Match'] = etag;
  if (cartId && cartId !== 'MISSING') headers['Idempotency-Key'] = cartId;
  return headers;
}

function loginForm(state) {
  const res = http.get(`${BASE_URL}/v2/login-form`, {
    headers: { 'Content-Type': 'application/json' },
    redirects: 0,
  });
  check(res, { 'login-form status 200': (r) => r.status === 200 });
  const csrf = extractCsrfFromHtml(res.body);
  if (csrf) state.csrf = csrf;
  return res;
}

function login(state, username) {
  const payload = JSON.stringify({
    username: username,
    password: 'bench',
    csrf: state.csrf,
  });
  const res = http.post(`${BASE_URL}/v2/login`, payload, {
    headers: { 'Content-Type': 'application/json' },
    redirects: 0,
  });
  check(res, { 'login has csrf': (r) => r.body && r.body.includes('"csrf"') });
  const body = parseJsonResponse(res);
  if (body && body.csrf) state.csrf = body.csrf;
  const location = extractLocation(res.headers);
  if (location) {
    const locRes = http.get(new URL(location, BASE_URL).toString(), {
      headers: getHeaders(state.csrf, state.etag, state.cartId),
      redirects: 0,
    });
    const locBody = parseJsonResponse(locRes);
    if (locBody) {
      if (locBody.csrf) state.csrf = locBody.csrf;
      if (locBody.grant_id) state.grantId = locBody.grant_id;
    }
  }
  return res;
}

function getCatalog(state) {
  const res = http.get(`${BASE_URL}/v2/catalog`, {
    headers: getHeaders(state.csrf, state.etag, state.cartId),
    redirects: 0,
  });
  check(res, { 'catalog status 200': (r) => r.status === 200 });
  const body = parseJsonResponse(res);
  if (body && body.data && body.data.products) {
    for (const product of body.data.products) {
      if (product.variants && product.variants.length > 0 && product.variants[0].in_stock === true) {
        state.productId = product.id;
        state.variantId = product.variants[0].id;
        break;
      }
    }
  }
  return res;
}

function createCart(state) {
  const payload = JSON.stringify({
    product_id: state.productId,
    variant_id: state.variantId,
    grant_id: state.grantId !== 'MISSING' ? state.grantId : undefined,
  });
  const res = http.post(`${BASE_URL}/v2/carts`, payload, {
    headers: getHeaders(state.csrf, state.etag, state.cartId),
    redirects: 0,
  });
  check(res, { 'cart created': (r) => r.status === 201 && r.body && r.body.includes('"id"') });
  const body = parseJsonResponse(res);
  if (body) {
    if (body.csrf) state.csrf = body.csrf;
    if (body.id) {
      state.cartId = body.id;
      state.hasCart = true;
    }
  }
  const etag = extractEtag(res.headers);
  if (etag) state.etag = etag;
  return res;
}

function postOrder(state) {
  const payload = JSON.stringify({ cart_id: state.cartId });
  const res = http.post(`${BASE_URL}/v2/orders`, payload, {
    headers: getHeaders(state.csrf, state.etag, state.cartId),
    redirects: 0,
  });
  const body = parseJsonResponse(res);
  if (body && body.csrf) state.csrf = body.csrf;
  const etag = extractEtag(res.headers);
  if (etag) state.etag = etag;
  return { res, body };
}

function renewSession(state) {
  const res = http.post(`${BASE_URL}/v2/session/renew`, '{}', {
    headers: getHeaders(state.csrf, state.etag, state.cartId),
    redirects: 0,
  });
  const body = parseJsonResponse(res);
  if (body && body.csrf) state.csrf = body.csrf;
  return { res, body };
}

function recoverCart(state) {
  const res = http.post(`${BASE_URL}/v2/carts/${state.cartId}/recover`, '{}', {
    headers: getHeaders(state.csrf, state.etag, state.cartId),
    redirects: 0,
  });
  const body = parseJsonResponse(res);
  if (body && body.csrf) state.csrf = body.csrf;
  return { res, body };
}

function handleExpiryRecovery(state, operationFn, operationName) {
  // Attempt the operation once
  let result = operationFn(state);
  let body = result.body;
  let res = result.res;

  if (isExpiryError(body)) {
    // Renew session
    const renewResult = renewSession(state);
    const renewBody = renewResult.body;

    if (isExpiryError(renewBody)) {
      // Session revoked, need fresh login
      loginForm(state);
      login(state, state.username);
    }

    if (state.hasCart) {
      recoverCart(state);
    }

    // Retry the interrupted operation once
    result = operationFn(state);
    body = result.body;
    res = result.res;
  }

  return { res, body };
}

export default function () {
  const vuId = __VU;
  const username = `bench-${vuId}`;

  const state = {
    username: username,
    csrf: 'MISSING',
    cartId: 'MISSING',
    etag: 'MISSING',
    hasCart: false,
    grantId: 'MISSING',
    productId: 'MISSING',
    variantId: 'MISSING',
  };

  // Fresh login
  loginForm(state);
  login(state, username);

  // Catalog
  getCatalog(state);

  // Create cart
  createCart(state);

  // Post order with expiry recovery
  const orderResult = handleExpiryRecovery(state, postOrder, 'order');
  check(orderResult.res, {
    'order accepted': (r) => r.status === 201 && r.body && r.body.includes('"accepted"') && r.body.includes('true'),
  });
}
