                r.failure(f"create cart status {r.status_code}")
            elif not re.search(r'"id"\s*:\s*"cart-', r.text):
                r.failure("create cart missing id")
        return r

    def _do_order(self):
        payload = {"cart_id": self.cart}
        with self.client.post(
            "/v2/orders",
            json=payload,
            headers=self._headers(),
            catch_response=True,
            name="/v2/orders",
        ) as r:
            self._extract_csrf(r)
            self._extract_recover(r)
            self._extract_etag(r)
            if r.status_code != 201:
                r.failure(f"order status {r.status_code}")
            elif not re.search(r'"accepted"\s*:\s*true', r.text):
                r.failure("order not accepted")
        return r

    def _do_renew(self):
        with self.client.post(
            "/v2/session/renew",
            json={},
            headers=self._headers(),
            catch_response=True,
            name="/v2/session/renew",
        ) as r:
            self._extract_csrf(r)
            self._extract_recover(r)
            self._extract_etag(r)
            if r.status_code != 200:
                r.failure(f"renew status {r.status_code}")
        return r

    def _do_recover_cart(self):
        if not self.has_cart:
            return None
        with self.client.post(
            f"/v2/carts/{self.cart}/recover",
            json={},
            headers=self._headers(),
            catch_response=True,
            name="/v2/carts/recover",
        ) as r:
            self._extract_csrf(r)
            self._extract_recover(r)
            self._extract_etag(r)
            if r.status_code != 200:
                r.failure(f"recover cart status {r.status_code}")
        return r

    def _do_full_relogin(self):
        self._do_login_form()
        self._do_login()
        if self.redirect:
            self._do_redirect_get()

    def _handle_expiry(self, original_operation):
        """Handle expired/session error: renew, recover cart, retry original operation once."""
        if not self.recover:
            return original_operation
        self._do_renew()
        if self.recover:
            self._do_full_relogin()
        self._do_recover_cart()
        # Retry the original operation once
        return original_operation

    def _journey(self):
        # Fresh login
        self._do_login_form()
        self._do_login()
        if self.redirect:
            self._do_redirect_get()

        # Catalog
        self._do_catalog()

        # Create cart
        self._do_create_cart()

        # Order
        self._do_order()

        # Handle expiry if detected
        if self.recover:
            self._handle_expiry(self._do_order)

    @task
    def run_journey(self):
        if self.iterations_done >= self.max_iterations:
            raise StopUser()
        self.iterations_done += 1
        self._journey()


