  { username: 'bench-1', password: 'bench', quantity: 2 },
  { username: 'bench-2', password: 'bench', quantity: 3 },
  { username: 'bench-3', password: 'bench', quantity: 4 },
  { username: 'bench-4', password: 'bench', quantity: 5 },
  { username: 'bench-5', password: 'bench', quantity: 6 },
  { username: 'bench-6', password: 'bench', quantity: 7 },
  { username: 'bench-7', password: 'bench', quantity: 8 },
  { username: 'bench-8', password: 'bench', quantity: 9 },
  { username: 'bench-9', password: 'bench', quantity: 10 },
  { username: 'bench-10', password: 'bench', quantity: 11 },
  { username: 'bench-11', password: 'bench', quantity: 12 },
  { username: 'bench-12', password: 'bench', quantity: 13 },
  { username: 'bench-13', password: 'bench', quantity: 14 },
  { username: 'bench-14', password: 'bench', quantity: 15 },
  { username: 'bench-15', password: 'bench', quantity: 16 },
  { username: 'bench-16', password: 'bench', quantity: 17 },
];

const failure = new Rate('business_failure');
export const options = {
  scenarios: {
    journeys: {
      executor: 'per-vu-iterations',
      vus: 2,
      iterations: 2,
      maxDuration: '30s',
    },
  },
  thresholds: { checks: ['rate==1'] },
};

const base = __ENV.BASE_URL || 'http://127.0.0.1:8000';

function body(r) {
  try { return r.json(); } catch (_) { return {}; }
}

function raw(path, method = 'GET', data = null, extra = {}, csrfToken) {
  const headers = { 'Content-Type': 'application/json' };
  if (csrfToken) headers['X-CSRF-Token'] = csrfToken;
  Object.assign(headers, extra);
  const r = http.request(method, base + path, data === null ? null : JSON.stringify(data), {
    headers,
    redirects: 0,
    timeout: '3s',
  });
  const b = body(r);
  if (path === '/v2/work') {
    failure.add(r.status >= 400 && !(r.status === 401 && b.error === 'expired') && r.status !== 429);
  }
  return r;
}

function login() {
  let r = raw('/v2/login-form');
  const token = r.html().find('input[name="csrf"]').first().attr('value');
  const row = rows[(__VU - 1) % rows.length];
  r = raw('/v2/login', 'POST', { username: row.username, password: row.password, csrf: token });
  if (r.status === 302) {
    r = raw(r.headers.Location);
  }
  const b = body(r);
  const csrfToken = b.csrf || '';
  check(r, { login: (resp) => resp.status === 200 });
  return csrfToken;
}

function request(path, method = 'GET', data = null, extra = {}, csrfToken) {
  let r = raw(path, method, data, extra, csrfToken);
  if (r.status === 401 && ['expired', 'session'].indexOf(body(r).error) >= 0) {
    const renewed = raw('/v2/session/renew', 'POST', {}, {}, csrfToken);
    let newCsrf = csrfToken;
    if (renewed.status === 200) {
      const rb = body(renewed);
      if (rb.csrf) newCsrf = rb.csrf;
    } else {
      newCsrf = login();
    }
    r = raw(path, method, data, extra, newCsrf);
  }
  return r;
}

function flow() {
  // Fresh login and cart for every iteration
  let csrfToken = login();
  let cart = '';
  let grant = '';
  let etag = '';

  // Challenge mode (not used in default flow, but kept for completeness)
  if (cfg.mode === 'challenge') {
    let r = request('/v2/challenge-form', 'GET', null, {}, csrfToken);
    const form = r.html().find('form');
    const token = form.find('input[name="challenge"]').first().attr('value');
    r = request(form.attr('action'), 'POST', { challenge: token }, {}, csrfToken);
    const rb = body(r);
    if (rb.csrf) csrfToken = rb.csrf;
    r = request(r.headers.Location, 'GET', null, {}, csrfToken);
    const gb = body(r);
    if (gb.csrf) csrfToken = gb.csrf;
    grant = gb.grant_id;
  }

  // Catalog traversal
  let page = cfg.mode === 'pagination' ? '/v2/catalog/page' : '/v2/catalog';
  let product = null;
  for (let n = 0; n < 3 && page; n++) {
    const r = request(page, 'GET', null, {}, csrfToken);
    const b = body(r);
    if (b.csrf) csrfToken = b.csrf;
    product = b.data.products.find((p) => p.variants.some((v) => v.in_stock));
    if (product) break;
    page = b.next;
  }
  if (!product) {
    check(false, { 'eligible product': (x) => x });
    return;
  }

  const variant = product.variants.find((v) => v.in_stock);

  // Create cart
  let r = request('/v2/carts', 'POST', { product_id: product.id, variant_id: variant.id, grant_id: grant }, {}, csrfToken);
  let rb = body(r);
  if (rb.csrf) csrfToken = rb.csrf;
  cart = rb.id;
  etag = r.headers.Etag;
  check(r, { cart: (resp) => resp.status === 201 });

  // Update quantity if needed
  if (cfg.mode === 'etag' || cfg.mode === 'data') {
    const quantity = cfg.mode === 'data' ? rows[(__VU - 1) % rows.length].quantity : (cfg.quantity || 2);
    r = request('/v2/carts/' + cart, 'PATCH', { quantity: quantity }, { 'If-Match': etag }, csrfToken);
    if (r.status === 412) {
      const rr = request('/v2/carts/' + cart, 'GET', null, {}, csrfToken);
      etag = rr.headers.Etag;
      const rrb = body(rr);
      if (rrb.csrf) csrfToken = rrb.csrf;
      r = request('/v2/carts/' + cart, 'PATCH', { quantity: quantity }, { 'If-Match': etag }, csrfToken);
    }
    rb = body(r);
    if (rb.csrf) csrfToken = rb.csrf;
    etag = r.headers.Etag;
    check(r, { update: (resp) => resp.status === 200 });
  }

  // Reservation
  let reservation;
  if (cfg.mode === 'reservation') {
    r = request('/v2/reservations', 'POST', { cart_id: cart }, {}, csrfToken);
    rb = body(r);
    if (rb.csrf) csrfToken = rb.csrf;
    const url = rb.status_url;
    for (let n = 0; n < 5; n++) {
      sleep(0.05);
      r = request(url, 'GET', null, {}, csrfToken);
      const b = body(r);
      if (b.csrf) csrfToken = b.csrf;
      if (b.status === 'ready') {
        reservation = b.reservation_id;
        break;
      }
      if (b.status === 'failed') {
        check(false, { 'reservation ready': (x) => x });
        return;
      }
    }
    if (!reservation) return;
  }

  // Place order
  r = request('/v2/orders', 'POST', { cart_id: cart, reservation_id: reservation }, { 'Idempotency-Key': cart, 'If-Match': etag }, csrfToken);
  rb = body(r);
  if (rb.csrf) csrfToken = rb.csrf;
  check(r, { accepted: (resp) => resp.status === 201 && body(resp).accepted === true });
}

function work(override) {
  let csrfToken = login();
  const path = override || cfg.path || '/v2/work';
  let r = request(path, 'POST', {}, {}, csrfToken);
  for (let n = 0; n < 4 && r.status === 429; n++) {
    sleep(Number(r.headers['Retry-After']) + 0.01);
    r = request(path, 'POST', {}, {}, csrfToken);
  }
  check(r, {
    'operation or expected throttle': (resp) =>
      (resp.status === 200 && body(resp).ok === true) || (cfg.completion && resp.status === 429),
  });
}

export default function () {
  if (cfg.workload) {
    if (cfg.operation === 'journey') flow();
    else work();
  } else if (cfg.mode === 'errors') {
    let csrfToken = login();
    for (let n = 0; n < 4; n++) work();
  } else {
    flow();
  }
}

export function browse() {
  work('/v2/browse');
}

export function checkout() {
  flow();
}
