_CREDENTIAL_INDEX = 0


def _next_credential():
    global _CREDENTIAL_INDEX
    with _CREDENTIAL_LOCK:
        row = ROWS[_CREDENTIAL_INDEX % len(ROWS)]
        _CREDENTIAL_INDEX += 1
        return row


class ArrivalPlan:
    def __init__(self):
        self.started = None
        self.counts = {pool['name']: 0 for pool in POOLS}
        self.lock = Semaphore()

    def slot(self, pool, number):
        rates = CFG.get('rates', [pool['rate']]) if not CFG.get('pools') else [pool['rate']]
        spans = [15, 10, 10] if len(rates) > 1 else [DURATION]
        offset = 0
        for rate, span in zip(rates, spans):
            count = int(rate * span)
            if number < count:
                return offset + number / rate + (
                    number * 0.002 if pool.get('operation') == 'journey' else 0)
            number -= count
            offset += span
        return None

    def next(self):
        with self.lock:
