                .check(status().is(201), jsonPath("$.accepted").is("true"),
                    jsonPath("$.csrf").optional().saveAs("csrf")))));
    }

    public ModelSimulation() {
        setUp(
            scenario("matrix").exec(flow()).injectOpen(constantUsersPerSec(1.05).during(Duration.ofMillis(36000)))
        )
            .protocols(HTTP);
    }
}

