    // Assign profile based on VU ID
    state.profile = PROFILES[(vuId - 1) % PROFILES.length];
    // Assign username: bench-1..bench-16
    const userIndex = ((vuId - 1) % 16) + 1;
    state.username = `bench-${userIndex}`;
    state.ownerSeed = `${state.username}-${Date.now()}-${vuId}`;
    vuStates.set(vuId, state);
  }
  return vuStates.get(vuId);
}

function getCookie(cookies, name) {
  for (const cookie of cookies) {
    if (cookie.startsWith(name + '=')) {
