function extractCsrfFromHtml(html) {
  // Look for input[name=csrf] with value
  const csrfMatch = html.match(/input[^>]*name=["']csrf["'][^>]*value=["']([^"']+)["']/i);
  if (csrfMatch) return csrfMatch[1];
  // Try reversed attribute order
  const csrfMatch2 = html.match(/input[^>]*value=["']([^"']+)["'][^>]*name=["']csrf["']/i);
  if (csrfMatch2) return csrfMatch2[1];
  return null;
}

function extractNonceFromHtml(html) {
  const nonceMatch = html.match(/name=["']login_nonce["'][^>]*value=["']([^"']+)["']/i);
  if (nonceMatch) return nonceMatch[1];
  const nonceMatch2 = html.match(/value=["']([^"']+)["'][^>]*name=["']login_nonce["']/i);
  if (nonceMatch2) return nonceMatch2[1];
  return null;
}

function login(state) {
  // GET login form
  const formRes = http.get(`${BASE_URL}/v2/login-form`, {
    redirects: 0,
    cookies: {}
  });

  if (formRes.status !== 200) {
    return false;
  }

  const csrf = extractCsrfFromHtml(formRes.body);
  if (!csrf) {
    return false;
  }

  state.csrf = csrf;

  // POST login
  const loginRes = http.post(`${BASE_URL}/v2/login`, JSON.stringify({
    username: state.username,
    password: state.password,
    csrf: state.csrf
  }), {
    headers: {
      'Content-Type': 'application/json',
      'X-CSRF-Token': state.csrf
    },
    redirects: 0,
    cookies: {}
  });

  if (loginRes.status === 302) {
    // Follow Location exactly once
    const location = loginRes.headers['Location'];
    if (location) {
      const followRes = http.get(`${BASE_URL}${location}`, {
        redirects: 0,
        cookies: {}
      });
      if (followRes.status === 200) {
        try {
          const body = JSON.parse(followRes.body);
          if (body.csrf) state.csrf = body.csrf;
          if (body.user) state.authenticated = true;
        } catch (e) {
          // Try to extract from HTML
          const newCsrf = extractCsrfFromHtml(followRes.body);
          if (newCsrf) state.csrf = newCsrf;
          state.authenticated = true;
        }
      }
    }
  } else if (loginRes.status === 200) {
    try {
      const body = JSON.parse(loginRes.body);
      if (body.csrf) state.csrf = body.csrf;
      if (body.user) state.authenticated = true;
    } catch (e) {
      return false;
    }
  } else {
    return false;
  }

  // Extract session cookie from response
  const setCookie = loginRes.headers['Set-Cookie'];
  if (setCookie) {
    const sessionMatch = setCookie.match(/session=([^;]+)/);
    if (sessionMatch) {
      state.sessionCookie = `session=${sessionMatch[1]}`;
    }
  }

  return state.authenticated;
}

function renewSession(state) {
  const renewRes = http.post(`${BASE_URL}/v2/session/renew`, JSON.stringify({}), {
    headers: {
      'Content-Type': 'application/json',
      'X-CSRF-Token': state.csrf
    },
    cookies: state.sessionCookie ? { session: state.sessionCookie.split('=')[1] } : {}
  });

  if (renewRes.status === 200) {
    try {
      const body = JSON.parse(renewRes.body);
      if (body.csrf) state.csrf = body.csrf;
      return true;
    } catch (e) {
      return false;
    }
  }
  return false;
}

function recoverCart(state) {
  if (!state.cartId) return true;

  const recoverRes = http.post(`${BASE_URL}/v2/carts/${state.cartId}/recover`, JSON.stringify({}), {
    headers: {
      'Content-Type': 'application/json',
      'X-CSRF-Token': state.csrf
    },
