      if (body.csrf) state.csrf = body.csrf;
      return true;
    } catch (e) {
      return false;
    }
  }
  return false;
}

function handle401(state, operationFn) {
  // Try to determine error type
  // For simplicity, try renewal first
  if (renewSession(state)) {
    if (state.cartId) {
      recoverCart(state);
    }
    return operationFn();
  }

  // If renewal fails, try full re-login
  if (login(state)) {
    if (state.cartId) {
      recoverCart(state);
    }
    return operationFn();
  }

  return null;
}

function getCatalog(state) {
  const res = http.get(`${BASE_URL}/v2/catalog`, {
    headers: {
      'X-CSRF-Token': state.csrf
    },
    cookies: state.sessionCookie ? { session: state.sessionCookie.split('=')[1] } : {}
  });

  if (res.status === 401) {
