  return null;
}

function getCatalogPage(state, pageUrl) {
  const res = http.get(`${BASE_URL}${pageUrl}`, {
    headers: {
      'X-CSRF-Token': state.csrf
    },
    cookies: state.sessionCookie ? { session: state.sessionCookie.split('=')[1] } : {}
