  if (res.status === 401) {
    const retryRes = handle401(state, () => getCatalogPage(state, pageUrl));
    return retryRes;
  }

  if (res.status === 200) {
    try {
      const body = JSON.parse(res.body);
      if (body.csrf) state.csrf = body.csrf;
      return body;
