function createCart(state, productId, variantId) {
  const payload = {
    product_id: productId,
    variant_id: variantId
  };

  if (state.grantId) {
    payload.grant_id = state.grantId;
  }

  const res = http.post(`${BASE_URL}/v2/carts`, JSON.stringify(payload), {
    headers: {
      'Content-Type': 'application/json',
      'X-CSRF-Token': state.csrf
    },
    cookies: state.sessionCookie ? { session: state.sessionCookie.split('=')[1] } : {}
  });

  if (res.status === 401) {
    const retryRes = handle401(state, () => createCart(state, productId, variantId));
    return retryRes;
  }

  if (res.status === 201) {
    try {
      const body = JSON.parse(res.body);
      if (body.csrf) state.csrf = body.csrf;
      state.cartId = body.id;
      state.cartEtag = res.headers['ETag'] || null;
      state.idempotencyKey = `idem-${state.cartId}-${Date.now()}`;
      return body;
    } catch (e) {
      return null;
    }
  }
  return null;
}

function getCart(state) {
  const res = http.get(`${BASE_URL}/v2/carts/${state.cartId}`, {
    headers: {
      'X-CSRF-Token': state.csrf
    },
    cookies: state.sessionCookie ? { session: state.sessionCookie.split('=')[1] } : {}
  });

  if (res.status === 401) {
    const retryRes = handle401(state, () => getCart(state));
    return retryRes;
  }

  if (res.status === 200) {
    state.cartEtag = res.headers['ETag'] || state.cartEtag;
    try {
      const body = JSON.parse(res.body);
      if (body.csrf) state.csrf = body.csrf;
      return body;
    } catch (e) {
      return null;
    }
  }
  return null;
}

function updateCart(state, quantity) {
  const res = http.patch(`${BASE_URL}/v2/carts/${state.cartId}`, JSON.stringify({
    quantity: quantity
  }), {
    headers: {
      'Content-Type': 'application/json',
      'X-CSRF-Token': state.csrf,
      'If-Match': state.cartEtag || ''
    },
    cookies: state.sessionCookie ? { session: state.sessionCookie.split('=')[1] } : {}
  });

  if (res.status === 401) {
    const retryRes = handle401(state, () => updateCart(state, quantity));
    return retryRes;
  }

  if (res.status === 412) {
    // Re-read and retry once
    const cartData = getCart(state);
    if (cartData) {
      const retryRes = http.patch(`${BASE_URL}/v2/carts/${state.cartId}`, JSON.stringify({
        quantity: quantity
      }), {
        headers: {
          'Content-Type': 'application/json',
          'X-CSRF-Token': state.csrf,
          'If-Match': state.cartEtag || ''
        },
        cookies: state.sessionCookie ? { session: state.sessionCookie.split('=')[1] } : {}
      });
      if (retryRes.status === 200) {
        try {
          const body = JSON.parse(retryRes.body);
          if (body.csrf) state.csrf = body.csrf;
          state.cartEtag = retryRes.headers['ETag'] || state.cartEtag;
          return body;
        } catch (e) {
          return null;
        }
      }
    }
    return null;
  }

  if (res.status === 200) {
    try {
      const body = JSON.parse(res.body);
      if (body.csrf) state.csrf = body.csrf;
      state.cartEtag = res.headers['ETag'] || state.cartEtag;
      return body;
    } catch (e) {
      return null;
    }
  }
  return null;
}

function getChallengeForm(state) {
  const res = http.get(`${BASE_URL}/v2/challenge-form`, {
    headers: {
      'X-CSRF-Token': state.csrf
    },
    cookies: state.sessionCookie ? { session: state.sessionCookie.split('=')[1] } : {}
  });

  if (res.status === 401) {
    const retryRes = handle401(state, () => getChallengeForm(state));
    return retryRes;
  }

  if (res.status === 200) {
    // Extract form action and challenge input
    const actionMatch = res.body.match(/form[^>]*action=["']([^"']+)["']/i);
    const challengeMatch = res.body.match(/input[^>]*name=["']challenge["']/i);

    if (actionMatch && challengeMatch) {
      return {
        action: actionMatch[1],
        hasChallenge: true
      };
    }
  }
  return null;
}

function postChallenge(state, action, challengeValue) {
  const res = http.post(`${BASE_URL}${action}`, JSON.stringify({
    challenge: challengeValue
  }), {
    headers: {
      'Content-Type': 'application/json',
      'X-CSRF-Token': state.csrf
    },
    redirects: 0,
    cookies: state.sessionCookie ? { session: state.sessionCookie.split('=')[1] } : {}
  });

  if (res.status === 401) {
    const retryRes = handle401(state, () => postChallenge(state, action, challengeValue));
    return retryRes;
  }

  if (res.status === 302) {
    const location = res.headers['Location'];
    if (location) {
      const followRes = http.get(`${BASE_URL}${location}`, {
        headers: {
          'X-CSRF-Token': state.csrf
        },
        cookies: state.sessionCookie ? { session: state.sessionCookie.split('=')[1] } : {}
      });

      if (followRes.status === 200) {
        try {
          const body = JSON.parse(followRes.body);
          if (body.csrf) state.csrf = body.csrf;
          if (body.grant_id) state.grantId = body.grant_id;
          return body;
        } catch (e) {
          return null;
        }
      }
    }
  }
  return null;
}

function createReservation(state) {
  const res = http.post(`${BASE_URL}/v2/reservations`, JSON.stringify({
    cart_id: state.cartId
  }), {
    headers: {
      'Content-Type': 'application/json',
      'X-CSRF-Token': state.csrf
    },
    cookies: state.sessionCookie ? { session: state.sessionCookie.split('=')[1] } : {}
  });

  if (res.status === 401) {
    const retryRes = handle401(state, () => createReservation(state));
    return retryRes;
  }

  if (res.status === 202) {
    try {
      const body = JSON.parse(res.body);
      if (body.csrf) state.csrf = body.csrf;
      return body;
    } catch (e) {
      return null;
    }
  }
  return null;
}

function pollReservation(state, statusUrl) {
  for (let i = 0; i < 5; i++) {
    sleep(0.05); // at least 50ms apart

    const res = http.get(`${BASE_URL}${statusUrl}`, {
      headers: {
        'X-CSRF-Token': state.csrf
      },
      cookies: state.sessionCookie ? { session: state.sessionCookie.split('=')[1] } : {}
    });

    if (res.status === 401) {
      const retryRes = handle401(state, () => pollReservation(state, statusUrl));
      return retryRes;
    }

    if (res.status === 200) {
      try {
        const body = JSON.parse(res.body);
        if (body.csrf) state.csrf = body.csrf;
        if (body.status === 'ready' && body.reservation_id) {
          state.reservationId = body.reservation_id;
          return body;
        }
        if (body.status === 'failed') {
          return null;
        }
        // pending - continue polling
      } catch (e) {
        return null;
      }
    }
  }
  return null;
}

function createOrder(state) {
  const payload = {
    cart_id: state.cartId
  };

  if (state.reservationId) {
    payload.reservation_id = state.reservationId;
  }

  const headers = {
    'Content-Type': 'application/json',
    'X-CSRF-Token': state.csrf,
    'Idempotency-Key': state.idempotencyKey
  };

  if (state.cartEtag) {
    headers['If-Match'] = state.cartEtag;
  }

  const res = http.post(`${BASE_URL}/v2/orders`, JSON.stringify(payload), {
    headers: headers,
    cookies: state.sessionCookie ? { session: state.sessionCookie.split('=')[1] } : {}
  });

  if (res.status === 401) {
    const retryRes = handle401(state, () => createOrder(state));
    return retryRes;
  }

  if (res.status === 201) {
    try {
      const body = JSON.parse(res.body);
      if (body.csrf) state.csrf = body.csrf;
      if (body.accepted === true) {
        return body;
      }
      return null; // accepted:false is business failure
    } catch (e) {
      return null;
    }
  }

  if (res.status === 200) {
    try {
      const body = JSON.parse(res.body);
      if (body.csrf) state.csrf = body.csrf;
      if (body.accepted === true) {
        return body;
      }
      return null; // accepted:false is business failure
    } catch (e) {
      return null;
    }
  }

  return null;
}

function doWork(state) {
  const now = Date.now();

  // Check if we're in a 429 backoff period
  if (state.lastWork429Time > 0 && (now - state.lastWork429Time) < 1000) {
    return null; // Still in backoff
  }

  const res = http.post(`${BASE_URL}/v2/work`, JSON.stringify({}), {
    headers: {
      'Content-Type': 'application/json',
      'X-CSRF-Token': state.csrf
    },
    cookies: state.sessionCookie ? { session: state.sessionCookie.split('=')[1] } : {}
  });

  workTotalResponses.add(1);

  if (res.status === 401) {
    // Check error type
    let errorType = 'expired';
    try {
      const body = JSON.parse(res.body);
      if (body.error) errorType = body.error;
    } catch (e) {}

    if (errorType === 'expired') {
      // Expected expiry - not counted as unexpected
      const retryRes = handle401(state, () => doWork(state));
      return retryRes;
    } else if (errorType === 'session') {
      // Session revoked - try full re-login
      if (login(state)) {
        if (state.cartId) recoverCart(state);
        const retryRes = doWork(state);
        return retryRes;
      }
      workUnexpectedErrors.add(1);
      return null;
    } else {
      // denied - fail assertion
      workUnexpectedErrors.add(1);
      return null;
    }
  }

  if (res.status === 429) {
    // Scheduled 429 - expected, retry with Retry-After
    const retryAfter = parseInt(res.headers['Retry-After'] || '1');
    state.lastWork429Time = now;
    state.workRetryCount++;

    if (state.workRetryCount <= MAX_RETRY_AFTER_RETRIES) {
      sleep(retryAfter);
      state.lastWork429Time = 0;
      return doWork(state);
    }
    return null;
  }

  if (res.status === 200) {
    try {
      const body = JSON.parse(res.body);
      if (body.csrf) state.csrf = body.csrf;
      if (body.ok === true) {
        state.workRetryCount = 0;
        return body;
      }
    } catch (e) {
      workUnexpectedErrors.add(1);
      return null;
    }
  }

  if (res.status >= 500) {
    workUnexpectedErrors.add(1);
    return null;
  }

  workUnexpectedErrors.add(1);
  return null;
}

function fullJourney(state) {
  // Fresh login
  if (!login(state)) {
    return false;
  }

  // Fresh cart
  state.cartId = null;
  state.cartEtag = null;
  state.grantId = null;
  state.reservationId = null;
  state.idempotencyKey = null;

  // Get catalog
  let catalogData = getCatalog(state);
  if (!catalogData || !catalogData.data || !catalogData.data.products || catalogData.data.products.length === 0) {
    return false;
  }

  // Traverse catalog pages if profile requires
  let product = null;
  let variant = null;

  if (state.profile.reverse_catalog) {
    // Traverse at most 3 pages
    let pageUrl = '/v2/catalog/page';
    for (let i = 0; i < 3; i++) {
      const pageData = getCatalogPage(state, pageUrl);
      if (pageData && pageData.data && pageData.data.products && pageData.data.products.length > 0) {
        product = pageData.data.products[0];
        if (product.variants && product.variants.length > 0) {
          variant = product.variants[0];
          break;
        }
      }
      if (pageData && pageData.next) {
        pageUrl = pageData.next;
      } else {
        break;
      }
    }
  }

  if (!product || !variant) {
    // Fall back to first catalog product
    product = catalogData.data.products[0];
    if (product.variants && product.variants.length > 0) {
      variant = product.variants[0];
    } else {
      return false;
    }
  }

  // Get challenge/grant
  const challengeForm = getChallengeForm(state);
  if (challengeForm && challengeForm.hasChallenge) {
    const challengeResult = postChallenge(state, challengeForm.action, 'challenge-value');
    if (challengeResult && challengeResult.grant_id) {
      state.grantId = challengeResult.grant_id;
    }
  }

  // Create cart
  const cartResult = createCart(state, product.id, variant.id);
  if (!cartResult) {
    return false;
  }

  // Update cart quantity
  const quantity = 1 + (__VU % 20); // 1..20
  const updateResult = updateCart(state, quantity);
  if (!updateResult) {
    return false;
  }

  // Create reservation
  const reservationResult = createReservation(state);
  if (reservationResult && reservationResult.status_url) {
    const pollResult = pollReservation(state, reservationResult.status_url);
    if (pollResult && pollResult.reservation_id) {
      state.reservationId = pollResult.reservation_id;
    }
  }

  // Create order (checkout)
  checkoutStarts.add(1);
  const orderResult = createOrder(state);
  if (!orderResult) {
    return false;
  }

  return true;
}

export function setup() {
  // Record owner seeds
  const seeds = [];
  for (let i = 1; i <= 16; i++) {
    seeds.push({
      username: `bench-${i}`,
      seed: `bench-${i}-${Date.now()}-setup`
    });
  }
  return { seeds };
}

export default function(data) {
  const state = getVUState();
  const now = Date.now();

  // Check if we're in the scored window
  if (!t0Set) {
    // Try to set T0 with first authenticated eligible POST
    // We need to be authenticated first
    if (!state.authenticated) {
      login(state);
    }

    if (state.authenticated) {
      // This is the first authenticated eligible POST
      t0 = now;
      t0Set = true;
      console.log(`T0 set at ${t0}`);
    }
  }

  const elapsed = t0Set ? (now - t0) / 1000 : 0;

  if (t0Set && elapsed >= 0 && elapsed < WARMUP_SECONDS + SCORED_SECONDS) {
    // In warmup or scored window - do work
    const workResult = doWork(state);
    if (workResult) {
      workStarts.add(1);
      workCompletions.add(1);
    }
  } else if (t0Set && elapsed >= WARMUP_SECONDS + SCORED_SECONDS && elapsed < WARMUP_SECONDS + SCORED_SECONDS + DRAIN_SECONDS) {
    // Drain period - complete any in-flight work
    const workResult = doWork(state);
    if (workResult) {
      workStarts.add(1);
      workCompletions.add(1);
    }
  }

  // Occasionally run a full journey (checkout) - but this is not the scored pool
  // The scored pool is only POST /v2/work
  if (__ITER % 10 === 0) {
    fullJourney(state);
  }

  sleep(0.1);
}

export function teardown(data) {
  // Record final owner seeds
  const seeds = [];
  for (let i = 1; i <= 16; i++) {
    seeds.push({
      username: `bench-${i}`,
      seed: `bench-${i}-${Date.now()}-teardown`
    });
  }
  console.log('Owner seeds recorded:', JSON.stringify(seeds));
}

export const options = {
  scenarios: {
    work_pool: {
      executor: 'constant-arrival-rate',
