    private static String extractCsrf(String body) {
        if (body == null) return null;
        int idx = body.indexOf("name=\"csrf\"");
        if (idx < 0) idx = body.indexOf("name='csrf'");
        if (idx < 0) idx = body.indexOf("name=csrf");
        if (idx < 0) return null;
        int valIdx = body.indexOf("value=\"", idx);
        if (valIdx < 0) valIdx = body.indexOf("value='", idx);
        if (valIdx < 0) return null;
        int start = valIdx + 7;
        int end = body.indexOf("\"", start);
        if (end < 0) end = body.indexOf("'", start);
        if (end < 0) return null;
        return body.substring(start, end);
    }

