                .exec(session -> {
                    int status = session.getInt("status");
                    if (status == 200) {
                        String ok = session.getString("work_ok");
                        if ("true".equals(ok)) {
                            return session.set("work_done", true);
                        } else {
                            return session.markAsFailed();
                        }
                    } else if (status == 429) {
                        String retryAfter = session.getString("retry_after");
                        long delay = 1000;
                        if (retryAfter != null) {
                            try {
                                delay = Long.parseLong(retryAfter) * 1000;
