                    }
                })
                .doIf(session -> session.getInt("status") == 429 && session.getBoolean("work_done") == false)
                .on(
                        pause(session -> Duration.ofMillis(session.getLong("retry_delay")))
                )
        )
        .exec(session -> {
            Boolean done = session.getBoolean("work_done");
            if (done == null || !done) {
                return session.markAsFailed();
            }
            return session;
        });
    }

    private static ChainBuilder fullJourney() {
