function login(username, password) {
  const formRes = http.get(`${BASE_URL}/v2/login-form`, { redirects: 0 });
  if (formRes.status !== 200) {
    return { ok: false, error: `login-form status ${formRes.status}` };
  }

  const csrfMatch = formRes.body.match(/name=["']csrf["'][^>]*value=["']([^"']+)["']/i) ||
    formRes.body.match(/value=["']([^"']+)["'][^>]*name=["']csrf["']/i);
  if (!csrfMatch) {
    return { ok: false, error: 'no csrf in login form' };
  }
  const csrf = csrfMatch[1];

  const loginRes = http.post(`${BASE_URL}/v2/login`, JSON.stringify({
    username: username,
    password: password,
    csrf: csrf
  }), {
    headers: { 'Content-Type': 'application/json' },
    redirects: 0
  });

  if (loginRes.status === 302) {
    const location = loginRes.headers['Location'];
    if (!location) {
      return { ok: false, error: '302 without Location' };
    }
    const followRes = http.get(location.startsWith('http') ? location : `${BASE_URL}${location}`, { redirects: 0 });
    if (followRes.status !== 200) {
      return { ok: false, error: `follow status ${followRes.status}` };
    }
    try {
      const body = JSON.parse(followRes.body);
      return { ok: true, csrf: body.csrf, user: body.user };
    } catch (e) {
      return { ok: false, error: 'invalid JSON after redirect' };
    }
  }

  if (loginRes.status !== 200) {
    return { ok: false, error: `login status ${loginRes.status}` };
  }

  try {
    const body = JSON.parse(loginRes.body);
    return { ok: true, csrf: body.csrf, user: body.user };
  } catch (e) {
    return { ok: false, error: 'invalid login JSON' };
  }
}

