function updateCart(csrf, cartId, etag, quantity) {
  const res = http.patch(`${BASE_URL}/v2/carts/${cartId}`, JSON.stringify({ quantity: quantity }), {
    headers: {
      'Content-Type': 'application/json',
      'X-CSRF-Token': csrf,
      'If-Match': etag
    }
  });
  if (res.status === 412) {
    const reRead = getCart(csrf, cartId);
    if (!reRead.ok) {
      return { ok: false, error: `412 then re-read failed: ${reRead.error}`, status: res.status };
    }
    const retryRes = http.patch(`${BASE_URL}/v2/carts/${cartId}`, JSON.stringify({ quantity: quantity }), {
      headers: {
        'Content-Type': 'application/json',
        'X-CSRF-Token': csrf,
        'If-Match': reRead.etag
      }
    });
    if (retryRes.status !== 200) {
      return { ok: false, error: `cart update retry status ${retryRes.status}`, status: retryRes.status };
    }
    try {
      const body = JSON.parse(retryRes.body);
      return { ok: true, csrf: body.csrf || csrf, etag: retryRes.headers['ETag'] || retryRes.headers['Etag'] || retryRes.headers['etag'] };
    } catch (e) {
