      'Content-Type': 'application/json',
      'X-CSRF-Token': csrf
    }
  });
  if (res.status !== 200) {
    return { ok: false, error: `recover status ${res.status}`, status: res.status };
  }
  try {
    const body = JSON.parse(res.body);
    return { ok: true, csrf: body.csrf || csrf };
  } catch (e) {
    return { ok: false, error: 'invalid recover JSON', status: res.status };
  }
}

function doWork(csrf, profile) {
  const payload = {};
  if (profile.html_layout !== undefined) {
    payload.html_layout = profile.html_layout;
  }
  if (profile.reverse_catalog !== undefined) {
    payload.reverse_catalog = profile.reverse_catalog;
  }

  rawWorkCount.add(1);

  const startTime = Date.now();
  const res = http.post(`${BASE_URL}/v2/work`, JSON.stringify(payload), {
    headers: {
      'Content-Type': 'application/json',
      'X-CSRF-Token': csrf
    }
  });

  if (res.status === 429) {
    scheduled429Count.add(1);
    const retryAfter = res.headers['Retry-After'];
    const retryDelay = retryAfter ? parseFloat(retryAfter) : 1;
    if (retryDelay > 0) {
      sleep(retryDelay);
    }
    return { ok: false, error: 'scheduled 429', status: 429, retryable: true };
  }

  if (res.status === 401) {
    try {
      const body = JSON.parse(res.body);
      if (body.error === 'expired') {
        return { ok: false, error: 'expired', status: 401, expired: true };
      }
      if (body.error === 'session') {
        return { ok: false, error: 'session revoked', status: 401, revoked: true };
      }
      if (body.error === 'denied') {
        return { ok: false, error: 'denied', status: 401, denied: true };
      }
    } catch (e) {
      // fall through
    }
    return { ok: false, error: '401 unknown', status: 401 };
  }

  if (res.status === 500) {
    unexpectedErrorRate.add(1);
    businessFailureRate.add(1);
    return { ok: false, error: '500 unexpected', status: 500 };
  }

  if (res.status !== 200) {
    unexpectedErrorRate.add(1);
    businessFailureRate.add(1);
    return { ok: false, error: `work status ${res.status}`, status: res.status };
  }

  try {
    const body = JSON.parse(res.body);
    if (body.ok === true) {
      workCompletions.add(1);
      workStarts.add(1);
      return { ok: true, csrf: body.csrf || csrf, startTime: startTime };
    }
    unexpectedErrorRate.add(1);
    businessFailureRate.add(1);
    return { ok: false, error: 'work ok:false', status: res.status };
  } catch (e) {
    unexpectedErrorRate.add(1);
    businessFailureRate.add(1);
    return { ok: false, error: 'invalid work JSON', status: res.status };
  }
}

function handleExpiredWork(csrf, cartId, profile) {
  const renewRes = renewSession(csrf);
  if (!renewRes.ok) {
    return { ok: false, error: `renew failed: ${renewRes.error}`, status: renewRes.status };
  }
  let newCsrf = renewRes.csrf;
  if (cartId) {
    const recoverRes = recoverCart(newCsrf, cartId);
    if (!recoverRes.ok) {
      return { ok: false, error: `recover failed: ${recoverRes.error}`, status: recoverRes.status };
    }
    newCsrf = recoverRes.csrf;
  }
  return doWork(newCsrf, profile);
}

function handleRevokedWork(csrf, cartId, profile, username) {
  const loginRes = login(username, 'bench');
  if (!loginRes.ok) {
    return { ok: false, error: `re-login failed: ${loginRes.error}`, status: 0 };
  }
  let newCsrf = loginRes.csrf;
  if (cartId) {
    const recoverRes = recoverCart(newCsrf, cartId);
    if (!recoverRes.ok) {
      return { ok: false, error: `recover after re-login failed: ${recoverRes.error}`, status: recoverRes.status };
    }
    newCsrf = recoverRes.csrf;
  }
  return doWork(newCsrf, profile);
}

function fullJourney(username, profile) {
  const loginRes = login(username, 'bench');
  if (!loginRes.ok) {
    droppedWorkRate.add(1);
    return { ok: false, error: loginRes.error };
  }
  let csrf = loginRes.csrf;

  const catalogRes = getCatalog(csrf, profile.reverse_catalog || false);
  if (!catalogRes.ok) {
    droppedWorkRate.add(1);
    return { ok: false, error: catalogRes.error };
  }

  let products = catalogRes.products;
  let selectedProduct = null;
  let selectedVariant = null;

  if (profile.html_layout === 1) {
    let pageUrl = '/v2/catalog/page';
    for (let i = 0; i < 3; i++) {
      const pageRes = getCatalogPage(csrf, pageUrl);
      if (!pageRes.ok) {
        break;
      }
      if (pageRes.data && pageRes.data.products && pageRes.data.products.length > 0) {
        const p = pageRes.data.products[0];
        if (p.variants && p.variants.length > 0) {
          selectedProduct = p;
          selectedVariant = p.variants[0];
          break;
        }
      }
      if (!pageRes.next) {
        break;
      }
      pageUrl = pageRes.next;
    }
  }

  if (!selectedProduct) {
    for (const p of products) {
      if (p.variants && p.variants.length > 0) {
        selectedProduct = p;
        selectedVariant = p.variants[0];
        break;
      }
    }
  }

  if (!selectedProduct || !selectedVariant) {
    droppedWorkRate.add(1);
    return { ok: false, error: 'no product with variants found' };
  }

  let grantId = null;
  const challengeFormRes = getChallengeForm(csrf);
  if (challengeFormRes.ok) {
    const challengeRes = submitChallenge(csrf, challengeFormRes.action, challengeFormRes.challenge);
    if (challengeRes.ok) {
      grantId = challengeRes.grantId;
      csrf = challengeRes.csrf;
    }
  }

  const cartRes = createCart(csrf, selectedProduct.id, selectedVariant.id, grantId);
  if (!cartRes.ok) {
    droppedWorkRate.add(1);
    return { ok: false, error: cartRes.error };
  }
  csrf = cartRes.csrf;
  const cartId = cartRes.cartId;
  let etag = cartRes.etag;

  const updateRes = updateCart(csrf, cartId, etag, 1);
  if (!updateRes.ok) {
    droppedWorkRate.add(1);
    return { ok: false, error: updateRes.error };
  }
  csrf = updateRes.csrf;
  etag = updateRes.etag;

  let reservationId = null;
  const reservationRes = createReservation(csrf, cartId);
  if (reservationRes.ok) {
    csrf = reservationRes.csrf;
    const pollRes = pollReservation(csrf, reservationRes.statusUrl);
    if (pollRes.ok) {
      reservationId = pollRes.reservationId;
      csrf = pollRes.csrf;
    }
  }

  const idempotencyKey = `idem-${username}-${cartId}-${Date.now()}`;
  const orderRes = createOrder(csrf, cartId, reservationId, etag, idempotencyKey);
  if (!orderRes.ok) {
    droppedWorkRate.add(1);
    return { ok: false, error: orderRes.error };
  }
  csrf = orderRes.csrf;

  const workRes = doWork(csrf, profile);
  if (workRes.ok) {
    return { ok: true, startTime: workRes.startTime };
  }

  if (workRes.expired) {
    const retryRes = handleExpiredWork(csrf, cartId, profile);
    if (retryRes.ok) {
      return { ok: true, startTime: retryRes.startTime };
    }
    droppedWorkRate.add(1);
    return { ok: false, error: `expired retry failed: ${retryRes.error}` };
  }

  if (workRes.revoked) {
    const retryRes = handleRevokedWork(csrf, cartId, profile, username);
    if (retryRes.ok) {
      return { ok: true, startTime: retryRes.startTime };
    }
    droppedWorkRate.add(1);
    return { ok: false, error: `revoked retry failed: ${retryRes.error}` };
  }

  if (workRes.retryable) {
    for (let i = 0; i < 4; i++) {
      const retryRes = doWork(csrf, profile);
      if (retryRes.ok) {
        return { ok: true, startTime: retryRes.startTime };
      }
      if (!retryRes.retryable) {
        if (retryRes.expired) {
          const expRetry = handleExpiredWork(csrf, cartId, profile);
          if (expRetry.ok) {
            return { ok: true, startTime: expRetry.startTime };
          }
        }
        if (retryRes.revoked) {
          const revRetry = handleRevokedWork(csrf, cartId, profile, username);
          if (revRetry.ok) {
            return { ok: true, startTime: revRetry.startTime };
          }
        }
        droppedWorkRate.add(1);
        return { ok: false, error: `work retry failed: ${retryRes.error}` };
      }
    }
    droppedWorkRate.add(1);
    return { ok: false, error: 'work 429 retries exhausted' };
  }

  droppedWorkRate.add(1);
  return { ok: false, error: workRes.error };
}

