            payload["reservation_id"] = self.reservation_id

        headers = {
            "X-CSRF-Token": self.csrf_token or "",
            "Idempotency-Key": self.idempotency_key or f"idem-{self.cart_id}",
        }
        if self.cart_etag:
            headers["If-Match"] = self.cart_etag

        with self.client.post(
            "/v2/orders",
            json=payload,
            headers=headers,
            catch_response=True,
            name="order-create",
        ) as resp:
            if resp.status_code == 201:
                data = resp.json()
                if data.get("accepted") is True:
                    if "csrf" in data:
                        self.csrf_token = data["csrf"]
                    resp.success()
                    return True
                else:
                    resp.failure("Order not accepted (business failure)")
                    return False
            elif resp.status_code == 401:
                error_type = resp.json().get("error", "") if resp.headers.get("content-type", "").startswith("application/json") else ""
                if self.handle_401(error_type, "order-create"):
                    return self.create_order()
                resp.failure(f"Order create 401: {error_type}")
                return False
            else:
                resp.failure(f"Order create failed: {resp.status_code}")
                return False

    def do_work(self):
        headers = {"X-CSRF-Token": self.csrf_token or ""}

        with self.client.post(
            "/v2/work",
            json={},
            headers=headers,
            catch_response=True,
            name="work",
        ) as resp:
            if resp.status_code == 200:
                data = resp.json() if resp.headers.get("content-type", "").startswith("application/json") else {}
                if data.get("ok") is True:
                    resp.success()
                    return True
                else:
                    resp.failure("Work not ok")
                    return False
            elif resp.status_code == 429:
                retry_after = resp.headers.get("Retry-After", "1")
                try:
                    retry_after = int(retry_after)
                except ValueError:
                    retry_after = 1
                if self.work_retries < 4:
                    self.work_retries += 1
                    time.sleep(retry_after)
                    return self.do_work()
                else:
                    resp.failure("Work 429 retries exhausted")
                    return False
            elif resp.status_code == 401:
                error_type = resp.json().get("error", "") if resp.headers.get("content-type", "").startswith("application/json") else ""
                if error_type == "expired":
                    if self.handle_401("expired", "work"):
                        return self.do_work()
                    resp.failure(f"Work 401 expired: {error_type}")
                    return False
                elif error_type == "session":
                    if self.handle_401("session", "work"):
                        return self.do_work()
                    resp.failure(f"Work 401 session: {error_type}")
                    return False
                else:
                    resp.failure(f"Work 401 denied: {error_type}")
                    return False
            else:
                resp.failure(f"Work failed: {resp.status_code}")
                return False

    def run_journey(self):
        self.work_retries = 0
        self.cart_id = None
        self.cart_etag = None
        self.grant_id = None
        self.reservation_id = None
        self.idempotency_key = None

        product_variant = self.traverse_catalog()
        if not product_variant:
            return False

        product_id, variant_id = product_variant

        if not self.create_cart(product_id, variant_id):
            return False

        if not self.get_cart():
            return False

        if not self.update_cart(random.randint(1, 20)):
            return False

        challenge_action = self.get_challenge()
        if challenge_action:
            if not self.post_challenge(challenge_action):
                return False

        status_url = self.create_reservation()
        if status_url:
            if not self.poll_reservation(status_url):
                return False

        if not self.create_order():
            return False

        return True

    @task
    def shop_task(self):
        if self.iteration_count >= self.max_iterations:
            raise StopUser()

        self.iteration_count += 1

        if not self.authenticated:
            if not self.login():
                return

        journey_success = self.run_journey()

        if journey_success:
            if not self.work_started:
                self.work_started = True
                self.owner_seed = f"owner-{self.username}-{int(time.time()*1000)}"

            self.do_work()

        time.sleep(self.profile.get("delay_seconds", 0.2))


class WorkShape(LoadTestShape):
    def __init__(self):
        super().__init__()
        self.start_time = None
        self.t0 = None
        self.phase = "warmup"
        self.phase_start = None
        self.current_users = 2
        self.target_rate = 5
        self.max_users = 32
        self.drain_start = None

    def tick(self):
        current_time = time.time()

        if self.start_time is None:
            self.start_time = current_time
            self.phase_start = current_time
            return (self.current_users, self.target_rate)

        elapsed = current_time - self.start_time

        if self.t0 is None:
            if elapsed >= 10:
                self.t0 = current_time
                self.phase = "scored"
                self.phase_start = current_time
                return (self.current_users, self.target_rate)
            else:
                return (self.current_users, self.target_rate)

        scored_elapsed = current_time - self.t0

        if scored_elapsed < 5:
            self.phase = "warmup"
            return (self.current_users, self.target_rate)
        elif scored_elapsed < 35:
            self.phase = "scored"
            return (self.current_users, self.target_rate)
        elif scored_elapsed < 40:
            self.phase = "drain"
            if self.drain_start is None:
                self.drain_start = current_time
            drain_elapsed = current_time - self.drain_start
            if drain_elapsed >= 5:
                return None
            return (0, 0)
        else:
            return None


