public class ModelSimulation extends Simulation {

    // Base URL from environment
    private static final String BASE_URL = System.getenv().getOrDefault("BASE_URL", "http://127.0.0.1:8000");

    // Test parameters
    private static final int TARGET_RATE = 10; // starts per second
    private static final int WARMUP_SECONDS = 5;
    private static final int SCORED_SECONDS = 30;
    private static final int DRAIN_SECONDS = 5;
    private static final int TOTAL_SECONDS = WARMUP_SECONDS + SCORED_SECONDS + DRAIN_SECONDS;

    // Work pool: POST /v2/work
    private static final int WORK_DELAY_MS = 500;

    // HTTP protocol
    private static final HttpProtocolBuilder httpProtocol = http
            .baseUrl(BASE_URL)
            .disableAutoRedirect()
            .acceptHeader("application/json")
            .contentTypeHeader("application/json")
            .userAgentHeader("gatling-bench")
            .shareConnections();

    // Feeder for users
    private static final Iterator<Map<String, Object>> userFeeder =
            IteratorUtils.toIterator(
                    java.util.stream.IntStream.rangeClosed(1, 16)
                            .mapToObj(i -> {
                                Map<String, Object> m = new HashMap<>();
                                m.put("username", "bench-" + i);
                                m.put("password", "bench");
                                return m;
                            })
                            .iterator()
            );

    // Scenario: work pool operation
    private static final ScenarioBuilder workScenario = scenario("WorkPoolScenario")
            .feed(userFeeder)
            .exec(session -> {
                // Fresh login
                return session;
            })
            .exec(
                    http("GetLoginForm")
                            .get("/v2/login-form")
                            .check(
                                    regex("name=\"csrf\" value=\"([^\"]+)\"")
                                            .saveAs("loginCsrf")
                            )
                            .check(
                                    css("input[name=csrf]", "value")
                                            .saveAs("loginCsrfAlt")
                            )
            )
            .exec(session -> {
                String csrf = session.contains("loginCsrf") ? session.getString("loginCsrf") : session.getString("loginCsrfAlt");
                return session.set("csrfToken", csrf);
            })
            .exec(
                    http("Login")
                            .post("/v2/login")
                            .header("X-CSRF-Token", session -> session.getString("csrfToken"))
                            .body(StringBody(session -> {
                                String csrf = session.getString("csrfToken");
                                String username = session.getString("username");
                                String password = session.getString("password");
                                return String.format("{\"username\":\"%s\",\"password\":\"%s\",\"csrf\":\"%s\"}", username, password, csrf);
                            }))
                            .check(
                                    jsonPath("$.csrf").optional().saveAs("sessionCsrf")
                            )
                            .check(
                                    status().is(200)
                            )
            )
            .exec(session -> {
                String csrf = session.contains("sessionCsrf") ? session.getString("sessionCsrf") : session.getString("csrfToken");
                return session.set("csrfToken", csrf);
            })
            // Work operation
            .exec(
                    http("WorkOperation")
                            .post("/v2/work")
                            .header("X-CSRF-Token", session -> session.getString("csrfToken"))
                            .body(StringBody("{}"))
                            .check(
                                    status().is(200)
                            )
                            .check(
                                    jsonPath("$.ok").is("true")
                            )
            );

    // Scenario with delay for work pool
    private static final ScenarioBuilder workScenarioWithDelay = scenario("WorkPoolScenarioWithDelay")
            .exec(workScenario)
            .pause(Duration.ofMillis(WORK_DELAY_MS));

    {
        setUp(
                workScenarioWithDelay.injectOpen(
                        constantUsersPerSec(TARGET_RATE).during(Duration.ofSeconds(TOTAL_SECONDS))
                )
        ).protocols(httpProtocol)
                .maxDuration(Duration.ofSeconds(TOTAL_SECONDS + 5));
    }
}
