function getCsrfFromForm(html) {
  const match = html.match(/name=["']csrf["'][^>]*value=["']([^"']+)["']/i) ||
                html.match(/value=["']([^"']+)["'][^>]*name=["']csrf["']/i) ||
                html.match(/name=["']csrf["']\s+value=["']([^"']+)["']/i) ||
                html.match(/value=["']([^"']+)["']\s+name=["']csrf["']/i);
  if (match) return match[1];
  const inputMatch = html.match(/<input[^>]*name=["']csrf["'][^>]*>/i);
  if (inputMatch) {
    const valMatch = inputMatch[0].match(/value=["']([^"']*)["']/i);
    if (valMatch) return valMatch[1];
  }
  return null;
}

function getNonceFromForm(html) {
  const match = html.match(/name=["']login_nonce["'][^>]*value=["']([^"']+)["']/i) ||
                html.match(/value=["']([^"']+)["'][^>]*name=["']login_nonce["']/i);
  return match ? match[1] : null;
}

function login(username, password) {
  const formRes = http.get(`${BASE_URL}/v2/login-form`, {
    redirects: 0,
    tags: { name: 'login_form' }
  });
  if (formRes.status !== 200) {
    return { success: false, error: `login form status ${formRes.status}` };
  }
  const csrf = getCsrfFromForm(formRes.body);
  const nonce = getNonceFromForm(formRes.body);
  if (!csrf) {
    return { success: false, error: 'no csrf in login form' };
  }
  const loginRes = http.post(`${BASE_URL}/v2/login`, JSON.stringify({
    username: username,
    password: password,
    csrf: csrf
  }), {
    headers: { 'Content-Type': 'application/json' },
    redirects: 0,
    tags: { name: 'login' }
  });
  if (loginRes.status === 302) {
    const location = loginRes.headers['Location'];
    if (location) {
      const followRes = http.get(location.startsWith('http') ? location : `${BASE_URL}${location}`, {
        redirects: 0,
        tags: { name: 'login_follow' }
      });
      if (followRes.status !== 200) {
        return { success: false, error: `login follow status ${followRes.status}` };
      }
      const followCsrf = getCsrfFromForm(followRes.body);
      if (followCsrf) {
        return { success: true, csrf: followCsrf, user: username };
      }
      try {
        const json = followRes.json();
        if (json.csrf) {
          return { success: true, csrf: json.csrf, user: json.user || username };
        }
      } catch (e) {
        // ignore
      }
      return { success: false, error: 'no csrf after login follow' };
    }
    return { success: false, error: 'no location after login 302' };
  }
  if (loginRes.status === 200) {
    try {
      const json = loginRes.json();
      if (json.csrf) {
        return { success: true, csrf: json.csrf, user: json.user || username };
      }
    } catch (e) {
      // ignore
    }
    const csrf2 = getCsrfFromForm(loginRes.body);
    if (csrf2) {
      return { success: true, csrf: csrf2, user: username };
    }
    return { success: false, error: 'no csrf in login response' };
  }
  return { success: false, error: `login status ${loginRes.status}` };
}

