}

function postChallenge(csrf, action) {
  const url = action.startsWith('http') ? action : `${BASE_URL}${action}`;
  const res = http.post(url, JSON.stringify({ challenge: 'accept' }), {
    headers: {
      'Content-Type': 'application/json',
      'X-CSRF-Token': csrf
    },
    redirects: 0,
    tags: { name: 'challenge_post' }
  });
  if (res.status === 302) {
    const location = res.headers['Location'];
    if (location) {
      const followRes = http.get(location.startsWith('http') ? location : `${BASE_URL}${location}`, {
        headers: { 'X-CSRF-Token': csrf },
        redirects: 0,
        tags: { name: 'challenge_follow' }
      });
      if (followRes.status === 200) {
        try {
          const json = followRes.json();
          return {
            success: true,
            grantId: json.grant_id || null,
            csrf: json.csrf || csrf
          };
        } catch (e) {
          return { success: false, status: followRes.status, error: 'invalid challenge json' };
        }
      }
      return { success: false, status: followRes.status };
    }
    return { success: false, status: res.status, error: 'no location after challenge' };
  }
  return { success: false, status: res.status };
}

function createReservation(csrf, cartId) {
  const res = http.post(`${BASE_URL}/v2/reservations`, JSON.stringify({ cart_id: cartId }), {
    headers: {
      'Content-Type': 'application/json',
      'X-CSRF-Token': csrf
    },
    redirects: 0,
    tags: { name: 'reservation_create' }
  });
  if (res.status === 202) {
    try {
      const json = res.json();
      return {
        success: true,
        statusUrl: json.status_url,
        csrf: json.csrf || csrf
      };
    } catch (e) {
      return { success: false, status: res.status, error: 'invalid reservation json' };
    }
  }
  return { success: false, status: res.status };
}

function pollReservation(csrf, statusUrl) {
  const url = statusUrl.startsWith('http') ? statusUrl : `${BASE_URL}${statusUrl}`;
  for (let i = 0; i < 5; i++) {
    sleep(0.05);
    const res = http.get(url, {
      headers: { 'X-CSRF-Token': csrf },
      redirects: 0,
      tags: { name: 'reservation_poll' }
    });
    if (res.status === 200) {
      try {
        const json = res.json();
        if (json.status === 'ready' && json.reservation_id) {
          return {
            success: true,
            reservationId: json.reservation_id,
            csrf: json.csrf || csrf
          };
        }
        if (json.status === 'failed') {
          return { success: false, status: 'failed' };
        }
        if (json.status === 'pending') {
          continue;
        }
      } catch (e) {
        return { success: false, status: res.status, error: 'invalid poll json' };
      }
    }
    if (res.status !== 200) {
      return { success: false, status: res.status };
    }
  }
  return { success: false, status: 'timeout' };
}

function doWork(csrf, profile) {
  const startTime = Date.now();
  const res = http.post(`${BASE_URL}/v2/work`, JSON.stringify({}), {
    headers: {
      'Content-Type': 'application/json',
      'X-CSRF-Token': csrf
    },
    redirects: 0,
    tags: { name: 'work' }
  });
  const latency = Date.now() - startTime;
  workLatency.add(latency);
  workRequests.add(1);
  businessFailures.add(res.status >= 400 ? 1 : 0);

  if (res.status === 200) {
    try {
      const json = res.json();
      if (json.ok === true) {
        workSuccess.add(1);
        return { success: true, csrf: json.csrf || csrf, status: res.status };
      }
    } catch (e) {
      // ignore
    }
    workSuccess.add(1);
    return { success: true, csrf: csrf, status: res.status };
  }
  if (res.status === 429) {
    const retryAfter = parseInt(res.headers['Retry-After'] || '1', 10);
    return { success: false, status: 429, retryAfter: retryAfter || RETRY_AFTER, retryable: true };
  }
  if (res.status === 401) {
    try {
      const json = res.json();
      if (json.error === 'expired') {
        return { success: false, status: 401, errorType: 'expired', retryable: true };
      }
      if (json.error === 'session') {
        return { success: false, status: 401, errorType: 'session', retryable: true };
      }
      if (json.error === 'denied') {
        return { success: false, status: 401, errorType: 'denied', retryable: false };
      }
    } catch (e) {
      // ignore
    }
    return { success: false, status: 401, errorType: 'unknown', retryable: true };
  }
  workErrors.add(1);
  return { success: false, status: res.status, retryable: false };
}

function doWorkWithRetry(csrf, profile) {
  let currentCsrf = csrf;
  let retries = 0;
  let lastResult = null;

  while (retries <= MAX_RETRIES) {
    const result = doWork(currentCsrf, profile);
    lastResult = result;

    if (result.success) {
      return { success: true, csrf: result.csrf, status: result.status };
    }

    if (result.status === 429 && result.retryable) {
      retryCount.add(1);
      retries++;
      sleep(result.retryAfter || RETRY_AFTER);
      continue;
    }

    if (result.status === 401 && result.errorType === 'expired') {
      const renewResult = renewSession(currentCsrf);
      if (renewResult.success) {
        currentCsrf = renewResult.csrf;
        retryCount.add(1);
        retries++;
        continue;
      }
      // Renew failed, try fresh login
      const username = getRandomUser();
      const loginResult = login(username, 'bench');
      if (loginResult.success) {
        currentCsrf = loginResult.csrf;
        retryCount.add(1);
        retries++;
        continue;
      }
      workErrors.add(1);
      return { success: false, status: result.status, error: 'renew failed' };
    }

    if (result.status === 401 && result.errorType === 'session') {
      const username = getRandomUser();
      const loginResult = login(username, 'bench');
      if (loginResult.success) {
        currentCsrf = loginResult.csrf;
        retryCount.add(1);
        retries++;
        continue;
      }
      workErrors.add(1);
      return { success: false, status: result.status, error: 'session recovery failed' };
    }

    if (result.status === 401 && result.errorType === 'denied') {
      workErrors.add(1);
      return { success: false, status: result.status, error: 'denied' };
    }

    // Other errors (500, etc.)
    workErrors.add(1);
    return { success: false, status: result.status, error: 'unexpected error' };
  }

  workDropped.add(1);
  return { success: false, status: lastResult ? lastResult.status : 429, error: 'max retries exceeded' };
}

function performCheckoutJourney(csrf, profile) {
  // Fresh cart for each journey
  const reverse = profile.reverse_catalog || false;
  const htmlLayout = profile.html_layout || 0;

  // Get catalog
  const catalogResult = getCatalog(csrf, reverse);
  if (!catalogResult.success || catalogResult.products.length === 0) {
    return { success: false, csrf: csrf, error: 'catalog failed' };
  }

  let product = null;
  let variant = null;
  let grantId = null;

  // Try to find a product with in-stock variant
  for (const p of catalogResult.products) {
    if (p.variants && p.variants.length > 0) {
      for (const v of p.variants) {
        if (v.in_stock) {
          product = p;
          variant = v;
          break;
        }
      }
      if (product) break;
    }
  }

  // If no in-stock variant, try catalog pages
  if (!product && catalogResult.next) {
    let nextUrl = catalogResult.next;
    for (let i = 0; i < 3 && !product; i++) {
      const pageResult = getCatalogPage(csrf, nextUrl, reverse);
      if (!pageResult.success || !pageResult.product) break;
      const p = pageResult.product;
      if (p.variants && p.variants.length > 0) {
        for (const v of p.variants) {
          if (v.in_stock) {
            product = p;
            variant = v;
            break;
          }
        }
      }
      if (!product && pageResult.next) {
        nextUrl = pageResult.next;
      } else {
        break;
      }
    }
  }

  if (!product || !variant) {
    return { success: false, csrf: csrf, error: 'no in-stock product' };
  }

  // Try challenge for grant_id
  const challengeForm = getChallengeForm(csrf);
  if (challengeForm.success) {
    const challengeResult = postChallenge(csrf, challengeForm.action);
    if (challengeResult.success && challengeResult.grantId) {
      grantId = challengeResult.grantId;
      csrf = challengeResult.csrf;
    }
  }

  // Create cart
  const cartResult = createCart(csrf, product.id, variant.id, grantId);
  if (!cartResult.success) {
    return { success: false, csrf: csrf, error: 'cart create failed' };
  }
  let currentCsrf = cartResult.csrf;
  const cartId = cartResult.cartId;
  let etag = cartResult.etag;

  // Get cart to get fresh etag
  const getCartResult = getCart(currentCsrf, cartId);
  if (getCartResult.success) {
    etag = getCartResult.etag || etag;
  }

  // Patch cart with quantity
  const quantity = Math.floor(Math.random() * 20) + 1;
  let patchResult = patchCart(currentCsrf, cartId, quantity, etag);
  if (!patchResult.success && patchResult.status === 412) {
    // Re-read and retry once
    const reReadResult = getCart(currentCsrf, cartId);
    if (reReadResult.success) {
      etag = reReadResult.etag;
      patchResult = patchCart(currentCsrf, cartId, quantity, etag);
    }
  }
  if (patchResult.success) {
    currentCsrf = patchResult.csrf;
    etag = patchResult.etag;
  } else if (patchResult.status === 401) {
    // Handle 401 on patch
    const renewResult = renewSession(currentCsrf);
    if (renewResult.success) {
      currentCsrf = renewResult.csrf;
      const recoverResult = recoverCart(cartId, currentCsrf);
      if (recoverResult.success) {
        currentCsrf = recoverResult.csrf;
        const reReadResult = getCart(currentCsrf, cartId);
        if (reReadResult.success) {
          etag = reReadResult.etag;
          patchResult = patchCart(currentCsrf, cartId, quantity, etag);
          if (patchResult.success) {
            currentCsrf = patchResult.csrf;
            etag = patchResult.etag;
          }
        }
      }
    }
  }

  // Create reservation
  let reservationId = null;
  const reservationResult = createReservation(currentCsrf, cartId);
  if (reservationResult.success) {
    currentCsrf = reservationResult.csrf;
    const pollResult = pollReservation(currentCsrf, reservationResult.statusUrl);
    if (pollResult.success) {
      reservationId = pollResult.reservationId;
      currentCsrf = pollResult.csrf;
    }
  }

  // Create order
  const idempotencyKey = `order-${cartId}-${Date.now()}-${Math.random().toString(36).substr(2, 9)}`;
  const orderResult = createOrder(currentCsrf, cartId, reservationId, idempotencyKey, etag);
  if (orderResult.success && orderResult.accepted) {
    checkoutStarts.add(1);
    currentCsrf = orderResult.csrf;
    return { success: true, csrf: currentCsrf, orderId: orderResult.orderId };
  }
  if (orderResult.status === 401) {
    // Handle 401 on order
    const renewResult = renewSession(currentCsrf);
    if (renewResult.success) {
      currentCsrf = renewResult.csrf;
      const recoverResult = recoverCart(cartId, currentCsrf);
      if (recoverResult.success) {
        currentCsrf = recoverResult.csrf;
        const reReadResult = getCart(currentCsrf, cartId);
        if (reReadResult.success) {
          etag = reReadResult.etag;
          const retryOrder = createOrder(currentCsrf, cartId, reservationId, idempotencyKey, etag);
          if (retryOrder.success && retryOrder.accepted) {
            checkoutStarts.add(1);
            currentCsrf = retryOrder.csrf;
            return { success: true, csrf: currentCsrf, orderId: retryOrder.orderId };
          }
        }
      }
    }
  }

  return { success: false, csrf: currentCsrf, error: 'order failed' };
}

export const options = {
  scenarios: {
    main: {
      executor: 'shared-iterations',
      vus: USERS,
      iterations: ITERATIONS,
      maxDuration: '60s',
      gracefulStop: '5s',
    }
  },
  thresholds: {}
};

export function setup() {
  // Pre-login all users to warm up sessions
  const sessions = {};
  for (const username of users) {
    const result = login(username, 'bench');
    if (result.success) {
      sessions[username] = { csrf: result.csrf, user: result.user };
    }
  }
  return { sessions: sessions };
}

export default function(data) {
  const sessions = data.sessions || {};
  const username = getRandomUser();
  const profile = getRandomProfile();

  let session = sessions[username];
  if (!session) {
    const loginResult = login(username, 'bench');
    if (!loginResult.success) {
      return;
    }
    session = { csrf: loginResult.csrf, user: loginResult.user };
    sessions[username] = session;
  }

  let csrf = session.csrf;

  // Perform checkout journey (this is the "journey" that counts checkout starts)
  const journeyResult = performCheckoutJourney(csrf, profile);
  if (journeyResult.success) {
    csrf = journeyResult.csrf;
    session.csrf = csrf;
  } else {
    csrf = journeyResult.csrf;
    session.csrf = csrf;
  }

  // Perform work operation (this is the declared pool operation)
  const workResult = doWorkWithRetry(csrf, profile);
  if (workResult.success) {
    csrf = workResult.csrf;
    session.csrf = csrf;
    operationStarts.add(1);
    operationSuccess.add(1);
  } else {
    operationStarts.add(1);
    operationErrors.add(1);
  }

  // Simulate work delay
  sleep(profile.delay_seconds || 0.5);
}

export function teardown(data) {
  // Record owner seeds
  const seeds = {};
  for (const username of users) {
    const session = data.sessions && data.sessions[username];
    if (session) {
      seeds[username] = session.csrf;
    }
  }
  console.log('OWNER_SEEDS:' + JSON.stringify(seeds));
}
