import http from 'k6/http';
import { check, sleep } from 'k6';
import { Counter, Rate, Trend } from 'k6/metrics';
import { URL } from 'https://jslib.k6.io/url/1.0.0/index.js';

const BASE_URL = __ENV.BASE_URL || 'http://127.0.0.1:8000';

const workSuccess = new Counter('work_success');
const workError = new Counter('work_error');
const workDropped = new Counter('work_dropped');
const businessFailure = new Rate('business_failure');
const workLatency = new Trend('work_latency', true);

const PROFILES = [
  {},
  { html_layout: 1, reverse_catalog: true }
];

const USERS = ['bench-1', 'bench-2', 'bench-3', 'bench-4', 'bench-5', 'bench-6', 'bench-7', 'bench-8',
  'bench-9', 'bench-10', 'bench-11', 'bench-12', 'bench-13', 'bench-14', 'bench-15', 'bench-16'];

function getProfile(vuId) {
  return PROFILES[vuId % PROFILES.length];
}

function login(username, password) {
  const formRes = http.get(`${BASE_URL}/v2/login-form`, { redirects: 0 });
  if (formRes.status !== 200) {
    return null;
  }
  const csrfMatch = formRes.body.match(/name="csrf"[^>]*value="([^"]+)"/);
  if (!csrfMatch) {
    return null;
  }
  const csrf = csrfMatch[1];
  const loginRes = http.post(`${BASE_URL}/v2/login`, JSON.stringify({
    username: username,
    password: password,
    csrf: csrf
  }), {
    headers: { 'Content-Type': 'application/json' },
    redirects: 0
  });
  if (loginRes.status === 302) {
    const location = loginRes.headers['Location'];
    if (location) {
      const followRes = http.get(location.startsWith('http') ? location : `${BASE_URL}${location}`, { redirects: 0 });
      if (followRes.status !== 200) {
        return null;
      }
      try {
        const body = JSON.parse(followRes.body);
        return { csrf: body.csrf, user: body.user };
      } catch (e) {
        return null;
      }
    }
    return null;
  }
  if (loginRes.status !== 200) {
    return null;
  }
  try {
    const body = JSON.parse(loginRes.body);
    return { csrf: body.csrf, user: body.user };
  } catch (e) {
    return null;
  }
}

function renewSession(csrf) {
  const res = http.post(`${BASE_URL}/v2/session/renew`, JSON.stringify({}), {
    headers: {
      'Content-Type': 'application/json',
      'X-CSRF-Token': csrf
    },
    redirects: 0
  });
  if (res.status === 200) {
    try {
      const body = JSON.parse(res.body);
      return body.csrf || csrf;
    } catch (e) {
      return csrf;
    }
  }
  return null;
}

function recoverCart(cartId, csrf) {
  const res = http.post(`${BASE_URL}/v2/carts/${cartId}/recover`, JSON.stringify({}), {
    headers: {
      'Content-Type': 'application/json',
      'X-CSRF-Token': csrf
    },
    redirects: 0
  });
  return res.status < 400;
}

function getCatalog(profile) {
  const res = http.get(`${BASE_URL}/v2/catalog`, { redirects: 0 });
  if (res.status !== 200) {
    return null;
  }
  try {
    const body = JSON.parse(res.body);
    if (body.data && body.data.products && body.data.products.length > 0) {
      return body.data.products;
    }
  } catch (e) {
    return null;
  }
  return null;
}

function getCatalogPage(profile, pageUrl) {
  const url = pageUrl.startsWith('http') ? pageUrl : `${BASE_URL}${pageUrl}`;
  const res = http.get(url, { redirects: 0 });
  if (res.status !== 200) {
    return null;
  }
  try {
    const body = JSON.parse(res.body);
    return body;
  } catch (e) {
    return null;
  }
}

function createCart(productId, variantId, grantId, csrf) {
  const payload = {
    product_id: productId,
    variant_id: variantId
  };
  if (grantId) {
    payload.grant_id = grantId;
  }
  const res = http.post(`${BASE_URL}/v2/carts`, JSON.stringify(payload), {
    headers: {
      'Content-Type': 'application/json',
      'X-CSRF-Token': csrf
    },
    redirects: 0
  });
  if (res.status === 201) {
    try {
      const body = JSON.parse(res.body);
      return {
        id: body.id,
        csrf: body.csrf || csrf,
        etag: res.headers['ETag'] || res.headers['Etag'] || null
      };
    } catch (e) {
      return null;
    }
  }
  return null;
}

function getCart(cartId, csrf) {
  const res = http.get(`${BASE_URL}/v2/carts/${cartId}`, {
    headers: { 'X-CSRF-Token': csrf },
    redirects: 0
  });
  if (res.status === 200) {
    return {
      etag: res.headers['ETag'] || res.headers['Etag'] || null,
      body: res.body
    };
  }
  return null;
}

function patchCart(cartId, quantity, etag, csrf) {
  const res = http.patch(`${BASE_URL}/v2/carts/${cartId}`, JSON.stringify({ quantity: quantity }), {
    headers: {
      'Content-Type': 'application/json',
      'X-CSRF-Token': csrf,
      'If-Match': etag
    },
    redirects: 0
  });
  return res;
}

function getChallengeForm(csrf) {
  const res = http.get(`${BASE_URL}/v2/challenge-form`, {
    headers: { 'X-CSRF-Token': csrf },
    redirects: 0
  });
  if (res.status !== 200) {
    return null;
  }
  const actionMatch = res.body.match(/action="([^"]+)"/);
  const challengeMatch = res.body.match(/name="challenge"[^>]*value="([^"]+)"/);
  if (!actionMatch || !challengeMatch) {
    return null;
  }
  return {
    action: actionMatch[1],
    challenge: challengeMatch[1]
  };
}

function postChallenge(action, challenge, csrf) {
  const url = action.startsWith('http') ? action : `${BASE_URL}${action}`;
  const res = http.post(url, JSON.stringify({ challenge: challenge }), {
    headers: {
      'Content-Type': 'application/json',
      'X-CSRF-Token': csrf
    },
    redirects: 0
  });
  if (res.status === 302) {
    const location = res.headers['Location'];
    if (location) {
      const followRes = http.get(location.startsWith('http') ? location : `${BASE_URL}${location}`, {
        headers: { 'X-CSRF-Token': csrf },
        redirects: 0
      });
      if (followRes.status === 200) {
        try {
          const body = JSON.parse(followRes.body);
          return {
            grant_id: body.grant_id,
            csrf: body.csrf || csrf
          };
        } catch (e) {
          return null;
        }
      }
    }
  }
  return null;
}

function createReservation(cartId, csrf) {
  const res = http.post(`${BASE_URL}/v2/reservations`, JSON.stringify({ cart_id: cartId }), {
    headers: {
      'Content-Type': 'application/json',
      'X-CSRF-Token': csrf
    },
    redirects: 0
  });
  if (res.status === 202) {
    try {
      const body = JSON.parse(res.body);
      return {
        status_url: body.status_url,
        csrf: body.csrf || csrf
      };
    } catch (e) {
      return null;
    }
  }
  return null;
}

function pollReservation(statusUrl, csrf) {
  const url = statusUrl.startsWith('http') ? statusUrl : `${BASE_URL}${statusUrl}`;
  for (let i = 0; i < 5; i++) {
    sleep(0.05);
    const res = http.get(url, {
      headers: { 'X-CSRF-Token': csrf },
      redirects: 0
    });
    if (res.status === 200) {
      try {
        const body = JSON.parse(res.body);
        if (body.status === 'ready') {
          return {
            reservation_id: body.reservation_id,
            csrf: body.csrf || csrf
          };
        }
        if (body.status === 'failed') {
          return null;
        }
      } catch (e) {
        return null;
      }
    }
  }
  return null;
}

function createOrder(cartId, reservationId, idempotencyKey, etag, csrf) {
  const payload = {
    cart_id: cartId
  };
  if (reservationId) {
    payload.reservation_id = reservationId;
  }
  const headers = {
    'Content-Type': 'application/json',
    'X-CSRF-Token': csrf,
    'Idempotency-Key': idempotencyKey
  };
  if (etag) {
    headers['If-Match'] = etag;
  }
  const res = http.post(`${BASE_URL}/v2/orders`, JSON.stringify(payload), {
    headers: headers,
    redirects: 0
  });
  return res;
}

function doWork(csrf) {
  const startTime = Date.now();
  let attempts = 0;
  let res;
  while (attempts < 5) {
    res = http.post(`${BASE_URL}/v2/work`, JSON.stringify({}), {
      headers: {
        'Content-Type': 'application/json',
        'X-CSRF-Token': csrf
      },
      redirects: 0
    });
    attempts++;
    if (res.status === 429) {
      const retryAfter = parseInt(res.headers['Retry-After'] || '1', 10);
      sleep(Math.max(1, retryAfter));
      continue;
    }
    break;
  }
  const latency = Date.now() - startTime;
  workLatency.add(latency);
  if (res.status === 200) {
    try {
      const body = JSON.parse(res.body);
      if (body.ok === true) {
        workSuccess.add(1);
        return { success: true, csrf: body.csrf || csrf };
      }
    } catch (e) {
      // fall through
    }
    workError.add(1);
    businessFailure.add(1);
    return { success: false, csrf: csrf };
  } else if (res.status === 429) {
    workDropped.add(1);
    businessFailure.add(0);
    return { success: false, csrf: csrf, scheduled429: true };
  } else if (res.status === 401) {
    workError.add(1);
    businessFailure.add(1);
    return { success: false, csrf: csrf, expired: true };
  } else {
    workError.add(1);
    businessFailure.add(1);
    return { success: false, csrf: csrf };
  }
}

function fullJourney(vuId, iterationId) {
  const username = USERS[vuId % USERS.length];
  const profile = getProfile(vuId);

  // Fresh login
  let session = login(username, 'bench');
  if (!session) {
    return;
  }
  let csrf = session.csrf;

  // Get catalog
  let products = getCatalog(profile);
  if (!products || products.length === 0) {
    return;
  }

  // Pick first product with in-stock variant
  let selectedProduct = null;
  let selectedVariant = null;
  for (const product of products) {
    if (product.variants && product.variants.length > 0) {
      for (const variant of product.variants) {
        if (variant.in_stock) {
          selectedProduct = product;
          selectedVariant = variant;
          break;
        }
      }
      if (selectedProduct) break;
    }
  }
  if (!selectedProduct || !selectedVariant) {
    return;
  }

  // Optional: traverse catalog pages (at most 3)
  if (profile.reverse_catalog) {
    let pageUrl = '/v2/catalog/page';
    for (let i = 0; i < 3; i++) {
      const pageData = getCatalogPage(profile, pageUrl);
      if (!pageData || !pageData.next) break;
      pageUrl = pageData.next;
    }
  }

  // Optional: challenge for grant_id
  let grantId = null;
  if (profile.html_layout === 1) {
    const challengeForm = getChallengeForm(csrf);
    if (challengeForm) {
      const challengeResult = postChallenge(challengeForm.action, challengeForm.challenge, csrf);
      if (challengeResult) {
        grantId = challengeResult.grant_id;
        csrf = challengeResult.csrf;
      }
    }
  }

  // Create cart
  const cart = createCart(selectedProduct.id, selectedVariant.id, grantId, csrf);
  if (!cart) {
    return;
  }
  csrf = cart.csrf;
  let cartId = cart.id;
  let etag = cart.etag;

  // Patch cart quantity
  const quantity = 1 + (iterationId % 20);
  let patchRes = patchCart(cartId, quantity, etag, csrf);
  if (patchRes.status === 412) {
    // Re-read and retry once
    const cartData = getCart(cartId, csrf);
    if (cartData && cartData.etag) {
      etag = cartData.etag;
      patchRes = patchCart(cartId, quantity, etag, csrf);
    }
  }
  if (patchRes.status === 200) {
    try {
      const body = JSON.parse(patchRes.body);
      csrf = body.csrf || csrf;
      etag = patchRes.headers['ETag'] || patchRes.headers['Etag'] || etag;
    } catch (e) {
      // ignore
    }
  }

  // Create reservation
  let reservationId = null;
  const reservation = createReservation(cartId, csrf);
  if (reservation) {
    csrf = reservation.csrf;
    const pollResult = pollReservation(reservation.status_url, csrf);
    if (pollResult) {
      reservationId = pollResult.reservation_id;
      csrf = pollResult.csrf;
    }
  }

  // Create order
  const idempotencyKey = `order-${vuId}-${iterationId}-${Date.now()}`;
  const orderRes = createOrder(cartId, reservationId, idempotencyKey, etag, csrf);
  if (orderRes.status === 201) {
    try {
      const body = JSON.parse(orderRes.body);
      if (body.accepted === true) {
        csrf = body.csrf || csrf;
        // Success - now do work
        const workResult = doWork(csrf);
        if (workResult.success) {
          csrf = workResult.csrf;
        } else if (workResult.expired) {
          // Try renewal
          const newCsrf = renewSession(csrf);
          if (newCsrf) {
            csrf = newCsrf;
            // Recover cart and retry work once
            recoverCart(cartId, csrf);
            const retryWork = doWork(csrf);
            if (retryWork.success) {
              csrf = retryWork.csrf;
            }
          }
        }
      }
    } catch (e) {
      // ignore
    }
  } else if (orderRes.status === 401) {
    // Handle expiry
    try {
      const body = JSON.parse(orderRes.body);
      if (body.error === 'expired') {
        const newCsrf = renewSession(csrf);
        if (newCsrf) {
          csrf = newCsrf;
          recoverCart(cartId, csrf);
          // Retry order once
          const retryOrder = createOrder(cartId, reservationId, idempotencyKey, etag, csrf);
          if (retryOrder.status === 201) {
            try {
              const retryBody = JSON.parse(retryOrder.body);
              if (retryBody.accepted === true) {
                csrf = retryBody.csrf || csrf;
                const workResult = doWork(csrf);
                if (workResult.success) {
                  csrf = workResult.csrf;
                }
              }
            } catch (e) {
              // ignore
            }
          }
        }
      }
    } catch (e) {
      // ignore
    }
  }
}

