import os
import time
import random
from locust import HttpUser, task, between, LoadTestShape, events
from locust.exception import StopUser

BASE_URL = os.environ.get("BASE_URL", "http://127.0.0.1:8000")

ACCOUNTS = [f"bench-{i}" for i in range(1, 17)] + ["bench"]
PASSWORD = "bench"

class ShopUser(HttpUser):
    wait_time = between(0.05, 0.15)

    def __init__(self, *args, **kwargs):
        super().__init__(*args, **kwargs)
        self.csrf_token = None
        self.session_cookie = None
        self.cart_id = None
        self.cart_etag = None
        self.grant_id = None
        self.reservation_id = None
        self.idempotency_key = None
        self.work_retries = 0
        self.authenticated = False
        self.owner_seed = None

    def on_start(self):
        self.owner_seed = random.choice(ACCOUNTS)
        self.login()

    def login(self):
        # GET login form
        with self.client.get("/v2/login-form", catch_response=True) as resp:
            if resp.status_code != 200:
                resp.failure(f"Login form failed: {resp.status_code}")
                return False
            # Extract CSRF from input[name=csrf]
            import re
            match = re.search(r'name="csrf"[^>]*value="([^"]+)"', resp.text)
            if not match:
                match = re.search(r'name=[\'"]csrf[\'"][^>]*value=[\'"]([^\'"]+)[\'"]', resp.text)
            if not match:
                resp.failure("No CSRF token in login form")
                return False
            self.csrf_token = match.group(1)

        # POST login
        with self.client.post("/v2/login", 
                             json={"username": self.owner_seed, "password": PASSWORD, "csrf": self.csrf_token},
                             headers={"X-CSRF-Token": self.csrf_token},
                             catch_response=True) as resp:
            if resp.status_code == 302:
                location = resp.headers.get("Location")
                if location:
                    with self.client.get(location, catch_response=True) as resp2:
                        if resp2.status_code != 200:
                            resp2.failure(f"Login redirect failed: {resp2.status_code}")
                            return False
                        resp = resp2
                else:
                    resp.failure("302 without Location")
                    return False
            if resp.status_code != 200:
                resp.failure(f"Login failed: {resp.status_code}")
                return False
            data = resp.json()
            if "csrf" in data:
                self.csrf_token = data["csrf"]
            self.authenticated = True
            return True

    def renew_session(self):
        with self.client.post("/v2/session/renew", 
                             json={},
                             headers={"X-CSRF-Token": self.csrf_token},
                             catch_response=True) as resp:
            if resp.status_code == 200:
                data = resp.json()
                if "csrf" in data:
                    self.csrf_token = data["csrf"]
                return True
            return False

    def recover_cart(self):
        if self.cart_id:
            with self.client.post(f"/v2/carts/{self.cart_id}/recover",
                                 json={},
                                 headers={"X-CSRF-Token": self.csrf_token},
                                 catch_response=True) as resp:
                if resp.status_code == 200:
                    data = resp.json()
                    if "csrf" in data:
                        self.csrf_token = data["csrf"]
                    return True
        return False

    def handle_401(self, resp, operation_retry_func):
        """Handle 401 errors. Returns True if operation should be retried."""
        error_type = None
        try:
            data = resp.json()
            error_type = data.get("error")
        except:
            pass

        if error_type == "expired":
            if self.renew_session():
                if self.cart_id:
                    self.recover_cart()
                return True
            return False
        elif error_type == "session":
            # Session revoked, need fresh login
            if self.login():
                if self.cart_id:
                    self.recover_cart()
                return True
            return False
        elif error_type == "denied":
            # Not expiry, fail assertion
            resp.failure("401 denied error")
            return False
        return False

    def create_cart(self):
        # Get catalog
        with self.client.get("/v2/catalog", catch_response=True) as resp:
            if resp.status_code != 200:
                resp.failure(f"Catalog failed: {resp.status_code}")
                return False
            data = resp.json()
            products = data.get("data", {}).get("products", [])
            if not products:
                resp.failure("No products in catalog")
                return False
            product = products[0]
            variants = product.get("variants", [])
            if not variants:
                resp.failure("No variants for product")
                return False
            variant = variants[0]
            product_id = product["id"]
            variant_id = variant["id"]

        # Create cart
        payload = {"product_id": product_id, "variant_id": variant_id}
        if self.grant_id:
            payload["grant_id"] = self.grant_id

        with self.client.post("/v2/carts",
                             json=payload,
                             headers={"X-CSRF-Token": self.csrf_token},
                             catch_response=True) as resp:
            if resp.status_code == 401:
                if self.handle_401(resp, self.create_cart):
                    return self.create_cart()
                return False
            if resp.status_code != 201:
                resp.failure(f"Cart creation failed: {resp.status_code}")
                return False
            data = resp.json()
            self.cart_id = data.get("id")
            if "csrf" in data:
                self.csrf_token = data["csrf"]
            self.cart_etag = resp.headers.get("ETag")
            return True

    def get_challenge(self):
        with self.client.get("/v2/challenge-form", catch_response=True) as resp:
            if resp.status_code != 200:
                resp.failure(f"Challenge form failed: {resp.status_code}")
                return False
            import re
            match = re.search(r'action="([^"]*challenges/[^"]*)"', resp.text)
            if not match:
                match = re.search(r'action=[\'"]([^\'"]*challenges/[^\'"]*)[\'"]', resp.text)
            if not match:
                resp.failure("No challenge action found")
                return False
            action = match.group(1)
            challenge_match = re.search(r'name="challenge"[^>]*value="([^"]+)"', resp.text)
            if not challenge_match:
                challenge_match = re.search(r'name=[\'"]challenge[\'"][^>]*value=[\'"]([^\'"]+)[\'"]', resp.text)
            if not challenge_match:
                resp.failure("No challenge value found")
                return False
            challenge_value = challenge_match.group(1)

        # POST challenge
        if action.startswith("/"):
            url = action
        else:
            url = "/" + action

        with self.client.post(url,
                             json={"challenge": challenge_value},
                             headers={"X-CSRF-Token": self.csrf_token},
                             catch_response=True) as resp:
            if resp.status_code == 302:
                location = resp.headers.get("Location")
                if location:
                    with self.client.get(location, catch_response=True) as resp2:
                        if resp2.status_code != 200:
                            resp2.failure(f"Challenge redirect failed: {resp2.status_code}")
                            return False
                        data = resp2.json()
                        if "grant_id" in data:
                            self.grant_id = data["grant_id"]
                        if "csrf" in data:
                            self.csrf_token = data["csrf"]
                        return True
                else:
                    resp.failure("Challenge 302 without Location")
                    return False
            elif resp.status_code == 200:
                data = resp.json()
                if "grant_id" in data:
                    self.grant_id = data["grant_id"]
                if "csrf" in data:
                    self.csrf_token = data["csrf"]
                return True
            else:
                resp.failure(f"Challenge POST failed: {resp.status_code}")
                return False

    def create_reservation(self):
        if not self.cart_id:
            return False

        with self.client.post("/v2/reservations",
                             json={"cart_id": self.cart_id},
                             headers={"X-CSRF-Token": self.csrf_token},
                             catch_response=True) as resp:
            if resp.status_code == 401:
                if self.handle_401(resp, self.create_reservation):
                    return self.create_reservation()
                return False
            if resp.status_code != 202:
                resp.failure(f"Reservation failed: {resp.status_code}")
                return False
            data = resp.json()
            status_url = data.get("status_url")
            if "csrf" in data:
                self.csrf_token = data["csrf"]

        # Poll status
        for i in range(5):
            time.sleep(0.05)
            with self.client.get(status_url, catch_response=True) as resp:
                if resp.status_code == 401:
                    if self.handle_401(resp, self.create_reservation):
                        return self.create_reservation()
                    return False
                if resp.status_code != 200:
                    resp.failure(f"Reservation status failed: {resp.status_code}")
                    return False
                data = resp.json()
                if "csrf" in data:
                    self.csrf_token = data["csrf"]
                status = data.get("status")
                if status == "ready":
                    self.reservation_id = data.get("reservation_id")
                    return True
                elif status == "failed":
                    return False
                # pending, continue polling

        return False

    def checkout(self):
        if not self.cart_id:
            return False

        # Get cart to get ETag
        with self.client.get(f"/v2/carts/{self.cart_id}", catch_response=True) as resp:
            if resp.status_code == 401:
                if self.handle_401(resp, self.checkout):
                    return self.checkout()
                return False
            if resp.status_code != 200:
                resp.failure(f"Get cart failed: {resp.status_code}")
                return False
            self.cart_etag = resp.headers.get("ETag")
            data = resp.json()
            if "csrf" in data:
                self.csrf_token = data["csrf"]

        # Update quantity
        payload = {"quantity": random.randint(1, 20)}
        headers = {"X-CSRF-Token": self.csrf_token}
        if self.cart_etag:
            headers["If-Match"] = self.cart_etag

        with self.client.patch(f"/v2/carts/{self.cart_id}",
                              json=payload,
                              headers=headers,
                              catch_response=True) as resp:
            if resp.status_code == 401:
                if self.handle_401(resp, self.checkout):
                    return self.checkout()
                return False
            if resp.status_code == 412:
                # Re-read and retry once
                with self.client.get(f"/v2/carts/{self.cart_id}", catch_response=True) as resp2:
                    if resp2.status_code == 200:
                        self.cart_etag = resp2.headers.get("ETag")
                        data = resp2.json()
                        if "csrf" in data:
                            self.csrf_token = data["csrf"]
                        headers = {"X-CSRF-Token": self.csrf_token}
                        if self.cart_etag:
                            headers["If-Match"] = self.cart_etag
                        with self.client.patch(f"/v2/carts/{self.cart_id}",
                                              json=payload,
                                              headers=headers,
                                              catch_response=True) as resp3:
                            if resp3.status_code == 401:
                                if self.handle_401(resp3, self.checkout):
                                    return self.checkout()
                                return False
                            if resp3.status_code != 200:
                                resp3.failure(f"Cart update retry failed: {resp3.status_code}")
                                return False
                            data = resp3.json()
                            if "csrf" in data:
                                self.csrf_token = data["csrf"]
                    else:
                        resp2.failure(f"Cart re-read failed: {resp2.status_code}")
                        return False
            elif resp.status_code != 200:
                resp.failure(f"Cart update failed: {resp.status_code}")
                return False
            else:
                data = resp.json()
                if "csrf" in data:
                    self.csrf_token = data["csrf"]

        # Create order
        if not self.idempotency_key:
            self.idempotency_key = f"order-{self.cart_id}-{int(time.time()*1000)}"

        order_payload = {"cart_id": self.cart_id}
        if self.reservation_id:
            order_payload["reservation_id"] = self.reservation_id

        order_headers = {
            "X-CSRF-Token": self.csrf_token,
            "Idempotency-Key": self.idempotency_key
        }
        if self.cart_etag:
            order_headers["If-Match"] = self.cart_etag

        with self.client.post("/v2/orders",
                             json=order_payload,
                             headers=order_headers,
                             catch_response=True) as resp:
            if resp.status_code == 401:
                if self.handle_401(resp, self.checkout):
                    return self.checkout()
                return False
            if resp.status_code == 201:
                data = resp.json()
                if data.get("accepted") == True:
                    if "csrf" in data:
                        self.csrf_token = data["csrf"]
                    return True
                else:
                    resp.failure("Order not accepted")
                    return False
            elif resp.status_code == 200:
                data = resp.json()
                if data.get("accepted") == False:
                    resp.failure("Business failure: accepted=false")
                    return False
                else:
                    if "csrf" in data:
                        self.csrf_token = data["csrf"]
                    return True
            else:
                resp.failure(f"Order failed: {resp.status_code}")
                return False

    def do_work(self):
        """Perform the /v2/work operation. Returns True if successful."""
        with self.client.post("/v2/work",
                             json={},
                             headers={"X-CSRF-Token": self.csrf_token},
                             catch_response=True) as resp:
            if resp.status_code == 401:
                if self.handle_401(resp, self.do_work):
                    return self.do_work()
                return False
            if resp.status_code == 429:
                # Scheduled 429, retry after 1s
                retry_after = resp.headers.get("Retry-After", "1")
                try:
                    wait_time = float(retry_after)
                except:
                    wait_time = 1.0
                if self.work_retries < 4:
                    self.work_retries += 1
                    time.sleep(wait_time)
                    return self.do_work()
                else:
                    resp.failure("Work 429 retries exhausted")
                    return False
            if resp.status_code == 200:
                data = resp.json()
                if data.get("ok") == True:
                    if "csrf" in data:
                        self.csrf_token = data["csrf"]
                    self.work_retries = 0
                    return True
                else:
                    resp.failure("Work not ok")
                    return False
            if resp.status_code == 500:
                resp.failure("Work 500 error")
                return False
            resp.failure(f"Work failed: {resp.status_code}")
            return False

    @task
    def work_task(self):
        if not self.authenticated:
            self.login()
            if not self.authenticated:
                return

        # Fresh journey: login and cart
        self.login()
        if not self.authenticated:
            return

        # Reset journey state
        self.cart_id = None
        self.cart_etag = None
        self.grant_id = None
        self.reservation_id = None
        self.idempotency_key = None
        self.work_retries = 0

        # Create cart
        if not self.create_cart():
            return

        # Optionally get challenge (some profiles need it)
        # Profile with html_layout=1 and reverse_catalog=true might need challenge
        # We'll try challenge if needed
        if random.random() < 0.3:
            self.get_challenge()

        # Create reservation
        if random.random() < 0.5:
            self.create_reservation()

        # Checkout
        if not self.checkout():
            return

        # Do work
        self.do_work()

        # Stop after one iteration
        raise StopUser()


class WorkShape(LoadTestShape):
    """
    Shape: 5/s for 10s, 15/s for 10s, 5/s for 10s
    Total 30s of load, plus warmup
    """
    phases = [
        {"duration": 10, "rate": 5},
        {"duration": 10, "rate": 15},
        {"duration": 10, "rate": 5},
    ]

    def tick(self):
        run_time = self.get_run_time()

        # Warmup period: 5s before scoring starts
        # During warmup, we still need to generate load
        # The scoring starts at T0+5 where T0 is first authenticated POST
        # We'll generate load from the start

        if run_time < 5:
            # Warmup phase - generate some initial load
            # Use a moderate rate to get things going
            current_rate = 5
            user_count = max(1, int(current_rate * 2))
            return (user_count, current_rate)

        # Scoring phase: 30s total (3 phases of 10s each)
        scoring_time = run_time - 5

        if scoring_time < 0:
            scoring_time = 0

        if scoring_time >= 30:
            # Drain period
            return None

        # Determine which phase we're in
        if scoring_time < 10:
            target_rate = 5
        elif scoring_time < 20:
            target_rate = 15
        else:
            target_rate = 5

        # Calculate user count needed
        # Each user takes ~1-2s per journey, so we need enough users
        user_count = max(1, int(target_rate * 3))

        return (user_count, target_rate)

