import os
import time
import random
from locust import HttpUser, task, between, LoadTestShape, events
from locust.exception import StopUser

BASE_URL = os.environ.get("BASE_URL", "http://127.0.0.1:8000")

# Global state for tracking
class GlobalState:
    def __init__(self):
        self.work_completions = 0
        self.work_starts = 0
        self.raw_ceiling_buckets = {}
        self.t0 = None
        self.owner_seeds = {}
        self.retry_after_times = {}
        self.active_workers = 0
        self.max_workers = 32

state = GlobalState()

class ShopUser(HttpUser):
    wait_time = between(0.05, 0.15)

    def __init__(self, *args, **kwargs):
        super().__init__(*args, **kwargs)
        self.username = None
        self.password = "bench"
        self.csrf_token = None
        self.session_cookie = None
        self.cart_id = None
        self.cart_etag = None
        self.grant_id = None
        self.reservation_id = None
        self.idempotency_key = None
        self.work_retries = 0
        self.iteration_count = 0
        self.max_iterations = 2
        self.authenticated = False
        self.login_nonce = None
        self.challenge_id = None
        self.challenge_action = None
        self.cart_recoverable = False
        self.work_success_count = 0
        self.work_attempt_count = 0
        self.last_work_time = 0
        self.retry_after_until = 0
        self.owner_seed = None

    def on_start(self):
        """Initialize user - login and setup"""
        self.username = f"bench-{random.randint(1, 16)}"
        self.owner_seed = self.username
        state.owner_seeds[self.username] = time.time()
        self.login()

    def login(self):
        """Perform login flow"""
        # Get login form
        with self.client.get("/v2/login-form", catch_response=True) as response:
            if response.status_code == 200:
                # Extract CSRF token
                import re
                csrf_match = re.search(r'name="csrf"[^>]*value="([^"]+)"', response.text)
                if not csrf_match:
                    csrf_match = re.search(r'name=[\'"]csrf[\'"][^>]*value=[\'"]([^\'"]+)[\'"]', response.text)
                if csrf_match:
                    self.csrf_token = csrf_match.group(1)
                # Extract login_nonce
                nonce_match = re.search(r'login_nonce[^>]*value="([^"]+)"', response.text)
                if nonce_match:
                    self.login_nonce = nonce_match.group(1)
                response.success()
            else:
                response.failure(f"Login form failed: {response.status_code}")
                return

        # Perform login
        if self.csrf_token:
            login_data = {
                "username": self.username,
                "password": self.password,
                "csrf": self.csrf_token
            }
            with self.client.post("/v2/login", json=login_data, catch_response=True, allow_redirects=False) as response:
                if response.status_code in (200, 302):
                    if response.status_code == 302:
                        location = response.headers.get("Location")
                        if location:
                            with self.client.get(location, catch_response=True) as redirect_response:
                                if redirect_response.status_code == 200:
                                    try:
                                        data = redirect_response.json()
                                        if "csrf" in data:
                                            self.csrf_token = data["csrf"]
                                        if "user" in data:
                                            self.authenticated = True
                                    except:
                                        pass
                                    redirect_response.success()
                                else:
                                    redirect_response.failure(f"Redirect failed: {redirect_response.status_code}")
                    else:
                        try:
                            data = response.json()
                            if "csrf" in data:
                                self.csrf_token = data["csrf"]
                            if "user" in data:
                                self.authenticated = True
                        except:
                            pass
                    response.success()
                else:
                    response.failure(f"Login failed: {response.status_code}")
                    self.authenticated = False
        else:
            self.authenticated = False

    def renew_session(self):
        """Renew expired session"""
        if not self.csrf_token:
            self.login()
            return

        with self.client.post("/v2/session/renew", json={}, headers={"X-CSRF-Token": self.csrf_token}, catch_response=True) as response:
            if response.status_code == 200:
                try:
                    data = response.json()
                    if "csrf" in data:
                        self.csrf_token = data["csrf"]
                except:
                    pass
                response.success()
            elif response.status_code == 401:
                # Session revoked, need fresh login
                self.login()
                response.success()
            else:
                response.failure(f"Renew failed: {response.status_code}")

    def recover_cart(self):
        """Recover cart after session expiry"""
        if self.cart_id and self.csrf_token:
            with self.client.post(f"/v2/carts/{self.cart_id}/recover", json={}, headers={"X-CSRF-Token": self.csrf_token}, catch_response=True) as response:
                if response.status_code == 200:
                    response.success()
                elif response.status_code == 401:
                    # Try fresh login then recover
                    self.login()
                    if self.authenticated and self.csrf_token:
                        with self.client.post(f"/v2/carts/{self.cart_id}/recover", json={}, headers={"X-CSRF-Token": self.csrf_token}, catch_response=True) as retry_response:
                            if retry_response.status_code == 200:
                                retry_response.success()
                            else:
                                retry_response.failure(f"Cart recovery failed: {retry_response.status_code}")
                    else:
                        response.failure("Cannot recover cart - login failed")
                else:
                    response.failure(f"Cart recovery failed: {response.status_code}")

    def get_catalog(self):
        """Get catalog"""
        with self.client.get("/v2/catalog", catch_response=True) as response:
            if response.status_code == 200:
                try:
                    data = response.json()
                    if "data" in data and "products" in data["data"]:
                        products = data["data"]["products"]
                        if products:
                            return products[0]
                except:
                    pass
                response.success()
            else:
                response.failure(f"Catalog failed: {response.status_code}")
        return None

    def create_cart(self, product_id, variant_id):
        """Create cart"""
        cart_data = {
            "product_id": product_id,
            "variant_id": variant_id
        }
        if self.grant_id:
            cart_data["grant_id"] = self.grant_id

        headers = {"X-CSRF-Token": self.csrf_token} if self.csrf_token else {}

        with self.client.post("/v2/carts", json=cart_data, headers=headers, catch_response=True) as response:
            if response.status_code == 201:
                try:
                    data = response.json()
                    if "id" in data:
                        self.cart_id = data["id"]
                    if "csrf" in data:
                        self.csrf_token = data["csrf"]
                    if "ETag" in response.headers:
                        self.cart_etag = response.headers["ETag"]
                    self.idempotency_key = f"idem-{self.cart_id}-{int(time.time()*1000)}"
                except:
                    pass
                response.success()
            elif response.status_code == 401:
                # Session expired
                self.renew_session()
                if self.authenticated:
                    # Retry once
                    headers = {"X-CSRF-Token": self.csrf_token} if self.csrf_token else {}
                    with self.client.post("/v2/carts", json=cart_data, headers=headers, catch_response=True) as retry_response:
                        if retry_response.status_code == 201:
                            try:
                                data = retry_response.json()
                                if "id" in data:
                                    self.cart_id = data["id"]
                                if "csrf" in data:
                                    self.csrf_token = data["csrf"]
                                if "ETag" in retry_response.headers:
                                    self.cart_etag = retry_response.headers["ETag"]
                                self.idempotency_key = f"idem-{self.cart_id}-{int(time.time()*1000)}"
                            except:
                                pass
                            retry_response.success()
                        else:
                            retry_response.failure(f"Cart creation retry failed: {retry_response.status_code}")
                else:
                    response.failure("Cart creation failed - cannot authenticate")
            else:
                response.failure(f"Cart creation failed: {response.status_code}")

    def get_challenge(self):
        """Get challenge form"""
        with self.client.get("/v2/challenge-form", catch_response=True) as response:
            if response.status_code == 200:
                import re
                action_match = re.search(r'action="([^"]*)"', response.text)
                if action_match:
                    self.challenge_action = action_match.group(1)
                    # Extract challenge ID from action
                    id_match = re.search(r'/v2/challenges/(\d+)', self.challenge_action)
                    if id_match:
                        self.challenge_id = id_match.group(1)
                challenge_match = re.search(r'name="challenge"[^>]*value="([^"]+)"', response.text)
                if challenge_match:
                    self.challenge_value = challenge_match.group(1)
                response.success()
            else:
                response.failure(f"Challenge form failed: {response.status_code}")

    def submit_challenge(self):
        """Submit challenge"""
        if not self.challenge_action or not self.challenge_value:
            return

        headers = {"X-CSRF-Token": self.csrf_token} if self.csrf_token else {}
        challenge_data = {"challenge": self.challenge_value}

        with self.client.post(self.challenge_action, json=challenge_data, headers=headers, catch_response=True, allow_redirects=False) as response:
            if response.status_code == 302:
                location = response.headers.get("Location")
                if location:
                    with self.client.get(location, catch_response=True) as redirect_response:
                        if redirect_response.status_code == 200:
                            try:
                                data = redirect_response.json()
                                if "grant_id" in data:
                                    self.grant_id = data["grant_id"]
                                if "csrf" in data:
                                    self.csrf_token = data["csrf"]
                            except:
                                pass
                            redirect_response.success()
                        else:
                            redirect_response.failure(f"Challenge redirect failed: {redirect_response.status_code}")
                response.success()
            else:
                response.failure(f"Challenge submission failed: {response.status_code}")

    def create_reservation(self):
        """Create reservation"""
        if not self.cart_id:
            return

        headers = {"X-CSRF-Token": self.csrf_token} if self.csrf_token else {}
        reservation_data = {"cart_id": self.cart_id}

        with self.client.post("/v2/reservations", json=reservation_data, headers=headers, catch_response=True) as response:
            if response.status_code == 202:
                try:
                    data = response.json()
                    if "status_url" in data:
                        self.status_url = data["status_url"]
                    if "csrf" in data:
                        self.csrf_token = data["csrf"]
                except:
                    pass
                response.success()
            else:
                response.failure(f"Reservation creation failed: {response.status_code}")

    def poll_reservation(self):
        """Poll reservation status"""
        if not hasattr(self, 'status_url') or not self.status_url:
            return

        for i in range(5):
            time.sleep(0.05)
            with self.client.get(self.status_url, catch_response=True) as response:
                if response.status_code == 200:
                    try:
                        data = response.json()
                        if data.get("status") == "ready":
                            if "reservation_id" in data:
                                self.reservation_id = data["reservation_id"]
                            response.success()
                            return
                        elif data.get("status") == "failed":
                            response.success()
                            return
                        elif data.get("status") == "pending":
                            response.success()
                            continue
                    except:
                        pass
                    response.success()
                else:
                    response.failure(f"Reservation poll failed: {response.status_code}")
                    return

    def create_order(self):
        """Create order"""
        if not self.cart_id:
            return

        headers = {"X-CSRF-Token": self.csrf_token} if self.csrf_token else {}
        if self.cart_etag:
            headers["If-Match"] = self.cart_etag
        if self.idempotency_key:
            headers["Idempotency-Key"] = self.idempotency_key

        order_data = {"cart_id": self.cart_id}
        if self.reservation_id:
            order_data["reservation_id"] = self.reservation_id

        with self.client.post("/v2/orders", json=order_data, headers=headers, catch_response=True) as response:
            if response.status_code == 201:
                try:
                    data = response.json()
                    if data.get("accepted") == True:
                        if "csrf" in data:
                            self.csrf_token = data["csrf"]
                        response.success()
                    else:
                        response.failure("Order not accepted")
                except:
                    response.failure("Invalid order response")
            elif response.status_code == 401:
                # Session expired
                self.renew_session()
                if self.authenticated and self.cart_id:
                    self.recover_cart()
                    # Retry once
                    headers = {"X-CSRF-Token": self.csrf_token} if self.csrf_token else {}
                    if self.cart_etag:
                        headers["If-Match"] = self.cart_etag
                    if self.idempotency_key:
                        headers["Idempotency-Key"] = self.idempotency_key
                    with self.client.post("/v2/orders", json=order_data, headers=headers, catch_response=True) as retry_response:
                        if retry_response.status_code == 201:
                            try:
                                data = retry_response.json()
                                if data.get("accepted") == True:
                                    if "csrf" in data:
                                        self.csrf_token = data["csrf"]
                                    retry_response.success()
                                else:
                                    retry_response.failure("Order not accepted on retry")
                            except:
                                retry_response.failure("Invalid order retry response")
                        else:
                            retry_response.failure(f"Order retry failed: {retry_response.status_code}")
                else:
                    response.failure("Order failed - cannot recover session")
            else:
                response.failure(f"Order creation failed: {response.status_code}")

    def do_work(self):
        """Perform work operation"""
        current_time = time.time()

        # Check if we need to wait for Retry-After
        if current_time < self.retry_after_until:
            wait_time = self.retry_after_until - current_time
            time.sleep(wait_time)
            current_time = time.time()

        # Track raw work start
        state.work_starts += 1
        bucket_key = int(current_time)
        if bucket_key not in state.raw_ceiling_buckets:
            state.raw_ceiling_buckets[bucket_key] = 0
        state.raw_ceiling_buckets[bucket_key] += 1

        # Set T0 if not set
        if state.t0 is None:
            state.t0 = current_time

        headers = {"X-CSRF-Token": self.csrf_token} if self.csrf_token else {}

        with self.client.post("/v2/work", json={}, headers=headers, catch_response=True) as response:
            if response.status_code == 200:
                try:
                    data = response.json()
                    if data.get("ok") == True:
                        # Successful completion
                        state.work_completions += 1
                        self.work_success_count += 1
                        self.work_retries = 0
                        self.last_work_time = time.time()
                        response.success()
                    else:
                        response.failure("Work not ok")
                except:
                    response.failure("Invalid work response")
            elif response.status_code == 429:
                # Scheduled 429 - expected, not a failure
                retry_after = response.headers.get("Retry-After", "1")
                try:
                    retry_after_seconds = int(retry_after)
                except:
                    retry_after_seconds = 1

                self.retry_after_until = time.time() + retry_after_seconds
                self.work_retries += 1

                if self.work_retries <= 4:
                    # Will retry after waiting
                    response.success()
                else:
                    response.failure("Too many 429 retries")
            elif response.status_code == 401:
                # Session expired - renew and retry once
                self.renew_session()
                if self.authenticated:
                    headers = {"X-CSRF-Token": self.csrf_token} if self.csrf_token else {}
                    with self.client.post("/v2/work", json={}, headers=headers, catch_response=True) as retry_response:
                        if retry_response.status_code == 200:
                            try:
                                data = retry_response.json()
                                if data.get("ok") == True:
                                    state.work_completions += 1
                                    self.work_success_count += 1
                                    self.work_retries = 0
                                    self.last_work_time = time.time()
                                    retry_response.success()
                                else:
                                    retry_response.failure("Work retry not ok")
                            except:
                                retry_response.failure("Invalid work retry response")
                        elif retry_response.status_code == 429:
                            retry_after = retry_response.headers.get("Retry-After", "1")
                            try:
                                retry_after_seconds = int(retry_after)
                            except:
                                retry_after_seconds = 1
                            self.retry_after_until = time.time() + retry_after_seconds
                            self.work_retries += 1
                            if self.work_retries <= 4:
                                retry_response.success()
                            else:
                                retry_response.failure("Too many 429 retries after renewal")
                        else:
                            retry_response.failure(f"Work retry after renewal failed: {retry_response.status_code}")
                else:
                    response.failure("Work failed - cannot renew session")
            elif response.status_code == 500:
                response.failure("Unexpected 500 error")
            else:
                response.failure(f"Work failed: {response.status_code}")

    def setup_journey(self):
        """Setup cart and reservation for work"""
        # Get catalog
        product = self.get_catalog()
        if not product:
            return False

        product_id = product.get("id")
        variants = product.get("variants", [])
        if not variants:
            return False

        variant_id = variants[0].get("id")

        # Get challenge
        self.get_challenge()
        if self.challenge_action and self.challenge_value:
            self.submit_challenge()

        # Create cart
        self.create_cart(product_id, variant_id)
        if not self.cart_id:
            return False

        # Create reservation
        self.create_reservation()
        self.poll_reservation()

        return True

    @task
    def work_task(self):
        """Main task - perform work operations"""
        if self.iteration_count >= self.max_iterations:
            raise StopUser()

        self.iteration_count += 1

        # Ensure authenticated
        if not self.authenticated:
            self.login()
            if not self.authenticated:
                return

        # Setup journey if needed
        if not self.cart_id:
            self.setup_journey()

        # Perform work
        self.do_work()

        # If we got a 429, wait and retry
        while self.work_retries > 0 and self.work_retries <= 4:
            current_time = time.time()
            if current_time < self.retry_after_until:
                time.sleep(self.retry_after_until - current_time)
            self.do_work()
            if self.work_retries == 0:
                break

        # Small delay between iterations
        time.sleep(0.1)

class WorkLoadShape(LoadTestShape):
    """Load shape for work pool"""

    def __init__(self):
        super().__init__()
        self.start_time = time.time()
        self.target_users = 2
        self.current_users = 0
        self.phase = "warmup"
        self.phase_start = self.start_time
        self.t0 = None
        self.warmup_duration = 5
        self.score_duration = 30
        self.drain_duration = 5
        self.total_duration = 40
        self.work_rate = 8  # target operations per second
        self.raw_ceiling = 12  # max raw work starts per second
        self.last_tick_time = self.start_time
        self.tick_count = 0

    def tick(self):
        current_time = time.time()
        elapsed = current_time - self.start_time

        # Check if we should stop
        if elapsed > self.total_duration:
            return None

        # Determine phase
        if elapsed < self.warmup_duration:
            self.phase = "warmup"
            # Ramp up to target users
            target = self.target_users
        elif elapsed < self.warmup_duration + self.score_duration:
            self.phase = "scoring"
            target = self.target_users
        else:
            self.phase = "drain"
            target = 0

        # Calculate user count
        if self.phase == "warmup":
            # Ramp up
            progress = elapsed / self.warmup_duration
            target = int(self.target_users * progress) + 1
            if target > self.target_users:
                target = self.target_users
        elif self.phase == "drain":
            target = 0

        # Return tuple (user_count, spawn_rate)
        if target != self.current_users:
            self.current_users = target
            return (target, 1)

        return None

