    private static ChainBuilder handle401AndRetry(String username, ChainBuilder operation) {
        return exec(session -> {
            String error = session.getString("error");
            if (error != null && error.contains("401")) {
                String errorType = session.getString("errorType");
                if ("expired".equals(errorType)) {
                    return session.set("shouldRenew", true);
                } else if ("session".equals(errorType)) {
                    return session.set("shouldRelogin", true);
                } else {
                    throw new RuntimeException("401 denied for " + username);
                }
            }
            return session.set("shouldRenew", false).set("shouldRelogin", false);
        }).doIf(session -> session.getBoolean("shouldRenew")).then(
                exec(renewSession(username)).exec(recoverCart(username)).exec(operation)
        ).doIf(session -> session.getBoolean("shouldRelogin")).then(
                exec(login(username)).exec(recoverCart(username)).exec(operation)
        );
    }

    private static ChainBuilder workOperation(String username) {
        return exec(session -> {
            long now = System.currentTimeMillis();
            long t0 = t0Ref.get();
            if (t0 == null) {
                t0Ref.compareAndSet(null, now);
                t0 = t0Ref.get();
            }
            long elapsed = now - t0;
            if (elapsed >= WARMUP_SECONDS * 1000L && elapsed < (WARMUP_SECONDS + SCORE_SECONDS) * 1000L) {
                // Count operation start
                operationCounter.incrementAndGet();
                // Track per-second burst
                long secondBucket = currentSecondBucket.get();
                long secondStart = currentSecondStart.get();
                if (secondStart == 0) {
                    currentSecondStart.set(now);
                    secondStart = now;
                }
                if (now - secondStart >= 1000L) {
                    // Move to next second
                    lastSecondBucket.set(secondBucket);
                    currentSecondBucket.set(1);
                    currentSecondStart.set(now);
                } else {
                    currentSecondBucket.incrementAndGet();
                }
            }
            return session;
        }).exec(
                http("POST work")
                        .post("/v2/work")
                        .header("X-CSRF-Token", session -> userCsrf.get(username))
                        .body(StringBody("{}"))
                        .check(status().in(200, 429, 500))
                        .check(bodyString().saveAs("workResponse"))
        ).exec(session -> {
            int status = session.getInt("status");
            workTotal.incrementAndGet();
            if (status == 200) {
                workSuccesses.incrementAndGet();
                String body = session.getString("workResponse");
                String csrf = extractCsrfFromJson(body);
                if (csrf != null) {
                    userCsrf.put(username, csrf);
                }
            } else if (status == 429) {
                // Scheduled 429, retry after 1s up to 4 times
                work429Retries.incrementAndGet();
                return session.set("workRetryCount", session.getInt("workRetryCount") + 1);
            } else if (status == 500) {
                workUnexpectedFailures.incrementAndGet();
                throw new RuntimeException("Unexpected 500 from /v2/work for " + username);
            }
            return session;
        }).doWhile(session -> session.getInt("status") == 429 && session.getInt("workRetryCount") < 4).on(
                exec(session -> session.set("workRetryCount", session.getInt("workRetryCount") + 1))
                        .pause(Duration.ofSeconds(1))
                        .exec(workOperation(username))
        );
    }

