import io.gatling.javaapi.core.*;
import io.gatling.javaapi.http.*;
import io.gatling.javaapi.core.CoreDsl.*;
import io.gatling.javaapi.http.HttpDsl.*;

import java.time.Duration;
import java.util.*;
import java.util.concurrent.atomic.AtomicLong;
import java.util.concurrent.atomic.AtomicBoolean;

public class ModelSimulation extends Simulation {

    // --- Configuration ---
    private static final String BASE_URL = System.getenv().getOrDefault("BASE_URL", "http://127.0.0.1:8000");
    private static final int TARGET_RATE = 10; // starts per second
    private static final int WARMUP_SECONDS = 5;
    private static final int SCORED_SECONDS = 30;
    private static final int DRAIN_SECONDS = 5;
    private static final int TOTAL_RUN_SECONDS = WARMUP_SECONDS + SCORED_SECONDS + DRAIN_SECONDS;
    private static final int MAX_VUS = 32;
    private static final int MAX_RETRIES_429 = 4;
    private static final int MAX_POLLS = 5;
    private static final long POLL_INTERVAL_MS = 50;

    // --- Shared state ---
    private static final AtomicLong t0 = new AtomicLong(0);
    private static final AtomicBoolean t0Set = new AtomicBoolean(false);
    private static final AtomicLong workStartCount = new AtomicLong(0);
    private static final AtomicLong workSuccessCount = new AtomicLong(0);
    private static final AtomicLong workFailureCount = new AtomicLong(0);
    private static final AtomicLong droppedStartCount = new AtomicLong(0);
    private static final AtomicLong unexpectedErrorCount = new AtomicLong(0);

    // --- HTTP Protocol ---
    private static final HttpProtocolBuilder httpProtocol = http
            .baseUrl(BASE_URL)
            .disableAutoRedirect()
            .acceptHeader("application/json")
            .contentTypeHeader("application/json")
            .userAgentHeader("gatling-bench")
            .shareConnections();

    // --- Feeder for users ---
    private static final Iterator<Map<String, Object>> userFeeder = IteratorFeeder(
            java.util.stream.IntStream.rangeClosed(1, 16)
                    .mapToObj(i -> Collections.<String, Object>singletonMap("username", "bench-" + i))
                    .iterator()
    );

    // --- Scenario ---
    private static final ScenarioBuilder workScenario = scenario("WorkScenario")
            .feed(userFeeder)
            .exec(session -> {
                // Fresh login
                return session.set("csrf", null).set("sessionCookie", null).set("cartId", null).set("grantId", null);
            })
            // Step 1: GET login form
            .exec(http("GetLoginForm")
                    .get("/v2/login-form")
                    .check(status().is(200))
                    .check(regex("name=\"csrf\" value=\"([^\"]+)\"").saveAs("csrf"))
                    .check(regex("name=\"csrf\" value='([^']+)'").optional().saveAs("csrfAlt"))
                    .check(regex("name=\"csrf\" value=([^ >]+)").optional().saveAs("csrfAlt2"))
            )
            .exec(session -> {
                String csrf = session.getString("csrf");
                if (csrf == null) csrf = session.getString("csrfAlt");
                if (csrf == null) csrf = session.getString("csrfAlt2");
                return session.set("csrf", csrf);
            })
            // Step 2: POST login
            .exec(http("Login")
                    .post("/v2/login")
                    .header("X-CSRF-Token", session -> session.getString("csrf"))
                    .body(StringBody(session -> {
                        String csrf = session.getString("csrf");
                        String username = session.getString("username");
                        return String.format("{\"username\":\"%s\",\"password\":\"bench\",\"csrf\":\"%s\"}", username, csrf);
                    }))
                    .check(status().is(200).or(status().is(302)))
                    .check(header("Location").optional().saveAs("loginLocation"))
                    .check(jsonPath("$.csrf").optional().saveAs("newCsrf"))
                    .check(header("Set-Cookie").optional().saveAs("setCookie"))
            )
            .exec(session -> {
                String newCsrf = session.getString("newCsrf");
                if (newCsrf != null) session = session.set("csrf", newCsrf);
                String loc = session.getString("loginLocation");
                if (loc != null) {
                    session = session.set("loginLocation", loc);
                }
                return session;
            })
            // Follow redirect if present
            .doIf(session -> session.contains("loginLocation")).then(
                    exec(http("FollowLoginRedirect")
                            .get(session -> session.getString("loginLocation"))
                            .check(status().is(200))
                            .check(jsonPath("$.csrf").optional().saveAs("newCsrf2"))
                    )
                            .exec(session -> {
                                String csrf = session.getString("newCsrf2");
                                if (csrf != null) session = session.set("csrf", csrf);
                                return session;
                            })
            )
            // Step 3: GET catalog
            .exec(http("GetCatalog")
                    .get("/v2/catalog")
                    .check(status().is(200))
                    .check(jsonPath("$.data.products[0].id").optional().saveAs("productId"))
                    .check(jsonPath("$.data.products[0].variants[0].id").optional().saveAs("variantId"))
                    .check(jsonPath("$.data.products[0].variants[0].in_stock").optional().saveAs("inStock"))
            )
            .exec(session -> {
                if (session.getString("productId") == null || session.getString("variantId") == null) {
                    // Try page
                    return session.set("needPage", true);
                }
                return session.set("needPage", false);
            })
            .doIf(session -> session.getBoolean("needPage")).then(
                    exec(http("GetCatalogPage")
                            .get("/v2/catalog/page")
                            .check(status().is(200))
                            .check(jsonPath("$.data.id").optional().saveAs("productId"))
                            .check(jsonPath("$.data.variants[0].id").optional().saveAs("variantId"))
                            .check(jsonPath("$.data.variants[0].in_stock").optional().saveAs("inStock"))
                    )
            )
            // Step 4: Create cart
            .exec(http("CreateCart")
                    .post("/v2/carts")
                    .header("X-CSRF-Token", session -> session.getString("csrf"))
                    .body(StringBody(session -> {
                        String productId = session.getString("productId");
                        String variantId = session.getString("variantId");
                        String grantId = session.getString("grantId");
                        if (grantId != null) {
                            return String.format("{\"product_id\":\"%s\",\"variant_id\":\"%s\",\"grant_id\":\"%s\"}", productId, variantId, grantId);
                        }
                        return String.format("{\"product_id\":\"%s\",\"variant_id\":\"%s\"}", productId, variantId);
                    }))
                    .check(status().is(201))
                    .check(jsonPath("$.id").saveAs("cartId"))
                    .check(jsonPath("$.csrf").optional().saveAs("newCsrf3"))
                    .check(header("ETag").optional().saveAs("etag"))
            )
            .exec(session -> {
                String csrf = session.getString("newCsrf3");
                if (csrf != null) session = session.set("csrf", csrf);
                return session;
            })
            // Step 5: PATCH cart quantity
            .exec(http("PatchCart")
                    .patch(session -> "/v2/carts/" + session.getString("cartId"))
                    .header("X-CSRF-Token", session -> session.getString("csrf"))
                    .header("If-Match", session -> session.getString("etag"))
                    .body(StringBody("{\"quantity\":1}"))
                    .check(status().is(200).or(status().is(412)))
                    .check(header("ETag").optional().saveAs("etag2"))
                    .check(jsonPath("$.csrf").optional().saveAs("newCsrf4"))
            )
            .exec(session -> {
                String csrf = session.getString("newCsrf4");
                if (csrf != null) session = session.set("csrf", csrf);
                String etag = session.getString("etag2");
                if (etag != null) session = session.set("etag", etag);
                return session;
            })
            // Retry on 412
            .doIf(session -> session.getInt("statusCode") == 412).then(
                    exec(http("ReReadCart")
                            .get(session -> "/v2/carts/" + session.getString("cartId"))
                            .check(status().is(200))
                            .check(header("ETag").saveAs("etag"))
                    )
                            .exec(http("PatchCartRetry")
                                    .patch(session -> "/v2/carts/" + session.getString("cartId"))
                                    .header("X-CSRF-Token", session -> session.getString("csrf"))
                                    .header("If-Match", session -> session.getString("etag"))
                                    .body(StringBody("{\"quantity\":1}"))
                                    .check(status().is(200))
                                    .check(header("ETag").optional().saveAs("etag2"))
                                    .check(jsonPath("$.csrf").optional().saveAs("newCsrf5"))
                            )
                            .exec(session -> {
                                String csrf = session.getString("newCsrf5");
                                if (csrf != null) session = session.set("csrf", csrf);
                                String etag = session.getString("etag2");
                                if (etag != null) session = session.set("etag", etag);
                                return session;
                            })
            )
            // Step 6: Create order (checkout)
            .exec(http("CreateOrder")
                    .post("/v2/orders")
                    .header("X-CSRF-Token", session -> session.getString("csrf"))
                    .header("Idempotency-Key", session -> "order-" + session.getString("cartId") + "-" + System.nanoTime())
                    .body(StringBody(session -> String.format("{\"cart_id\":\"%s\"}", session.getString("cartId"))))
                    .check(status().is(201).or(status().is(200)))
                    .check(jsonPath("$.accepted").optional().saveAs("accepted"))
                    .check(jsonPath("$.id").optional().saveAs("orderId"))
                    .check(jsonPath("$.csrf").optional().saveAs("newCsrf6"))
            )
            .exec(session -> {
                String csrf = session.getString("newCsrf6");
                if (csrf != null) session = session.set("csrf", csrf);
                return session;
            })
            // Step 7: POST /v2/work - the measured operation
            .exec(session -> {
                long now = System.currentTimeMillis();
                if (t0Set.compareAndSet(false, true)) {
                    t0.set(now);
                }
                return session;
            })
            .exec(http("Work")
                    .post("/v2/work")
                    .header("X-CSRF-Token", session -> session.getString("csrf"))
                    .body(StringBody("{}"))
                    .check(status().is(200).or(status().is(429)))
                    .check(header("Retry-After").optional().saveAs("retryAfter"))
                    .check(jsonPath("$.ok").optional().saveAs("ok"))
            )
            .exec(session -> {
                int status = session.getInt("statusCode");
                if (status == 200) {
                    workSuccessCount.incrementAndGet();
                } else if (status == 429) {
                    // Scheduled 429 - expected, not a failure
                    // Retry up to 4 times with Retry-After
                    String retryAfter = session.getString("retryAfter");
                    long delayMs = 1000;
                    if (retryAfter != null) {
                        try { delayMs = Long.parseLong(retryAfter) * 1000; } catch (Exception e) {}
                    }
                    session = session.set("retryDelayMs", delayMs);
                    session = session.set("retryCount", 0);
                } else {
                    workFailureCount.incrementAndGet();
                    unexpectedErrorCount.incrementAndGet();
                }
                return session;
            })
            // Retry loop for 429
            .asLongAs(session -> session.getInt("statusCode") == 429 && session.getInt("retryCount") < MAX_RETRIES_429).on(
                    pause(session -> Duration.ofMillis(session.getLong("retryDelayMs")))
                            .exec(http("WorkRetry")
                                    .post("/v2/work")
                                    .header("X-CSRF-Token", session -> session.getString("csrf"))
                                    .body(StringBody("{}"))
                                    .check(status().is(200).or(status().is(429)))
                                    .check(header("Retry-After").optional().saveAs("retryAfter"))
                                    .check(jsonPath("$.ok").optional().saveAs("ok"))
                            )
                            .exec(session -> {
                                int status = session.getInt("statusCode");
                                if (status == 200) {
                                    workSuccessCount.incrementAndGet();
                                } else if (status == 429) {
                                    String retryAfter = session.getString("retryAfter");
                                    long delayMs = 1000;
                                    if (retryAfter != null) {
                                        try { delayMs = Long.parseLong(retryAfter) * 1000; } catch (Exception e) {}
                                    }
                                    session = session.set("retryDelayMs", delayMs);
                                    session = session.set("retryCount", session.getInt("retryCount") + 1);
                                } else {
                                    workFailureCount.incrementAndGet();
                                    unexpectedErrorCount.incrementAndGet();
                                }
                                return session;
                            })
            )
            // Final check: if still 429 after retries, count as dropped
            .exec(session -> {
                if (session.getInt("statusCode") == 429) {
                    droppedStartCount.incrementAndGet();
                }
                return session;
            });

    {
        setUp(
                workScenario.injectOpen(
                        constantUsersPerSec(TARGET_RATE).during(TOTAL_RUN_SECONDS)
                )
        ).protocols(httpProtocol)
                .maxDuration(Duration.ofSeconds(TOTAL_RUN_SECONDS + 10))
                .assertions(
                        global().failedRequests().percent().lt(1.0),
                        global().responseTime().max().lt(5000)
                );
    }

    // Helper to create iterator feeder
    private static Iterator<Map<String, Object>> IteratorFeeder(Iterator<Map<String, Object>> iterator) {
        return iterator;
    }
}
