PASSWORD = "bench"

class ShopUser(HttpUser):
    wait_time = between(0.05, 0.15)

    def __init__(self, *args, **kwargs):
        super().__init__(*args, **kwargs)
        self.username = random.choice(ACCOUNTS)
        self.csrf_token = None
        self.session_cookie = None
        self.cart_id = None
        self.cart_etag = None
        self.grant_id = None
        self.reservation_id = None
        self.idempotency_key = None
        self.work_retries = 0
        self.authenticated = False
        self.work_start_time = None
        self.t0_recorded = False

    def on_start(self):
        self.login()

    def login(self):
        # GET login form
        with self.client.get("/v2/login-form", catch_response=True) as resp:
            if resp.status_code != 200:
                resp.failure(f"Login form failed: {resp.status_code}")
                return False
            # Extract CSRF from input[name=csrf]
            import re
            match = re.search(r'name="csrf"[^>]*value="([^"]*)"', resp.text)
            if not match:
                match = re.search(r'name=[\'"]csrf[\'"][^>]*value=[\'"]([^\'"]*)[\'"]', resp.text)
            if not match:
                resp.failure("No CSRF token in login form")
                return False
            self.csrf_token = match.group(1)

        # POST login
        with self.client.post("/v2/login", 
                             json={"username": self.username, "password": PASSWORD, "csrf": self.csrf_token},
                             headers={"X-CSRF-Token": self.csrf_token},
                             catch_response=True) as resp:
            if resp.status_code == 302:
                location = resp.headers.get("Location")
                if location:
                    with self.client.get(location, catch_response=True) as resp2:
                        if resp2.status_code != 200:
                            resp2.failure(f"Login redirect failed: {resp2.status_code}")
                            return False
                        resp = resp2
                else:
                    resp.failure("302 without Location")
                    return False
            if resp.status_code != 200:
                resp.failure(f"Login failed: {resp.status_code}")
                return False
            try:
                data = resp.json()
                if "csrf" in data:
                    self.csrf_token = data["csrf"]
                if "user" in data:
                    self.authenticated = True
            except:
                resp.failure("Invalid login response")
                return False
        return True

