        with self.client.post("/v2/carts",
                             json=payload,
                             headers={"X-CSRF-Token": self.csrf_token},
                             catch_response=True) as resp:
            if resp.status_code == 201:
                try:
                    data = resp.json()
                    self.cart_id = data.get("id")
                    if "csrf" in data:
                        self.csrf_token = data["csrf"]
                    self.cart_etag = resp.headers.get("ETag")
