    def update_cart(self, quantity):
        if not self.cart_id or not self.cart_etag:
            return False
        with self.client.patch(f"/v2/carts/{self.cart_id}",
                              json={"quantity": quantity},
                              headers={"X-CSRF-Token": self.csrf_token, "If-Match": self.cart_etag},
