                elif error == "session":
                    if self.login():
                        if self.recover_cart():
                            return self.update_cart(quantity)
                else:
                    resp.failure(f"Cart update denied: {error}")
            else:
                resp.failure(f"Cart update failed: {resp.status_code}")
        return False

    def create_order(self):
        if not self.cart_id:
            return False
        if not self.idempotency_key:
            self.idempotency_key = f"key-{self.cart_id}-{int(time.time()*1000)}"
        headers = {"X-CSRF-Token": self.csrf_token, "Idempotency-Key": self.idempotency_key}
