                            self.csrf_token = data["csrf"]
                        return True
                    else:
                        resp.failure("Order not accepted")
                except:
                    resp.failure("Invalid order response")
            elif resp.status_code == 200:
                try:
                    data = resp.json()
                    if data.get("accepted") == False:
                        resp.failure("Business failure: order not accepted")
                    else:
                        if "csrf" in data:
                            self.csrf_token = data["csrf"]
                        return True
                except:
                    resp.failure("Invalid order response")
            elif resp.status_code == 401:
