    def get_challenge(self):
        with self.client.get("/v2/challenge-form", catch_response=True) as resp:
            if resp.status_code != 200:
                resp.failure(f"Challenge form failed: {resp.status_code}")
                return False
            import re
            action_match = re.search(r'action="([^"]*)"', resp.text)
            challenge_match = re.search(r'name="challenge"[^>]*value="([^"]*)"', resp.text)
            if not action_match or not challenge_match:
                resp.failure("No challenge form data")
                return False
            action = action_match.group(1)
            challenge = challenge_match.group(1)
            with self.client.post(action,
                                 json={"challenge": challenge},
                                 headers={"X-CSRF-Token": self.csrf_token},
                                 catch_response=True) as resp2:
                if resp2.status_code == 302:
                    location = resp2.headers.get("Location")
                    if location:
                        with self.client.get(location, catch_response=True) as resp3:
                            if resp3.status_code == 200:
                                try:
                                    data = resp3.json()
                                    self.grant_id = data.get("grant_id")
                                    if "csrf" in data:
                                        self.csrf_token = data["csrf"]
                                    return True
                                except:
                                    resp3.failure("Invalid challenge response")
                            else:
                                resp3.failure(f"Challenge location failed: {resp3.status_code}")
                    else:
                        resp2.failure("Challenge 302 without Location")
                elif resp2.status_code == 401:
                    error = resp2.json().get("error", "") if resp2.headers.get("content-type", "").startswith("application/json") else ""
                    if error == "expired":
                        if self.renew_session():
                            return self.get_challenge()
                    elif error == "session":
                        if self.login():
                            return self.get_challenge()
                    else:
                        resp2.failure(f"Challenge denied: {error}")
                else:
                    resp2.failure(f"Challenge failed: {resp2.status_code}")
        return False

    def create_reservation(self):
