                                        status = data2.get("status")
                                        if status == "ready":
                                            self.reservation_id = data2.get("reservation_id")
                                            if "csrf" in data2:
                                                self.csrf_token = data2["csrf"]
                                            return True
                                        elif status == "failed":
                                            return False
                                        elif status == "pending":
                                            continue
                                    except:
                                        resp2.failure("Invalid reservation status")
                                elif resp2.status_code == 401:
                                    error = resp2.json().get("error", "") if resp2.headers.get("content-type", "").startswith("application/json") else ""
                                    if error == "expired":
                                        if self.renew_session():
                                            continue
                                    elif error == "session":
                                        if self.login():
                                            continue
                                    else:
                                        resp2.failure(f"Reservation status denied: {error}")
                                        return False
                                else:
                                    resp2.failure(f"Reservation status failed: {resp2.status_code}")
                                    return False
                except:
                    resp.failure("Invalid reservation response")
            elif resp.status_code == 401:
                error = resp.json().get("error", "") if resp.headers.get("content-type", "").startswith("application/json") else ""
                if error == "expired":
                    if self.renew_session():
