                            return self.create_reservation()
                else:
                    resp.failure(f"Reservation denied: {error}")
            else:
                resp.failure(f"Reservation failed: {resp.status_code}")
        return False

    def do_work(self):
        if not self.authenticated:
            return False
        # Record start time for eligible requests
        self.work_start_time = time.time()
        with self.client.post("/v2/work",
                             json={},
                             headers={"X-CSRF-Token": self.csrf_token},
                             catch_response=True) as resp:
            if resp.status_code == 200:
                try:
                    data = resp.json()
                    if data.get("ok") == True:
                        if "csrf" in data:
                            self.csrf_token = data["csrf"]
                        # Record T0 if not already
                        if not self.t0_recorded:
                            self.t0_recorded = True
                            events.test_start.fire(environment=self.environment)
                        return True
                    else:
                        resp.failure("Work not ok")
                except:
                    resp.failure("Invalid work response")
            elif resp.status_code == 429:
                # Scheduled 429 - expected, retry with Retry-After
                retry_after = resp.headers.get("Retry-After", "1")
                try:
                    retry_after = int(retry_after)
                except:
                    retry_after = 1
                if self.work_retries < 4:
                    self.work_retries += 1
                    time.sleep(retry_after)
                    return self.do_work()
                else:
                    resp.failure("Too many 429 retries")
            elif resp.status_code == 401:
                error = resp.json().get("error", "") if resp.headers.get("content-type", "").startswith("application/json") else ""
                if error == "expired":
                    if self.renew_session():
                        return self.do_work()
                elif error == "session":
                    if self.login():
                        return self.do_work()
                else:
                    resp.failure(f"Work denied: {error}")
            elif resp.status_code == 500:
                resp.failure("Unexpected 500 error")
            else:
                resp.failure(f"Work failed: {resp.status_code}")
        return False

