class WorkLoadShape(LoadTestShape):
    def __init__(self):
        super().__init__()
        self.start_time = time.time()
        self.t0 = None
        self.phase = "warmup"
        self.phase_start = None

    def tick(self):
        current_time = time.time()
        elapsed = current_time - self.start_time

        # Check if T0 has been recorded
        if self.t0 is None:
            # Check if any user has recorded T0
            for user in self.user_classes[0].instances:
                if user.t0_recorded:
                    self.t0 = current_time
                    self.phase = "warmup"
                    self.phase_start = self.t0
                    break

        if self.t0 is None:
            # Still waiting for T0, keep users running
            if elapsed > 10:
                # T0 not recorded within 10s, stop
                return None
            return (2, 2)

        t0_elapsed = current_time - self.t0

        if t0_elapsed < 5:
            # Warmup phase
            return (2, 2)
        elif t0_elapsed < 35:
            # Scored phase: 30 seconds total
            # Phased targets: 5/s for first 10s, 15/s for next 10s, 5/s for last 10s
            scored_elapsed = t0_elapsed - 5
            if scored_elapsed < 10:
                # First plateau: 5/s
                target_rate = 5
            elif scored_elapsed < 20:
                # Second plateau: 15/s
                target_rate = 15
            else:
                # Third plateau: 5/s
                target_rate = 5

            # Calculate required users based on rate and latency
            # With latency up to 600ms, need enough users to sustain rate
            # Rate = users / latency
            # users = rate * latency
            # For 15/s with 600ms latency: 15 * 0.6 = 9 users
            # For 5/s with 600ms latency: 5 * 0.6 = 3 users
            # But we need to account for journey overhead
            # Use a multiplier to ensure enough users
            if target_rate == 15:
                users = 20
            else:
                users = 8
            return (users, users)
        else:
            # Drain phase: <=5s
            if t0_elapsed < 40:
                return (2, 2)
            else:
                return None

