        // Look for input name=csrf value="..."
        idx = body.indexOf("name=\"csrf\"");
        if (idx >= 0) {
            int valueIdx = body.indexOf("value=\"", idx);
            if (valueIdx >= 0) {
                int start = valueIdx + 7;
                int end = body.indexOf("\"", start);
