            int end = body.indexOf("\"", start);
            if (end >= 0) {
                return body.substring(start, end);
            }
        }
        return null;
    }

    private static String extractChallengeInputName(String body) {
        if (body == null) return null;
        int idx = body.indexOf("name=\"challenge\"");
        if (idx >= 0) {
            return "challenge";
        }
        return null;
    }

    // --- Chain: Login ---
    private static ChainBuilder login() {
        return exec(
            http("GET /v2/login-form")
                .get("/v2/login-form")
                .check(status().is(200))
                .check(bodyString().saveAs("loginFormBody"))
        )
        .exec(session -> {
            String body = session.getString("loginFormBody");
            String csrf = extractCsrf(body);
            String nonce = extractLoginNonce(body);
            if (csrf == null) {
                // Try to find csrf in input
                int idx = body.indexOf("name=\"csrf\"");
                if (idx >= 0) {
                    int valueIdx = body.indexOf("value=\"", idx);
                    if (valueIdx >= 0) {
                        int start = valueIdx + 7;
                        int end = body.indexOf("\"", start);
                        if (end >= 0) {
                            csrf = body.substring(start, end);
                        }
                    }
                }
            }
            return session.set("csrf", csrf).set("login_nonce", nonce);
        })
        .exec(
            http("POST /v2/login")
                .post("/v2/login")
                .header("X-CSRF-Token", session -> session.getString("csrf"))
                .body(StringBody(session -> {
                    String csrf = session.getString("csrf");
                    String nonce = session.getString("login_nonce");
                    String username = session.getString("username");
                    return String.format("{\"username\":\"%s\",\"password\":\"%s\",\"csrf\":\"%s\",\"login_nonce\":\"%s\"}", username, PASSWORD, csrf, nonce != null ? nonce : "");
                }))
                .check(status().in(200, 302))
                .check(bodyString().saveAs("loginResponseBody"))
                .check(header("Location").optional().saveAs("loginLocation"))
        )
        .exec(session -> {
            String body = session.getString("loginResponseBody");
            String csrf = extractCsrf(body);
            if (csrf != null) {
                session = session.set("csrf", csrf);
            }
            String location = session.getString("loginLocation");
            if (location != null && !location.isEmpty()) {
                session = session.set("loginRedirect", location);
            }
            return session;
        })
        .doIf(session -> session.contains("loginRedirect")).then(
            exec(
                http("GET login redirect")
                    .get(session -> session.getString("loginRedirect"))
                    .check(status().in(200, 302))
                    .check(bodyString().saveAs("loginRedirectBody"))
                    .check(header("Location").optional().saveAs("loginRedirectLocation2"))
            )
            .exec(session -> {
                String body = session.getString("loginRedirectBody");
                String csrf = extractCsrf(body);
                if (csrf != null) {
                    session = session.set("csrf", csrf);
                }
                String loc2 = session.getString("loginRedirectLocation2");
                if (loc2 != null && !loc2.isEmpty()) {
                    session = session.set("loginRedirect2", loc2);
                }
                return session;
            })
            .doIf(session -> session.contains("loginRedirect2")).then(
                exec(
                    http("GET login redirect 2")
                        .get(session -> session.getString("loginRedirect2"))
                        .check(status().in(200, 302))
                        .check(bodyString().saveAs("loginRedirectBody2"))
                )
                .exec(session -> {
                    String body = session.getString("loginRedirectBody2");
                    String csrf = extractCsrf(body);
                    if (csrf != null) {
                        session = session.set("csrf", csrf);
                    }
                    return session;
                })
            )
        );
    }

    // --- Chain: Get catalog ---
    private static ChainBuilder getCatalog() {
        return exec(
            http("GET /v2/catalog")
                .get("/v2/catalog")
                .header("X-CSRF-Token", session -> session.getString("csrf"))
                .check(status().is(200))
                .check(bodyString().saveAs("catalogBody"))
        )
        .exec(session -> {
            String body = session.getString("catalogBody");
            String productId = extractFirstProductId(body);
            String variantId = extractFirstVariantId(body);
            String next = extractNextPage(body);
            return session.set("productId", productId).set("variantId", variantId).set("nextPage", next);
        });
    }

    // --- Chain: Traverse catalog pages (up to 3) ---
    private static ChainBuilder traverseCatalogPages() {
        return exec(getCatalog())
            .asLongAs(session -> {
                String next = session.getString("nextPage");
                Integer pageCount = session.getInt("pageCount");
                if (pageCount == null) pageCount = 0;
                return next != null && !next.equals("null") && pageCount < 3;
            }).on(
                exec(session -> {
                    String next = session.getString("nextPage");
                    return session.set("nextPageUrl", next);
                })
                .exec(
                    http("GET catalog page")
                        .get(session -> session.getString("nextPageUrl"))
                        .header("X-CSRF-Token", session -> session.getString("csrf"))
                        .check(status().is(200))
                        .check(bodyString().saveAs("catalogPageBody"))
                )
                .exec(session -> {
                    String body = session.getString("catalogPageBody");
                    String productId = extractFirstProductId(body);
                    String variantId = extractFirstVariantId(body);
                    String next = extractNextPage(body);
                    Integer pageCount = session.getInt("pageCount");
                    if (pageCount == null) pageCount = 0;
                    pageCount++;
                    return session.set("productId", productId).set("variantId", variantId).set("nextPage", next).set("pageCount", pageCount);
                })
            );
    }

    // --- Chain: Create cart ---
    private static ChainBuilder createCart() {
        return exec(session -> {
            String grantId = session.getString("grantId");
            String productId = session.getString("productId");
            String variantId = session.getString("variantId");
            String body;
            if (grantId != null && !grantId.isEmpty()) {
                body = String.format("{\"product_id\":\"%s\",\"variant_id\":\"%s\",\"grant_id\":\"%s\"}", productId, variantId, grantId);
            } else {
                body = String.format("{\"product_id\":\"%s\",\"variant_id\":\"%s\"}", productId, variantId);
            }
            return session.set("cartCreateBody", body);
        })
        .exec(
            http("POST /v2/carts")
                .post("/v2/carts")
                .header("X-CSRF-Token", session -> session.getString("csrf"))
                .body(StringBody(session -> session.getString("cartCreateBody")))
                .check(status().is(201))
                .check(bodyString().saveAs("cartCreateResponse"))
                .check(header("ETag").optional().saveAs("cartEtag"))
        )
        .exec(session -> {
            String body = session.getString("cartCreateResponse");
            String cartId = extractCartId(body);
            String csrf = extractCsrf(body);
            if (csrf != null) {
                session = session.set("csrf", csrf);
            }
            return session.set("cartId", cartId);
        });
    }

    // --- Chain: Get cart ---
    private static ChainBuilder getCart() {
        return exec(
            http("GET /v2/carts/{cartId}")
                .get("/v2/carts/" + session -> session.getString("cartId"))
                .header("X-CSRF-Token", session -> session.getString("csrf"))
                .check(status().is(200))
                .check(header("ETag").optional().saveAs("cartEtag"))
                .check(bodyString().saveAs("cartGetBody"))
        )
        .exec(session -> {
            String body = session.getString("cartGetBody");
            String csrf = extractCsrf(body);
            if (csrf != null) {
                session = session.set("csrf", csrf);
            }
            return session;
        });
    }

    // --- Chain: Update cart quantity ---
    private static ChainBuilder updateCartQuantity(int quantity) {
        return exec(session -> {
            String etag = session.getString("cartEtag");
            return session.set("cartUpdateBody", String.format("{\"quantity\":%d}", quantity))
                .set("cartUpdateEtag", etag);
        })
        .exec(
            http("PATCH /v2/carts/{cartId}")
                .patch("/v2/carts/" + session -> session.getString("cartId"))
                .header("X-CSRF-Token", session -> session.getString("csrf"))
                .header("If-Match", session -> session.getString("cartUpdateEtag"))
                .body(StringBody(session -> session.getString("cartUpdateBody")))
                .check(status().in(200, 412))
                .check(bodyString().saveAs("cartPatchBody"))
                .check(header("ETag").optional().saveAs("cartPatchEtag"))
        )
        .exec(session -> {
            String body = session.getString("cartPatchBody");
            String csrf = extractCsrf(body);
            if (csrf != null) {
                session = session.set("csrf", csrf);
            }
            String etag = session.getString("cartPatchEtag");
            if (etag != null) {
                session = session.set("cartEtag", etag);
            }
            return session;
        })
        .doIf(session -> session.getInt("cartPatchStatus") != null && session.getInt("cartPatchStatus") == 412).then(
            exec(getCart())
            .exec(session -> {
                String etag = session.getString("cartEtag");
                return session.set("cartUpdateEtag", etag);
            })
            .exec(
                http("PATCH retry /v2/carts/{cartId}")
                    .patch("/v2/carts/" + session -> session.getString("cartId"))
                    .header("X-CSRF-Token", session -> session.getString("csrf"))
                    .header("If-Match", session -> session.getString("cartUpdateEtag"))
                    .body(StringBody(session -> session.getString("cartUpdateBody")))
                    .check(status().in(200, 412))
                    .check(bodyString().saveAs("cartPatchBody2"))
                    .check(header("ETag").optional().saveAs("cartPatchEtag2"))
            )
            .exec(session -> {
                String body = session.getString("cartPatchBody2");
                String csrf = extractCsrf(body);
                if (csrf != null) {
                    session = session.set("csrf", csrf);
                }
                String etag = session.getString("cartPatchEtag2");
                if (etag != null) {
                    session = session.set("cartEtag", etag);
                }
                return session;
            })
        );
    }

    // --- Chain: Challenge flow ---
    private static ChainBuilder challengeFlow() {
        return exec(
            http("GET /v2/challenge-form")
                .get("/v2/challenge-form")
                .header("X-CSRF-Token", session -> session.getString("csrf"))
                .check(status().is(200))
                .check(bodyString().saveAs("challengeFormBody"))
        )
        .exec(session -> {
            String body = session.getString("challengeFormBody");
            String action = extractChallengeAction(body);
            String csrf = extractCsrf(body);
            if (csrf != null) {
                session = session.set("csrf", csrf);
            }
            return session.set("challengeAction", action);
        })
        .exec(
            http("POST challenge")
                .post(session -> session.getString("challengeAction"))
                .header("X-CSRF-Token", session -> session.getString("csrf"))
                .body(StringBody("{\"challenge\":\"bench\"}"))
                .check(status().is(302))
                .check(header("Location").saveAs("challengeLocation"))
        )
        .exec(
            http("GET challenge redirect")
                .get(session -> session.getString("challengeLocation"))
                .header("X-CSRF-Token", session -> session.getString("csrf"))
