            return session.set("grantId", grantId);
        });
    }

    // --- Chain: Reservation flow ---
    private static ChainBuilder reservationFlow() {
        return exec(session -> {
            String cartId = session.getString("cartId");
            return session.set("reservationBody", String.format("{\"cart_id\":\"%s\"}", cartId));
        })
        .exec(
            http("POST /v2/reservations")
                .post("/v2/reservations")
                .header("X-CSRF-Token", session -> session.getString("csrf"))
                .body(StringBody(session -> session.getString("reservationBody")))
                .check(status().is(202))
                .check(bodyString().saveAs("reservationResponse"))
        )
        .exec(session -> {
            String body = session.getString("reservationResponse");
            String statusUrl = extractStatusUrl(body);
            String csrf = extractCsrf(body);
            if (csrf != null) {
                session = session.set("csrf", csrf);
            }
            return session.set("reservationStatusUrl", statusUrl).set("reservationPollCount", 0);
        })
        .asLongAs(session -> {
            Integer count = session.getInt("reservationPollCount");
            String status = session.getString("reservationStatus");
            return count != null && count < 5 && (status == null || !status.equals("ready"));
        }).on(
            exec(session -> {
                Integer count = session.getInt("reservationPollCount");
                if (count == null) count = 0;
                count++;
                return session.set("reservationPollCount", count);
            })
            .pause(Duration.ofMillis(50))
            .exec(
                http("GET reservation status")
                    .get(session -> session.getString("reservationStatusUrl"))
                    .header("X-CSRF-Token", session -> session.getString("csrf"))
                    .check(status().is(200))
                    .check(bodyString().saveAs("reservationStatusBody"))
            )
            .exec(session -> {
                String body = session.getString("reservationStatusBody");
                String status = null;
                if (body != null) {
                    int idx = body.indexOf("\"status\"");
                    if (idx >= 0) {
                        int colonIdx = body.indexOf(":", idx);
                        if (colonIdx >= 0) {
                            int quoteIdx = body.indexOf("\"", colonIdx + 1);
                            if (quoteIdx >= 0) {
                                int endQuote = body.indexOf("\"", quoteIdx + 1);
                                if (endQuote >= 0) {
                                    status = body.substring(quoteIdx + 1, endQuote);
                                }
                            }
                        }
                    }
                }
                String reservationId = extractReservationId(body);
                String csrf = extractCsrf(body);
                if (csrf != null) {
                    session = session.set("csrf", csrf);
                }
                if (reservationId != null) {
                    session = session.set("reservationId", reservationId);
                }
                return session.set("reservationStatus", status);
            })
        );
    }

    // --- Chain: Checkout (POST /v2/orders) ---
    private static ChainBuilder checkout() {
        return exec(session -> {
            String cartId = session.getString("cartId");
            String reservationId = session.getString("reservationId");
            String idempotencyKey = "key-" + cartId + "-" + System.nanoTime();
            String etag = session.getString("cartEtag");
            String body;
            if (reservationId != null && !reservationId.isEmpty()) {
                body = String.format("{\"cart_id\":\"%s\",\"reservation_id\":\"%s\"}", cartId, reservationId);
            } else {
                body = String.format("{\"cart_id\":\"%s\"}", cartId);
            }
            return session.set("checkoutBody", body)
                .set("idempotencyKey", idempotencyKey)
                .set("checkoutEtag", etag);
        })
        .exec(
            http("POST /v2/orders")
                .post("/v2/orders")
                .header("X-CSRF-Token", session -> session.getString("csrf"))
                .header("Idempotency-Key", session -> session.getString("idempotencyKey"))
                .header("If-Match", session -> session.getString("checkoutEtag"))
                .body(StringBody(session -> session.getString("checkoutBody")))
                .check(status().in(201, 200, 401, 429, 500))
                .check(bodyString().saveAs("checkoutResponseBody"))
                .check(header("Retry-After").optional().saveAs("retryAfter"))
        )
        .exec(session -> {
            String body = session.getString("checkoutResponseBody");
            String csrf = extractCsrf(body);
            if (csrf != null) {
                session = session.set("csrf", csrf);
            }
            Integer status = session.getInt("status");
            if (status != null && status == 201) {
                // Check accepted:true
                if (body != null && body.contains("\"accepted\":true")) {
                    session = session.set("checkoutCommitted", true);
                } else {
                    session = session.set("checkoutCommitted", false);
                }
            } else if (status != null && status == 200) {
                // accepted:false is business failure
                session = session.set("checkoutCommitted", false);
            } else {
                session = session.set("checkoutCommitted", false);
            }
            return session;
        });
    }

    // --- Chain: Handle 401 expiry ---
    private static ChainBuilder handle401Expiry() {
        return exec(session -> {
            String body = session.getString("checkoutResponseBody");
            String error = null;
            if (body != null) {
                int idx = body.indexOf("\"error\"");
                if (idx >= 0) {
                    int colonIdx = body.indexOf(":", idx);
                    if (colonIdx >= 0) {
                        int quoteIdx = body.indexOf("\"", colonIdx + 1);
                        if (quoteIdx >= 0) {
                            int endQuote = body.indexOf("\"", quoteIdx + 1);
                            if (endQuote >= 0) {
                                error = body.substring(quoteIdx + 1, endQuote);
                            }
                        }
                    }
                }
            }
            return session.set("authError", error);
        })
        .doIf(session -> "expired".equals(session.getString("authError"))).then(
            exec(
                http("POST /v2/session/renew")
                    .post("/v2/session/renew")
                    .header("X-CSRF-Token", session -> session.getString("csrf"))
                    .body(StringBody("{}"))
                    .check(status().in(200, 401))
                    .check(bodyString().saveAs("renewResponseBody"))
            )
            .exec(session -> {
                String body = session.getString("renewResponseBody");
                String csrf = extractCsrf(body);
                if (csrf != null) {
                    session = session.set("csrf", csrf);
                }
                return session;
            })
            .doIf(session -> session.contains("cartId")).then(
                exec(
                    http("POST /v2/carts/{cartId}/recover")
                        .post("/v2/carts/" + session -> session.getString("cartId") + "/recover")
                        .header("X-CSRF-Token", session -> session.getString("csrf"))
                        .body(StringBody("{}"))
                        .check(status().in(200, 401))
                        .check(bodyString().saveAs("recoverResponseBody"))
                )
                .exec(session -> {
                    String body = session.getString("recoverResponseBody");
                    String csrf = extractCsrf(body);
                    if (csrf != null) {
                        session = session.set("csrf", csrf);
                    }
                    return session;
                })
            )
            // Retry checkout once
            .exec(checkout())
        );
    }

    // --- Chain: Handle 429 retry ---
    private static ChainBuilder handle429Retry() {
        return exec(session -> {
            Integer retryCount = session.getInt("retry429Count");
            if (retryCount == null) retryCount = 0;
            return session.set("retry429Count", retryCount);
        })
        .asLongAs(session -> {
            Integer status = session.getInt("status");
            Integer retryCount = session.getInt("retry429Count");
            return status != null && status == 429 && retryCount != null && retryCount < MAX_RETRIES_429;
        }).on(
            exec(session -> {
                Integer retryCount = session.getInt("retry429Count");
                if (retryCount == null) retryCount = 0;
                retryCount++;
                return session.set("retry429Count", retryCount);
            })
            .pause(Duration.ofSeconds(1))
            .exec(checkout())
        );
    }

    // --- Chain: Full checkout journey ---
    private static ChainBuilder checkoutJourney() {
        return exec(login())
            .exec(getCatalog())
            .exec(traverseCatalogPages())
            .exec(challengeFlow())
            .exec(createCart())
            .exec(getCart())
            .exec(updateCartQuantity(2))
            .exec(reservationFlow())
            .exec(checkout())
            .exec(handle401Expiry())
            .exec(handle429Retry());
    }

    // --- Chain: Browse operation ---
    private static ChainBuilder browseOperation() {
        return exec(
            http("POST /v2/browse")
                .post("/v2/browse")
                .header("X-CSRF-Token", session -> session.getString("csrf"))
                .body(StringBody("{}"))
                .check(status().in(200, 429, 401, 500))
                .check(bodyString().saveAs("browseResponseBody"))
                .check(header("Retry-After").optional().saveAs("browseRetryAfter"))
        )
        .exec(session -> {
            String body = session.getString("browseResponseBody");
            String csrf = extractCsrf(body);
            if (csrf != null) {
                session = session.set("csrf", csrf);
            }
            return session;
        })
        .doIf(session -> session.getInt("status") != null && session.getInt("status") == 429).then(
            exec(session -> {
                Integer retryCount = session.getInt("browseRetry429Count");
                if (retryCount == null) retryCount = 0;
                return session.set("browseRetry429Count", retryCount);
            })
            .asLongAs(session -> {
                Integer status = session.getInt("status");
                Integer retryCount = session.getInt("browseRetry429Count");
                return status != null && status == 429 && retryCount != null && retryCount < MAX_RETRIES_429;
            }).on(
                exec(session -> {
                    Integer retryCount = session.getInt("browseRetry429Count");
                    if (retryCount == null) retryCount = 0;
                    retryCount++;
                    return session.set("browseRetry429Count", retryCount);
                })
                .pause(Duration.ofSeconds(1))
                .exec(
                    http("POST /v2/browse retry")
                        .post("/v2/browse")
                        .header("X-CSRF-Token", session -> session.getString("csrf"))
                        .body(StringBody("{}"))
                        .check(status().in(200, 429, 401, 500))
                        .check(bodyString().saveAs("browseResponseBody"))
                        .check(header("Retry-After").optional().saveAs("browseRetryAfter"))
                )
                .exec(session -> {
                    String body = session.getString("browseResponseBody");
                    String csrf = extractCsrf(body);
                    if (csrf != null) {
                        session = session.set("csrf", csrf);
                    }
                    return session;
                })
            )
        );
    }

    // --- Chain: Browse user (login then browse) ---
    private static ChainBuilder browseUser() {
        return exec(login())
            .exec(browseOperation());
    }

    // --- Scenario: Browse pool ---
    private static ScenarioBuilder browseScenario = scenario("BrowsePool")
        .feed(userFeederBuilder)
        .exec(browseUser());

    // --- Scenario: Checkout pool ---
    private static ScenarioBuilder checkoutScenario = scenario("CheckoutPool")
        .feed(userFeederBuilder)
        .exec(checkoutJourney());

    {
        setUp(
            browseScenario.injectOpen(
                constantUsersPerSec(BROWSE_RATE).during(Duration.ofSeconds(TOTAL_RUNTIME))
            ),
            checkoutScenario.injectOpen(
                constantUsersPerSec(CHECKOUT_RATE).during(Duration.ofSeconds(TOTAL_RUNTIME))
            )
        )
        .protocols(httpProtocol)
        .maxDuration(Duration.ofSeconds(TOTAL_RUNTIME + 10))
        .assertions(
            global().failedRequests().percent().lt(1.0)
        );
    }
