                    html.match(/name=["']csrf["'][^>]*value=["']([^"']+)["']/i);
  const csrf = csrfMatch ? csrfMatch[1] : null;
  const nonceMatch = html.match(/name=["']login_nonce["'][^>]*value=["']([^"']+)["']/i) ||
                     html.match(/value=["']([^"']+)["'][^>]*name=["']login_nonce["']/i);
  const nonce = nonceMatch ? nonceMatch[1] : null;
  return { csrf, nonce };
}

function parseChallengeForm(html) {
  const actionMatch = html.match(/action=["']([^"']*\/v2\/challenges\/[^"']+)["']/i);
  const action = actionMatch ? actionMatch[1] : null;
  const challengeMatch = html.match(/name=["']challenge["'][^>]*value=["']([^"']+)["']/i) ||
                         html.match(/value=["']([^"']+)["'][^>]*name=["']challenge["']/i);
  const challenge = challengeMatch ? challengeMatch[1] : null;
  return { action, challenge };
}

function getSessionCookie(response) {
  const setCookies = response.headers['Set-Cookie'] || [];
  for (const sc of setCookies) {
    if (sc.startsWith('session=')) {
      return sc.split(';')[0];
    }
  }
  return null;
}

function login(username, password) {
  const formRes = http.get(`${BASE_URL}/v2/login-form`, { redirects: 0 });
  if (formRes.status !== 200) {
