    return null;
  }
  const { csrf, nonce } = parseForm(formRes.body);
  if (!csrf) {
    unexpectedErrors.add(1);
    return null;
  }
  const loginRes = http.post(`${BASE_URL}/v2/login`, JSON.stringify({
    username: username,
    password: password,
    csrf: csrf
  }), {
    headers: { 'Content-Type': 'application/json' },
    redirects: 0
  });
  if (loginRes.status === 302) {
    const loc = loginRes.headers['Location'];
    if (loc) {
      const locRes = http.get(loc.startsWith('http') ? loc : `${BASE_URL}${loc}`, { redirects: 0 });
      if (locRes.status !== 200) {
        unexpectedErrors.add(1);
        return null;
      }
      const sessionCookie = getSessionCookie(locRes);
      const body = JSON.parse(locRes.body);
      return { csrf: body.csrf, user: body.user, sessionCookie };
    }
    unexpectedErrors.add(1);
    return null;
  }
  if (loginRes.status !== 200) {
    unexpectedErrors.add(1);
    return null;
  }
  const sessionCookie = getSessionCookie(loginRes);
  const body = JSON.parse(loginRes.body);
  return { csrf: body.csrf, user: body.user, sessionCookie };
}

function renewSession(currentCsrf) {
  const res = http.post(`${BASE_URL}/v2/session/renew`, '{}', {
    headers: {
      'Content-Type': 'application/json',
      'X-CSRF-Token': currentCsrf
    },
    redirects: 0
  });
  if (res.status === 200) {
    const body = JSON.parse(res.body);
    return { csrf: body.csrf || currentCsrf, renewed: true };
  }
  return { csrf: currentCsrf, renewed: false };
}

function recoverCart(cartId, csrf) {
  const res = http.post(`${BASE_URL}/v2/carts/${cartId}/recover`, '{}', {
    headers: {
      'Content-Type': 'application/json',
