function getCatalog(profile) {
  const res = http.get(`${BASE_URL}/v2/catalog`, { redirects: 0 });
  if (res.status !== 200) {
    unexpectedErrors.add(1);
    return null;
  }
  const body = JSON.parse(res.body);
