      }
      if (body.status === 'failed') {
        return { reservationId: null, csrf: body.csrf || csrf };
      }
    } else {
      unexpectedErrors.add(1);
      return { reservationId: null, csrf };
    }
  }
  return { reservationId: null, csrf };
}

function doWork(csrf) {
  const res = http.post(`${BASE_URL}/v2/work`, '{}', {
    headers: {
      'Content-Type': 'application/json',
      'X-CSRF-Token': csrf
    },
    redirects: 0
  });
  workResponses.add(1);
  if (res.status === 200) {
    completedWork.add(1);
    return { ok: true, csrf };
  }
  if (res.status === 429) {
    scheduled429s.add(1);
    const retryAfter = parseInt(res.headers['Retry-After'] || '1');
    sleep(Math.min(retryAfter, 1));
    return { ok: false, csrf, retry429: true };
  }
  if (res.status === 401) {
    const body = JSON.parse(res.body || '{}');
    if (body.error === 'expired') {
      return { ok: false, csrf, expired: true };
    }
    if (body.error === 'session') {
      return { ok: false, csrf, sessionRevoked: true };
    }
    if (body.error === 'denied') {
      workFailures.add(1);
      return { ok: false, csrf, denied: true };
    }
  }
  workFailures.add(1);
  unexpectedErrors.add(1);
  return { ok: false, csrf };
}

function doBrowse(csrf) {
  const res = http.post(`${BASE_URL}/v2/browse`, '{}', {
    headers: {
      'Content-Type': 'application/json',
      'X-CSRF-Token': csrf
    },
    redirects: 0
  });
  businessResponses.add(1);
  if (res.status === 200) {
    const body = JSON.parse(res.body);
    if (body.ok === true) {
      return { ok: true, csrf: body.csrf || csrf };
    }
    unexpectedErrors.add(1);
    return { ok: false, csrf: body.csrf || csrf };
  }
  if (res.status === 429) {
    scheduled429s.add(1);
    const retryAfter = parseInt(res.headers['Retry-After'] || '1');
    sleep(Math.min(retryAfter, 1));
    return { ok: false, csrf, retry429: true };
  }
  if (res.status === 401) {
    const body = JSON.parse(res.body || '{}');
    if (body.error === 'expired') {
      return { ok: false, csrf, expired: true };
    }
    if (body.error === 'session') {
      return { ok: false, csrf, sessionRevoked: true };
