function handle401Expiry(csrf, cartId, operationFn) {
  const renewRes = renewSession(csrf);
  if (renewRes.renewed) {
    let newCsrf = renewRes.csrf;
    if (cartId) {
      const recRes = recoverCart(cartId, newCsrf);
      newCsrf = recRes.csrf;
    }
    return operationFn(newCsrf);
  }
  return { ok: false, csrf, sessionRevoked: true };
}

function handleSessionRevoked(username, password, cartId, operationFn) {
  const loginRes = login(username, password);
  if (!loginRes) {
    return { ok: false, csrf: null, sessionRevoked: true };
  }
  let newCsrf = loginRes.csrf;
  if (cartId) {
    const recRes = recoverCart(cartId, newCsrf);
    newCsrf = recRes.csrf;
  }
  return operationFn(newCsrf);
}

function checkoutJourney(username, password, profile) {
  const loginRes = login(username, password);
  if (!loginRes) {
    droppedWork.add(1);
    return;
  }
  let csrf = loginRes.csrf;
  let cartId = null;
  let etag = null;
  let grantId = null;

  // Catalog selection
  const products = getCatalog(profile);
  if (!products || products.length === 0) {
    droppedWork.add(1);
    return;
  }
  let selectedProduct = null;
  let selectedVariant = null;
  for (const p of products) {
    if (p.variants && p.variants.length > 0) {
      for (const v of p.variants) {
        if (v.in_stock) {
          selectedProduct = p;
          selectedVariant = v;
          break;
        }
      }
      if (selectedProduct) break;
    }
  }
  if (!selectedProduct) {
    // Try catalog pages
    let nextUrl = '/v2/catalog/page';
    for (let i = 0; i < 3 && !selectedProduct; i++) {
      const pageRes = getCatalogPage(profile, nextUrl);
      if (!pageRes) break;
      const p = pageRes.product;
      if (p && p.variants) {
        for (const v of p.variants) {
          if (v.in_stock) {
            selectedProduct = p;
            selectedVariant = v;
            break;
          }
        }
      }
      if (!selectedProduct && pageRes.next) {
        nextUrl = pageRes.next;
      } else {
        break;
      }
    }
  }
  if (!selectedProduct) {
    droppedWork.add(1);
    return;
  }

  // Challenge
  const challengeForm = getChallengeForm(csrf);
  if (challengeForm && challengeForm.action && challengeForm.challenge) {
    const challengeRes = postChallenge(challengeForm.action, challengeForm.challenge, csrf);
    if (challengeRes) {
      csrf = challengeRes.csrf;
      grantId = challengeRes.grantId;
    }
  }

  // Create cart
  const cartRes = createCart(selectedProduct.id, selectedVariant.id, grantId, csrf);
  if (!cartRes) {
    droppedWork.add(1);
    return;
  }
  cartId = cartRes.cartId;
  csrf = cartRes.csrf;
  etag = cartRes.etag;

  // Patch cart
  const patchRes = patchCart(cartId, 1, etag, csrf);
  csrf = patchRes.csrf;
  if (patchRes.retry) {
    const cartGet = getCart(cartId, csrf);
    if (cartGet) {
      etag = cartGet.etag;
      csrf = cartGet.csrf;
      const retryPatch = patchCart(cartId, 1, etag, csrf);
      csrf = retryPatch.csrf;
      etag = retryPatch.etag || etag;
    }
  } else {
    etag = patchRes.etag || etag;
  }

  // Reservation
  const reservationRes = createReservation(cartId, csrf);
  if (!reservationRes) {
    droppedWork.add(1);
    return;
  }
  csrf = reservationRes.csrf;
  const pollRes = pollReservation(reservationRes.statusUrl, csrf);
  csrf = pollRes.csrf;
  const reservationId = pollRes.reservationId;

  // Checkout with delay
  const now = Date.now();
  const t0 = getT0();
  let delay = profile.checkout_delay_seconds;
  if (t0 > 0 && now - t0 > profile.checkout_slow_after_seconds * 1000) {
    delay = profile.checkout_slow_seconds;
  }
  sleep(delay);

  // Place order
  const idempotencyKey = `cart-${cartId}-${__VU}-${__ITER}`;
  const orderPayload = { cart_id: cartId };
  if (reservationId) orderPayload.reservation_id = reservationId;
  const orderHeaders = {
    'Content-Type': 'application/json',
    'X-CSRF-Token': csrf,
    'Idempotency-Key': idempotencyKey
  };
  if (etag) orderHeaders['If-Match'] = etag;

  const orderRes = http.post(`${BASE_URL}/v2/orders`, JSON.stringify(orderPayload), {
    headers: orderHeaders,
    redirects: 0
  });

  if (orderRes.status === 201) {
    const body = JSON.parse(orderRes.body);
    if (body.accepted === true) {
      checkoutStarts.add(1);
      checkoutLatency.add((Date.now() - now) / 1000);
      csrf = body.csrf || csrf;
      return;
    }
    unexpectedErrors.add(1);
    droppedWork.add(1);
    return;
  }
  if (orderRes.status === 200) {
    const body = JSON.parse(orderRes.body);
    if (body.accepted === false) {
      // Business failure
      droppedWork.add(1);
      return;
    }
  }
  if (orderRes.status === 401) {
    const body = JSON.parse(orderRes.body || '{}');
    if (body.error === 'expired') {
      const retryRes = handle401Expiry(csrf, cartId, (newCsrf) => {
        const retryOrderRes = http.post(`${BASE_URL}/v2/orders`, JSON.stringify(orderPayload), {
          headers: {
            'Content-Type': 'application/json',
            'X-CSRF-Token': newCsrf,
            'Idempotency-Key': idempotencyKey,
            ...(etag ? { 'If-Match': etag } : {})
          },
          redirects: 0
        });
        if (retryOrderRes.status === 201) {
          const rb = JSON.parse(retryOrderRes.body);
          if (rb.accepted === true) {
            checkoutStarts.add(1);
            checkoutLatency.add((Date.now() - now) / 1000);
            return { ok: true, csrf: rb.csrf || newCsrf };
          }
        }
        return { ok: false, csrf: newCsrf };
      });
      if (retryRes.ok) return;
      csrf = retryRes.csrf;
    } else if (body.error === 'session') {
      const retryRes = handleSessionRevoked(username, password, cartId, (newCsrf) => {
        const retryOrderRes = http.post(`${BASE_URL}/v2/orders`, JSON.stringify(orderPayload), {
          headers: {
            'Content-Type': 'application/json',
            'X-CSRF-Token': newCsrf,
            'Idempotency-Key': idempotencyKey,
            ...(etag ? { 'If-Match': etag } : {})
          },
          redirects: 0
        });
        if (retryOrderRes.status === 201) {
          const rb = JSON.parse(retryOrderRes.body);
          if (rb.accepted === true) {
            checkoutStarts.add(1);
            checkoutLatency.add((Date.now() - now) / 1000);
            return { ok: true, csrf: rb.csrf || newCsrf };
          }
        }
        return { ok: false, csrf: newCsrf };
      });
      if (retryRes.ok) return;
      csrf = retryRes.csrf;
    } else if (body.error === 'denied') {
      unexpectedErrors.add(1);
      droppedWork.add(1);
      return;
    }
  }
  unexpectedErrors.add(1);
  droppedWork.add(1);
}

function browseOperation(username, password, profile) {
  const loginRes = login(username, password);
  if (!loginRes) {
    droppedWork.add(1);
    return;
  }
  let csrf = loginRes.csrf;
  let cartId = null;

  const browseRes = doBrowse(csrf);
  if (browseRes.ok) {
    browseStarts.add(1);
    browseLatency.add(0);
    csrf = browseRes.csrf;
    return;
  }
  if (browseRes.expired) {
    const retryRes = handle401Expiry(csrf, cartId, (newCsrf) => {
      const r = doBrowse(newCsrf);
      if (r.ok) {
        browseStarts.add(1);
        browseLatency.add(0);
        return { ok: true, csrf: r.csrf };
      }
      return { ok: false, csrf: r.csrf };
    });
    if (retryRes.ok) return;
    csrf = retryRes.csrf;
  } else if (browseRes.sessionRevoked) {
    const retryRes = handleSessionRevoked(username, password, cartId, (newCsrf) => {
      const r = doBrowse(newCsrf);
      if (r.ok) {
        browseStarts.add(1);
        browseLatency.add(0);
        return { ok: true, csrf: r.csrf };
      }
      return { ok: false, csrf: r.csrf };
    });
    if (retryRes.ok) return;
    csrf = retryRes.csrf;
  } else if (browseRes.retry429) {
    // Retry up to 4 times
    for (let i = 0; i < 4; i++) {
      const r = doBrowse(csrf);
      if (r.ok) {
        browseStarts.add(1);
        browseLatency.add(0);
        csrf = r.csrf;
        return;
      }
      if (r.expired) {
        const retryRes = handle401Expiry(csrf, cartId, (newCsrf) => {
          const rr = doBrowse(newCsrf);
          if (rr.ok) {
            browseStarts.add(1);
            browseLatency.add(0);
            return { ok: true, csrf: rr.csrf };
          }
          return { ok: false, csrf: rr.csrf };
        });
        if (retryRes.ok) return;
        csrf = retryRes.csrf;
        break;
      }
      if (r.sessionRevoked) {
        const retryRes = handleSessionRevoked(username, password, cartId, (newCsrf) => {
          const rr = doBrowse(newCsrf);
          if (rr.ok) {
            browseStarts.add(1);
            browseLatency.add(0);
            return { ok: true, csrf: rr.csrf };
          }
          return { ok: false, csrf: rr.csrf };
        });
        if (retryRes.ok) return;
        csrf = retryRes.csrf;
        break;
      }
      if (!r.retry429) break;
    }
  }
  droppedWork.add(1);
}

