        self.idempotency_key = None
        self.logged_in = False
        self.iteration_count = 0
        self.max_iterations = 2

    def on_start(self):
        self.client.cookies.clear()
        self.login()

    def login(self):
        # GET login form
        with self.client.get(
            "/v2/login-form",
            catch_response=True,
            allow_redirects=False,
        ) as resp:
            if resp.status_code >= 400:
                resp.failure(f"login-form failed: {resp.status_code}")
                return
            # Extract csrf from input[name=csrf]
            import re
            match = re.search(r'name=["\']csrf["\'][^>]*value=["\']([^"\']+)["\']', resp.text)
            if not match:
                match = re.search(r'value=["\']([^"\']+)["\'][^>]*name=["\']csrf["\']', resp.text)
            if not match:
                resp.failure("no csrf token in login form")
                return
            self.csrf_token = match.group(1)

        # POST login
        with self.client.post(
            "/v2/login",
            json={"username": self.username, "password": PASSWORD, "csrf": self.csrf_token},
            headers={"X-CSRF-Token": self.csrf_token},
            catch_response=True,
            allow_redirects=False,
        ) as resp:
            if resp.status_code == 302:
                location = resp.headers.get("Location")
                if location:
                    with self.client.get(
                        location,
                        catch_response=True,
                        allow_redirects=False,
                    ) as resp2:
                        if resp2.status_code >= 400:
                            resp2.failure(f"login redirect failed: {resp2.status_code}")
                            return
                        self._process_login_response(resp2)
                else:
                    resp.failure("302 without Location")
                    return
            elif resp.status_code < 400:
                self._process_login_response(resp)
            else:
                resp.failure(f"login failed: {resp.status_code}")

    def _process_login_response(self, resp):
        try:
            data = resp.json()
            self.csrf_token = data.get("csrf", self.csrf_token)
            self.logged_in = True
        except Exception:
            resp.failure("invalid login response")
            return

    def renew_session(self):
        with self.client.post(
            "/v2/session/renew",
            json={},
            headers={"X-CSRF-Token": self.csrf_token},
            catch_response=True,
            allow_redirects=False,
        ) as resp:
            if resp.status_code < 400:
                try:
                    data = resp.json()
                    self.csrf_token = data.get("csrf", self.csrf_token)
                except Exception:
                    pass
                return True
            else:
                resp.failure(f"renew failed: {resp.status_code}")
                return False

    def recover_cart(self):
        if not self.cart_id:
            return False
        with self.client.post(
            f"/v2/carts/{self.cart_id}/recover",
            json={},
            headers={"X-CSRF-Token": self.csrf_token},
            catch_response=True,
            allow_redirects=False,
        ) as resp:
            if resp.status_code < 400:
                try:
                    data = resp.json()
                    self.csrf_token = data.get("csrf", self.csrf_token)
                except Exception:
                    pass
                return True
            else:
                resp.failure(f"recover failed: {resp.status_code}")
                return False

    def handle_401(self, resp, operation_name):
        try:
            error_data = resp.json()
            error_type = error_data.get("error", "")
        except Exception:
            error_type = ""

        if error_type == "expired":
            if self.renew_session():
                if self.cart_id:
                    self.recover_cart()
                return "retry"
            else:
                return "fail"
        elif error_type == "session":
            # Revoked session: re-login and recover cart
            self.login()
            if self.cart_id:
                self.recover_cart()
            return "retry"
        elif error_type == "denied":
            resp.failure("denied error is not expiry")
            return "fail"
        else:
            resp.failure(f"unexpected 401: {error_type}")
            return "fail"

    def get_catalog(self):
        with self.client.get(
            "/v2/catalog",
            headers={"X-CSRF-Token": self.csrf_token},
            catch_response=True,
            allow_redirects=False,
        ) as resp:
            if resp.status_code == 401:
                action = self.handle_401(resp, "catalog")
                if action == "retry":
                    return self.get_catalog()
                return None
            if resp.status_code >= 400:
                resp.failure(f"catalog failed: {resp.status_code}")
                return None
            try:
                data = resp.json()
                products = data.get("data", {}).get("products", [])
                if products:
                    return products[0]
            except Exception:
                resp.failure("invalid catalog response")
            return None

    def get_catalog_page(self, page_url=None):
        url = page_url or "/v2/catalog/page"
        with self.client.get(
            url,
            headers={"X-CSRF-Token": self.csrf_token},
            catch_response=True,
            allow_redirects=False,
        ) as resp:
            if resp.status_code == 401:
                action = self.handle_401(resp, "catalog_page")
                if action == "retry":
                    return self.get_catalog_page(page_url)
                return None
            if resp.status_code >= 400:
                resp.failure(f"catalog page failed: {resp.status_code}")
                return None
            try:
                data = resp.json()
                product = data.get("data", {}).get("product")
                next_url = data.get("next")
                return product, next_url
            except Exception:
                resp.failure("invalid catalog page response")
                return None, None

    def create_cart(self, product_id, variant_id):
        payload = {"product_id": product_id, "variant_id": variant_id}
        if self.grant_id:
            payload["grant_id"] = self.grant_id
        with self.client.post(
            "/v2/carts",
            json=payload,
            headers={"X-CSRF-Token": self.csrf_token},
            catch_response=True,
            allow_redirects=False,
        ) as resp:
            if resp.status_code == 401:
                action = self.handle_401(resp, "create_cart")
                if action == "retry":
                    return self.create_cart(product_id, variant_id)
                return False
            if resp.status_code == 201:
                try:
                    data = resp.json()
                    self.cart_id = data.get("id")
                    self.csrf_token = data.get("csrf", self.csrf_token)
                    self.cart_etag = resp.headers.get("ETag")
                    return True
                except Exception:
                    resp.failure("invalid cart creation response")
                    return False
            else:
                resp.failure(f"create cart failed: {resp.status_code}")
                return False

    def get_cart(self):
        with self.client.get(
            f"/v2/carts/{self.cart_id}",
            headers={"X-CSRF-Token": self.csrf_token},
            catch_response=True,
            allow_redirects=False,
        ) as resp:
            if resp.status_code == 401:
                action = self.handle_401(resp, "get_cart")
                if action == "retry":
                    return self.get_cart()
                return False
            if resp.status_code < 400:
                self.cart_etag = resp.headers.get("ETag")
                return True
            else:
                resp.failure(f"get cart failed: {resp.status_code}")
                return False

    def update_cart_quantity(self, quantity):
        if not self.cart_etag:
            if not self.get_cart():
                return False
        with self.client.patch(
            f"/v2/carts/{self.cart_id}",
            json={"quantity": quantity},
            headers={
                "X-CSRF-Token": self.csrf_token,
                "If-Match": self.cart_etag,
            },
            catch_response=True,
            allow_redirects=False,
        ) as resp:
            if resp.status_code == 401:
                action = self.handle_401(resp, "update_cart")
                if action == "retry":
                    return self.update_cart_quantity(quantity)
                return False
            if resp.status_code == 412:
                # Re-read and retry once
                if self.get_cart():
                    with self.client.patch(
                        f"/v2/carts/{self.cart_id}",
                        json={"quantity": quantity},
                        headers={
                            "X-CSRF-Token": self.csrf_token,
                            "If-Match": self.cart_etag,
                        },
                        catch_response=True,
                        allow_redirects=False,
                    ) as resp2:
                        if resp2.status_code == 401:
                            action = self.handle_401(resp2, "update_cart_retry")
                            if action == "retry":
                                return self.update_cart_quantity(quantity)
                            return False
                        if resp2.status_code < 400:
                            self.cart_etag = resp2.headers.get("ETag")
                            return True
                        else:
                            resp2.failure(f"update cart retry failed: {resp2.status_code}")
                            return False
                return False
            if resp.status_code < 400:
                self.cart_etag = resp.headers.get("ETag")
                return True
            else:
                resp.failure(f"update cart failed: {resp.status_code}")
                return False

    def get_challenge(self):
        with self.client.get(
            "/v2/challenge-form",
            headers={"X-CSRF-Token": self.csrf_token},
            catch_response=True,
            allow_redirects=False,
        ) as resp:
            if resp.status_code == 401:
                action = self.handle_401(resp, "challenge_form")
                if action == "retry":
                    return self.get_challenge()
                return False
            if resp.status_code >= 400:
                resp.failure(f"challenge form failed: {resp.status_code}")
                return False
            import re
            match = re.search(r'action=["\']([^"\']+)["\']', resp.text)
            if not match:
                resp.failure("no challenge action found")
                return False
            action_url = match.group(1)
            match2 = re.search(r'name=["\']challenge["\']', resp.text)
            if not match2:
                resp.failure("no challenge input found")
                return False
            # Submit challenge
            with self.client.post(
                action_url,
                json={"challenge": "bench"},
                headers={"X-CSRF-Token": self.csrf_token},
                catch_response=True,
                allow_redirects=False,
            ) as resp2:
                if resp2.status_code == 401:
                    action = self.handle_401(resp2, "challenge_submit")
                    if action == "retry":
                        return self.get_challenge()
                    return False
                if resp2.status_code == 302:
                    location = resp2.headers.get("Location")
                    if location:
                        with self.client.get(
                            location,
                            headers={"X-CSRF-Token": self.csrf_token},
                            catch_response=True,
                            allow_redirects=False,
                        ) as resp3:
                            if resp3.status_code == 401:
                                action = self.handle_401(resp3, "challenge_location")
                                if action == "retry":
                                    return self.get_challenge()
                                return False
                            if resp3.status_code < 400:
                                try:
                                    data = resp3.json()
                                    self.grant_id = data.get("grant_id")
                                    self.csrf_token = data.get("csrf", self.csrf_token)
                                    return True
                                except Exception:
                                    resp3.failure("invalid challenge response")
                                    return False
                            else:
                                resp3.failure(f"challenge location failed: {resp3.status_code}")
                                return False
                    else:
                        resp2.failure("302 without Location")
                        return False
                else:
                    resp2.failure(f"challenge submit failed: {resp2.status_code}")
                    return False

    def create_reservation(self):
        with self.client.post(
            "/v2/reservations",
            json={"cart_id": self.cart_id},
            headers={"X-CSRF-Token": self.csrf_token},
            catch_response=True,
            allow_redirects=False,
        ) as resp:
            if resp.status_code == 401:
                action = self.handle_401(resp, "reservation")
                if action == "retry":
                    return self.create_reservation()
                return False
            if resp.status_code == 202:
                try:
                    data = resp.json()
                    status_url = data.get("status_url")
                    self.csrf_token = data.get("csrf", self.csrf_token)
                except Exception:
                    resp.failure("invalid reservation response")
                    return False
                # Poll status
                for _ in range(5):
                    time.sleep(0.05)
                    with self.client.get(
                        status_url,
                        headers={"X-CSRF-Token": self.csrf_token},
                        catch_response=True,
                        allow_redirects=False,
                    ) as poll_resp:
                        if poll_resp.status_code == 401:
                            action = self.handle_401(poll_resp, "reservation_poll")
                            if action == "retry":
                                continue
                            return False
                        if poll_resp.status_code < 400:
                            try:
                                poll_data = poll_resp.json()
                                status = poll_data.get("status")
                                if status == "ready":
                                    self.reservation_id = poll_data.get("reservation_id")
                                    self.csrf_token = poll_data.get("csrf", self.csrf_token)
                                    return True
                                elif status == "failed":
                                    return False
                                # pending: continue polling
                            except Exception:
                                poll_resp.failure("invalid poll response")
                                return False
                        else:
                            poll_resp.failure(f"poll failed: {poll_resp.status_code}")
                            return False
                return False
            else:
                resp.failure(f"reservation failed: {resp.status_code}")
                return False

    def place_order(self):
        if not self.idempotency_key:
            self.idempotency_key = generate_idempotency_key()
        payload = {"cart_id": self.cart_id}
        if self.reservation_id:
            payload["reservation_id"] = self.reservation_id
        headers = {
            "X-CSRF-Token": self.csrf_token,
            "Idempotency-Key": self.idempotency_key,
        }
        if self.cart_etag:
            headers["If-Match"] = self.cart_etag
        with self.client.post(
            "/v2/orders",
            json=payload,
            headers=headers,
            catch_response=True,
            allow_redirects=False,
        ) as resp:
            if resp.status_code == 401:
                action = self.handle_401(resp, "place_order")
                if action == "retry":
                    return self.place_order()
                return False
            if resp.status_code == 201:
                try:
                    data = resp.json()
                    if data.get("accepted") is True:
                        self.csrf_token = data.get("csrf", self.csrf_token)
                        return True
                    else:
                        resp.failure("order not accepted")
                        return False
                except Exception:
                    resp.failure("invalid order response")
                    return False
            elif resp.status_code == 200:
                try:
                    data = resp.json()
                    if data.get("accepted") is False:
                        resp.failure("business failure: accepted=false")
                        return False
                except Exception:
                    pass
                resp.failure(f"unexpected 200: {resp.text[:100]}")
                return False
            else:
                resp.failure(f"order failed: {resp.status_code}")
                return False

    def do_browse(self):
        with self.client.post(
            "/v2/browse",
            json={},
            headers={"X-CSRF-Token": self.csrf_token},
            catch_response=True,
            allow_redirects=False,
        ) as resp:
            if resp.status_code == 401:
                action = self.handle_401(resp, "browse")
                if action == "retry":
                    return self.do_browse()
                return False
            if resp.status_code == 429:
                # Scheduled 429: retry after 1s, up to 4 retries
                for _ in range(4):
                    time.sleep(1)
                    with self.client.post(
                        "/v2/browse",
                        json={},
                        headers={"X-CSRF-Token": self.csrf_token},
                        catch_response=True,
                        allow_redirects=False,
                    ) as retry_resp:
                        if retry_resp.status_code == 401:
                            action = self.handle_401(retry_resp, "browse_retry")
                            if action == "retry":
                                continue
                            return False
                        if retry_resp.status_code < 400:
                            return True
                        if retry_resp.status_code == 429:
                            continue
                        else:
                            retry_resp.failure(f"browse retry failed: {retry_resp.status_code}")
                            return False
                resp.failure("browse 429 retries exhausted")
                return False
            if resp.status_code < 400:
                return True
            else:
                resp.failure(f"browse failed: {resp.status_code}")
                return False

    def do_checkout_journey(self):
        # Fresh login/cart for each journey
        self.login()
        if not self.logged_in:
            return False

        # Get catalog
        product = self.get_catalog()
        if not product:
            # Try catalog page
            product, _ = self.get_catalog_page()
            if not product:
                return False

        product_id = product.get("id")
        variants = product.get("variants", [])
        if not variants:
            return False
        variant = variants[0]
        variant_id = variant.get("id")

        # Optional challenge
        self.grant_id = None
        # Try to get challenge (may fail, that's ok)
        self.get_challenge()

        # Create cart
        if not self.create_cart(product_id, variant_id):
            return False

        # Update quantity
        if not self.update_cart_quantity(1):
            return False

        # Create reservation
        self.reservation_id = None
        if not self.create_reservation():
            # Reservation failed, but we can still try checkout without it
            pass

        # Place order
        self.idempotency_key = generate_idempotency_key()
        return self.place_order()

    @task
    def run_iteration(self):
        if self.iteration_count >= self.max_iterations:
            raise StopUser()
        self.iteration_count += 1

        # Determine pool based on user type
        # We'll use a simple approach: alternate between browse and checkout
        # But the shape will control the actual rates
        # Here we just do the operation based on a flag set by the shape
        if hasattr(self, "pool_type") and self.pool_type == "checkout":
            self.do_checkout_journey()
        else:
            self.do_browse()


class ShopLoadShape(LoadTestShape):
    """
    Shape that maintains separate browse and checkout pools.
    Browse: 8/s, Checkout: 2/s
    """
    def __init__(self):
        super().__init__()
        self.start_time = time.time()
        self.browse_rate = 8.0
        self.checkout_rate = 2.0
        self.total_rate = self.browse_rate + self.checkout_rate
        self.checkout_fraction = self.checkout_rate / self.total_rate

    def tick(self):
        run_time = time.time() - self.start_time
        if run_time > 45:
            return None

        # Total users needed: rate * average response time
        # Assume average response time ~0.5s for browse, ~2s for checkout
        # Total users = browse_rate * 0.5 + checkout_rate * 2
        # = 8 * 0.5 + 2 * 2 = 4 + 4 = 8
        # But we need to account for the checkout journey being longer
        # Let's use a more conservative estimate
        total_users = int(self.total_rate * 2.5)  # 10 * 2.5 = 25
        total_users = max(total_users, 10)
        total_users = min(total_users, 64)

        # Assign pool types to users
        # We'll use a round-robin approach based on user index
        # The shape doesn't directly control which user does what,
        # so we'll set a class variable that users check
        checkout_count = int(total_users * self.checkout_fraction)
        browse_count = total_users - checkout_count

        # Store the pool assignment in a class variable
        # Users will check this in their task
        # We need to assign specific users to specific pools
        # Since we can't easily control individual users from the shape,
        # we'll use a different approach: each user randomly picks a pool
        # based on the fraction, but we'll seed it to maintain the ratio
        # Actually, let's use a simpler approach: use the user's ID to determine pool
        # This is done in the user's task method

        return (total_users, total_users)

    def get_user_pool(self, user_index):
        """Determine pool for a user based on index."""
        # Use a deterministic assignment
        # Users 0-3 are checkout (4 users for 2/s with ~2s journey)
        # Users 4+ are browse
        # But we need to be more dynamic
        # Let's use a hash-based approach
        checkout_users = max(1, int(64 * self.checkout_fraction))
        if user_index < checkout_users:
            return "checkout"
        return "browse"


# Override the user's task to use pool assignment
