# Global pool assignment
_pool_assignments = {}

def assign_pools(total_users, checkout_fraction):
    global _pool_assignments
    _pool_assignments = {}
    checkout_count = max(1, int(total_users * checkout_fraction))
    for i in range(total_users):
        if i < checkout_count:
            _pool_assignments[i] = "checkout"
        else:
            _pool_assignments[i] = "browse"


# Modify the user's task to use the pool assignment
# We'll do this by patching the run_iteration method
# Actually, let's just use a class variable that gets updated

class ShopUserWithPools(ShopUser):
    pool_type = "browse"

    def on_start(self):
        super().on_start()
        # Determine pool based on user ID
        # Locust assigns user IDs starting from 0
        # We'll use a global counter
        global _user_counter
        if not hasattr(ShopUserWithPools, "_counter"):
            ShopUserWithPools._counter = 0
        self.user_index = ShopUserWithPools._counter
        ShopUserWithPools._counter += 1

        # Check if we have a pool assignment
        if self.user_index in _pool_assignments:
            self.pool_type = _pool_assignments[self.user_index]
        else:
            # Default: use fraction
            if self.user_index < 4:
                self.pool_type = "checkout"
            else:
                self.pool_type = "browse"

    @task
    def run_iteration(self):
        if self.iteration_count >= self.max_iterations:
            raise StopUser()
        self.iteration_count += 1

        if self.pool_type == "checkout":
            self.do_checkout_journey()
        else:
            self.do_browse()


# Use the pooled user class
class BrowseUser(ShopUserWithPools):
