        self.iteration_count += 1
        self.do_browse()


class CheckoutPoolUser(ShopUser):
    """User that only does checkout journeys."""
    pool_type = "checkout"

    @task
    def checkout_task(self):
        if self.iteration_count >= self.max_iterations:
            raise StopUser()
        self.iteration_count += 1
        self.do_checkout_journey()


class PooledLoadShape(LoadTestShape):
    """
    Shape that maintains separate browse and checkout pools.
    Browse: 8/s, Checkout: 2/s
    """
    def __init__(self):
        super().__init__()
        self.start_time = time.time()
        self.browse_rate = 8.0
        self.checkout_rate = 2.0

    def tick(self):
        run_time = time.time() - self.start_time
        if run_time > 45:
            return None

        # Calculate user counts
        # Browse: 8/s with ~0.3s response = ~3 users, add buffer = 5
        # Checkout: 2/s with ~2s journey = ~4 users, add buffer = 6
        # But we need to return a tuple of (user_count, spawn_rate)
        # For multiple user classes, we return a dict
        # Actually, Locust 2.x supports returning a dict for multiple user classes
        # But the shape needs to return (user_count, spawn_rate) or a dict

        # For simplicity, we'll use a single user class with pool assignment
        # Total users = browse_users + checkout_users
        browse_users = 6
        checkout_users = 4
        total_users = browse_users + checkout_users

        # Set pool assignments
        global _pool_assignments
        _pool_assignments = {}
        for i in range(total_users):
            if i < checkout_users:
                _pool_assignments[i] = "checkout"
            else:
                _pool_assignments[i] = "browse"

        return (total_users, total_users)


# Final user class with pool assignment
class PooledShopUser(ShopUser):
    _user_counter = 0
    pool_type = "browse"

    def on_start(self):
        super().on_start()
        self.user_index = PooledShopUser._user_counter
        PooledShopUser._user_counter += 1

        if self.user_index in _pool_assignments:
            self.pool_type = _pool_assignments[self.user_index]
        else:
            # Default: first 20% are checkout
            if self.user_index < 4:
                self.pool_type = "checkout"
            else:
                self.pool_type = "browse"

    @task
    def run_iteration(self):
        if self.iteration_count >= self.max_iterations:
            raise StopUser()
        self.iteration_count += 1

        if self.pool_type == "checkout":
            self.do_checkout_journey()
        else:
            self.do_browse()


# Use these as the final classes
class HttpUserFinal(PooledShopUser):
    pass


class LoadTestShapeFinal(PooledLoadShape):
    pass


# Locust looks for classes named HttpUser and LoadTestShape
# We'll use the pooled versions
HttpUser = PooledShopUser
LoadTestShape = PooledLoadShape
